window.NOTAS=[{"id":"2026-11-28-la-fgr-catea-cuatro-domicilios-en-la-cdmx-por-el-caso-taddei-investiga","t":"La FGR catea cuatro domicilios en la CDMX por el caso Taddei; investiga a 50 personas físicas y morales","c":"politica","f":"2026-11-28T06:45","r":"La fiscal general Ernestina Godoy informó en un video que la FGR realizó cateos en dos domicilios de la colonia Condesa, uno en Jardines del Pedregal y otro en Polanco, dentro de la investigación por presunta corrupción en el INE que involucra a 50 personas físicas y morales, entre ellas la expresidenta del instituto Guadalupe Taddei. La Fiscalía integra 16 carpetas por posibles irregularidades en contratos de funcionarios del INE y de los organismos electorales locales. En uno de los inmuebles, según la FGR, se localizaron presuntas urnas y mamparas electorales, y se revisó documentación de adquisiciones de 2014 a 2026.","b":"","img":"ine","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4911347/la-fgr-catea-4-domicilios-ligados-a-caso-taddei-hay-50-personas-fisicas-involucradas/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-28-primera-tormenta-invernal-sheinbaum-pide-extremar-precauciones-ante-ne","t":"Primera tormenta invernal: Sheinbaum pide extremar precauciones ante nevadas, lluvias torrenciales y heladas de hasta -10 °C","c":"nacional","f":"2026-11-28T06:44","r":"La presidenta Claudia Sheinbaum llamó a la población a abrigarse y seguir las recomendaciones durante el fin de semana por la primera tormenta invernal de la temporada 2026-2027. El Servicio Meteorológico Nacional prevé este sábado lluvias torrenciales en Jalisco, Colima, Michoacán y puntos de Guerrero, con acumulados de hasta 250 mm en el occidente, y posible nieve o aguanieve por encima de 2,800 metros en Michoacán, Guanajuato, Querétaro, Hidalgo, Edomex, CDMX, Morelos, Tlaxcala, Puebla y Veracruz. En las sierras de Chihuahua y Durango las mínimas llegan a -10 °C; el domingo el sistema se debilitará, aunque seguirán las heladas.","b":"","img":"lluvia","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/11/28/estados/020n2est"],["Infobae","https://www.infobae.com/mexico/2026/11/28/en-vivo-clima-cdmx-y-resto-de-mexico-hoy-sabado-28-de-noviembre-tormenta-invernal-amenaza-con-lluvias-y-nevadas/"],["Infobae","https://www.infobae.com/mexico/2026/11/28/las-impresionantes-fotos-de-cdmx-bajo-la-tormenta-invernal-que-azota-al-pais/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-28-comision-del-ine-propone-medir-la-sobrerrepresentacion-por-partido-y-n","t":"Comisión del INE propone medir la sobrerrepresentación por partido y no por coalición; el Consejo General votará el lunes","c":"politica","f":"2026-11-28T06:43","r":"La Comisión de Prerrogativas y Partidos Políticos del INE aprobó un proyecto que mantiene el criterio de asignación de las 200 diputaciones plurinominales para 2027 y mide los límites de sobrerrepresentación por partido, no por coalición. Según lo reportado, las consejeras y consejeros Norma de la Cruz y Arturo Chávez rechazaron, 2 votos contra 1, la propuesta de Arturo Castillo. La comisión también respaldó un mecanismo de afiliación efectiva para impedir transferencias de militantes entre partidos. El proyecto pasará al Consejo General el lunes 30 de noviembre.","b":"","img":"ine","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4911307/el-ine-no-hace-cambios-la-asignacion-de-pluris-queda-por-partido-no-por-coalicion/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-28-eu-ofrece-a-caro-quintero-un-acuerdo-de-culpabilidad-que-le-evitaria-e","t":"EU ofrece a Caro Quintero un acuerdo de culpabilidad que le evitaría el juicio por el asesinato de Kiki Camarena","c":"seguridad","f":"2026-11-28T06:42","r":"El Departamento de Justicia de Estados Unidos entregó el viernes a la defensa de Rafael Caro Quintero una oferta para que se declare culpable de los cargos que enfrenta en una corte federal de Nueva York, entre ellos el asesinato del agente de la DEA Enrique \"Kiki\" Camarena. Los términos no se dieron a conocer. Los fiscales pidieron al juez Frederick Block mantener el inicio del juicio el 8 de marzo de 2027 mientras no haya acuerdo; las partes deben informar avances el lunes 30 de noviembre.","b":"","img":"ultimahora","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4911136/eu-ofrece-un-acuerdo-de-culpabilidad-a-caro-quintero-defensa-analizara-los-terminos/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-28-mexico-vuelve-al-superavit-comercial-en-octubre-298-millones-de-dolare","t":"México vuelve al superávit comercial en octubre: 298 millones de dólares, con exportaciones que crecen 30.2%","c":"economia","f":"2026-11-28T06:41","r":"El Inegi reportó un superávit comercial de 298.2 millones de dólares en octubre, tras el déficit de 606 millones de septiembre. Las exportaciones sumaron 86,008.7 millones de dólares, 30.2% más que hace un año; las no petroleras crecieron 31.2% y las petroleras cayeron 3.4%. Las importaciones llegaron a 85,710.5 millones (+30.8%). De enero a octubre el saldo acumulado es positivo por 9,552.5 millones de dólares, frente a 209 millones en el mismo periodo de 2025.","b":"","img":"bolsa","foto":"","cred":"","src":[["Industry News MX","https://www.industrynewsmx.com/mexico-registra-superavit-comercial-de-298-2-mdd-en-octubre-exportaciones-crecen-30-2/"],["La Crónica","https://www.cronica.com.mx/negocios/2026/11/27/mexico-registra-en-octubre-superavit-comercial-por-298-millones-de-dolares-inegi/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-el-peso-cierra-su-segunda-semana-de-perdidas-cae-2-7-51-centavos-pese","t":"El peso cierra su segunda semana de pérdidas: cae 2.7%, 51 centavos, pese al repunte del viernes","c":"economia","f":"2026-11-28T06:40","r":"Con el cierre del viernes en 19.67 pesos por dólar según Banxico, el peso acumuló una depreciación semanal de 2.7%, equivalente a 51 centavos frente al cierre de 19.16 del 20 de noviembre; es su segunda semana con pérdidas. En la última sesión la moneda ganó 0.25%. Analistas de Monex e IMB Capital atribuyeron el movimiento del viernes a la reactivación del mercado estadounidense tras Acción de Gracias y al apetito por riesgo. En ventanilla de Banamex el dólar se vendió en 20.15 pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/mercados/2026/11/27/peso-dolar-tipo-de-cambio-precio-hoy-27-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-el-colegio-de-escritores-de-latinoamerica-rompe-con-radio-centro-en-ap","t":"El Colegio de Escritores de Latinoamérica rompe con Radio Centro en apoyo a Ximena Santaolalla","c":"nacional","f":"2026-11-28T06:39","r":"El Colegio de Escritores de Latinoamérica anunció el viernes que termina su colaboración en el programa \"La Octava\", de Grupo Radio Centro, luego de que la escritora Ximena Santaolalla denunciara haber sufrido violencia sexual en su infancia y señalara como agresor a Francisco Aguirre Gómez, expresidente de la empresa. El Colegio rechazó el primer comunicado de la radiodifusora, que trató el caso como un asunto personal, y pidió una sanción social contra Aguirre Gómez. El testimonio se publicó en El País en el marco del 25 de noviembre.","b":"","img":"estudio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/28/suman-apoyos-a-ximena-santaolalla-colegio-de-escritores-de-latinoamerica-rompe-relacion-con-grupo-de-medios-en-mexico/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-una-delegacion-de-mas-de-1-500-zapatistas-se-traslada-de-chiapas-a-la","t":"Una delegación de más de 1,500 zapatistas se traslada de Chiapas a la CDMX para reunirse con madres buscadoras","c":"nacional","f":"2026-11-28T06:38","r":"Integrantes del EZLN, encabezados por el capitán Marcos, inician este fin de semana su viaje en caravana de autobuses desde Chiapas hacia la Ciudad de México para un encuentro con familias de personas desaparecidas, según la agenda de la agencia EFE. De acuerdo con la planeación difundida por Animal Político, la delegación es de 1,509 personas, tendrá como base la Casa de los Pueblos Samir Flores Soberanes y su regreso está previsto, de forma tentativa, para el 10 de enero de 2027.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/28/sabado-28-de-noviembre-de-2026-0200-gmt/"],["Animal Político","https://grupoanimal.mx/sociedad/ezln-visita-cdmx-reunion-madres-buscadoras-diciembre"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-chihuahua-el-exfiscal-cesar-jauregui-acusado-de-traicion-a-la-patria-e","t":"Chihuahua: el exfiscal César Jáuregui, acusado de traición a la patria, envía un mensaje desde el Altiplano","c":"estados","f":"2026-11-28T06:37","r":"El exfiscal general de Chihuahua César Jáuregui Moreno difundió un audio desde el penal de máxima seguridad del Altiplano, en el Estado de México, en el que dijo encontrarse bien, calificó su proceso como una injusticia y agradeció el respaldo de militantes del PAN. Fue detenido el 17 de octubre por el caso de la presunta participación de agentes de la CIA en un operativo contra un narcolaboratorio en la sierra de Chihuahua; la FGR lo acusa de traición a la patria y un juez lo vinculó a proceso el 25 de octubre con prisión preventiva. Su defensa impugna la vinculación.","b":"","img":"chihuahua","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4911111/cesar-jauregui-acusado-de-traicion-a-la-patria-reaparece-con-mensaje-desde-prision/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-detienen-en-michoacan-a-un-segundo-implicado-en-el-feminicidio-de-la-i","t":"Detienen en Michoacán a un segundo implicado en el feminicidio de la influencer Valeria Márquez","c":"seguridad","f":"2026-11-28T06:36","r":"La Fiscalía de Jalisco informó la detención en Michoacán de un hombre por su probable participación en el feminicidio de Valeria Márquez, asesinada en mayo de 2025 en su salón de belleza en Zapopan mientras hacía una transmisión en vivo. La captura se logró en coordinación con la Secretaría de Seguridad federal; es el segundo detenido por el caso.","b":"","img":"jalisco","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4911074/autoridades-capturan-a-otro-presunto-implicado-en-el-feminicidio-de-valeria-marquez/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-policias-de-mazatlan-repelen-una-agresion-armada-cerca-de-el-tiro-muer","t":"Policías de Mazatlán repelen una agresión armada cerca de El Tiro; mueren cuatro presuntos delincuentes","c":"seguridad","f":"2026-11-28T06:35","r":"Agentes del Grupo de Operaciones Especiales de la policía municipal de Mazatlán, Sinaloa, repelieron un ataque de civiles armados cerca del poblado El Tiro; cuatro presuntos integrantes de la delincuencia organizada murieron y ningún policía resultó herido, informó la Secretaría de Seguridad estatal. Se aseguraron armas largas, cartuchos y un vehículo. El hecho ocurrió un día después del ataque en una cerrajería de la colonia Benito Juárez en el que murieron cuatro hombres.","b":"","img":"ultimahora","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4911137/policias-de-mazatlan-repelen-agresion-de-civiles-armados-y-abaten-a-4-aseguran-armas/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-morelos-tres-muertos-y-dos-heridos-en-ataques-armados-en-cuernavaca-y","t":"Morelos: tres muertos y dos heridos en ataques armados en Cuernavaca y Yecapixtla","c":"estados","f":"2026-11-28T06:34","r":"Entre la noche del miércoles y la tarde del jueves se registraron tres personas asesinadas y dos heridas por disparos en Morelos. En la colonia Las Granjas de Cuernavaca murió un motociclista; en Amatitlán, también en Cuernavaca, fueron hallados sin vida una mujer y un hombre dentro de una vivienda, junto a una pistola. En Juan Morales, Yecapixtla, dos hombres de entre 25 y 30 años fueron baleados y llevados al Hospital General de Cuautla. No se reportaron detenidos.","b":"","img":"carretera","foto":"","cred":"","src":[["Quadratín Morelos","https://morelos.quadratin.com.mx/marcan-ataques-armados-jornada-violenta-en-cuernavaca-y-yecapixtla/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-cdmx-suma-63-mil-600-atenciones-a-personas-en-situacion-de-calle-por-e","t":"CDMX suma 63 mil 600 atenciones a personas en situación de calle por el frío; este fin de semana irá a Iztapalapa, GAM y V. Carranza","c":"cdmx","f":"2026-11-28T06:33","r":"El Gobierno de la Ciudad de México ha entregado 21,200 cenas calientes, 21,200 kits de invierno y 21,200 prendas de abrigo, además de 300 vacunas y 1,300 consultas médicas a personas en situación de calle. Opera cuatro puntos fijos (Alameda, Plaza de las Conchitas, Plaza de la Soledad y la Central de Abasto). El viernes, 168 servidores públicos atendieron a 321 personas en Cuauhtémoc; el sábado y el domingo los recorridos serán en Venustiano Carranza, Gustavo A. Madero e Iztapalapa. Protección Civil reportó la caída de dos árboles por lluvia y viento, sin lesionados.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/28/gobierno-de-cdmx-despliega-brigadas-para-proteger-a-personas-en-situacion-de-calle-ante-frio-extremo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-el-hoy-no-circula-sabatino-se-mantiene-pese-a-la-tormenta-invernal-des","t":"El Hoy No Circula sabatino se mantiene pese a la tormenta invernal: descansan holograma 1 par y todos los holograma 2","c":"cdmx","f":"2026-11-28T06:32","r":"Las autoridades mantienen sin cambios el Hoy No Circula de este sábado 28 de noviembre en la Zona Metropolitana del Valle de México. De 5:00 a 22:00 horas no circulan los autos con holograma 1 y placa terminada en número par ni todos los de holograma 2; los holograma 1 con terminación impar sí pueden circular. Aplica en las 16 alcaldías y en los municipios conurbados del Estado de México.","b":"","img":"metrobus","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4910838/cambia-el-hoy-no-circula-por-el-clima-para-este-sabado-28-de-noviembre-en-la-zmvm/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-proveedor-de-pemex-reclama-181-millones-de-pesos-a-mexxus-por-servicio","t":"Proveedor de Pemex reclama 181 millones de pesos a Mexxus por servicios en plataformas del Golfo","c":"economia","f":"2026-11-28T06:31","r":"Antonio Carlos Santos, apoderado de la empresa Soluciones Comerciales Tecnológicas y de Protección Ambiental (SCTPA), respondió a Mexxus Drilling International, que negó haberla contratado. Santos reclama 181.6 millones de pesos por 21 servicios prestados a Pemex Exploración y Producción entre 2020 y 2023 en las plataformas Abkatún-A, Pol-A y Litoral-A, y exhibió un documento de pagos de Pemex de junio de 2022 donde Mexxus aparece con 73.6 millones de pesos. Mexxus sostiene que trató directamente con Pemex; las acusaciones no han sido resueltas por una autoridad.","b":"","img":"pemex","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/deportes/2026/11/27/antonio-carlos-santos-responde-a-mexxus-por-presunto-fraude-con-pemex/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-la-relatora-de-la-onu-francesca-albanese-pasa-otra-noche-en-el-aeropue","t":"La relatora de la ONU Francesca Albanese pasa otra noche en el aeropuerto de Costa Rica; un tribunal frena su expulsión","c":"internacional","f":"2026-11-28T06:30","r":"Francesca Albanese, relatora especial de la ONU para los territorios palestinos, cumplió una segunda noche retenida en el aeropuerto Juan Santamaría, luego de que Migración le negara la entrada por una alerta internacional. La Sala Constitucional admitió un hábeas corpus y ordenó como medida cautelar que no sea expulsada. Albanese recibió de forma virtual, desde el aeropuerto, un doctorado honoris causa de la Universidad de Costa Rica; según EFE, prevé viajar después a México.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/28/albanese-pasara-otra-noche-en-el-aeropuerto-de-costa-rica-vigilada-a-cada-paso/"],["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/28/temas-del-dia-de-efe-internacional-del-sabado-28-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-ucrania-y-rusia-intercambian-ataques-siete-muertos-en-nizhyn-y-seis-en","t":"Ucrania y Rusia intercambian ataques: siete muertos en Nizhyn y seis en zonas ocupadas de Donetsk y Zaporiyia","c":"internacional","f":"2026-11-28T06:29","r":"Un ataque ruso contra una empresa en Nizhyn, en la región de Chernígov, dejó al menos siete muertos, según el Servicio de Emergencias de Ucrania. Por su parte, autoridades prorrusas reportaron seis fallecidos en ataques ucranianos: cuatro, entre ellos dos niños, en Makíivka (Donetsk), y dos en un ataque contra una ambulancia en Zaporiyia. Las negociaciones de paz mediadas por Estados Unidos se reanudaron el 10 de noviembre y el Kremlin rechaza una tregua invernal.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/28/mueren-seis-personas-en-ataques-ucranianos-contra-zonas-ocupadas-en-donetsk-y-zaporiyia/"],["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/28/temas-del-dia-de-efe-internacional-del-sabado-28-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-eu-niega-cobrar-peaje-en-ormuz-y-haber-robado-petroleros-iranies-neutr","t":"EU niega cobrar peaje en Ormuz y haber robado petroleros iraníes; neutraliza un buque que intentó romper el bloqueo","c":"internacional","f":"2026-11-28T06:28","r":"El Comando Central de Estados Unidos rechazó las acusaciones del comandante de la Armada iraní, Shahram Irani, de que cobra 2.5 millones de dólares a los barcos comerciales por cruzar el estrecho de Ormuz y de que robó dos petroleros. También informó que neutralizó en el golfo de Omán al granelero Pacific Archer, con bandera de Palaos, que intentó romper el bloqueo naval a Irán; la tripulación resultó ilesa.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/28/eeuu-niega-que-cobre-a-los-barcos-por-pasar-por-ormuz-y-el-robo-de-dos-petroleros-de-iran/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-marc-marquez-anuncia-por-sorpresa-su-retiro-con-10-titulos-mundiales-u","t":"Marc Márquez anuncia por sorpresa su retiro con 10 títulos mundiales, una semana después de su octavo de MotoGP","c":"deportes","f":"2026-11-28T06:27","r":"El piloto español Marc Márquez, de 33 años, anunció su retirada del motociclismo durante los primeros entrenamientos libres del Gran Premio de Valencia, última carrera de la temporada, con carteles en el box de Ducati. Se despide con 10 campeonatos mundiales: ocho de MotoGP, uno de 125 cc y uno de Moto2; con el octavo título de la categoría reina igualó a Giacomo Agostini. No dio a conocer sus planes.","b":"","img":"autodromo","foto":"","cred":"","src":[["Infobae (Europa Press)","https://www.infobae.com/america/agencias/2026/11/27/ultima-hora-marc-marquez-anuncia-su-retirada-por-sorpresa-tras-su-decimo-titulo-mundial-de-motociclismo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-28-openai-corrige-un-error-de-facturacion-los-usuarios-agotaran-hasta-40","t":"OpenAI corrige un error de facturación: los usuarios agotarán hasta 40% más rápido sus límites en GPT-6.2","c":"tecnologia","f":"2026-11-28T06:26","r":"OpenAI corrigió una falla que aplicaba descuentos indebidos en el consumo de los modelos GPT-6.2 Astra y Sol, por lo que los usuarios agotarán sus límites de uso 40% más rápido con Astra y 25% más rápido con Sol. Thibault Sottiaux, jefe de ingeniería de ChatGPT, informó en X que no se cobrará la diferencia y que habrá un restablecimiento de límites para los planes Go, Plus, Pro y Business.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae (Europa Press)","https://www.infobae.com/america/agencias/2026/11/27/openai-corrige-un-error-de-facturacion-en-gpt-62-astra-y-sol-los-usuarios-agotaran-sus-limites-un-40-y-25-mas-rapido/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-sheinbaum-espera-cerrar-en-diciembre-un-acuerdo-arancelario-con-trump","t":"Sheinbaum espera cerrar en diciembre un acuerdo arancelario con Trump; ya hay unos 90 puntos resueltos","c":"nacional","f":"2026-11-27T18:43","r":"En su conferencia del viernes, la presidenta Claudia Sheinbaum dijo que espera alcanzar en diciembre un acuerdo sobre aranceles con Donald Trump, con quien prevé reunirse en el marco del G20. Señaló que alrededor de 90 puntos de la negociación con EU, sobre barreras no arancelarias, ya están resueltos, y que el secretario Marcelo Ebrard seguirá las pláticas sobre los aranceles de la sección 232 a automóviles, acero y aluminio.","b":"","img":"palacio","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-viernes-27-noviembre-2026-minuto-minuto-vivo-n6349586"],["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-227-de-noviembre-de-2026"]],"dest":true,"a":"Redacción"},{"id":"2026-11-27-sheinbaum-descarta-por-ahora-retirar-los-aranceles-a-productos-de-chin","t":"Sheinbaum descarta por ahora retirar los aranceles a productos de China pese a la petición de Pekín","c":"economia","f":"2026-11-27T18:42","r":"La presidenta rechazó retirar o reducir, por el momento, los aranceles a mercancías chinas, aunque el gobierno de China pidió revisar fracciones arancelarias específicas. Dijo que modificar esa política es inviable por ahora por el Plan México, aunque las conversaciones comerciales siguen abiertas. México planteó abrir más espacio a sus productos, sobre todo agropecuarios, y Marcelo Ebrard sigue en Asia, donde asistió a la reunión ministerial del TIPAT.","b":"","img":"palacio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/sheinbaum-descarta-retirar-reducir-aranceles-china"],["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-viernes-27-noviembre-2026-minuto-minuto-vivo-n6349586"]],"dest":true,"a":"Redacción"},{"id":"2026-11-27-mexico-y-el-comando-norte-de-eu-evaluan-aumentar-las-operaciones-espej","t":"México y el Comando Norte de EU evalúan aumentar las operaciones espejo en la frontera","c":"seguridad","f":"2026-11-27T18:41","r":"Los secretarios de la Defensa, Ricardo Trevilla Trejo, y de Marina, Raymundo Pedro Morales Ángeles, se reunieron del 16 al 18 de noviembre con el general Gregory M. Guillot, jefe del Comando Norte y del NORAD, en la base Davis-Monthan, en Tucson, Arizona. Revisaron el plan de actividades 2027, el incremento de las operaciones simultáneas o \"espejo\", en las que cada país despliega fuerzas en su propio territorio sin cruzar la frontera, y la cooperación en seguridad marítima y ayuda ante desastres.","b":"","img":"texas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/fuerzas-armadas-de-mexico-y-comando-norte-de-eeuu-evaluan-incremento-de-operaciones-espejo-en-la-frontera/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-27-sheinbaum-niega-que-la-extradicion-del-chapo-isidro-sea-moneda-de-camb","t":"Sheinbaum niega que la extradición del Chapo Isidro sea moneda de cambio en la negociación con EU","c":"politica","f":"2026-11-27T18:40","r":"Consultada sobre el posible envío a Estados Unidos de Fausto Isidro Meza Flores, \"el Chapo Isidro\", la presidenta negó que forme parte de la negociación comercial o que sea una concesión a Washington. También reiteró que la relación con EU en seguridad es de cooperación y no de subordinación.","b":"","img":"palacio","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-227-de-noviembre-de-2026"],["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-viernes-27-noviembre-2026-minuto-minuto-vivo-n6349586"]],"dest":true,"a":"Redacción"},{"id":"2026-11-27-abre-la-bodega-nacional-de-arte-en-chapultepec-con-334-obras-a-la-vist","t":"Abre la Bodega Nacional de Arte en Chapultepec con 334 obras a la vista del público","c":"nacional","f":"2026-11-27T18:39","r":"El gobierno federal inauguró la Bodega Nacional de Arte, en la Cuarta Sección del Bosque de Chapultepec, que resguardará la colección de 12 museos del INBAL, unas 69 mil 500 obras. Según la secretaria de Cultura, Claudia Curiel de Icaza, el complejo tiene 45 mil metros cuadrados, 12 edificios y 11 bóvedas, y fue diseñado por Mauricio Rocha. El público podrá visitar 334 piezas, con obras de Frida Kahlo, Leonora Carrington y Siqueiros, a partir del próximo miércoles; su operación costará 120 millones de pesos al año.","b":"","img":"bellas","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-viernes-27-noviembre-2026-minuto-minuto-vivo-n6349586"],["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-227-de-noviembre-de-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-sheinbaum-cuestiona-el-perfil-ideologico-de-la-fil-curiel-de-icaza-ira","t":"Sheinbaum cuestiona el perfil ideológico de la FIL; Curiel de Icaza irá a la inauguración","c":"politica","f":"2026-11-27T18:38","r":"La presidenta informó que la secretaria de Cultura, Claudia Curiel de Icaza, la representará en la inauguración de la Feria Internacional del Libro de Guadalajara 2026. En la misma respuesta, Sheinbaum puso en duda el perfil ideológico de la feria. También anunció la distribución de un millón de libros de escritoras mexicanas y latinoamericanas, con una primera etapa en 2026 que continuará en 2027.","b":"","img":"palacio","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-viernes-27-noviembre-2026-minuto-minuto-vivo-n6349586"],["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-227-de-noviembre-de-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-el-museo-nacional-de-antropologia-elegido-el-mejor-museo-del-mundo-en","t":"El Museo Nacional de Antropología, elegido el mejor museo del mundo en un ranking internacional","c":"nacional","f":"2026-11-27T18:37","r":"Durante la conferencia presidencial se informó que el Museo Nacional de Antropología ocupó el primer lugar de la lista \"The World's 100 Best Museums 2026/27\", elaborada por Worth a Journey. En la misma sesión se dio a conocer que la sección Suave Patria ganó un premio como mejor serie de microespacios divulgativos.","b":"","img":"palacio","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-viernes-27-noviembre-2026-minuto-minuto-vivo-n6349586"],["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-227-de-noviembre-de-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-el-peso-rompe-su-racha-negativa-y-cierra-en-19-67-por-dolar","t":"El peso rompe su racha negativa y cierra en 19.67 por dólar","c":"economia","f":"2026-11-27T18:36","r":"El peso mexicano terminó el viernes con una ganancia de 0.25% frente al dólar y cerró en 19.6726 unidades, según el cierre de Banxico, contra 19.7214 del jueves. En la semana, sin embargo, la moneda acumuló una pérdida, después de siete sesiones a la baja. El euro cerró en 21.5068 pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["Heraldo Binario","https://www.heraldobinario.com.mx/tendencias/2026/11/27/precio-dolar-peso-cierra-con-ligera-apreciacion-este-viernes-27-de-noviembre-43936.html"],["Infobae","https://www.infobae.com/mexico/2026/11/27/dolar-hoy-en-mexico-cotizacion-de-cierre-del-27-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-la-bolsa-mexicana-sube-1-85-y-cierra-la-semana-con-una-ganancia-de-4-4","t":"La Bolsa Mexicana sube 1.85% y cierra la semana con una ganancia de 4.41%","c":"economia","f":"2026-11-27T18:35","r":"El S&P/BMV IPC avanzó 1.85% el viernes y cerró en 71 mil 657.88 unidades, con lo que acumuló un alza semanal de 4.41%. Las emisoras con mayores ganancias del día fueron Grupo Industrial Saltillo (6.69%), Peñoles (6.61%) y Aeroméxico (5.8%); en la semana destacaron Alpek, Peñoles y Cemex. Se negociaron 155 millones de acciones por 14 mil 267 millones de pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["MVS Noticias","https://mvsnoticias.com/economia/2026/11/27/repunta-bolsa-mexicana-de-valores-185-por-ciento-755052.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-el-brent-baja-1-2-a-95-44-dolares-pero-termina-la-semana-al-alza-por-r","t":"El Brent baja 1.2% a 95.44 dólares, pero termina la semana al alza por riesgos en Medio Oriente","c":"economia","f":"2026-11-27T18:34","r":"El barril de Brent para enero cerró el viernes en 95.44 dólares, con una caída de 1.13 dólares, y el WTI bajó 0.7% a 83.08 dólares. En la semana, el Brent subió por los ataques a instalaciones petroleras y buques en Medio Oriente, incluidos los del estrecho de Ormuz. La OPEP+ se reúne este domingo.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/27/el-brent-registra-una-subida-semanal-por-los-riesgos-sobre-el-suministro-mundial/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-sheinbaum-presenta-queja-formal-por-la-linea-de-denuncias-de-la-dea-y","t":"Sheinbaum presenta queja formal por la línea de denuncias de la DEA y dice que el cruce de fentanilo bajó 65%","c":"seguridad","f":"2026-11-27T18:33","r":"La presidenta informó que México presentó una queja formal por el canal de denuncias que abrió la DEA y reiteró que la relación con EU es de cooperación, no de subordinación. Afirmó que se han decomisado miles de laboratorios y que el cruce de fentanilo hacia EU bajó cerca de 65% desde el inicio de su gobierno. También dijo que hay límites jurídicos para la participación de EU en cursos de la Academia de Policía de Querétaro.","b":"","img":"palacio","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-viernes-27-noviembre-2026-minuto-minuto-vivo-n6349586"],["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-227-de-noviembre-de-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-morelos-seguridad-dice-que-el-regidor-asesinado-gabriel-rivas-nunca-pi","t":"Morelos: Seguridad dice que el regidor asesinado Gabriel Rivas nunca pidió protección","c":"estados","f":"2026-11-27T18:32","r":"El secretario de Seguridad de Morelos, José Luis Bucio Quiroz, afirmó que su dependencia no recibió denuncias ni solicitudes de protección del regidor de Morena Gabriel Rivas Ríos, asesinado el 4 de noviembre en Cuernavaca, y que nunca se le hizo una evaluación de riesgo. El fiscal Fernando Blumenkron informó de la detención de un presunto autor material; entre las líneas de investigación está la postura del regidor sobre el predio La Casa Aguatera.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/la-sspc-no-recibio-denuncias-ni-solicitudes-de-proteccion-por-parte-del-regidor-de-morena-gabriel-rivas-asesinado-en-morelos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-chiapas-agricultura-se-reune-con-nestle-y-cafeticultores-para-buscar-u","t":"Chiapas: Agricultura se reúne con Nestlé y cafeticultores para buscar un precio justo","c":"estados","f":"2026-11-27T18:31","r":"La secretaria de Agricultura, Columba Jazmín López Gutiérrez, sostuvo reuniones con productores de café de Chiapas y con la empresa Nestlé, informó la presidenta Sheinbaum. El objetivo, dijo, es que los cafeticultores obtengan un precio justo por su cosecha.","b":"","img":"palacio","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-227-de-noviembre-de-2026"],["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-viernes-27-noviembre-2026-minuto-minuto-vivo-n6349586"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-la-fil-de-guadalajara-abre-este-sabado-con-italia-como-invitado-de-hon","t":"La FIL de Guadalajara abre este sábado con Italia como invitado de honor","c":"estados","f":"2026-11-27T18:30","r":"La edición 40 de la Feria Internacional del Libro de Guadalajara se realizará del 28 de noviembre al 6 de diciembre, con Italia como país invitado de honor. Entre los participantes figuran Salman Rushdie y Gioconda Belli, y el programa incluye un homenaje a Juan Rulfo.","b":"","img":"jalisco","foto":"","cred":"","src":[["EFE / Infobae","https://www.infobae.com/america/agencias/2026/11/27/temas-del-dia-de-efe-internacional-del-viernes-27-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-hallan-muerto-en-una-cisterna-a-un-guardia-de-seguridad-en-la-benito-j","t":"Hallan muerto en una cisterna a un guardia de seguridad en la Benito Juárez","c":"cdmx","f":"2026-11-27T18:29","r":"El cuerpo de un guardia de seguridad privada de unos 30 años fue hallado el viernes dentro de la cisterna de un edificio en Tejocotes y San Lorenzo, colonia Tlacoquemécatl del Valle. Lo encontró su relevo, con la tapa abierta; la Fiscalía capitalina investiga cómo cayó. Es el séptimo caso de personas halladas muertas en cisternas en la capital en 2026.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/hallan-muerto-dentro-de-una-cisterna-a-guardia-de-seguridad-en-edificio-de-cdmx-es-el-septimo-caso-del-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-vecinos-de-miguel-hidalgo-denuncian-que-reabrieron-hospedajes-clausura","t":"Vecinos de Miguel Hidalgo denuncian que reabrieron hospedajes clausurados","c":"cdmx","f":"2026-11-27T18:28","r":"Habitantes de la alcaldía Miguel Hidalgo denunciaron que al menos cinco de ocho inmuebles clausurados por ofrecer hospedaje de corta estancia, conocidos como \"motelitos de lujo\", siguen operando, en calles como Bosque de Duraznos, Platón, Horacio y Monte Chimborazo. Los sellos se reportaron el 29 de octubre; los vecinos piden cuentas al alcalde Mauricio Tabe.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/vecinos-denuncian-que-motelitos-de-lujo-reabrieron-en-miguel-hidalgo-pese-a-clausuras/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-tribunal-confirma-por-unanimidad-el-amparo-de-vadhir-derbez","t":"Tribunal confirma por unanimidad el amparo de Vadhir Derbez","c":"entretenimiento","f":"2026-11-27T18:27","r":"Un tribunal colegiado ratificó por unanimidad el amparo que un juez de Distrito concedió a Vadhir Derbez, al concluir que la Fiscalía de la CDMX no acreditó elementos para una orden de aprehensión en una denuncia por presunta violación. El actor sostiene que fue víctima de un intento de extorsión; la identidad de la denunciante no se ha hecho pública.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/tribunal-colegiado-confirma-amparo-a-vadhir-derbez-por-unanimidad-fiscalia-cdmx-no-acredito-elementos-para-detenerlo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-liguilla-asi-llegan-los-cuartos-de-final-a-la-vuelta-cruz-azul-y-toluc","t":"Liguilla: así llegan los cuartos de final a la vuelta; Cruz Azul y Toluca, con ventaja","c":"deportes","f":"2026-11-27T18:26","r":"Tras la ida, Toluca ganó 2-0 a Atlas, Monterrey y América empataron 0-0, Pachuca venció 2-1 a Chivas y Cruz Azul goleó 4-0 al León. Si los marcadores se mantienen, las semifinales serían Cruz Azul contra Pachuca y América contra Toluca. En empate global avanza el mejor ubicado en la tabla; la ida de semifinales será el 2 y 3 de diciembre.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/11/27/quien-avanza-a-semifinales-de-la-liga-mx-asi-marcha-la-liguilla-del-apertura-2026-tras-los-partidos-de-ida/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-costa-rica-niega-la-entrada-a-la-relatora-de-la-onu-francesca-albanese","t":"Costa Rica niega la entrada a la relatora de la ONU Francesca Albanese","c":"internacional","f":"2026-11-27T18:25","r":"El gobierno de Costa Rica rechazó el ingreso al país de Francesca Albanese, relatora especial de la ONU para los territorios palestinos ocupados, quien iba a recibir un doctorado honoris causa de la Universidad de Costa Rica.","b":"","img":"ultimahora","foto":"","cred":"","src":[["EFE / Infobae","https://www.infobae.com/america/agencias/2026/11/27/temas-del-dia-de-efe-internacional-del-viernes-27-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-arranca-el-black-friday-en-eu-preven-182-7-millones-de-compradores","t":"Arranca el Black Friday en EU; prevén 182.7 millones de compradores","c":"internacional","f":"2026-11-27T18:24","r":"La Federación Nacional de Minoristas de EU estima que 182.7 millones de personas comprarán durante el fin de semana de Acción de Gracias y que las ventas de noviembre y diciembre podrían superar por primera vez el billón de dólares.","b":"","img":"texas","foto":"","cred":"","src":[["EFE / Infobae","https://www.infobae.com/america/agencias/2026/11/27/temas-del-dia-de-efe-internacional-del-viernes-27-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-la-conasami-preve-un-aumento-de-10-a-11-al-salario-minimo-para-2027-lo","t":"La Conasami prevé un aumento de 10% a 11% al salario mínimo para 2027; los trabajadores piden 15%","c":"nacional","f":"2026-11-27T06:59","r":"Luis Felipe Munguía, presidente de la Comisión Nacional de los Salarios Mínimos, dijo ante la Comisión de Trabajo de la Cámara de Diputados que el incremento para 2027 podría quedar entre 10% y 11%. El Consejo de Representantes se declaró en sesión permanente este jueves; el sector obrero pide 15% y Coparmex plantea inflación más dos puntos, cerca de 9.9%. El mínimo vigente es de 315.04 pesos diarios en la zona general y 440.87 en la frontera norte; el acuerdo se espera entre la primera y la segunda semana de diciembre y aplicaría desde el 1 de enero para unos 8 millones de trabajadores.","b":"","img":"palacio","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/economia/2026/11/26/salario-minimo-2027-aumentaria-entre-10-y-11-cuando-se-dara-a-conocer-segun-conasami/"],["Infobae","https://www.infobae.com/mexico/2026/11/26/negociacion-del-salario-minimo-2027-arranca-con-propuestas-de-aumento-de-10-a-mas-de-15/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-27-morena-reta-al-pan-pri-y-mc-a-eliminar-las-diputaciones-plurinominales","t":"Morena reta al PAN, PRI y MC a eliminar las diputaciones plurinominales","c":"politica","f":"2026-11-27T06:58","r":"Ignacio Mier, coordinador de Morena en el Senado, pidió a la oposición respaldar una reforma que elimine las plurinominales y el tope de sobrerrepresentación de 8%: \"Si no hay 8%, no debe de haber plurinominales\", dijo. Arturo Ávila, vocero de Morena en San Lázaro, prepara una reforma constitucional para suprimir las 200 diputaciones plurinominales a partir de 2030 y calcula un ahorro de hasta 40% en el gasto de la Cámara. Ávila retó a Ricardo Anaya, Jorge Romero, Alejandro Moreno y Jorge Álvarez Máynez a fijar postura.","b":"","img":"senado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/26/ignacio-mier-y-arturo-avila-retan-al-pan-pri-y-mc-a-presentar-reforma-profunda-para-pluris/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-27-a-un-mes-de-la-renuncia-de-taddei-el-ine-suma-140-salidas-y-la-fgr-tie","t":"A un mes de la renuncia de Taddei, el INE suma 140 salidas y la FGR tiene 15 carpetas sin órdenes de aprehensión","c":"politica","f":"2026-11-27T06:57","r":"La consejera Carla Humphrey afirmó que \"se acabó la era Taddei\" y el instituto contabiliza 140 separaciones o renuncias ligadas al caso, incluidos 10 integrantes de la Junta General Ejecutiva. Según Expansión, la FGR integra 15 carpetas de investigación sin orden de aprehensión, mientras el Órgano Interno de Control imputó a cinco funcionarios y mantiene 18 expedientes. Blanca Cruz preside de forma interina desde el 28 de octubre; los diputados esperarán la resolución del Tribunal Electoral sobre la demanda del PAN para emitir la convocatoria.","b":"","img":"ine","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/26/ine-taddei-30-dias-renuncia"],["Infobae","https://www.infobae.com/mexico/2026/11/26/se-acabo-la-era-taddei-en-el-ine-tras-renuncia-de-140-personas-resalta-carla-humphrey/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-27-monreal-presenta-con-todos-los-partidos-una-iniciativa-contra-abusos-e","t":"Monreal presenta con todos los partidos una iniciativa contra abusos en seguros de gastos médicos","c":"politica","f":"2026-11-27T06:56","r":"El coordinador de Morena en San Lázaro, Ricardo Monreal, presentó en el pleno una iniciativa respaldada también por PAN, PRI, PT, PVEM y MC que modifica cinco leyes y 34 artículos. Permitiría cambiar de aseguradora sin perder antigüedad ni periodos de espera, garantizaría a mayores de 60 años ajustar su póliza sin perder derechos y obligaría a transparentar los criterios de aumento de primas; los hospitales tendrían que publicar catálogos de precios. Monreal propuso discutirla el lunes en comisiones y el martes en el pleno.","b":"","img":"palacio","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/politica/2026/11/26/monreal-presenta-iniciativa-contra-abusos-en-seguros-de-gastos-medicos-384420.html"]],"dest":true,"a":"Redacción"},{"id":"2026-11-27-el-desempleo-sube-a-3-0-en-octubre-el-empleo-formal-pierde-507-mil-pla","t":"El desempleo sube a 3.0% en octubre; el empleo formal pierde 507 mil plazas y crece la informalidad","c":"economia","f":"2026-11-27T06:55","r":"Con datos de la ENOE del Inegi, la tasa de desocupación de octubre fue de 3.0%, frente a 2.6% un año antes, con 1.9 millones de personas sin empleo, 225 mil más que en octubre de 2025. En el mes se sumaron 738,285 personas ocupadas, pero el empleo formal bajó en 507,903 plazas y el informal creció en 1,246,188. La tasa de informalidad laboral subió a 55.7%; Gabriela Siller, de Banco Base, señaló que es la mayor alza mensual del empleo informal desde julio de 2021.","b":"","img":"palacio","foto":"","cred":"","src":[["Diario de Yucatán","https://www.yucatan.com.mx/general/2026/11/26/inegi-en-octubre-se-crearon-738285-empleos-en-mexico.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-la-pobreza-laboral-baja-a-30-5-en-el-tercer-trimestre-su-menor-nivel-d","t":"La pobreza laboral baja a 30.5% en el tercer trimestre, su menor nivel desde 2005","c":"economia","f":"2026-11-27T06:54","r":"Según el Inegi, 30.5% de la población no podía comprar la canasta alimentaria con su ingreso laboral en el tercer trimestre de 2026, 3.8 puntos menos que un año antes. El ingreso laboral real per cápita subió 9.3% anual, a 3,656.17 pesos mensuales, y 12.1% en zonas rurales. Chiapas (57.5%), Oaxaca (55.6%) y Guerrero (53.1%) tienen los niveles más altos; Baja California Sur (15.3%) y Baja California (16.0%), los más bajos.","b":"","img":"palacio","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/dinero/2026/11/26/la-pobreza-laboral-en-mexico-cae-a-305-en-el-tercer-trimestre-de-2026-su-nivel-mas-bajo-desde-2005-mientras-el-ingreso-laboral-real-sube-93-anual-segun-el-inegi/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-pan-pri-y-mc-no-acuden-al-foro-del-ine-sobre-sobrerrepresentacion-wold","t":"PAN, PRI y MC no acuden al foro del INE sobre sobrerrepresentación; Woldenberg pide cambiar el criterio","c":"politica","f":"2026-11-27T06:53","r":"El INE realizó el foro \"La representación proporcional en México. Perspectivas y dilemas\" sin la presencia de PAN, PRI y MC. José Woldenberg y Jacqueline Peschard plantearon modificar el criterio de asignación; Woldenberg señaló que la fórmula de 2024 dio 20 puntos más de escaños que de votos. El consejero Uuc-kib Espadas defendió la lectura textual de la Constitución, y magistrados del Tribunal Electoral dijeron que solo una reforma constitucional puede cambiar el sistema.","b":"","img":"ine","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/2026/11/26/la-oposicion-boicotea-foro-del-ine-sobre-la-sobrerrepresentacion-384440.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-operacion-enjambre-detienen-al-alcalde-de-atzitzintla-puebla-por-secue","t":"Operación Enjambre: detienen al alcalde de Atzitzintla, Puebla, por secuestro exprés y robo de vehículo","c":"seguridad","f":"2026-11-27T06:52","r":"Autoridades federales detuvieron a Eduardo \"N\", presidente municipal de Atzitzintla, con una orden de aprehensión por secuestro exprés y robo de vehículo agravado; lo vinculan con el líder de \"Los Zúñiga\", grupo dedicado al robo al autotransporte en la autopista 150-D Puebla-Veracruz. El secretario Omar García Harfuch informó del arresto en redes sociales. Con esta detención, la Operación Enjambre suma seis servidores públicos detenidos en 28 acciones, tres de ellos alcaldes.","b":"","img":"palacio","foto":"","cred":"","src":[["El Informador","https://www.informador.mx/mexico/operacion-enjambre-harfuch-informa-la-detencion-del-presidente-municipal-de-atzitzintla-puebla-20261126-0127.html"],["Expansión Política","https://politica.expansion.mx/mexico/2026/11/26/detienen-alcalde-atzitzintla-puebla-secuestro-expres"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-el-peso-rompe-su-racha-de-siete-caidas-y-abre-el-viernes-en-19-54-por","t":"El peso rompe su racha de siete caídas y abre el viernes en 19.54 por dólar","c":"economia","f":"2026-11-27T06:51","r":"El dólar se ofrecía en promedio en 19.54 pesos al inicio de la sesión de este viernes, frente a un cierre previo de 19.71, una variación de -0.83% según datos de Dow Jones citados por Infobae. El movimiento interrumpe la serie de siete jornadas de depreciación de la moneda mexicana.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/precio-del-dolar-hoy-en-mexico-cotizacion-de-apertura-del-27-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-juez-desecha-un-amparo-contra-la-extradicion-del-chapo-isidro-porque-e","t":"Juez desecha un amparo contra la extradición del \"Chapo Isidro\" porque el detenido no lo firmó","c":"seguridad","f":"2026-11-27T06:50","r":"El Juzgado Tercero de Distrito en Materia Penal de Toluca desechó el amparo 1395/2026, promovido por un tercero contra una supuesta orden de entregar a Fausto Isidro Meza Flores a Estados Unidos, porque no llevaba la firma del detenido, quien puede firmar desde el penal del Altiplano. La presidenta Sheinbaum dijo que la FGR y el Gabinete de Seguridad decidirán si se le extradita o se le procesa primero en México. Su audiencia inicial está fijada para el sábado 28 de noviembre.","b":"","img":"palacio","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/11/26/desechan-solicitud-de-amparo-del-chapo-isidro-porque-no-firmo-el-documento/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-la-seccion-22-inicia-un-paro-de-48-horas-en-oaxaca-en-acapulco-chocan","t":"La Sección 22 inicia un paro de 48 horas en Oaxaca; en Acapulco chocan maestros de la CETEG y el SNTE","c":"estados","f":"2026-11-27T06:49","r":"Los maestros de la Sección 22 de la CNTE exigen una mesa con el secretario de Educación, Mario Delgado; su dirigente, Yenny Aracely Pérez, denunció un déficit de más de 8 mil trabajadores y adeudos con más de 13 mil escuelas. Durante el paro bloquearon casetas, las instalaciones de Pemex en Santa María El Tule y cruceros de la capital. En Acapulco, la CETEG bloqueó la Costera para impedir una asamblea de la Sección 14 del SNTE y hubo enfrentamientos; se acordó una reunión el 7 de diciembre con autoridades laborales y Gobernación.","b":"","img":"carretera","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/11/27/estados/032n3est"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-jalisco-detienen-a-cuatro-por-contratar-seguros-de-vida-a-nombre-de-pe","t":"Jalisco: detienen a cuatro por contratar seguros de vida a nombre de personas pobres y luego asesinarlas","c":"seguridad","f":"2026-11-27T06:48","r":"La Fiscalía de Jalisco detuvo a Jorge Luis \"N\", Carlos Alonso \"N\", Pasiano \"N\" y Regina Jazmín \"N\", acusados de homicidio doloso y fraude. En cateos del 23 de noviembre en Zapopan y El Arenal se aseguraron 17 vehículos, un cheque por más de 10 millones de pesos, más de 2 millones en efectivo y pólizas de seguro. Se investigan cuatro casos, tres en Jalisco y uno en Sinaloa; un juez de Tequila definirá este viernes su situación jurídica.","b":"","img":"jalisco","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/reclutaban-a-gente-de-escasos-recursos-contrataban-seguros-a-su-nombre-y-luego-los-asesinaban-asi-operaba-la-celula-desarticulada-en-jalisco/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-sonora-rumbo-a-2027-colosio-se-registra-por-mc-y-morena-presenta-a-lor","t":"Sonora rumbo a 2027: Colosio se registra por MC y Morena presenta a Lorenia Valles como precandidata única","c":"estados","f":"2026-11-27T06:47","r":"El senador con licencia Luis Donaldo Colosio Riojas se registró como precandidato de Movimiento Ciudadano a la gubernatura de Sonora, acompañado por Dante Delgado y Jorge Álvarez Máynez, y aseguró que no busca dividir el voto. Horas después, Morena presentó a la senadora con licencia Lorenia Valles Sampedro como su precandidata única. La precampaña irá del 2 de diciembre de 2026 al 10 de enero de 2027.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/27/morena-responde-a-movimiento-ciudadano-presenta-a-lorenia-valles-como-precandidata-unica-en-sonora/"],["La Jornada","https://www.jornada.com.mx/2026/11/27/estados/031n4est"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-ataque-armado-en-una-cerrajeria-de-mazatlan-deja-cuatro-muertos","t":"Ataque armado en una cerrajería de Mazatlán deja cuatro muertos","c":"seguridad","f":"2026-11-27T06:46","r":"La noche del jueves, hombres armados entraron a una cerrajería en las calles Agustín Melgar y Constitución, en la colonia Benito Juárez de Mazatlán, y dispararon contra quienes estaban dentro. Dos hombres murieron en el lugar y otros dos durante su traslado al hospital. No se informó de detenidos.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Quadratín","https://mexico.quadratin.com.mx/atentado-en-cerrajeria-de-mazatlan-deja-4-muertos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-el-congreso-del-edomex-aprueba-exigir-nacionalidad-mexicana-unica-para","t":"El Congreso del Edomex aprueba exigir nacionalidad mexicana única para ser gobernador desde 2029","c":"estados","f":"2026-11-27T06:45","r":"Con 56 votos a favor y 17 en contra, el Congreso mexiquense aprobó en lo general una reforma constitucional que pide poseer únicamente la nacionalidad mexicana para aspirar a la gubernatura a partir de la elección de 2029; quien tenga otra deberá renunciar a ella antes de registrarse. También se exige no estar inscrito en el Registro Nacional de Obligaciones Alimentarias. La reforma pasa ahora a los 125 ayuntamientos.","b":"","img":"palacio","foto":"","cred":"","src":[["La Jornada Estado de México","https://lajornadaestadodemexico.com/congreso-edomex-requisito-de-nacionalidad-unica-para-aspirar-a-la-gubernatura/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-iran-afirma-que-hizo-disparos-de-advertencia-contra-un-caza-de-eu-en-e","t":"Irán afirma que hizo disparos de advertencia contra un caza de EU en el estrecho de Ormuz","c":"internacional","f":"2026-11-27T06:44","r":"La Guardia Revolucionaria aseguró que su defensa aérea disparó advertencias contra un caza estadounidense cerca de la isla de Hengam, que según su versión escoltaba \"embarcaciones infractoras\" y salió del espacio aéreo iraní tras una maniobra brusca. Teherán calificó su espacio aéreo como \"línea roja\". Las fuerzas de Estados Unidos no han comentado el supuesto incidente.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Menorca.info / Europa Press","https://www.menorca.info/actualidad/internacional/2026/11/27/2758799/iran-asegura-haber-realizado-disparos-advertencias-contra-eeuu-estrecho-ormuz.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-zelenski-alerta-que-rusia-prepara-un-nuevo-ataque-masivo-contra-la-red","t":"Zelenski alerta que Rusia prepara un nuevo ataque masivo contra la red eléctrica de Ucrania","c":"internacional","f":"2026-11-27T06:43","r":"El presidente ucraniano dijo que, según su inteligencia, Rusia completa los preparativos para golpear la infraestructura energética, logística y servicios críticos antes del invierno, y pidió más interceptores Patriot. Jared Kushner, enviado de Estados Unidos, afirmó en un podcast que Putin aceptó no usar armas nucleares y que las negociaciones están en un punto muerto por el tema territorial. Moscú dijo haber interceptado 343 drones ucranianos sobre 15 regiones.","b":"","img":"ultimahora","foto":"","cred":"","src":[["News4JAX / AP","https://www.news4jax.com/news/2026/11/26/zelenskyy-warns-of-imminent-major-russian-attack-on-ukraines-power-grid/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-pobladores-de-milpa-alta-frenan-por-sexta-vez-un-desalojo-en-villa-mil","t":"Pobladores de Milpa Alta frenan por sexta vez un desalojo en Villa Milpa Alta","c":"cdmx","f":"2026-11-27T06:42","r":"Decenas de vecinos levantaron barricadas, tocaron campanas y lanzaron cohetones hasta la madrugada para impedir el desalojo de ocho integrantes de la familia Villanueva de un predio de 700 metros cuadrados en la avenida México. La Secretaría de Seguridad Ciudadana informó que envió 250 elementos como resguardo perimetral; los pobladores hablan de mil policías. La diligencia se suspendió por falta de condiciones.","b":"","img":"zocalo","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/11/27/capital/033n2cap"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-cuartos-de-final-cruz-azul-golea-4-0-al-leon-y-pachuca-remonta-2-1-a-c","t":"Cuartos de final: Cruz Azul golea 4-0 al León y Pachuca remonta 2-1 a Chivas en la ida","c":"deportes","f":"2026-11-27T06:41","r":"Cruz Azul venció 4-0 al León con dos goles de José Paradela (8' y 66'), uno de Nicolás Ibáñez (30') y otro de Gabriel Fernández (73'); la vuelta será el domingo en el Estadio Azteca. En el Estadio Hidalgo, Chivas se adelantó con un autogol de Eduardo Dos Santos, pero Oussama Idrissi anotó al 48' y en tiempo agregado para el 2-1 de Pachuca; Idrissi fue expulsado por doble amarilla. La vuelta se jugará el domingo en casa de Chivas.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/espana/agencias/2026/11/27/el-campeon-cruz-azul-golea-al-leon-en-juego-de-ida-de-cuartos-de-final/"],["La Silla Rota","https://lasillarota.com/deportes/2026/11/26/pachuca-remonto-ante-chivas-con-doblete-de-idrissi-en-la-ida-539166.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-27-espana-cierra-la-campana-de-las-elecciones-generales-del-domingo-con-e","t":"España cierra la campaña de las elecciones generales del domingo con el PP al frente de los sondeos","c":"internacional","f":"2026-11-27T06:40","r":"Los partidos españoles cierran este viernes la campaña rumbo a las elecciones generales del domingo 29 de noviembre, en las que pueden votar 38.8 millones de personas. El PP de Alberto Núñez Feijóo encabeza las encuestas pero no alcanzaría la mayoría absoluta y podría necesitar a Vox. Pedro Sánchez adelantó los comicios después de que el Congreso rechazara un paquete sobre vivienda y desahucios.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Primicias","https://www.primicias.ec/internacional/elecciones-espana-29n-cierre-campana-pedro-sanchez-feijoo-abascal-138109/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-sheinbaum-envia-al-senado-una-reforma-de-justicia-familiar-divorcio-en","t":"Sheinbaum envía al Senado una reforma de justicia familiar: divorcio en una audiencia y protección en 24 horas ante violencia vicaria","c":"nacional","f":"2026-11-26T18:35","r":"La presidenta Claudia Sheinbaum anunció que este jueves remitirá al Senado una reforma al Código Nacional de Procedimientos Civiles y Familiares, presentada en la mañanera por Arturo Zaldívar y la secretaria de las Mujeres, Laura Itzel Castillo. Plantea divorcios en una sola audiencia, pensión alimenticia provisional desde que se admite la demanda y que el juez pueda consultar al SAT y a los bancos para calcularla. En casos de violencia vicaria prevé protección en 24 horas, suspensión de convivencias y restitución de hijos sin conciliación con el agresor. Para la adopción propone un juicio especial por abandono con audiencia única en 25 días; entre 25 mil y 35 mil niñas y niños viven en centros de asistencia. Según Zaldívar, en 2024 los tribunales locales recibieron 905,504 asuntos familiares.","b":"","img":"senado","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"],["El Financiero","https://elfinanciero.com.mx/nacional/2026/11/26/claudia-sheinbaum-mananera-temas-hoy-26-de-noviembre-de-2026-en-vivo"]],"dest":true,"a":"Redacción"},{"id":"2026-11-26-el-peso-hila-siete-caidas-y-cierra-en-19-72-por-dolar-banxico-asegura","t":"El peso hila siete caídas y cierra en 19.72 por dólar; Banxico asegura que el mercado está ordenado","c":"economia","f":"2026-11-26T18:34","r":"El tipo de cambio cerró este jueves en 19.7214 pesos por dólar con datos de Banxico, 12.66 centavos (0.65%) más que el miércoles; es la séptima sesión seguida de pérdidas y el nivel más débil del peso desde abril de 2025. El FIX quedó en 19.7203 y en ventanilla Banamex vendió el dólar en 20.20 pesos. Banco Base calcula una depreciación acumulada de 6.37% en la racha, que atribuye al desarme de posiciones de carry trade. La gobernadora Victoria Rodríguez Ceja dijo que el mercado cambiario se ha mantenido ordenado y que Banxico no tiene un nivel objetivo para la moneda.","b":"","img":"bolsa","foto":"","cred":"","src":[["Palco Noticias","https://www.palcoquintanarroense.com.mx/tipo-de-cambio-peso-dolar-bmv-cierre-26-noviembre-2026/"],["Infobae","https://www.infobae.com/mexico/2026/11/26/dolar-hoy-en-mexico-cotizacion-de-cierre-del-26-de-noviembre/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-26-banxico-eleva-a-1-9-su-pronostico-de-crecimiento-para-2026-y-preve-lle","t":"Banxico eleva a 1.9% su pronóstico de crecimiento para 2026 y prevé llegar a la meta de inflación al cierre de 2027","c":"economia","f":"2026-11-26T18:33","r":"En su informe trimestral de julio a septiembre, el Banco de México subió su estimación de crecimiento del PIB para 2026 de 1.5% a 1.9%, con un rango de 1.7% a 2.1%, por un desempeño del tercer trimestre mejor al previsto. Para 2027 mantuvo 2.0% y para 2028 anticipa 2.5%. Elevó a 3.7% su previsión de inflación para el cuarto trimestre de 2026 y reiteró que espera alcanzar la meta de 3% al cierre de 2027. El subgobernador Gabriel Cuadra dijo que el repunte de la inflación a 3.96% en la primera quincena de noviembre ya estaba contemplado; la tasa de interés está en 6.25%.","b":"","img":"palacio","foto":"","cred":"","src":[["Expansión","https://expansion.mx/economia/2026/11/26/banxico-expectativa-pib-economia-2026-2027"],["La Política Online","https://www.lapoliticaonline.com/mexico/economia-mx/banxico-defiende-su-recorte-de-tasas-descarta-riesgos-por-la-depreciacion-del-peso/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-26-sheinbaum-califica-de-injerencia-la-linea-de-la-dea-para-denunciar-a-p","t":"Sheinbaum califica de injerencia la línea de la DEA para denunciar a políticos y reclama 54 extradiciones sin respuesta de EU","c":"politica","f":"2026-11-26T18:32","r":"La presidenta Claudia Sheinbaum consideró una injerencia que la DEA abriera canales de WhatsApp y Signal para recibir denuncias sobre funcionarios mexicanos ligados al Cártel de Sinaloa, y dijo que esa agencia \"tiene mucho que hacer en su país\". Afirmó que México tiene alrededor de 54 solicitudes de extradición a Estados Unidos sin respuesta, que no extraditaría sin reciprocidad y citó el caso de Inés Gómez Mont, a quien EU no entregó a México. Sobre Fausto Isidro Meza, \"El Chapo Isidro\", detenido recientemente, señaló que la FGR y el gabinete de seguridad evaluarán si se le envía a Estados Unidos.","b":"","img":"palacio","foto":"","cred":"","src":[["El Financiero","https://elfinanciero.com.mx/nacional/2026/11/26/claudia-sheinbaum-mananera-temas-hoy-26-de-noviembre-de-2026-en-vivo"],["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-26-capturan-en-tamazula-durango-a-el-chapo-felix-operador-ligado-a-los-ma","t":"Capturan en Tamazula, Durango, a \"El Chapo Félix\", operador ligado a Los Mayos, y a otras tres personas","c":"seguridad","f":"2026-11-26T18:31","r":"El Gabinete de Seguridad informó la detención de Fernando \"N\", alias \"El Chapo Félix\", señalado como operador de la célula \"Fuerzas Especiales Zambada\" de la facción de Los Mayos del Cártel de Sinaloa, en el poblado de Cupia, municipio de Tamazula, Durango. Con él fueron detenidos Javier \"N\", Marco \"N\" y un menor de edad. En el operativo de Semar, con apoyo de un helicóptero, y la SSPC se aseguraron cuatro armas largas, ocho cargadores, 260 cartuchos y seis chalecos antibalas. Los detenidos quedaron a disposición del Ministerio Público.","b":"","img":"ultimahora","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4910605/el-chapo-felix-operador-de-celula-ligada-a-los-mayos-cae-con-otros-3-en-durango/"],["Infobae","https://www.infobae.com/mexico/2026/11/26/debilitan-a-los-mayos-con-un-decomiso-de-mas-de-14-millones-de-pesos-de-droga-en-mexicali-hay-un-detenido/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-sheinbaum-pide-a-la-fgr-investigar-al-exfiscal-de-chihuahua-guillermo","t":"Sheinbaum pide a la FGR investigar al exfiscal de Chihuahua Guillermo Zuany por presuntos vínculos con recursos del crimen","c":"estados","f":"2026-11-26T18:30","r":"La presidenta Claudia Sheinbaum pidió a la Fiscalía General de la República investigar los señalamientos contra el exfiscal de Chihuahua, Guillermo Zuany, sobre el presunto manejo de recursos del crimen organizado. Según la mandataria, un exvicefiscal fue quien estableció la relación entre la Fiscalía estatal y agentes de la CIA que operaban en territorio nacional sin autorización del gobierno federal.","b":"","img":"chihuahua","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-mexico-pide-coordinacion-con-eu-por-restos-de-cohetes-de-spacex-en-sus","t":"México pide coordinación con EU por restos de cohetes de SpaceX en sus aguas; Profepa evaluará sanciones","c":"nacional","f":"2026-11-26T18:29","r":"Tras una reunión con la Embajada de Estados Unidos, la presidenta Claudia Sheinbaum pidió mayor coordinación entre las autoridades aeronáuticas de México y de Estados Unidos para establecer un permiso de uso del espacio aéreo mexicano en los lanzamientos de SpaceX, saber con qué frecuencia ocurrirán y, si es necesario, reubicar la zona de lanzamiento. Indicó que la Profepa determinará posibles sanciones contra la empresa de Elon Musk por los restos que han caído en aguas mexicanas.","b":"","img":"texas","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"],["El Financiero","https://elfinanciero.com.mx/nacional/2026/11/26/claudia-sheinbaum-mananera-temas-hoy-26-de-noviembre-de-2026-en-vivo"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-sheinbaum-ofrece-apoyo-a-la-escritora-ximena-santaolalla-para-presenta","t":"Sheinbaum ofrece apoyo a la escritora Ximena Santaolalla para presentar denuncia por abuso sexual en su infancia","c":"nacional","f":"2026-11-26T18:28","r":"La escritora Ximena Santaolalla denunció públicamente que su padrastro, el empresario Francisco Aguirre, dueño de Grupo Radio Centro, abusó sexualmente de ella durante su infancia. La presidenta Claudia Sheinbaum dijo que le envió un mensaje de solidaridad y le ofreció el apoyo del gobierno federal para presentar la denuncia formal, que espera se presente.","b":"","img":"palacio","foto":"","cred":"","src":[["El Financiero","https://elfinanciero.com.mx/nacional/2026/11/26/claudia-sheinbaum-mananera-temas-hoy-26-de-noviembre-de-2026-en-vivo"],["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-sheinbaum-responde-a-salinas-pliego-por-su-llamado-a-un-boicot-fiscal","t":"Sheinbaum responde a Salinas Pliego por su llamado a un boicot fiscal: pagar impuestos es una obligación","c":"politica","f":"2026-11-26T18:27","r":"Ante el llamado del empresario Ricardo Salinas Pliego a dejar de pagar impuestos, la presidenta Claudia Sheinbaum afirmó que contribuir es una obligación y que el empresario está \"muy aislado\". Aseguró que la recaudación fiscal creció 2% en 2026 frente a 2025.","b":"","img":"palacio","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-si-el-pan-no-quiere-participar-en-2027-que-no-participen-responde-shei","t":"Si el PAN no quiere participar en 2027, \"que no participen\", responde Sheinbaum","c":"politica","f":"2026-11-26T18:26","r":"Sobre la advertencia del PAN de no participar en las elecciones de 2027, la presidenta Claudia Sheinbaum dijo que es una decisión de ese partido y sugirió que su dirigencia tiene dudas sobre cuántos votos podría obtener. En el contexto de la crisis del INE, la Cámara Nacional de la Industria de Artes Gráficas envió una carta en la que denuncia que intermediarios sin planta ni trabajadores han desplazado a fabricantes en las compras públicas, y pidió una investigación.","b":"","img":"ine","foto":"","cred":"","src":[["El Financiero","https://elfinanciero.com.mx/nacional/2026/11/26/claudia-sheinbaum-mananera-temas-hoy-26-de-noviembre-de-2026-en-vivo"],["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-el-ejercito-asegura-50-kilos-de-metanfetamina-en-mexicali-hay-un-deten","t":"El Ejército asegura 50 kilos de metanfetamina en Mexicali; hay un detenido ligado a Los Mayos","c":"seguridad","f":"2026-11-26T18:25","r":"Elementos del Ejército aseguraron alrededor de 50 kilogramos de metanfetamina, un vehículo y detuvieron a una persona en la colonia Jardines del Lago, en Mexicali, Baja California, el 25 de noviembre. El Gabinete de Seguridad estimó una afectación de 14.1 millones de pesos a Los Mayos. Participaron la Fuerza Estatal de Seguridad Ciudadana y la Policía Municipal; el caso quedó en manos de la FGR en Mexicali.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/26/debilitan-a-los-mayos-con-un-decomiso-de-mas-de-14-millones-de-pesos-de-droga-en-mexicali-hay-un-detenido/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-jalisco-detienen-a-11-en-jilotlan-de-los-dolores-con-43-armas-en-ajiji","t":"Jalisco: detienen a 11 en Jilotlán de los Dolores con 43 armas; en Ajijic hallan fusiles Barrett y granadas","c":"estados","f":"2026-11-26T18:24","r":"El Gabinete de Seguridad reportó que en El Limoncito, municipio de Jilotlán de los Dolores, fueron detenidas 11 personas y se aseguraron 43 armas, entre ellas un fusil Barrett y dos ametralladoras, además de cuatro vehículos. En Ajijic, municipio de Chapala, se aseguraron dos fusiles Barrett, cuatro armas largas, 73 cargadores, 1,507 cartuchos y 10 granadas. En la misma jornada se inhabilitó un laboratorio de drogas sintéticas en Ixtlán del Río, Nayarit, con 1,400 kilos de precursores químicos.","b":"","img":"jalisco","foto":"","cred":"","src":[["Argon México","https://argonmexico.com/2026/11/26/operativos-de-seguridad-dejan-12-detenidos-y-decomiso-de-arsenal-en-cinco-estados/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-madres-y-padres-de-los-43-de-ayotzinapa-marchan-del-angel-de-la-indepe","t":"Madres y padres de los 43 de Ayotzinapa marchan del Ángel de la Independencia al Hemiciclo a Juárez","c":"cdmx","f":"2026-11-26T18:23","r":"Familiares de los 43 normalistas de Ayotzinapa realizaron este jueves una marcha del Ángel de la Independencia al Hemiciclo a Juárez a partir de las 16:00 horas. La SSC de la Ciudad de México reportó además ocho concentraciones y una marcha del Movimiento Plural de Maquileros hacia la Secretaría de Economía, con posibles afectaciones viales en Cuauhtémoc y Miguel Hidalgo.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/26/en-vivo-bloqueos-en-carreteras-accidentes-y-manifestaciones-26-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-el-ipn-elegira-por-voto-a-su-director-80-aspirantes-inscritos-y-5-241","t":"El IPN elegirá por voto a su director: 80 aspirantes inscritos y 5,241 votos en el primer día","c":"nacional","f":"2026-11-26T18:22","r":"Ochenta académicos se registraron como aspirantes a la dirección general del Instituto Politécnico Nacional, y en el primer día de votación se emitieron 5,241 votos, informó la presidenta Claudia Sheinbaum. De la consulta saldrán dos ternas, una de hombres y otra de mujeres. Aunque la designación corresponde a la presidenta, se decidió que por primera vez se haga mediante votación.","b":"","img":"palacio","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/la-mananera-de-claudia-sheinbaum-26-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-la-bolsa-mexicana-cae-1-43-por-toma-de-utilidades-tras-el-repunte-del","t":"La Bolsa mexicana cae 1.43% por toma de utilidades tras el repunte del miércoles","c":"economia","f":"2026-11-26T18:21","r":"El S&P/BMV IPC retrocedió 1.43% y cerró en 70,353.18 puntos, luego de un repunte de más de 3% el miércoles; analistas lo atribuyeron a toma de utilidades y un ajuste técnico. Entre las emisoras, Alpek bajó 5.79% y GCC subió 4.47%. Wall Street permaneció cerrado por el Día de Acción de Gracias y el viernes operará con horario reducido.","b":"","img":"bolsa","foto":"","cred":"","src":[["Palco Noticias","https://www.palcoquintanarroense.com.mx/tipo-de-cambio-peso-dolar-bmv-cierre-26-noviembre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-el-brent-sube-a-96-53-dolares-por-ataques-en-el-golfo-persico-la-opep","t":"El Brent sube a 96.53 dólares por ataques en el Golfo Pérsico; la OPEP+ se reúne el domingo","c":"economia","f":"2026-11-26T18:20","r":"El crudo Brent para enero avanzó 2.02% a 96.53 dólares por barril y el WTI subió 1.42% a 84.87 dólares. El alza se atribuyó a un ataque de los hutíes contra la refinería saudí de Ras Tanura y a un reporte del gobierno iraní sobre al menos dos buques petroleros alcanzados por misiles en el estrecho de Ormuz. La OPEP+ tiene reunión el 29 de noviembre.","b":"","img":"pemex","foto":"","cred":"","src":[["Palco Noticias","https://www.palcoquintanarroense.com.mx/tipo-de-cambio-peso-dolar-bmv-cierre-26-noviembre-2026/"],["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/26/temas-del-dia-de-efe-internacional-del-jueves-26-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-el-espanol-pablo-hernandez-de-cos-presidira-el-banco-central-europeo-e","t":"El español Pablo Hernández de Cos presidirá el Banco Central Europeo en lugar de Christine Lagarde","c":"internacional","f":"2026-11-26T18:19","r":"Pablo Hernández de Cos, presidente del Banco de Pagos Internacionales y exgobernador del Banco de España, encabezará el Banco Central Europeo a partir del 8 de febrero de 2027. Sustituirá a Christine Lagarde, que deja el cargo nueve meses antes de terminar su mandato. Será el primer español al frente del BCE y su quinto presidente.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Euronews","https://es.euronews.com/2026/11/26/el-espanol-pablo-hernandez-de-cos-nuevo-presidente-del-banco-central-europeo"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-por-primera-vez-en-100-anos-se-pospone-el-desfile-de-accion-de-gracias","t":"Por primera vez en 100 años se pospone el desfile de Acción de Gracias de Macy's por una tormenta en Nueva York","c":"internacional","f":"2026-11-26T18:18","r":"El tradicional desfile de Macy's, que llegaba a su edición 100, se trasladó del jueves 26 al sábado 28 de noviembre por una tormenta costera con pronóstico de vientos de hasta 64 km/h y ráfagas cercanas a 105 km/h. La gobernadora Kathy Hochul declaró estado de emergencia en Nueva York, Long Island, Westchester y otros condados, y el alcalde Zohran Mamdani emitió una alerta de viaje.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/estados-unidos/2026/11/26/el-desfile-de-accion-de-gracias-de-macys-se-pospone-por-primera-vez-en-100-anos-de-historia-cuando-sera-y-donde-verlo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-toluca-saca-ventaja-de-2-0-sobre-atlas-este-jueves-juegan-pachuca-chiv","t":"Toluca saca ventaja de 2-0 sobre Atlas; este jueves juegan Pachuca-Chivas y León-Cruz Azul","c":"deportes","f":"2026-11-26T18:17","r":"En la ida de cuartos de final del Apertura 2026, Toluca venció 2-0 a Atlas en el Nemesio Diez con dos goles del brasileño Helinho, uno de ellos de penal. Este jueves se disputan Pachuca contra Chivas (19:00 h, Estadio Hidalgo) y León contra Cruz Azul (21:10 h). Las vueltas serán el sábado 28 y el domingo 29; si el marcador global termina empatado, avanza el equipo mejor ubicado en la tabla.","b":"","img":"estadio","foto":"","cred":"","src":[["Grupo Animal","https://grupoanimal.mx/deportes/liga-mx-apertura-2026-resultados-cuartos-de-final-liguilla"],["TV Azteca","https://www.tvazteca.com/aztecadeportes/liguilla-del-apertura-2026-al-momento-asi-quedan-las-llaves-de-cuartos-de-final-tras-los-primeros-partidos-de-ida-y-que-necesita-cada-equipo-para-avanzar/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-putin-saca-al-cineasta-alexandr-sokurov-del-consejo-de-derechos-humano","t":"Putin saca al cineasta Alexandr Sokúrov del Consejo de Derechos Humanos del Kremlin","c":"entretenimiento","f":"2026-11-26T18:16","r":"El presidente ruso Vladímir Putin excluyó al director Alexandr Sokúrov, ganador del León de Oro de Venecia en 2011 con \"Fausto\", del Consejo de Derechos Humanos adscrito al Kremlin, según los cambios publicados en el portal oficial del Estado. También salieron el abogado Vladimir Riajovski, Yana Vlásova y el escritor Maxim Zámshev. En enero, Sokúrov ya había sido apartado del consejo para el desarrollo del cine.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/cultura/2026/11/26/putin-expulso-del-consejo-de-derechos-humanos-del-kremlin-a-sokurov-el-cienasta-que-gano-el-leon-de-oro-de-venecia/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-sheinbaum-envia-a-san-lazaro-la-ley-del-imss-bienestar-los-estados-adh","t":"Sheinbaum envía a San Lázaro la ley del IMSS-Bienestar: los estados adheridos pagarían una aportación anual obligatoria","c":"nacional","f":"2026-11-26T06:59","r":"La presidenta remitió el 25 de noviembre a la Cámara de Diputados una iniciativa para expedir la Ley de Servicios de Salud del IMSS-Bienestar y reformar la Ley General de Salud; fue turnada a las comisiones de Salud y de Presupuesto. El organismo administraría los recursos federales de los estados que federalizaron sus servicios, y estos cubrirían una aportación anual fijada por el propio IMSS-Bienestar que, de no pagarse, podría descontarse de sus participaciones. La propuesta crea un Consejo General de Coordinación presidido por el Ejecutivo, prevé un plan de transición de al menos 10 años si un convenio termina antes de tiempo y haría que las reglas de financiamiento entren en vigor el 1 de enero de 2027. Morena busca votarla antes del 15 de diciembre; Hacienda sostiene que no crea plazas ni requiere más presupuesto.","b":"","img":"imss","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/26/imss-bienestar-tendria-una-nueva-ley-que-busca-modificar-sheinbaum-en-los-servicios-de-salud/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-26-mexico-queda-fuera-por-ahora-de-los-nuevos-aranceles-que-eu-propone-a","t":"México queda fuera, por ahora, de los nuevos aranceles que EU propone a 14 economías; la Bolsa sube 2.99%","c":"economia","f":"2026-11-26T06:58","r":"La Oficina del Representante Comercial de Estados Unidos (USTR) publicó el 25 de noviembre los resultados de su investigación por sobrecapacidad industrial bajo la Sección 301 y propuso aranceles a 14 economías, entre ellas China, la Unión Europea, Japón, Corea del Sur, India y Vietnam. México y Noruega también fueron investigados, pero quedaron sin determinación por ahora; los comentarios por escrito se recibirán hasta el 5 de enero de 2027. Jamieson Greer dijo a CNBC que ha tenido conversaciones “muy buenas” con México, centradas en el superávit comercial y el uso de insumos chinos. Tras el anuncio, el S&P/BMV IPC ganó 2.99% y cerró en 71 mil 372.25 puntos, su mayor alza desde junio, con Peñoles (+8.2%) y Grupo México (+7.13%) al frente.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión","https://expansion.mx/economia/2026/11/25/eu-propone-aranceles-14-economias-mexico-queda-fuera"],["El Financiero","https://www.elfinanciero.com.mx/economia/2026/11/26/mexico-libra-nueva-ola-de-aranceles-de-trump-hemos-tenido-buenas-conversaciones-dice-jamieson-greer/"],["El Informador","https://www.informador.mx/economia/ipc-de-la-bolsa-mexicana-gana-2.99--tras-nuevo-anuncio-de-aranceles-de-trump-20261125-0171.html"]],"dest":true,"a":"Redacción"},{"id":"2026-11-26-sheinbaum-envia-una-nota-diplomatica-a-eu-tras-la-salida-de-ines-gomez","t":"Sheinbaum envía una nota diplomática a EU tras la salida de Inés Gómez Mont hacia España","c":"politica","f":"2026-11-26T06:57","r":"De acuerdo con el Departamento de Seguridad Nacional de Estados Unidos, la exconductora aceptó una salida voluntaria y dejó el país el 23 de noviembre con destino a España; estaba detenida por razones migratorias desde el 30 de octubre. En México tiene órdenes de aprehensión por presunta delincuencia organizada y operaciones con recursos de procedencia ilícita, y el gobierno ya pidió su extradición. En la mañanera del 25 de noviembre, la presidenta cuestionó por qué se retiró la ficha roja de Interpol, pidió reciprocidad al recordar que México ha entregado a 94 personas requeridas por EU y mencionó que un implicado en el caso Ayotzinapa sigue sin ser enviado, tema que dijo haber tratado con Marco Rubio.","b":"","img":"palacio","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/25/sheinbaum-reclama-eu-por-ines-gomez-mont"]],"dest":true,"a":"Redacción"},{"id":"2026-11-26-en-el-25n-sheinbaum-pide-al-senado-aprobar-este-periodo-la-ley-general","t":"En el 25N, Sheinbaum pide al Senado aprobar este periodo la Ley General contra el Feminicidio y lanza ‘Hombres por la Transformación’","c":"nacional","f":"2026-11-26T06:56","r":"En el Día Internacional para la Eliminación de la Violencia contra la Mujer, la presidenta dijo esperar que el Senado apruebe antes de que concluya el periodo ordinario, a mediados de diciembre, la ley que envió en julio. La iniciativa, de 62 artículos, propone un tipo penal único de feminicidio en las 32 entidades, con penas de 50 a 70 años de prisión y multas de mil a dos mil UMA. El gobierno presentó además la campaña ‘Hombres por la Transformación’, con 12 compromisos contra el machismo que llegará a más de 300 planteles y más de 170 mil alumnos, y una guía de seguridad digital elaborada con Google, Meta y TikTok.","b":"","img":"palacio","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/mexico/2026/11/25/sheinbaum-espera-que-senado-apruebe-ley-para-sancionar-feminicidio-en-actual-periodo-de-sesiones/"],["El Financiero","https://elfinanciero.com.mx/nacional/2026/11/25/claudia-sheinbaum-mananera-temas-hoy-25-de-noviembre-de-2026-en-vivo"]],"dest":true,"a":"Redacción"},{"id":"2026-11-26-el-peso-suma-seis-caidas-y-cierra-en-19-59-por-dolar-su-peor-nivel-des","t":"El peso suma seis caídas y cierra en 19.59 por dólar, su peor nivel desde mayo de 2025","c":"economia","f":"2026-11-26T06:55","r":"El tipo de cambio de cierre reportado por Banxico el 25 de noviembre fue de 19.5948 pesos por dólar, una depreciación de alrededor de 0.88% frente a la sesión previa y la sexta jornada seguida de pérdidas. En ventanilla, Banamex vendió el dólar en 20.08 pesos. Analistas atribuyen el movimiento a la aversión al riesgo por la sobrevaluación de las acciones tecnológicas y de inteligencia artificial, y al desarme de posiciones de carry trade ante una menor diferencia de tasas con Estados Unidos.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/mercados/2026/11/25/peso-dolar-tipo-de-cambio-hoy-25-de-noviembre-de-2026/"],["Intolerancia Diario","https://intoleranciadiario.com/articles/finanzas/2026/11/25/1060890-dolar-cierra-en-su-nivel-mas-alto-desde-mayo-de-2025-y-toca-los-20-pesos-en-ventanilla.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-el-desempleo-sube-a-2-9-en-el-tercer-trimestre-la-informalidad-alcanza","t":"El desempleo sube a 2.9% en el tercer trimestre; la informalidad alcanza a 33.1 millones de personas","c":"economia","f":"2026-11-26T06:54","r":"La Encuesta Nacional de Ocupación y Empleo del Inegi para el tercer trimestre de 2026 registró 1.8 millones de personas desocupadas, 163 mil 476 más que en el trimestre anterior, con lo que la tasa pasó de 2.7% a 2.9%. Según Banco Base, es el nivel más alto desde el tercer trimestre de 2024. La desocupación fue de 3.0% entre mujeres y 2.8% entre hombres. Los trabajadores informales sumaron 33.1 millones, 55% de la población ocupada.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión","https://expansion.mx/economia/2026/11/25/desempleo-en-mexico-alcanza-a-1-8-millones-de-personas-se-incrementa-mas-en-las-mujeres"],["La Razón","https://www.razon.com.mx/negocios/2026/11/26/informalidad-aumenta-en-el-3er-trimestre-del-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-el-senado-pospone-a-2027-las-reformas-a-la-ley-organica-del-poder-judi","t":"El Senado pospone a 2027 las reformas a la Ley Orgánica del Poder Judicial y a la Ley de Amparo; habrá parlamento abierto","c":"politica","f":"2026-11-26T06:53","r":"El paquete de reformas secundarias impulsado por la nueva cúpula judicial no se votará en diciembre. Javier Corral, presidente de la Comisión de Justicia, explicó que el plazo constitucional permite aprobarlo hasta el 30 de julio de 2027, e Ignacio Mier propuso que comisiones de ambas cámaras trabajen un solo dictamen. El presidente de la Suprema Corte, Hugo Aguilar, dijo que la propuesta tiene cuatro ejes, entre ellos la elección judicial de 2028 y la autonomía presupuestal, e informó que 85% de los jueces aprobó su primera evaluación de desempeño.","b":"","img":"senado","foto":"","cred":"","src":[["Grupo Animal","https://grupoanimal.mx/politica/reforma-poder-judicial-senado-parlamento-abierto-2027"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-la-dea-abre-lineas-de-whatsapp-y-signal-para-denunciar-a-narcos-y-func","t":"La DEA abre líneas de WhatsApp y Signal para denunciar a narcos y funcionarios corruptos en Sinaloa","c":"seguridad","f":"2026-11-26T06:52","r":"El administrador de la DEA, Terry Cole, anunció el 25 de noviembre canales para recibir denuncias, que pueden ser anónimas, sobre integrantes de grupos designados como terroristas en Sinaloa, funcionarios que les den apoyo y sus redes de lavado de dinero. Las líneas funcionan por WhatsApp, Signal, Threema y correo electrónico, y Cole adelantó que publicaría otras para Jalisco y el CJNG. El anuncio ocurre días después de la captura de ‘El Chapo Isidro’; la fiscal Ernestina Godoy ha dicho que EU no ha presentado una solicitud formal de extradición ni pruebas contra Rubén Rocha Moya y otros señalados.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/2026/11/25/dea-publica-whatsapp-para-denunciar-a-narcos-y-funcionarios-corruptos-384371.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-militares-abaten-a-siete-presuntos-integrantes-del-cartel-de-los-reyes","t":"Militares abaten a siete presuntos integrantes del Cártel de los Reyes y detienen a 10 en los límites de Jalisco y Michoacán","c":"seguridad","f":"2026-11-26T06:51","r":"La Defensa informó que el 25 de noviembre soldados que hacían reconocimiento entre Peribán de Ramos, Michoacán, y Jilotlán de los Dolores, Jalisco, fueron atacados por una célula que buscaban, ligada a Fernando ‘N’, alias ‘El Maníaco’. En el enfrentamiento murieron siete agresores y 10 personas fueron detenidas. Se aseguraron un fusil Barrett calibre .50, una ametralladora, 33 armas de fuego, una granada y cuatro vehículos; los detenidos fueron entregados a la FGR en Zamora, como parte del Plan Michoacán.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/26/defensa-confirma-siete-criminales-abatidos-y-10-detenidos-tras-enfrentamiento-contra-celula-del-cartel-de-los-reyes/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-garcia-harfuch-entrega-104-patrullas-en-culiacan-y-asegura-que-los-ope","t":"García Harfuch entrega 104 patrullas en Culiacán y asegura que los operativos en Sinaloa serán permanentes","c":"seguridad","f":"2026-11-26T06:50","r":"Durante la visita del Gabinete de Seguridad a Culiacán, el 24 de noviembre, se entregaron 104 vehículos: 57 para la policía estatal y 47 para la municipal, como parte de un programa de más de 200 unidades que incluye blindados; Mazatlán recibirá unidades próximamente. El secretario Omar García Harfuch dijo que tienen la responsabilidad de seguir trabajando para detener a quienes generan violencia. Al acto asistieron mandos de la Defensa, Marina y Guardia Nacional y la gobernadora interina Graciela Domínguez.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/tenemos-deber-detener-violencia-entrega-vehiculos-culiacan"],["Crónica","https://www.cronica.com.mx/nacional/2026/11/24/garcia-harfuch-refuerza-seguridad-en-sinaloa-con-patrullas-y-vehiculos-blindados/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-diputados-preven-un-periodo-extraordinario-para-elegir-a-quien-presida","t":"Diputados prevén un periodo extraordinario para elegir a quien presida el INE si el Tribunal resuelve después del 15 de diciembre","c":"politica","f":"2026-11-26T06:49","r":"Raúl Bolaños Cacho Cué, presidente de la Mesa Directiva de San Lázaro, dijo que si el Tribunal Electoral resuelve la demanda del PAN después del cierre del periodo ordinario, muy probablemente habrá que convocar a sesiones extraordinarias. Morena acordó esperar el fallo. Bolaños criticó que el PAN llevara el tema a tribunales y afirmó que sigue el diálogo para integrar, con consenso de todas las fuerzas, una lista de cinco aspirantes para suceder a Guadalupe Taddei.","b":"","img":"ine","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/camara-diputados-preve-periodo-extraordinario-suplente-guadalupe-taddei-ine"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-sheinbaum-afirma-que-las-cuentas-de-ruben-rocha-moya-nunca-se-desconge","t":"Sheinbaum afirma que las cuentas de Rubén Rocha Moya “nunca se descongelaron”","c":"politica","f":"2026-11-26T06:48","r":"En la mañanera del 25 de noviembre, la presidenta explicó que el exgobernador de Sinaloa pidió a un juzgado poder cobrar su pensión, que la UIF presentó un recurso de inconformidad y que el juez le dio la razón, aunque Rocha aún puede impugnar. De acuerdo con El Financiero, un tribunal federal revocó el amparo y ordenó volver a bloquear las cuentas donde recibe tres pensiones mientras avanzan las investigaciones. Sheinbaum dijo no conocer los montos.","b":"","img":"palacio","foto":"","cred":"","src":[["El Financiero","https://elfinanciero.com.mx/nacional/2026/11/25/claudia-sheinbaum-mananera-temas-hoy-25-de-noviembre-de-2026-en-vivo"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-la-suprema-corte-atrae-el-amparo-de-padres-de-la-guarderia-abc-contra","t":"La Suprema Corte atrae el amparo de padres de la Guardería ABC contra la expropiación de inmuebles en Hermosillo","c":"nacional","f":"2026-11-26T06:47","r":"El pleno de la SCJN decidió por mayoría atraer el caso, con los votos en contra de Hugo Aguilar, Irving Espinosa, María Estela Ríos y Sara Irene Herrerías. Los padres impugnan el decreto del gobernador Alfonso Durazo para expropiar siete inmuebles y construir un espacio público con un memorial, pues sostienen que su demolición podría destruir pruebas mientras las investigaciones sobre el incendio siguen abiertas. En la misma sesión, la Corte validó que al menos 50% de los cargos de la carrera judicial sean para mujeres y firmó el Pacto Nacional por la Justicia de Género.","b":"","img":"palacio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/scjn-atrae-amparo-guarderia-abc-expropiacion-sonora"],["Infobae","https://www.infobae.com/mexico/2026/11/26/suprema-corte-firma-el-pacto-nacional-por-la-justicia-de-genero-este-25-de-noviembre-e-instala-comite-de-seguimiento/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-llega-la-primera-tormenta-invernal-preven-hasta-250-mm-de-lluvia-en-gu","t":"Llega la primera tormenta invernal: prevén hasta 250 mm de lluvia en Guerrero y Michoacán y heladas de -10 °C en Chihuahua y Durango","c":"estados","f":"2026-11-26T06:46","r":"El Servicio Meteorológico Nacional prevé que una vaguada polar ingrese desde este jueves 26 por el noroeste y oeste del país, con posible aguanieve o nieve en zonas montañosas de Jalisco, Colima y Michoacán desde la noche, y el viernes en el centro y oriente. Para el viernes 27 se esperan de 150 a 250 milímetros de lluvia en el sur de Michoacán y Guerrero, de 75 a 150 mm en Jalisco, Colima y el Estado de México, y de 50 a 75 mm en la Ciudad de México. En las sierras de Chihuahua y Durango las temperaturas bajarían a entre -10 y -5 °C del viernes al domingo, y en el Istmo de Tehuantepec habría rachas de 90 a 100 km/h.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/26/alerta-por-primera-tormenta-invernal-en-mexico-estos-son-los-estados-con-lluvias-heladas-y-posible-aguanieve/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-manolo-jimenez-rinde-su-tercer-informe-en-muzquiz-y-anuncia-siete-obra","t":"Manolo Jiménez rinde su tercer informe en Múzquiz y anuncia siete obras por más de 14 mil millones de pesos en Coahuila","c":"estados","f":"2026-11-26T06:45","r":"El gobernador de Coahuila presentó su informe el 25 de noviembre en Múzquiz y anunció siete obras prioritarias de carreteras, libramientos, puentes y vialidades por más de 14 mil millones de pesos, que deberán concluir en 2029. Dijo que en tres años se invirtieron casi 6 mil millones de pesos en infraestructura y más de 12 mil millones en seguridad. Asistieron la gobernadora de Aguascalientes, Tere Jiménez, y el dirigente nacional del PRI, Alejandro Moreno.","b":"","img":"carretera","foto":"","cred":"","src":[["Superchannel 12","https://superchannel12.com/coahuila/manolo-jimenez-va-por-mas-seguridad-y-14-mmdp-en-megaobras-711711"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-brugada-anuncia-que-la-cdmx-asumira-los-centros-de-justicia-para-las-m","t":"Brugada anuncia que la CDMX asumirá los Centros de Justicia para las Mujeres y construirá cuatro más en 2027","c":"cdmx","f":"2026-11-26T06:44","r":"La jefa de Gobierno informó que a los cuatro centros que ya operan se sumarán en 2027 otros en Cuauhtémoc, Gustavo A. Madero, Tláhuac y Álvaro Obregón, con la meta de tener al menos uno por alcaldía. Funcionarán las 24 horas con Ministerio Público y jueces en el mismo lugar, y la fiscal Bertha Alcalde dijo que se añadirá la atención de delitos sexuales. Además, hijas e hijos de víctimas de feminicidio recibirán un apoyo de 2 mil 555 pesos mensuales.","b":"","img":"zocalo","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/cdmx/2026/11/25/gobierno-de-cdmx-asumira-los-centros-de-justicia-para-las-mujeres-384360.html"],["La Razón","https://www.razon.com.mx/ciudad/2026/11/26/anuncia-brugada-4-centros-de-justicia-para-las-mujeres/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-trump-y-rutte-piden-a-rusia-no-ampliar-la-guerra-zelenski-espera-fecha","t":"Trump y Rutte piden a Rusia no ampliar la guerra; Zelenski espera fecha para una ronda de paz con participación europea","c":"internacional","f":"2026-11-26T06:43","r":"Donald Trump y el secretario general de la OTAN, Mark Rutte, se reunieron el 25 de noviembre en Mar-a-Lago y, en una declaración conjunta, subrayaron la importancia de que Rusia evite acciones que amplíen la guerra y pidieron una solución pacífica lo antes posible; también hablaron de Irán y del gasto en defensa. Ese día, Volodímir Zelenski dijo que Kiev espera que EU fije la fecha de la próxima reunión, que a su juicio debe incluir a los europeos. El asesor del Kremlin Yuri Ushakov afirmó que no hay decisión sobre esa participación.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Kyiv Post","https://www.kyivpost.com/post/91224"],["aNews","https://www.anews.com.tr/world/2026/11/25/zelenskyy-says-ukraine-waiting-for-us-to-set-date-for-new-round-of-peace-talks-with-russia"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-cuartos-de-final-monterrey-aguanta-con-diez-y-empata-0-0-con-america-t","t":"Cuartos de final: Monterrey aguanta con diez y empata 0-0 con América; Toluca vence 2-0 a Atlas","c":"deportes","f":"2026-11-26T06:42","r":"En la ida de cuartos del Apertura 2026, Rayados jugó con un hombre menos desde el minuto 10 por la expulsión de Ricardo Chávez y el portero Luis Cárdenas sostuvo el empate sin goles; la vuelta será en el Estadio Azteca, donde a América le basta otro empate por su mejor posición en la tabla. En el Nemesio Díez, Toluca superó 2-0 a Atlas con dos goles de Helinho, uno de ellos de penal. La vuelta entre Atlas y Toluca será el sábado 28 en el Estadio Jalisco.","b":"","img":"estadio","foto":"","cred":"","src":[["Claro Sports","https://www.clarosports.com/futbol/liga-mx/el-mochis-mantiene-vivo-a-monterrey-america-perdona-con-uno-mas-y-todo-se-definira-en-el-azteca/"],["En Juego Deportes","https://www.enjuegodeportes.com/liga-mx/toluca-vence-2-0-atlas-ida-cuartos-de-final-liguilla-apertura-2026-helinho/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-el-tas-devuelve-a-senegal-el-titulo-de-la-copa-africana-marruecos-acud","t":"El TAS devuelve a Senegal el título de la Copa Africana; Marruecos acudirá al Tribunal Federal suizo","c":"deportes","f":"2026-11-26T06:41","r":"El Tribunal de Arbitraje Deportivo anuló la decisión de la CAF que había dado a Marruecos la victoria 3-0 por la mesa y restituyó el triunfo 1-0 de Senegal en la final del 18 de enero en Rabat. Senegal había abandonado el campo durante 14 minutos tras un penal en contra; el TAS concluyó que reanudar el juego era facultad exclusiva del árbitro. La CAF dijo que acatará el fallo, mientras la federación marroquí anunció que lo impugnará ante el Tribunal Federal Supremo de Suiza.","b":"","img":"estadio","foto":"","cred":"","src":[["The National","https://www.thenationalnews.com/sport/football/2026/11/25/senegal-vs-morocco-afcon-verdict-cas-ruling-explained-and-what-happens-next/"],["Al Jazeera","https://aljazeera.com/sports/2026/11/25/senegal-deny-moroccos-allegations-of-contact-with-cas-amid-afcon-row"]],"dest":false,"a":"Redacción"},{"id":"2026-11-26-jennifer-barreto-de-puerto-rico-gana-miss-universo-2026-la-mexicana-ma","t":"Jennifer Barreto, de Puerto Rico, gana Miss Universo 2026; la mexicana María Vargas queda fuera del Top 12","c":"entretenimiento","f":"2026-11-26T06:40","r":"La puertorriqueña Jennifer Barreto, trabajadora social de 27 años, ganó la 75ª edición del certamen celebrada en San Juan; es la sexta corona para Puerto Rico y la primera ganadora casada y madre desde que se eliminó esa restricción. La dominicana Melissa Núñez fue primera finalista y la venezolana Clara Vegas, segunda. La representante de México, María Vargas, avanzó al grupo de 30 semifinalistas, pero no entró al Top 12; la mexicana Fátima Bosch entregó la corona.","b":"","img":"estudio","foto":"","cred":"","src":[["ABC7","https://abc7.com/story/miss-universe-jennifer-barreto-puerto-rico-crowned-winner-another-turbulent-year-worlds-biggest-pageant/20078920/"],["Infobae","https://www.infobae.com/mexico/2026/11/25/en-que-lugar-quedo-la-mexicana-maria-vargas-en-miss-universo-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-la-inflacion-sube-a-3-96-anual-en-la-primera-quincena-de-noviembre-por","t":"La inflación sube a 3.96% anual en la primera quincena de noviembre por el fin del subsidio eléctrico de verano","c":"economia","f":"2026-11-24T06:59","r":"Los precios al consumidor aumentaron 0.54% en la primera mitad de noviembre y la tasa anual llegó a 3.96%, frente a 3.61% un año antes, informó el Inegi. El índice subyacente bajó 0.10% en la quincena, mientras el no subyacente subió 2.72%, empujado por frutas y verduras (5.50%) y por energéticos y tarifas del gobierno (2.35%). La mayor presión vino de la electricidad, tras concluir el subsidio de verano en 11 ciudades, además del jitomate, el tomate verde y el huevo.","b":"","img":"bolsa","foto":"","cred":"","src":[["La Silla Rota","https://lasillarota.com/negocios/2026/11/24/inflacion-sube-a-396-anual-durante-la-primera-quincena-de-noviembre-538689.html"]],"dest":true,"a":"Redacción"},{"id":"2026-11-24-la-fgr-tiene-15-carpetas-abiertas-y-ubica-unos-40-domicilios-ligados-a","t":"La FGR tiene 15 carpetas abiertas y ubica unos 40 domicilios ligados a la corrupción en el INE","c":"politica","f":"2026-11-24T06:58","r":"La fiscal general Ernestina Godoy se reunió en privado con la Junta de Coordinación Política de la Cámara de Diputados y después informó que la FGR mantiene 15 carpetas de investigación y tiene identificados alrededor de 40 domicilios donde podría realizar diligencias. Precisó que la indagatoria es general y no solo contra la expresidenta del INE Guadalupe Taddei y el proveedor José Alfredo Hernández Casillas, quienes, dijo, estarían en México, aunque aún no hay orden de aprehensión. Añadió que los videos de Taddei con el contratista no bastan como prueba y se analiza su autenticidad.","b":"","img":"ine","foto":"","cred":"","src":[["La Prensa de Coahuila","https://laprensadecoahuila.com.mx/2026/11/23/ubica-fgr-cuarenta-domicilios-ligados-a-corrupcion-en-ine/"],["CódigoQro / El Economista","https://codigoqro.mx/nota/region-4/2026/11/23/la-fgr-tiene-abiertas-15-carpetas-de-investigacion-por-caso-ine"]],"dest":true,"a":"Redacción"},{"id":"2026-11-24-sheinbaum-niega-que-hubo-invasion-en-el-operativo-de-guasave-eu-solo-a","t":"Sheinbaum niega que hubo invasión en el operativo de Guasave: EU solo aportó equipo de inteligencia a petición de México","c":"seguridad","f":"2026-11-24T06:57","r":"La presidenta Claudia Sheinbaum afirmó que la captura de Fausto Isidro Meza Flores, ‘El Chapo Isidro’, fue planeada y ejecutada por fuerzas mexicanas y que a Estados Unidos solo se le pidió equipo especializado de inteligencia. Reconoció que Washington buscaba una participación militar directa y que México la rechazó. El general Ricardo Trevilla sostuvo que no se violó ninguna ley; la Secretaría de Gobernación apoyará a las familias de los cuatro militares muertos en la Operación Centella a través de la CEAV.","b":"","img":"palacio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/24/mexico-niega-invasion-en-operativo-de-guasave-eu-coopero-a-peticion/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-24-la-ip-rechaza-un-alza-de-dos-digitos-al-salario-minimo-para-2027-no-ag","t":"La IP rechaza un alza de dos dígitos al salario mínimo para 2027: “No aguantamos”, advierte Concamin","c":"economia","f":"2026-11-24T06:56","r":"En la Reunión Anual de Industriales, el presidente de Concamin, Alejandro Malagón, rechazó el aumento de 15% que propuso el sector obrero en la Conasami y advirtió que podría provocar recortes de personal o cierres, sobre todo en micro y pequeñas empresas. José Medina Mora, del Consejo Coordinador Empresarial, dijo que ese incremento generaría pérdida de empleos y ubicó la propuesta del sector privado en alrededor de 6%.","b":"","img":"palacio","foto":"","cred":"","src":[["La Crónica","https://www.cronica.com.mx/nacional/2026/11/23/advierte-ip-aumento-al-salario-minimo-de-dos-digitos-provocara-recortes-y-cierre-de-empresas/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-24-sheinbaum-en-el-aniversario-de-la-independencia-en-la-mar-la-cooperaci","t":"Sheinbaum, en el aniversario de la Independencia en la Mar: “La cooperación no significa subordinación”","c":"nacional","f":"2026-11-24T06:55","r":"Durante la ceremonia por el 201 aniversario de la Consolidación de la Independencia en la Mar, la presidenta Sheinbaum dijo que México tiene derecho a decidir su propio modelo de desarrollo y que no renunciará a su soberanía al cooperar con otros países. En el acto, el secretario de Marina, almirante Raymundo Pedro Morales Ángeles, informó que la Armada construye siete Patrullas Oceánicas Clase Yucatán, que estarán listas en 2030, además de 12 patrullas costeras y dos buques multipropósito.","b":"","img":"palacio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/23/sheinbaum-afirma-que-mexico-no-renunciara-a-su-soberania-ante-intereses-extranjeros/"],["Excélsior","https://www.excelsior.com.mx/nacional/marina-buques-clase-yucatan-inteligencia-artificial-soberania-aguas"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-monreal-entrega-al-tribunal-electoral-su-informe-por-la-demanda-del-pa","t":"Monreal entrega al Tribunal Electoral su informe por la demanda del PAN: “No hay omisión” en la convocatoria del INE","c":"politica","f":"2026-11-24T06:54","r":"Ricardo Monreal presentará este martes al TEPJF un informe circunstanciado en respuesta a la demanda del PAN por la falta de convocatoria para elegir a la nueva presidencia del INE; la Jucopo lo aprobó con votos de Morena, PT y PVEM y la abstención de la oposición. El coordinador panista Elías Lixa acusó que se omitieron sus objeciones. La bancada de Morena se reunirá el miércoles para decidir si espera el fallo del Tribunal antes de emitir la convocatoria.","b":"","img":"senado","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/mundo/2026/11/24/monreal-responde-a-demanda-del-pan-que-acusa-la-falta-de-convocatoria-para-elegir-la-presidencia-del-ine-no-hay-omision-de-nuestro-trabajo-ni-violacion-a-la-norma/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-el-tfja-resolvera-este-miercoles-si-sanciona-a-edmundo-jacobo-y-otros","t":"El TFJA resolverá este miércoles si sanciona a Edmundo Jacobo y otros dos exfuncionarios del INE por un contrato con Talleres Gráficos","c":"politica","f":"2026-11-24T06:53","r":"El Tribunal Federal de Justicia Administrativa decidirá el 25 de noviembre un procedimiento de responsabilidad contra el exsecretario ejecutivo del INE Edmundo Jacobo Molina y los exdirectores Miguel Ángel Solís y Roberto Heycher Cardiel. El caso se refiere a un contrato de 2018 con Talleres Gráficos de México para material electoral, con un anticipo de cerca de 500 millones de pesos; las sanciones posibles son inhabilitación y multas. El expediente se abrió en 2019 y estuvo detenido siete años.","b":"","img":"ine","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/politica/tfja-resolvera-proceso-edmundo-jacobo-exfuncionarios-ine-talleres-graficos"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-colosio-riojas-acepta-buscar-la-candidatura-de-movimiento-ciudadano-a","t":"Colosio Riojas acepta buscar la candidatura de Movimiento Ciudadano a la gubernatura de Sonora en 2027","c":"politica","f":"2026-11-24T06:52","r":"El senador Luis Donaldo Colosio Riojas anunció en un video que aceptó la invitación de Movimiento Ciudadano para competir por el gobierno de Sonora en 2027, tras meses de dudas sobre si contendería ahí o en Nuevo León. Recordó que su padre, Luis Donaldo Colosio Murrieta, asesinado en 1994, aspiraba a gobernar ese estado. Ahora deberá participar en el proceso interno del partido.","b":"","img":"senado","foto":"","cred":"","src":[["Infobae México","https://www.infobae.com/mexico/2026/11/24/colosio-riojas-da-el-si-a-movimiento-ciudadano-y-acepta-competir-por-el-gobierno-de-sonora-en-2027/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-sinaloa-concentra-23-del-personal-operativo-de-la-defensa-22-mil-667-e","t":"Sinaloa concentra 23% del personal operativo de la Defensa: 22 mil 667 elementos","c":"seguridad","f":"2026-11-24T06:51","r":"Al 9 de noviembre había 22 mil 667 elementos de la Secretaría de la Defensa desplegados en Sinaloa, de un total de 272 mil 721, lo que equivale a cerca de 23% del personal. El dato se da tras la Operación Centella en Guasave, en la que participaron 361 elementos y 14 aeronaves.","b":"","img":"carretera","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/24/sinaloa-absorbe-23-del-refuerzo-militar-nacional/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-la-bolsa-mexicana-rompe-una-racha-de-seis-caidas-el-ipc-sube-1-06-y-ci","t":"La Bolsa Mexicana rompe una racha de seis caídas: el IPC sube 1.06% y cierra en 69 mil 355 puntos","c":"economia","f":"2026-11-24T06:50","r":"El S&P/BMV IPC terminó el lunes en 69 mil 355.62 puntos, con un avance de 1.06%, tras seis sesiones a la baja y una pérdida de 3.62% la semana anterior. Destacaron Volaris (+7.32%), Alpek (+4.45%), Peñoles (+4.39%), Grupo México (+3.21%) y Cemex (+3.06%). En noviembre el índice acumula una baja de 0.67% y en el año, una ganancia de 7.78%.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Informador / EFE","https://www.informador.mx/economia/ipc-de-la-bolsa-mexicana-avanza-1.06--y-rompe-racha-negativa-de-seis-sesiones-20261123-0163.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-los-aranceles-de-eu-son-la-principal-presion-de-costos-para-45-de-las","t":"Los aranceles de EU son la principal presión de costos para 45% de las empresas en México, según HSBC","c":"economia","f":"2026-11-24T06:49","r":"La Encuesta Global de Comercio 2026 de HSBC, aplicada a 500 empresas en México, encontró que 45% ubica los aranceles como su principal presión de costos, por encima de los precios de proveedores (40%) y las materias primas (38%). El 68% espera que los costos altos persistan y 49% ya optimizó sus rutas comerciales; aun así, 90% prevé aumentar su comercio de bienes con Estados Unidos en los próximos dos años.","b":"","img":"texas","foto":"","cred":"","src":[["Expansión","https://expansion.mx/economia/2026/11/23/aranceles-de-eu-afectan-estructura-de-costos-de-45-de-empresas-en-mexico-dice-encuesta-de-hsbc"],["La Razón","https://www.razon.com.mx/negocios/2026/11/24/empresas-reorganizan-cadenas-por-gravamenes/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-huelga-en-el-colegio-de-bachilleres-de-campeche-cierra-sus-37-plantele","t":"Huelga en el Colegio de Bachilleres de Campeche cierra sus 37 planteles; más de 11 mil alumnos sin clases","c":"estados","f":"2026-11-24T06:48","r":"El sindicato Sutcobacam inició el lunes una huelga por tiempo indefinido que mantiene cerrados los 37 planteles del Colegio de Bachilleres de Campeche. Reclama unos 7 millones de pesos del aumento salarial de 2026 que debía pagarse antes del 30 de octubre y otros 17 millones por jubilaciones. El gobierno estatal ofreció pagar en diciembre, sin fecha definida, y lo ligó a la liberación de recursos federales.","b":"","img":"estudio","foto":"","cred":"","src":[["Diario Cambio 22","https://diariocambio22.mx/estalla-huelga-en-el-colegio-de-bachilleres-de-campeche-y-deja-a-mas-de-11-mil-alumnos-sin-clases-por-adeudo-salarial-de-7-millones-de-pesos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-transportistas-bloquean-el-boulevard-industrial-de-uruapan-tras-ser-ag","t":"Transportistas bloquean el Boulevard Industrial de Uruapan tras ser agredidos por presuntos productores de aguacate","c":"estados","f":"2026-11-24T06:47","r":"Transportistas bloquearon la noche del lunes el Boulevard Industrial de Uruapan, Michoacán, frente a la planta de Pemex, después de una agresión de presuntos productores que mantienen un filtro para impedir la entrada de aguacate de otros estados. Exigieron a los tres niveles de gobierno garantizar el libre tránsito; desde hace alrededor de un mes los productores retienen camiones y en varias ocasiones han quemado la fruta.","b":"","img":"carretera","foto":"","cred":"","src":[["RED Michoacán","https://www.redmichoacan.com/2026/11/23/bloquean-boulevard-industrial-de-uruapan-tras-agresion-a-transportistas-aguacateros/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-el-pan-acusa-que-iztapalapa-elevo-1-600-las-adjudicaciones-directas-al","t":"El PAN acusa que Iztapalapa elevó 1,600% las adjudicaciones directas; Alavez dice que hay 20 auditorías abiertas","c":"cdmx","f":"2026-11-24T06:46","r":"Según datos expuestos por el diputado local del PAN Andrés Sánchez Miranda, las adjudicaciones directas en Iztapalapa sumaron 765.8 millones de pesos en 2025, frente a 44.6 millones en 2022, un alza cercana a 1,600%. La alcaldesa Aleida Alavez respondió que hay 20 auditorías en curso y que no encubrirá irregularidades. En 2026, hasta el 11 de noviembre, las adjudicaciones directas suman 411.3 millones de pesos.","b":"","img":"zocalo","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/ciudad/2026/11/24/iztapalapa-eleva-las-adjudicaciones-directas-en-1600/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-la-union-europea-presenta-su-paquete-22-de-sanciones-contra-rusia-60-b","t":"La Unión Europea presenta su paquete 22 de sanciones contra Rusia: 60 bancos fuera de SWIFT y 70 buques más en la lista negra","c":"internacional","f":"2026-11-24T06:45","r":"La presidenta de la Comisión Europea, Ursula von der Leyen, presentó un nuevo paquete que excluiría a 60 bancos rusos del sistema SWIFT y añadiría más de 70 petroleros de la llamada flota fantasma. Incluye medidas contra redes de criptomonedas y pagos, contra terceros países que ayudan a evadir sanciones, y prohíbe la entrada a Europa de excombatientes rusos. El Consejo de la UE aún debe aprobarlo.","b":"","img":"paris","foto":"","cred":"","src":[["UPI vía Yahoo News","https://www.yahoo.com/news/world/articles/eu-unveils-22nd-russia-sanctions-055125708.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-trump-se-inclina-por-reanudar-ataques-contra-iran-tras-ano-nuevo-si-no","t":"Trump se inclina por reanudar ataques contra Irán tras Año Nuevo si no hay acuerdo; EU sanciona su red de “banca en la sombra”","c":"internacional","f":"2026-11-24T06:44","r":"En entrevista con Fox News, Donald Trump dijo que se inclina por retomar los ataques militares contra Irán en el nuevo año si no se alcanza un acuerdo de largo plazo. El lunes, el Departamento del Tesoro sancionó a más de dos decenas de casas de cambio, empresas fachada y personas vinculadas con la red financiera paralela iraní; el secretario Scott Bessent la describió como el último salvavidas financiero del régimen.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Al Jazeera","https://www.aljazeera.com/news/2026/11/23/us-escalates-sanctions-on-iran-targets-shadow-banking-networks"],["JNS","https://www.jns.org/news/u-s-news/trump-signals-renewed-iran-strikes-after-new-year-if-no-deal-reached"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-australia-aprobara-una-ley-que-permitira-demandar-a-las-redes-sociales","t":"Australia aprobará una ley que permitirá demandar a las redes sociales, con multas de hasta 5% de sus ingresos globales","c":"tecnologia","f":"2026-11-24T06:43","r":"El gobierno laborista australiano pactó con los Verdes aprobar la ley de Deber Digital de Cuidado, que eleva la multa máxima de 109 millones de dólares australianos a 5% de los ingresos globales de las plataformas y da a las personas el derecho de demandarlas por daños en línea. La norma fija estándares mínimos para apps, juegos y chatbots de inteligencia artificial y permitirá desactivar los algoritmos. Se prevé que el Senado la vote el miércoles.","b":"","img":"tech","foto":"","cred":"","src":[["AP vía ClickOnDetroit","https://www.clickondetroit.com/tech/2026/11/24/australia-set-to-pass-a-digital-duty-of-care-law-with-fines-up-to-5-of-tech-giants-global-revenue/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-emmy-internacional-2026-bobby-schofield-gana-como-mejor-actor-javier-c","t":"Emmy Internacional 2026: Bobby Schofield gana como mejor actor; Javier Cámara y Ricardo Darín se quedan sin premio","c":"entretenimiento","f":"2026-11-24T06:42","r":"El británico Bobby Schofield ganó el Emmy Internacional a mejor actor por ‘Unforgivable’, por encima de Javier Cámara (‘Yakarta’) y Ricardo Darín (‘El Eternauta’). La francesa ‘Carême’ fue elegida mejor drama y la argentina ‘División Palermo’ repitió como mejor comedia; Reino Unido sumó nueve estatuillas. Los nominados mexicanos, entre ellos Bárbara Mori y el documental sobre Marcial Maciel, no obtuvieron premio.","b":"","img":"estudio","foto":"","cred":"","src":[["EFE vía Metro Puerto Rico","https://www.metro.pr/entretenimiento/2026/11/24/bobby-schofield-mejor-actor-en-los-emmy-internacional-por-unforgivable/"],["elDiarioAR","https://www.eldiarioar.com/espectaculos/emmy-internacional-2026-division-palermo-gano-premios-nominaron-serie-menem-ricardo-darin-eternauta_1_13688790.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-miss-universo-2026-elige-reina-este-martes-en-puerto-rico-maria-vargas","t":"Miss Universo 2026 elige reina este martes en Puerto Rico; María Vargas representa a México","c":"entretenimiento","f":"2026-11-24T06:41","r":"La final de Miss Universo se celebra este martes 24 de noviembre en San Juan, Puerto Rico, con 116 candidatas. México compite con María Vargas y la corona la tiene la mexicana Fátima Bosch. Entre las favoritas figuran Venezuela, Francia, Puerto Rico, Filipinas y Colombia.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/entretenimiento/2026/11/23/miss-universo-2026-lista-completa-de-las-116-candidatas-y-quienes-son-las-favoritas-del-certamen/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-24-el-tas-decide-este-martes-si-senegal-recupera-el-titulo-de-la-copa-afr","t":"El TAS decide este martes si Senegal recupera el título de la Copa Africana que la CAF dio a Marruecos","c":"deportes","f":"2026-11-24T06:40","r":"El Tribunal de Arbitraje Deportivo anunciará este martes su fallo sobre la apelación de Senegal, que ganó 1-0 la final del 18 de enero en Rabat. Los jugadores senegaleses abandonaron el campo unos 14 minutos en protesta por un penalti que después falló Brahim Díaz, y en marzo la CAF dio el triunfo 3-0 y el trofeo a Marruecos.","b":"","img":"estadio","foto":"","cred":"","src":[["City AM","https://www.cityam.com/afcon-final-senegal-cas-appeal-decision/"],["Meridiano","https://meridiano.net/futbol/tas-tiene-una-decision-quien-es-el-campeon-de-la-copa-africa-2026112318500"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-el-chapo-isidro-ingresa-al-altiplano-con-prision-preventiva-oficiosa-t","t":"‘El Chapo Isidro’ ingresa al Altiplano con prisión preventiva oficiosa tras una audiencia de más de cuatro horas","c":"nacional","f":"2026-11-23T18:59","r":"Fausto Isidro Meza Flores llegó la tarde del lunes 23 al penal federal de El Altiplano, luego de que la jueza de control Alejandra Ramírez de la Vega le impusiera prisión preventiva oficiosa en una audiencia por videoconferencia de poco más de cuatro horas. La misma medida se dictó a Germán “N”, alias ‘Serafín’, y a José “N”, su cuñado. El traslado salió a las 16:05 de la FEMDO, en la colonia Guerrero, con más de 50 elementos del Ejército y la Guardia Nacional y ocho vehículos artillados. La defensa pidió ampliar de 72 a 144 horas el plazo para definir su situación jurídica.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/23/el-chapo-isidro-llega-al-altiplano-asi-fue-el-operativo-de-ingreso-al-penal-de-maxima-seguridad/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-23-defensa-eleva-a-16-los-presuntos-delincuentes-abatidos-en-la-operacion","t":"Defensa eleva a 16 los presuntos delincuentes abatidos en la Operación Centella; participaron 361 militares y 14 aeronaves","c":"nacional","f":"2026-11-23T18:58","r":"El secretario de la Defensa, Ricardo Trevilla Trejo, detalló en la mañanera la operación del 20 de noviembre en Guasave que terminó con la captura de ‘El Chapo Isidro’: murieron 16 presuntos integrantes de los Beltrán Leyva y cuatro militares, y otros diez elementos resultaron heridos. El comunicado inicial del 21 de noviembre hablaba de siete agresores muertos; nueve cuerpos fueron localizados después. Se aseguraron dos rifles Barrett, una ametralladora calibre .50 y 17 vehículos, ocho con blindaje artesanal, y entre el 21 y el 22 se retiraron 21 bloqueos. Trevilla negó la presencia de agentes extranjeros en tierra y dijo que Estados Unidos solo compartió información.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/23/operacion-centella-contra-el-chapo-isidro-dejo-16-presuntos-delincuentes-muertos-defensa-uso-14-aeronaves-y-361-militares/"],["Informador","https://www.informador.mx/la-mananera-de-sheinbaum-de-hoy-lunes-23-de-noviembre-de-2026-lb202611230001.html"]],"dest":true,"a":"Redacción"},{"id":"2026-11-23-sheinbaum-descarta-la-salida-de-garcia-harfuch-no-hay-ningun-cambio-en","t":"Sheinbaum descarta la salida de García Harfuch: “No hay ningún cambio en el gabinete”","c":"politica","f":"2026-11-23T18:57","r":"La presidenta Claudia Sheinbaum negó en su conferencia del lunes los rumores sobre la salida de Omar García Harfuch de la Secretaría de Seguridad y aseguró que lo mantiene en el cargo. Harfuch dijo que el Cártel de Guasave no está desarticulado y que en Sinaloa se ha detenido a más de 4 mil personas de distintas facciones. Sobre posibles investigaciones a funcionarios estatales, mencionó indagatorias “señaladas por otro país” relacionadas con el gobierno de Rubén Rocha Moya y remitió el tema a la FGR.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/23/omar-garcia-harfuch-sigue-en-la-secretaria-de-seguridad-pese-a-rumores-de-salida-confirma-claudia-sheinbaum/"],["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-lunes-23-noviembre-2026-minuto-minuto-vivo-n6348231"]],"dest":true,"a":"Redacción"},{"id":"2026-11-23-mexico-sera-sede-del-mundial-femenil-2031-junto-con-estados-unidos-cos","t":"México será sede del Mundial Femenil 2031 junto con Estados Unidos, Costa Rica y Jamaica","c":"deportes","f":"2026-11-23T18:56","r":"El Congreso Extraordinario de la FIFA, reunido este lunes en Zúrich, aprobó la candidatura conjunta de los cuatro países, la única registrada, que obtuvo 4.4 de 5 puntos en la evaluación técnica. El torneo tendrá 48 selecciones y 104 partidos; la propuesta inicial asigna cuatro sedes a México: los estadios Banorte (CDMX), Akron (Guadalajara), BBVA (Monterrey) y el TSM de Torreón. Será la primera Copa del Mundo femenina avalada por la FIFA que se juegue en el país. En la misma sesión, Reino Unido fue elegido para la edición de 2035.","b":"","img":"estadio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/deportes/mexico-tendra-mundial-fifa-confirma-pais-como-sede-copa-femenina-2031"],["Infobae","https://www.infobae.com/mexico/deportes/2026/11/23/fifa-confirma-a-mexico-como-sede-de-la-copa-mundial-femenina-2031-junto-a-otros-tres-paises-de-america/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-23-el-gabinete-de-seguridad-viaja-este-martes-a-culiacan-anuncian-720-cam","t":"El Gabinete de Seguridad viaja este martes a Culiacán; anuncian 720 cámaras y 30 lectores de placas en carreteras de Sinaloa","c":"seguridad","f":"2026-11-23T18:55","r":"Omar García Harfuch informó que el Gabinete de Seguridad estará el martes 24 en Culiacán para entregar las primeras patrullas y reunirse con la gobernadora interina, Graciela Domínguez Nava. Anunció la instalación de 720 cámaras y 30 detectores de placas en 240 puntos de los tramos Culiacán-Mazatlán y Mazatlán-Durango, y la entrega de más de 150 vehículos a corporaciones estatales y municipales. Según sus cifras, desde septiembre de 2024 se han asegurado mil 300 kilos de fentanilo e inhabilitado 2 mil 627 laboratorios en el estado.","b":"","img":"carretera","foto":"","cred":"","src":[["Palco Quintanarroense","https://www.palcoquintanarroense.com.mx/mananera-sheinbaum-en-vivo-23-noviembre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-mexico-y-china-crean-un-grupo-de-trabajo-para-elevar-las-exportaciones","t":"México y China crean un grupo de trabajo para elevar las exportaciones mexicanas; Ebrard pide destrabar protocolos agrícolas","c":"economia","f":"2026-11-23T18:54","r":"El secretario de Economía, Marcelo Ebrard, y el ministro de Comercio de China, Wang Wentao, acordaron este lunes en Beijing, durante la XI Reunión del Grupo de Alto Nivel México-China, formar un grupo que revise mecanismos para aumentar las ventas mexicanas a ese país. China exportará este año a México más de 130 mil millones de dólares, mientras que México venderá a China unos 10 mil millones. Ebrard pidió acelerar los protocolos para aguacate, limón, carne de res y de cerdo, sorgo y productos acuáticos procesados; Exportadora de Sal ofreció hasta 10 millones de toneladas en cuatro años.","b":"","img":"palacio","foto":"","cred":"","src":[["Crónica","https://www.cronica.com.mx/nacional/2026/11/23/mexico-y-china-crean-grupo-de-trabajo-para-impulsar-las-exportaciones-mexicanas/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-wall-street-se-dispara-el-s-p-500-sube-4-75-y-el-nasdaq-6-47-tras-el-r","t":"Wall Street se dispara: el S&P 500 sube 4.75% y el Nasdaq 6.47% tras el regreso de Jensen Huang a Nvidia","c":"economia","f":"2026-11-23T18:53","r":"Las bolsas de Nueva York recuperaron este lunes poco más de la mitad de lo perdido la semana pasada. Con cifras preliminares, el S&P 500 ganó 4.75% a 7 mil 238.84 puntos, el Nasdaq 6.47% a 24 mil 080.94 y el Dow Jones 3.02% a 49 mil 599.89. El impulso vino de Nvidia, que subió 31.5% después de que su consejo restituyera a Huang como director general; Oracle avanzó 12.3% y CoreWeave 22.3%.","b":"","img":"bolsa","foto":"","cred":"","src":[["Forbes México","https://forbes.com.mx/wall-street-cierra-con-fuerte-avance-tras-el-regreso-de-jensen-huang-como-ceo-de-nvidia"],["Yahoo Noticias (AP)","https://es-us.noticias.yahoo.com/wall-street-sube-regreso-huang-222659658.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-el-peso-cierra-en-19-17-por-dolar-casi-sin-cambios-frente-al-viernes","t":"El peso cierra en 19.17 por dólar, casi sin cambios frente al viernes","c":"economia","f":"2026-11-23T18:52","r":"El tipo de cambio cerró este lunes en 19.17 pesos por dólar, según datos del Banco de México, apenas 0.0069 pesos (0.04%) por encima del cierre previo de 19.1631. El FIX que publica Banxico se ubicó en 19.1648. Frente al euro, el peso cedió 0.77% y la moneda europea terminó en 21.0065 pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["Heraldo Binario","https://www.heraldobinario.com.mx/tendencias/2026/11/23/precio-dolar-peso-cierra-en-equilibrio-este-lunes-23-de-noviembre-43804.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-el-petroleo-cae-casi-4-el-brent-baja-a-89-37-dolares-ante-la-prevision","t":"El petróleo cae casi 4%: el Brent baja a 89.37 dólares ante la previsión de sobreoferta de la AIE","c":"economia","f":"2026-11-23T18:51","r":"El Brent retrocedió 3.46% a 89.37 dólares por barril y el WTI 3.88% a 80.17 dólares, su nivel más bajo desde agosto, tras llegar a cotizar por debajo de 80 durante la sesión. La Agencia Internacional de Energía prevé que en el último trimestre de 2026 la oferta mundial supere a la demanda, algo que no ocurría desde el inicio del conflicto entre Estados Unidos e Irán a finales de febrero.","b":"","img":"pemex","foto":"","cred":"","src":[["Potosinoticias / El Economista","https://potosinoticias.com/2026/11/23/petroleo-cae-casi-4-ante-previsiones-de-sobreoferta-mundial/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-el-ine-analiza-mantener-la-formula-de-plurinominales-de-2024-la-comisi","t":"El INE analiza mantener la fórmula de plurinominales de 2024; la comisión la revisará el viernes 27","c":"politica","f":"2026-11-23T18:50","r":"Un proyecto de la Dirección Ejecutiva de Prerrogativas y Partidos Políticos del INE, aún sin aprobar, propone conservar para 2027 el método de asignación de las 200 diputaciones de representación proporcional que se aplicó en 2024, cuando Morena, PVEM y PT obtuvieron alrededor de 54% de los votos y cerca de 73% de los escaños. La Comisión de Prerrogativas lo discutiría el viernes 27 de noviembre antes de pasar al Consejo General. Especialistas como Ricardo Becerra y la exconsejera Claudia Zavala sostienen que el instituto podría corregir la sobrerrepresentación.","b":"","img":"ine","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/mexico/2026/11/23/ine-perfila-mantener-formula-de-plurinominales-que-favorecio-a-morena-en-2024-y-podria-permitirle-conservar-su-mayoria-en-la-camara-de-diputados-en-2027/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-la-alcaldesa-de-guasave-dice-que-no-fue-avisada-del-operativo-contra-e","t":"La alcaldesa de Guasave dice que no fue avisada del operativo contra ‘El Chapo Isidro’; cerca de cien vehículos quedaron dañados","c":"estados","f":"2026-11-23T18:49","r":"Cecilia Ramírez Montoya, presidenta municipal de Guasave, afirmó en conferencia que el Ayuntamiento no recibió aviso previo del operativo federal del viernes por el hermetismo de las fuerzas militares. Dijo que alrededor de un centenar de vehículos resultaron dañados en la ciudad, la zona rural y las carreteras, y que coordinó con la gobernadora interina Graciela Domínguez Nava su retiro. Pidió no difundir rumores y aseguró que las fuerzas estatales y federales seguirán en las calles.","b":"","img":"carretera","foto":"","cred":"","src":[["Café Negro Portal","https://cafenegroportal.com/alcaldesa-de-guasave-asegura-que-no-fue-notificada-del-operativo-para-detener-a-el-chapo-isidro/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-comercios-de-guasave-reducen-horarios-y-la-central-camionera-opera-con","t":"Comercios de Guasave reducen horarios y la central camionera opera con pocas salidas tras la violencia","c":"estados","f":"2026-11-23T18:48","r":"En Guasave, algunos supermercados cierran desde las 19:00 horas y se reportaron saqueos en tiendas de conveniencia, mientras la central de autobuses mantiene limitadas sus corridas hacia Culiacán y Mazatlán. Escuelas públicas y privadas de Guasave y Juan José Ríos mantienen la suspensión de clases presenciales. Los restos del militar José Guadalupe Luna Castillo, originario de Juan José Ríos, fueron trasladados a Los Mochis.","b":"","img":"ultimahora","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/sinaloa/guasave-suspende-clases-presenciales-y-comercios-reducen-horarios-tras-captura-del-chapo-isidro/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-detienen-a-un-expolicia-de-taxco-senalado-por-la-desaparicion-forzada","t":"Detienen a un expolicía de Taxco señalado por la desaparición forzada de tres jóvenes en 2024","c":"seguridad","f":"2026-11-23T18:47","r":"La Fiscalía General del Estado de Guerrero detuvo a Juan Francisco “N”, exagente de la Policía Municipal de Taxco de Alarcón y presunto integrante de La Familia Michoacana, por la desaparición forzada de tres hombres el 23 de junio de 2024 en el paraje El Mirador, en Juliantla. Según la fiscalía, al día siguiente fueron sacados de los separos municipales. Medios locales señalan que dos de ellos fueron liberados días después y que Rodrigo, de 16 años, sigue sin ser localizado. En marzo ya había sido detenido otro policía por el mismo caso.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/23/detienen-a-expolicia-de-taxco-ligado-a-la-familia-michoacana-por-desaparicion-forzada-de-tres-hombres/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-la-universidad-rosario-castellanos-de-zacatecas-crecera-de-2-mil-a-10","t":"La Universidad Rosario Castellanos de Zacatecas crecerá de 2 mil a 10 mil alumnos y sumará Medicina y Enfermería","c":"nacional","f":"2026-11-23T18:46","r":"La presidenta Sheinbaum informó que el plantel de la Universidad Rosario Castellanos en Zacatecas, construido junto a una sede de la UAZ, ampliará su matrícula de 2 mil a 10 mil estudiantes con las carreras de Medicina y Enfermería; las actividades iniciarán en abril y la ampliación concluirá hacia finales de 2028. También dijo que el IMSS y la Secretaría de Ciencia desarrollan equipos de hemodiálisis y diálisis que están en una segunda fase de pruebas y esperan aval de Cofepris en pocos meses.","b":"","img":"unam","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/la-mananera-claudia-sheinbaum-hoy-lunes-23-noviembre-2026-minuto-minuto-vivo-n6348231"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-profeco-ubica-en-910-pesos-el-costo-promedio-de-la-canasta-basica-fina","t":"Profeco ubica en 910 pesos el costo promedio de la canasta básica; Finabien paga más por remesas","c":"economia","f":"2026-11-23T18:45","r":"En el reporte semanal de la mañanera, la Profeco informó que la canasta básica tuvo un precio promedio de 910 pesos. En el comparativo de envío de remesas con datos del 19 de noviembre, Finabien entregó 7 mil 682.14 pesos por cada 400 dólares. La dependencia también presentó ejemplos de descuentos del Buen Fin, que del 13 al 17 de noviembre incluyó más de 55 mil productos.","b":"","img":"palacio","foto":"","cred":"","src":[["Palco Quintanarroense","https://www.palcoquintanarroense.com.mx/mananera-sheinbaum-en-vivo-23-noviembre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-nvidia-restituye-a-jensen-huang-como-director-general-trump-asegura-qu","t":"Nvidia restituye a Jensen Huang como director general; Trump asegura que su intervención fue clave","c":"tecnologia","f":"2026-11-23T18:44","r":"El consejo de administración de Nvidia devolvió este lunes, por unanimidad, la presidencia y la dirección general a Jensen Huang, menos de dos semanas después de su renuncia del 12 de noviembre. La acción cerró con un alza de 31.5%. Trump dijo a CNBC que su intervención fue “muy importante” para el regreso; el consejo todavía investiga si Huang fue blanco de una espía extranjera.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae (EFE)","https://infobae.com/america/agencias/2026/11/23/temas-del-dia-de-efe-news-latino-del-lunes-23-de-noviembre"],["Yahoo Noticias (AP)","https://es-us.noticias.yahoo.com/wall-street-sube-regreso-huang-222659658.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-huelga-general-en-belgica-cierra-el-espacio-aereo-y-los-sindicatos-mar","t":"Huelga general en Bélgica: cierra el espacio aéreo y los sindicatos marchan contra los recortes de De Wever","c":"internacional","f":"2026-11-23T18:43","r":"Los tres grandes sindicatos belgas, CSC, FGTB y Synova, marcharon este lunes en Bruselas contra el ajuste de 10 mil millones de euros hasta 2029 que impulsa el gobierno del primer ministro Bart De Wever. Una huelga de controladores aéreos cerró el espacio aéreo hasta la noche: Zaventem y Charleroi cancelaron sus vuelos y el metro de Bruselas operó solo dos de sus cuatro líneas. Bélgica tiene un déficit de 5.3% del PIB y una deuda de 110.2%.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/23/los-tres-grandes-sindicatos-belgas-marchan-contra-los-recortes-del-gobierno-de-de-wever/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-la-liga-mx-fija-horarios-de-cuartos-de-final-america-monterrey-y-atlas","t":"La Liga MX fija horarios de cuartos de final: América-Monterrey y Atlas-Toluca abren el miércoles 25","c":"deportes","f":"2026-11-23T18:42","r":"La ida de cuartos se jugará el miércoles 25 (Toluca-Atlas a las 19:00 en el Nemesio Diez y Monterrey-América a las 21:10 en el BBVA) y el jueves 26 (Pachuca-Chivas a las 19:00 en el Hidalgo y León-Cruz Azul a las 21:10). Las vueltas serán el sábado 28 (Atlas-Toluca, 19:00, Estadio Jalisco; América-Monterrey, 21:10, Banorte) y el domingo 29 (Chivas-Pachuca, 19:07, Akron; Cruz Azul-León, 21:00, Banorte). En caso de empate global avanza el mejor ubicado en la tabla.","b":"","img":"estadio","foto":"","cred":"","src":[["TUDN","https://www.tudn.com/futbol/liga-mx/liguilla-liga-mx-fechas-y-horarios-de-cuartos-de-final-del-apertura-2026"],["Publimetro","https://www.publimetro.com.mx/deportes/2026/11/23/liga-mx-revela-fechas-y-horarios-para-los-duelos-de-cuartos-de-final-del-apertura-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-el-kremlin-acusa-que-ucrania-sigue-intentando-atacar-instalaciones-en","t":"El Kremlin acusa que Ucrania sigue intentando atacar instalaciones en Rusia","c":"internacional","f":"2026-11-23T18:41","r":"El portavoz de la Presidencia rusa, Dmitri Peskov, dijo este lunes que Ucrania ha intentado atentar contra instalaciones en territorio ruso en las últimas 48 horas y que Rusia continuará su ofensiva, con ataques diarios contra infraestructura militar ucraniana. Sus declaraciones llegan después del hundimiento de un buque ruso en un puerto de Libia, que Zelenski atribuyó a su país.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Prensa Latina","https://www.prensa-latina.cu/2026/11/23/ucrania-continua-con-intentos-de-atacar-instalaciones-en-rusia/"],["Just Security","https://www.justsecurity.org/165610/early-edition-november-23-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-detencion-de-un-padre-y-su-hija-mexicanos-en-el-aeropuerto-de-seattle","t":"Detención de un padre y su hija mexicanos en el aeropuerto de Seattle reaviva críticas a ICE","c":"internacional","f":"2026-11-23T18:40","r":"Agentes de ICE con el rostro cubierto detuvieron el sábado a un padre y su hija, ambos mexicanos y sin antecedentes penales según sus abogados, en la manga de embarque del aeropuerto de Seattle, cuando viajaban a un bautizo familiar en California. El caso volvió a encender la polémica por los operativos migratorios y la falta de identificación de los agentes.","b":"","img":"texas","foto":"","cred":"","src":[["Infobae (EFE)","https://infobae.com/america/agencias/2026/11/23/temas-del-dia-de-efe-news-latino-del-lunes-23-de-noviembre"],["Just Security","https://www.justsecurity.org/165610/early-edition-november-23-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-el-pib-de-mexico-crece-0-9-en-el-tercer-trimestre-y-3-3-a-tasa-anual-c","t":"El PIB de México crece 0.9% en el tercer trimestre y 3.3% a tasa anual, confirma el Inegi","c":"economia","f":"2026-11-23T06:40","r":"La economía avanzó 0.9% entre julio y septiembre frente al trimestre previo, por debajo del 1.4% del segundo trimestre, según las cifras revisadas que el Inegi publicó este lunes. A tasa anual el crecimiento fue de 3.3%, una décima más que la estimación oportuna de octubre. Los servicios subieron 1.2% trimestral, la industria 0.4% y el campo 0.3%; de enero a septiembre el PIB acumula 1.9% anual.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión","https://expansion.mx/economia/2026/11/23/pib-de-mexico-crece-0-9-tercer-trimestre-pierde-ritmo-inegi"],["El CEO","https://elceo.com/economia/pib-mexico-tercer-trimestre-2026-inegi-cifras-revisadas/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-23-ejercito-detiene-a-ocho-presuntos-integrantes-de-los-beltran-leyva-tra","t":"Ejército detiene a ocho presuntos integrantes de los Beltrán Leyva tras ser atacado en Sinaloa de Leyva","c":"seguridad","f":"2026-11-23T06:39","r":"Fuerzas especiales del Ejército y la policía estatal fueron atacadas la noche del domingo cuando hacían reconocimiento en El Platanito, municipio de Sinaloa de Leyva, informó la Defensa. Ocho presuntos integrantes de la facción que encabezaba ‘El Chapo Isidro’ fueron detenidos; se les aseguró un fusil Barrett y una ametralladora calibre .50, otra ametralladora Minimi, seis vehículos y una torreta. Según las autoridades, habrían participado en los narcobloqueos del viernes 20 y serán entregados a la FGR en Culiacán.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/estados/2026/11/22/enfrentamientos-en-sinaloa-de-leyva-tras-captura-del-chapo-isidro-detienen-a-8-de-sus-operadores/"],["La Jornada","https://www.jornada.com.mx/noticia/2026/11/22/politica/sinaloa-cae-celula-del-chapo-isidro-tras-agresion-al-ejercito-hay-8-detenidos"]],"dest":true,"a":"Redacción"},{"id":"2026-11-23-la-convocatoria-para-elegir-a-la-nueva-presidencia-del-ine-sigue-sin-l","t":"La convocatoria para elegir a la nueva presidencia del INE sigue sin llegar a San Lázaro; exconsejeros advierten riesgo para su autonomía","c":"politica","f":"2026-11-23T06:38","r":"La Cámara de Diputados aún no emite la convocatoria para sustituir a Guadalupe Taddei, mientras el INE es encabezado de forma provisional. Exconsejeros y académicas como Lorenzo Córdova, Guadalupe Salmorán y María del Carmen Alanís advierten que el discurso de Morena contra el instituto podría anticipar una reforma que le reste autonomía. Ricardo Monreal, presidente de la Jucopo, ha dicho que busca consensos; el PAN acudió al Tribunal Electoral, y la presidenta Sheinbaum dijo el 6 de noviembre que retomará su reforma electoral después de 2027.","b":"","img":"ine","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/23/preparan-terreno-reforma-electoral-advierten-captura-ine"]],"dest":true,"a":"Redacción"},{"id":"2026-11-23-el-pan-propone-cinco-medidas-contra-el-sarampion-ante-20-mil-701-casos","t":"El PAN propone cinco medidas contra el sarampión ante 20 mil 701 casos y 50 muertes desde 2025","c":"nacional","f":"2026-11-23T06:37","r":"La diputada federal Genoveva Huerta pidió garantizar el abasto de vacunas en todos los centros de salud, llevar la inmunización a aeropuertos, terminales, mercados y escuelas, y desplegar brigadas en las colonias de mayor riesgo. Citó cifras de la Secretaría de Salud de 20 mil 701 casos confirmados y 50 defunciones entre 2025 y noviembre de 2026. La legisladora y la diputada local Laura Álvarez Soto exigieron un informe sobre las existencias de vacunas.","b":"","img":"imss","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/23/oposicion-pide-medidas-para-atajar-el-sarampion/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-23-las-exportaciones-de-servidores-y-equipo-de-computo-superan-por-primer","t":"Las exportaciones de servidores y equipo de cómputo superan por primera vez a las automotrices","c":"economia","f":"2026-11-23T06:36","r":"De enero a septiembre, México exportó 163 mil 389 millones de dólares en equipo de procesamiento de datos, 207% más que un año antes, contra 143 mil 142 millones del sector automotriz, que creció 1.33%, según datos de Banxico citados por La Razón. La participación del rubro tecnológico en el total pasó de 17.8% a 39.7%, mientras la del automotriz bajó de 47.3% a 34.8%. El cambio se atribuye al auge de la inteligencia artificial y a que estos bienes casi no pagan aranceles en EU.","b":"","img":"tech2","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/negocios/2026/11/23/equipos-de-computo-destronan-al-sector-automotriz-como-generador-de-divisas/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-un-exdirectivo-ligado-a-empresas-investigadas-asistia-a-taddei-en-acto","t":"Un exdirectivo ligado a empresas investigadas asistía a Taddei en actos del INE, aunque el instituto no halló su contrato","c":"politica","f":"2026-11-23T06:35","r":"Juan Carlos Enrique Cuervo Escalona, exdirector del INE y apoderado legal de Corporativo Zeg hasta abril de 2025, aparece en actos oficiales de la elección judicial, entre ellos la entrega de constancias del 16 de junio de 2025, según La Razón. Una respuesta de transparencia indicó que no había registro de su contratación. La empresa forma parte de una red vinculada a proveedores de material electoral con contratos por unos 197 millones de pesos; el INE presentó una denuncia ante la FGR el 6 de noviembre.","b":"","img":"ine","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/23/exdirectivo-ligado-a-empresas-senaladas-asistia-a-taddei-ine-no-ubico-su-contrato/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-sheinbaum-alcanza-70-5-de-aprobacion-en-la-encuesta-semanal-de-metrics","t":"Sheinbaum alcanza 70.5% de aprobación en la encuesta semanal de MetricsMx","c":"politica","f":"2026-11-23T06:34","r":"La aprobación de la presidenta subió de 68.1% a 70.5% en la tercera semana de noviembre, con una desaprobación de 19.2%, según el sondeo telefónico a 800 adultos realizado el 18 de noviembre. Ante una posible baja de impuestos, 46.8% preferiría que se aplicara a la gasolina Magna y 36.1% al diésel. Sobre las amenazas arancelarias de EU por las caravanas migrantes, 53.3% opina que México debe reforzar los controles.","b":"","img":"palacio","foto":"","cred":"","src":[["SDPnoticias","https://www.sdpnoticias.com/mexico/sheinbaum-alcanza-705-de-aprobacion-esto-opinan-sobre-bajar-impuestos-a-la-gasolina-magna"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-sheinbaum-hara-este-lunes-el-balance-de-su-participacion-en-la-cumbre","t":"Sheinbaum hará este lunes el balance de su participación en la cumbre APEC y su reunión con Xi Jinping","c":"nacional","f":"2026-11-23T06:33","r":"La presidenta Claudia Sheinbaum tiene previsto informar sobre los resultados de su viaje a China para la cumbre del Foro de Cooperación Económica Asia-Pacífico y de sus encuentros bilaterales, entre ellos con el presidente Xi Jinping, de acuerdo con la agenda de la agencia EFE para este 23 de noviembre.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/23/agenda-informativa-multisoporte-america-para-el-lunes-23-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-el-dolar-abre-la-semana-en-19-18-pesos-tras-subir-3-56-en-los-ultimos","t":"El dólar abre la semana en 19.18 pesos tras subir 3.56% en los últimos siete días","c":"economia","f":"2026-11-23T06:32","r":"El tipo de cambio se ubicó en 19.18 pesos por dólar en la apertura del lunes, 0.08% arriba del cierre previo de 19.16, según datos de Dow Jones citados por Infobae. La divisa estadounidense acumula un alza de 3.56% en la semana. Las proyecciones para el cierre de 2026 van de 19.30 a 20.50 pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/23/precio-del-dolar-hoy-en-mexico-cotizacion-de-apertura-del-23-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-asesinan-en-puebla-a-un-sobrino-de-rafael-caro-quintero-y-a-su-escolta","t":"Asesinan en Puebla a un sobrino de Rafael Caro Quintero y a su escolta","c":"seguridad","f":"2026-11-23T06:31","r":"Juan Pablo Quintero Navidad y su escolta, un militar retirado, fueron atacados a balazos la tarde del sábado 21 en Lomas de Angelópolis, en el cruce de los bulevares de Los Lagos y Morelia, confirmó el secretario de Gobernación estatal, Samuel Aguilar Pala. Los agresores huyeron en una camioneta y dejaron un arma larga en el lugar. La Fiscalía de Puebla investiga con apoyo federal; no hay detenidos.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Serpientes y Escaleras","https://serpientesyescaleras.mx/asesinan-en-puebla-a-sobrino-de-rafael-caro-quintero-y-a-su-escolta-en-lomas-de-angelopolis/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-matan-a-dos-mujeres-en-el-estacionamiento-de-un-supermercado-de-ciudad","t":"Matan a dos mujeres en el estacionamiento de un supermercado de Ciudad Juárez","c":"seguridad","f":"2026-11-23T06:30","r":"Las víctimas estaban por bajar de una camioneta con placas de Texas en la colonia Altavista cuando hombres armados les dispararon, poco después de las 19:00 horas del sábado 21, frente a clientes de la tienda. Policías municipales hallaron horas después un vehículo abandonado que pudo usarse en el ataque. No se han dado a conocer sus identidades ni hay detenidos; en lo que va del año suman 478 asesinatos en la ciudad, 45 de ellos de mujeres.","b":"","img":"chihuahua","foto":"","cred":"","src":[["Quinta Fuerza","https://quintafuerza.mx/chihuahua/asesinan-dos-mujeres-supermercado-ciudad-juarez-chihuahua/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-escuelas-y-universidades-de-guasave-pasan-a-clases-a-distancia-este-lu","t":"Escuelas y universidades de Guasave pasan a clases a distancia este lunes tras la violencia del fin de semana","c":"estados","f":"2026-11-23T06:29","r":"La UAdeO en Guasave, la Preparatoria Casa Blanca de la UAS, la Secundaria General Insurgentes y varios colegios privados dieron clases en línea este lunes, tras los hechos violentos que siguieron a la captura de ‘El Chapo Isidro’. La Secretaría de Educación de Sinaloa no emitió una suspensión general de clases presenciales, y las autoridades municipales negaron que haya toque de queda.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Línea Directa","https://lineadirectaportal.com/sinaloa/tras-hechos-violentos-del-fin-de-semana-escuelas-de-guasave-optan-por-clases-virtuales-este-lunes-2026-11-22__1743664"],["El Financiero","https://www.elfinanciero.com.mx/estados/2026/11/22/enfrentamientos-en-sinaloa-de-leyva-tras-captura-del-chapo-isidro-detienen-a-8-de-sus-operadores/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-samuel-garcia-rinde-su-quinto-informe-y-asegura-que-los-homicidios-baj","t":"Samuel García rinde su quinto informe y asegura que los homicidios bajaron 90% en Nuevo León","c":"estados","f":"2026-11-23T06:28","r":"En el Parque del Agua, el gobernador afirmó que la Fuerza Civil pasó de 3 mil a más de 7 mil 500 elementos y que se invirtieron 35 mil millones de pesos en seguridad. También destacó la construcción de las líneas 4 y 6 del Metro y la compra de 22 trenes para las líneas 1 y 2. Las cifras son del propio mandatario.","b":"","img":"carretera","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/estados/2026/11/23/samuel-garcia-destaca-90-menos-homicidios/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-brugada-sube-a-2-mil-pesos-bimestrales-la-beca-de-transporte-para-univ","t":"Brugada sube a 2 mil pesos bimestrales la beca de transporte para universitarios a partir de 2027","c":"cdmx","f":"2026-11-23T06:27","r":"La jefa de Gobierno anunció que el apoyo ‘Transporte y Más’ pasará de mil 500 a 2 mil pesos al bimestre el próximo año, durante una entrega en la que se sumaron unos 30 mil estudiantes. La meta de este año es de 200 mil alumnos de universidades públicas que vivan en la capital, incluidas las ubicadas en el Estado de México.","b":"","img":"unam","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/ciudad/2026/11/23/aumenta-brugada-a-2-mil-pesos-becas-a-universitarios/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-marchas-por-el-25n-protestas-por-agua-y-el-concierto-de-soda-stereo-ma","t":"Marchas por el 25N, protestas por agua y el concierto de Soda Stereo marcan la agenda de la capital este lunes","c":"cdmx","f":"2026-11-23T06:26","r":"La SSC prevé una marcha estudiantil de la Prepa 8 hacia Ciudad Universitaria a las 12:00 horas, con motivo del Día Internacional de la Eliminación de la Violencia contra las Mujeres, además de protestas de colectivos feministas en juzgados de la colonia Doctores y del Reclusorio Oriente. Vecinos de Tlalpan e Iztacalco se manifestarán por falta de agua y motociclistas acudirán a la Semovi. Por la noche, Soda Stereo se presenta en el Palacio de los Deportes, con unas 20 mil personas previstas.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/23/en-vivo-bloqueos-accidentes-y-manifestaciones-hoy-23-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-hunden-una-corbeta-rusa-en-el-puerto-libio-de-bengasi-zelenski-se-atri","t":"Hunden una corbeta rusa en el puerto libio de Bengasi; Zelenski se atribuye el ataque","c":"internacional","f":"2026-11-23T06:25","r":"Un ataque con drones el domingo hundió una corbeta rusa atracada en Bengasi, en el este de Libia, sin víctimas según las autoridades locales; un buque comercial también fue alcanzado. El presidente ucraniano, Volodímir Zelenski, reivindicó el golpe contra dos buques rusos cerca de Libia, y el gobierno del este libio pidió a la ONU una investigación independiente. Drones ucranianos también atacaron depósitos de petróleo en Tatarstán.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/23/temas-del-dia-de-efe-internacional-del-lunes-23-de-noviembre-1200-gmt/"],["The Global Eye","https://theglobaleye.it/2026/11/23/global-news-23-november-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-rutte-pide-a-la-otan-un-plan-creible-para-invertir-5-del-pib-en-defens","t":"Rutte pide a la OTAN un plan creíble para invertir 5% del PIB en defensa; Zelenski dice estar listo para reunirse ‘mañana’","c":"internacional","f":"2026-11-23T06:24","r":"Ante la Asamblea Parlamentaria de la OTAN en Berlín, el secretario general Mark Rutte pidió una hoja de ruta para alcanzar el 5% del PIB en gasto de defensa a más tardar en 2035. Zelenski, por videoconferencia, llamó a acelerar las conversaciones de paz a cuatro bandas. El Consejo de Seguridad de la ONU sesiona este lunes sobre Ucrania.","b":"","img":"paris","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/23/temas-del-dia-de-efe-internacional-del-lunes-23-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-javier-camara-y-ricardo-darin-compiten-este-lunes-por-el-emmy-internac","t":"Javier Cámara y Ricardo Darín compiten este lunes por el Emmy Internacional a mejor actor","c":"entretenimiento","f":"2026-11-23T06:23","r":"Los premios Emmy Internacional se entregan este 23 de noviembre en Nueva York. El español Javier Cámara está nominado por ‘Yakarta’ y el argentino Ricardo Darín por ‘El eternauta’, según la agenda de EFE.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/23/lunes-23-de-noviembre-de-2026-0200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-chivas-vence-1-0-a-cruz-azul-y-termina-como-superlider-asi-quedan-los","t":"Chivas vence 1-0 a Cruz Azul y termina como superlíder; así quedan los cuartos de final","c":"deportes","f":"2026-11-23T06:22","r":"Con gol de Efraín Álvarez al minuto 21 en el Estadio Akron, Guadalajara cerró el Apertura 2026 con 33 puntos, uno más que Cruz Azul; América terminó tercero con 30. Los cuartos de final serán Chivas-Pachuca, Cruz Azul-León, América-Monterrey y Atlas-Toluca. La Liga MX dará a conocer fechas y horarios este lunes; la liguilla arranca el miércoles 25.","b":"","img":"estadio","foto":"","cred":"","src":[["Proceso / AP","https://www.proceso.com.mx/deportes/2026/11/22/chivas-vence-1-0-a-cruz-azul-y-se-impone-lider-del-torneo-apertura-384166.html"],["Sinaloa en Línea","https://sinaloaenlinea.com/liguilla-apertura-2026-cuartos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-23-los-49ers-aplastan-35-10-a-los-vikings-en-el-regreso-de-la-nfl-a-la-ci","t":"Los 49ers aplastan 35-10 a los Vikings en el regreso de la NFL a la Ciudad de México","c":"deportes","f":"2026-11-23T06:21","r":"Ante 85 mil 612 aficionados, San Francisco dominó con tres pases de anotación de Brock Purdy, dos de ellos para George Kittle, y una intercepción devuelta para touchdown. Los 49ers mejoraron a marca de 9-1 y Minnesota cayó a 7-3.","b":"","img":"estadio","foto":"","cred":"","src":[["ESPN","https://www.espn.com.co/futbol-americano/nfl/juego/_/juegoId/401873077/vikings-49ers"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-el-saldo-de-la-violencia-en-guasave-sube-a-20-muertos-entre-ellos-cuat","t":"El saldo de la violencia en Guasave sube a 20 muertos, entre ellos cuatro militares","c":"seguridad","f":"2026-11-22T18:59","r":"El reporte preliminar de este domingo eleva a 20 los fallecidos por los enfrentamientos en Guasave, Sinaloa, tras la captura de ‘El Chapo Isidro’: 16 civiles, señalados como presuntos integrantes de grupos delictivos, y cuatro elementos del Ejército. Cinco cuerpos calcinados requerirán pruebas de ADN para ser identificados y al menos 10 elementos de seguridad recibieron atención por heridas. Las autoridades advierten que la cifra definitiva se dará en los próximos días.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Meganoticias","https://www.meganoticias.mx/culiacan/noticia/suman-20-muertos-por-enfrentamientos-en-guasave/791135"]],"dest":true,"a":"Redacción"},{"id":"2026-11-22-el-pan-exige-a-morena-emitir-ya-la-convocatoria-para-elegir-a-quien-pr","t":"El PAN exige a Morena emitir ya la convocatoria para elegir a quien presida el INE hasta 2032","c":"politica","f":"2026-11-22T18:58","r":"El dirigente nacional del PAN, Jorge Romero, respaldó el recurso que su bancada presentó ante el Tribunal Electoral para que la Cámara de Diputados emita la convocatoria e integre el Comité Técnico de Evaluación. Guadalupe Taddei dejó el INE el 26 de octubre y Blanca Cruz ocupa la presidencia de forma provisional. Ricardo Monreal, presidente de la Jucopo, dijo que esperará la resolución del Tribunal para avanzar.","b":"","img":"ine","foto":"","cred":"","src":[["Político MX","https://politico.mx/2026/11/22/pan-exige-dejar-de-aplazar-la-renovacion-en-la-presidencia-del-ine"]],"dest":true,"a":"Redacción"},{"id":"2026-11-22-no-habra-clases-el-viernes-27-en-todo-el-pais-por-el-ultimo-consejo-te","t":"No habrá clases el viernes 27 en todo el país por el último Consejo Técnico del año; en Morelos, algunas escuelas pararán lunes y martes","c":"nacional","f":"2026-11-22T18:57","r":"La SEP confirmó que el viernes 27 de noviembre se realizará la última sesión del Consejo Técnico Escolar del año, por lo que no habrá clases en escuelas públicas y privadas de educación básica. Además, el lunes 23 y martes 24 algunas escuelas públicas de Morelos suspenderán actividades por asambleas de la Sección 19 del SNTE. El último día de clases del año será el 18 de diciembre y el regreso, el 7 de enero de 2027.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/22/sep-confirma-suspension-de-clases-del-23-al-27-de-noviembre-estos-son-los-lugares-donde-aplica-la-medida/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-22-fernandez-norona-denuncia-que-fue-agredido-en-el-centro-de-oaxaca-y-qu","t":"Fernández Noroña denuncia que fue agredido en el centro de Oaxaca y que le lastimaron la mano","c":"politica","f":"2026-11-22T18:56","r":"El senador de Morena Gerardo Fernández Noroña denunció en Facebook agresiones físicas y verbales en el centro de Oaxaca, donde realizaba actividades políticas, y dijo que pidió apoyo policial desde el lobby de un hotel. Según su relato, le lastimaron la mano izquierda, que ya tenía fracturada, y también agredieron a dos acompañantes. Hasta la publicación no había un reporte oficial de la policía de Oaxaca sobre el hecho.","b":"","img":"senado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/22/gerardo-fernandez-norona-denuncia-agresion-en-oaxaca-acabo-de-vivir-un-incidente-muy-grave/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-22-el-diesel-pierde-parte-de-su-estimulo-fiscal-pagara-80-centavos-de-iep","t":"El diésel pierde parte de su estímulo fiscal: pagará 80 centavos de IEPS por litro esta semana","c":"economia","f":"2026-11-22T18:55","r":"Hacienda redujo el estímulo al diésel de 100% a 89.16% para la semana del 21 al 27 de noviembre, con lo que su IEPS pasó de cero a 0.7981 pesos por litro; además retiró un apoyo complementario de 0.0418 pesos. En total, el diésel pierde unos 84 centavos de apoyo por litro. La Premium se mantiene sin estímulo, con 5.6579 pesos de IEPS, y el ajuste no implica un alza automática en el precio al público.","b":"","img":"pemex","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/negocios/subira-la-gasolina-hacienda-elimina-apoyo-a-magna-pero-el-mayor-ajuste-es-para-el-diesel/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-detienen-en-veracruz-a-tres-hombres-investigados-por-el-asesinato-de-u","t":"Detienen en Veracruz a tres hombres investigados por el asesinato de una regidora de Texhuacan y su esposo","c":"seguridad","f":"2026-11-22T18:54","r":"La Fiscalía de Veracruz detuvo en Acontla a Fabián ‘N’, Vicente Paul ‘N’ y Manuel Yair ‘N’, a quienes se les aseguraron armas, droga y tres motocicletas. Se investiga su posible relación con el ataque del 14 de noviembre en el que murieron la regidora de San Juan Texhuacan, Juana Tzanahua Hernández, y su esposo, Gervacio Hernández Mellado, dirigente local del PRI. En el operativo participaron Defensa, Guardia Nacional y la SSP.","b":"","img":"carretera","foto":"","cred":"","src":[["Veracruz en Red","https://veracruzenred.mx/detienen-a-tres-presuntos-asesinos-de-la-regidora-y-del-lider-local-del-pri-en-texhuacan"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-guasave-reporta-robos-a-tiendas-y-ocho-asesinatos-en-la-jornada-de-est","t":"Guasave reporta robos a tiendas y ocho asesinatos en la jornada de este domingo","c":"estados","f":"2026-11-22T18:53","r":"Reportes policiales documentan ocho hombres asesinados con armas de fuego durante el domingo en distintos puntos de Guasave, Sinaloa, entre ellos tres hallados junto a una camioneta cerca del estadio de Guasavito. También se reportaron robos en tiendas de conveniencia, con mercancía y unos 9 mil pesos en efectivo sustraídos, y daños a varias sucursales. La Fiscalía del estado está a cargo de las investigaciones.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Meganoticias","https://www.meganoticias.mx/culiacan/noticia/guasave-registra-robos-a-comercios-y-unos-8-muertos-tras-jornada-violenta/791077"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-chiapas-ofrece-empleo-temporal-en-tapachula-a-migrantes-de-la-caravana","t":"Chiapas ofrece empleo temporal en Tapachula a migrantes de la caravana tras la amenaza arancelaria de Trump","c":"estados","f":"2026-11-22T18:52","r":"El gobierno de Chiapas impulsa un esquema de empleo temporal en Tapachula para integrantes de la caravana ‘Dios con Nosotros’, con jornadas de cinco horas de lunes a viernes, apoyo económico semanal y estancia temporal ante el INM. La caravana salió de Tapachula el 10 de noviembre con unas 2 mil personas. El presidente Trump amenazó el 12 de noviembre con duplicar aranceles a México si no frena las caravanas.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/mexico/2026/11/22/chiapas-ofrece-empleo-a-migrantes-en-tapachula-tras-amenaza-de-trump/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-aguinaldo-2026-los-patrones-tienen-hasta-el-20-de-diciembre-para-pagar","t":"Aguinaldo 2026: los patrones tienen hasta el 20 de diciembre para pagar al menos 15 días de salario","c":"economia","f":"2026-11-22T18:51","r":"La Profedet recordó que el aguinaldo debe entregarse antes del 20 de diciembre y que el mínimo legal es de 15 días de salario, según el artículo 87 de la Ley Federal del Trabajo. Con el salario mínimo general de 2026, de 315.04 pesos diarios, quien trabajó todo el año debe recibir al menos 4 mil 725.60 pesos. Quienes laboraron solo una parte del año tienen derecho a la parte proporcional.","b":"","img":"bolsa","foto":"","cred":"","src":[["Por Esto!","https://www.poresto.com/mexico/2026/11/19/aguinaldo-fecha-limite-pago-calcular-cuanto-corresponde.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-tras-el-buen-fin-llegan-el-black-friday-el-viernes-27-y-el-cyber-monda","t":"Tras el Buen Fin llegan el Black Friday, el viernes 27, y el Cyber Monday, el lunes 30 de noviembre","c":"economia","f":"2026-11-22T18:50","r":"Luego de que El Buen Fin concluyó el 17 de noviembre, comercios en México se preparan para el Black Friday del viernes 27 y el Cyber Monday del lunes 30; varios extenderán sus promociones hasta el domingo 29. El primero abarca electrodomésticos, ropa, muebles y juguetes, mientras que el segundo se concentra en tecnología y compras en línea. Se recomienda fijar un presupuesto, comparar precios y verificar que las tiendas en línea sean oficiales.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/22/black-friday-y-cyber-monday-2026-cuando-son-y-cuales-son-sus-diferencias-en-mexico/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-academica-de-la-unam-describe-como-cautelosa-la-postura-de-mexico-ante","t":"Académica de la UNAM describe como “cautelosa” la postura de México ante China tras la cumbre APEC","c":"politica","f":"2026-11-22T18:49","r":"La catedrática de la UNAM Eva Luna calificó de cautelosa la participación de la presidenta Sheinbaum en la cumbre APEC en Shenzhen y sostuvo que el gobierno no puede arriesgar su relación con Estados Unidos, que concentra la mayor parte del comercio mexicano. Advirtió que la presión de Washington en seguridad podría traducirse en más aranceles, y propuso diversificar mercados con una política exterior activa.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/22/el-coqueteo-con-cautela-asi-describe-una-experta-de-la-unam-la-postura-de-mexico-ante-china/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-especialistas-de-la-unam-la-inteligencia-artificial-y-los-centros-de-d","t":"Especialistas de la UNAM: la inteligencia artificial y los centros de datos marcarán la relación México-EU","c":"tecnologia","f":"2026-11-22T18:48","r":"En una mesa redonda del CISAN de la UNAM, su director, Juan Carlos Barrón Pastor, advirtió que los centros de datos presionan la energía y el agua en Texas, Arizona y el norte de México. Otros académicos señalaron que las cadenas de suministro ahora priorizan la seguridad sobre el costo. La nota recuerda que ambos países suman 56 reuniones técnicas de negociación comercial.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/22/mexico-y-estados-unidos-por-que-la-inteligencia-artificial-y-la-tecnologia-marcaran-el-futuro-de-la-relacion-bilateral/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-la-cop31-cierra-con-el-pacto-de-antalya-sin-mencionar-los-combustibles","t":"La COP31 cierra con el “Pacto de Antalya” sin mencionar los combustibles fósiles; la UE lo rechaza","c":"internacional","f":"2026-11-22T18:47","r":"La cumbre climática COP31 en Antalya, Turquía, terminó fuera de plazo tras unos 13 días de negociaciones estancadas, con un texto final que no menciona de forma directa los combustibles fósiles. La Unión Europea rechazó el borrador de la presidencia turca y Panamá lo objetó formalmente. La ministra francesa Monique Barbut lo calificó como un retroceso inaceptable.","b":"","img":"ultimahora","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/22/temas-del-dia-de-efe-internacional-del-domingo-22-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-zelenski-pide-mas-interceptores-para-los-patriot-tras-el-derrumbe-en-d","t":"Zelenski pide más interceptores para los Patriot tras el derrumbe en Dimer; confirma cuatro muertos","c":"internacional","f":"2026-11-22T18:46","r":"Tras el ataque ruso con drones que derribó parte de un edificio de cinco pisos en Dimer, región de Kiev, el presidente Volodímir Zelenski informó que cuatro personas murieron y que aún no hay datos de otras diez. Pidió más misiles interceptores PAC-2 y PAC-3 para las baterías Patriot y señaló que en la última semana Rusia lanzó unos 2,700 drones, cerca de 1,460 bombas guiadas y 165 misiles.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Mundiario","https://www.mundiario.com/internacional/ucrania-busca-14-desaparecidos-derrumbe-edificio-ataque-ruso/20261122220927454382.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-un-barco-ruso-arde-en-el-golfo-de-finlandia-tras-un-ataque-con-drones","t":"Un barco ruso arde en el golfo de Finlandia tras un ataque con drones atribuido a Ucrania","c":"internacional","f":"2026-11-22T18:45","r":"El buque ruso Sparta II sufre un incendio en el golfo de Finlandia tras un ataque con drones que Moscú y Helsinki atribuyen a Ucrania. En paralelo, Kiev afirma haber derribado o neutralizado 161 drones Shahed, mientras Moscú asegura que neutralizó 170 drones ucranianos sobre siete regiones rusas y Crimea.","b":"","img":"ultimahora","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/22/temas-del-dia-de-efe-internacional-del-domingo-22-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-una-falla-en-el-sistema-de-delta-retrasa-cientos-de-vuelos-sobre-todo","t":"Una falla en el sistema de Delta retrasa cientos de vuelos, sobre todo en Atlanta","c":"internacional","f":"2026-11-22T18:44","r":"Una falla en el sistema automatizado que calcula peso y balance de los aviones antes del despegue impidió a Delta generar con normalidad las hojas de carga y retrasó cientos de vuelos, principalmente en el aeropuerto de Atlanta. La FAA llegó a detener los vuelos de Delta hacia esa ciudad y luego aplicó un programa de demoras en tierra con retrasos promedio de 57 minutos. La aerolínea opera con procedimientos manuales mientras restablece el sistema.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Semana","https://www.semana.com/mundo/articulo/atencion-viajeros-hay-retrasos-en-los-vuelos-de-la-aerolinea-delta-en-estados-unidos-hoy-22-de-noviembre/202638/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-santos-defiende-el-acuerdo-de-paz-con-las-farc-a-diez-anos-de-su-firma","t":"Santos defiende el acuerdo de paz con las FARC a diez años de su firma: asegura que ha salvado miles de vidas","c":"internacional","f":"2026-11-22T18:43","r":"El expresidente colombiano Juan Manuel Santos defendió en una entrevista con EFE el legado del acuerdo de paz firmado con la guerrilla de las FARC hace diez años, y aseguró que ha permitido salvar miles de vidas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/22/temas-del-dia-de-efe-internacional-del-domingo-22-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-liguilla-del-apertura-2026-atlas-toluca-el-unico-cruce-confirmado-el-c","t":"Liguilla del Apertura 2026: Atlas-Toluca, el único cruce confirmado; el Chivas-Cruz Azul define el liderato","c":"deportes","f":"2026-11-22T18:42","r":"Cruz Azul, América, Chivas, Atlas, Toluca, Monterrey, León y Pachuca son los ocho clasificados a la Liguilla. Cruz Azul llegó a la última jornada como líder con 32 puntos y necesitaba al menos empatar ante Chivas en el Estadio Akron para conservar el primer lugar; si gana el Rebaño, los cruces cambian. Los cuartos de final se jugarán el 25 y 26 de noviembre (ida) y el 28 y 29 (vuelta).","b":"","img":"estadio","foto":"","cred":"","src":[["Récord","https://www.record.com.mx/historia/estos-son-cuartos-de-final-apertura-2026-momento-2026112214583000509"],["La Silla Rota","https://lasillarota.com/deportes/2026/11/22/liguilla-liga-mx-apertura-2026-clasificados-cruces-y-fechas-538459.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-raphael-recibe-el-alta-tras-ser-llevado-al-hospital-y-cancelar-su-conc","t":"Raphael recibe el alta tras ser llevado al hospital y cancelar su concierto en A Coruña","c":"entretenimiento","f":"2026-11-22T18:41","r":"El cantante español Raphael, de 83 años, canceló su concierto del sábado en A Coruña y fue trasladado en ambulancia a un hospital por taquicardias y subida de tensión, según la nota. Recibió el alta el domingo tras pasar la noche en observación y escribió en redes que se encuentra mucho mejor. Tiene un concierto programado el 28 de noviembre en Málaga.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/22/fans-mexicanos-de-raphael-oran-por-el-tras-ser-llevado-al-hospital-de-emergencia-emiten-su-nuevo-parte-medico/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-la-comision-europea-confirma-que-en-el-ciberataque-que-sufrio-se-usaro","t":"La Comisión Europea confirma que en el ciberataque que sufrió se usaron herramientas de inteligencia artificial","c":"tecnologia","f":"2026-11-22T18:40","r":"El portavoz Thomas Regnier confirmó que en el ciberataque detectado el 22 de octubre contra la Comisión Europea se emplearon herramientas de IA, sin precisar cuáles. Bruselas desconectó varias aplicaciones internas y durante al menos diez días se afectaron trámites del personal como nóminas y vacaciones, aunque los salarios se pagaron con normalidad. La investigación sigue abierta y no se ha atribuido la autoría.","b":"","img":"tech2","foto":"","cred":"","src":[["El Nacional","https://www.elnacional.cat/es/tecnologia/inteligencia-artificial-ya-se-utiliza-atacar-gobiernos-comision-europea-confirma-ciberataque_1729460_102.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-ejercito-activa-un-plan-para-restablecer-la-paz-en-sinaloa-tras-la-cai","t":"Ejército activa un plan para restablecer la paz en Sinaloa tras la caída de ‘El Chapo Isidro’","c":"seguridad","f":"2026-11-22T06:59","r":"Luego de la captura de Fausto Isidro Meza Flores en Guasave, las Fuerzas Armadas y la Guardia Nacional pusieron en marcha un dispositivo de seguridad con las unidades conocidas como Murciélagos y Lobos. Según el reporte, el plan antibloqueo, junto con la Secretaría de Seguridad estatal, despejó los cierres carreteros registrados en Ahome, Guasave, Navolato y Guamúchil. Cinco de los detenidos en el operativo quedaron a disposición de la FGR en Culiacán.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Zolo Noticias","https://www.zolonoticias.com/2026/11/22/ejercito-implementa-plan-para-restaurar-la-paz-en-sinaloa/"],["Excélsior","https://www.excelsior.com.mx/nacional/ejercito-activa-plan-para-restaurar-paz"]],"dest":true,"a":"Redacción"},{"id":"2026-11-22-especialistas-preven-fragmentacion-y-mas-violencia-en-sinaloa-gobierno","t":"Especialistas prevén fragmentación y más violencia en Sinaloa; gobierno estatal asegura que la situación está bajo control","c":"nacional","f":"2026-11-22T06:58","r":"Académicos consultados por El Informador, Anuar Salvador García y Francisco Jiménez Reynoso, anticipan una reconfiguración de grupos criminales tras la captura de ‘El Chapo Isidro’, con posibles movimientos de Los Chapitos o de otras organizaciones. La gobernadora interina Graciela Domínguez Nava afirmó que la situación está controlada, aunque los autobuses entre Los Mochis y Culiacán seguían suspendidos. El embajador de EU, Ronald Johnson, elogió la cooperación bilateral en el operativo.","b":"","img":"palacio","foto":"","cred":"","src":[["El Informador","https://www.informador.mx/captura-de-el-chapo-isidro-aviva-la-disputa-por-sinaloa-l202611220003.html"]],"dest":true,"a":"Redacción"},{"id":"2026-11-22-gasolina-magna-se-queda-sin-estimulo-fiscal-pagara-6-70-pesos-de-ieps","t":"Gasolina Magna se queda sin estímulo fiscal: pagará 6.70 pesos de IEPS por litro esta semana","c":"economia","f":"2026-11-22T06:57","r":"La Secretaría de Hacienda retiró por completo el estímulo al IEPS de la Magna y la Premium para la semana del 21 al 27 de noviembre, por lo que la cuota de la Magna sube a 6.70 pesos por litro y la de la Premium queda en 5.66. El diésel pagará 0.80 pesos por litro tras diez semanas con cuota cero. El precio de la Magna se mantiene con el tope voluntario de 24 pesos por litro.","b":"","img":"pemex","foto":"","cred":"","src":[["Expansión","https://expansion.mx/economia/2026/11/20/gasolinas-magna-hacienda-quita-subsidio-sube-ieps-diesel"],["El Imparcial","https://www.elimparcial.com/dinero/2026/11/21/secretaria-de-hacienda-retiro-todo-el-estimulo-fiscal-a-la-gasolina-magna-del-21-al-27-de-noviembre-por-lo-que-automovilistas-pagaran-la-cuota-maxima-de-670-pesos-de-ieps-por-litro/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-22-beltrones-propone-que-el-consejo-del-ine-designe-a-sus-altos-mandos-po","t":"Beltrones propone que el Consejo del INE designe a sus altos mandos por mayoría calificada y vote en público contratos millonarios","c":"politica","f":"2026-11-22T06:56","r":"El senador Manlio Fabio Beltrones presentó una reforma constitucional para que el Consejo General del INE nombre a sus altos funcionarios por mayoría calificada y vote de forma pública los contratos superiores a 10 millones de pesos. La propuesta llega en medio del desacuerdo en San Lázaro para elegir a la nueva presidencia del instituto; el senador morenista Ignacio Mier abrió la posibilidad de que la presidenta interina Blanca Cruz siga en el cargo durante el proceso de 2027.","b":"","img":"ine","foto":"","cred":"","src":[["Síntesis legislativa (Sociedad Noticias)","https://sociedad-noticias.com/2026/11/22/sintesis-de-informacion-legislativa-domingo-22-de-noviembre-de-2026/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-22-ariadna-montiel-atribuye-a-programas-sociales-la-salida-de-17-3-millon","t":"Ariadna Montiel atribuye a programas sociales la salida de 17.3 millones de personas de la pobreza","c":"politica","f":"2026-11-22T06:55","r":"Ariadna Montiel, de Morena, afirmó con cifras del Banco Mundial que 17.3 millones de personas dejaron la pobreza monetaria entre 2018 y 2026, lo que atribuyó a los programas sociales y al aumento del salario mínimo. Señaló que el Presupuesto 2027, de 10.6 billones de pesos, destina más de un billón a programas de bienestar y 1.1 billones a inversión pública.","b":"","img":"palacio","foto":"","cred":"","src":[["Síntesis legislativa (Sociedad Noticias)","https://sociedad-noticias.com/2026/11/22/sintesis-de-informacion-legislativa-domingo-22-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-patricia-mercado-anuncia-iniciativa-para-regular-el-uso-de-motocicleta","t":"Patricia Mercado anuncia iniciativa para regular el uso de motocicletas","c":"politica","f":"2026-11-22T06:54","r":"La diputada de Movimiento Ciudadano y presidenta de la Comisión de Movilidad, Patricia Mercado, anunció una iniciativa para regular las motocicletas. Indicó que 25% de los accidentes viales involucran a motociclistas, aunque aclaró que no necesariamente son los responsables.","b":"","img":"senado","foto":"","cred":"","src":[["Síntesis legislativa (Sociedad Noticias)","https://sociedad-noticias.com/2026/11/22/sintesis-de-informacion-legislativa-domingo-22-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-encuesta-de-banxico-64-de-los-analistas-ve-mejor-la-economia-que-hace","t":"Encuesta de Banxico: 64% de los analistas ve mejor la economía que hace un año, destaca Gerardo Esquivel","c":"economia","f":"2026-11-22T06:53","r":"En la cumbre empresarial de Concanaco Servytur en Tijuana, el exsubgobernador de Banxico Gerardo Esquivel expuso que la proporción de especialistas que perciben una economía mejor que un año antes pasó de 46% en septiembre a 64% en octubre. Recordó que la inflación bajó de un máximo de 8.70% a 3.75% y la tasa de referencia de 11.25% a 6.25%, y que las previsiones de crecimiento para 2026 han mejorado.","b":"","img":"bolsa","foto":"","cred":"","src":[["Cúspide México","https://cuspidemexico.com/2026/11/21/economia-de-mexico-2026-27-senales-de-recuperacion-gerardo-esquivel-en-la-cumbre-de-concanaco-servytur/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-fovissste-preve-hasta-61-mil-financiamientos-de-vivienda-en-2027","t":"Fovissste prevé hasta 61 mil financiamientos de vivienda en 2027","c":"economia","f":"2026-11-22T06:52","r":"El programa de financiamiento del Fovissste para 2027, publicado en el Diario Oficial, contempla hasta 61 mil créditos: 48 mil hipotecarios y 13 mil para otros fines de vivienda, por un monto de hasta 39,816.6 millones de pesos.","b":"","img":"imss","foto":"","cred":"","src":[["Síntesis legislativa (Sociedad Noticias)","https://sociedad-noticias.com/2026/11/22/sintesis-de-informacion-legislativa-domingo-22-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-eu-emite-alerta-de-viaje-por-la-violencia-en-sinaloa-y-pide-evitar-car","t":"EU emite alerta por la violencia en Sinaloa y pide evitar la carretera","c":"seguridad","f":"2026-11-22T06:51","r":"El gobierno de Estados Unidos emitió una alerta para sus ciudadanos por la violencia en Sinaloa tras la captura de ‘El Chapo Isidro’ y les recomendó evitar la carretera en la zona, informó UnoTV.","b":"","img":"carretera","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/internacional/ee-uu-emite-alerta-por-violencia-en-sinaloa-tras-captura-de-chapo-isidro-pide-evitar-carretera/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-hallan-cuerpos-calcinados-y-tres-hombres-asesinados-en-guasave-bajo-fu","t":"Hallan cuerpos calcinados y tres hombres asesinados en Guasave, bajo fuerte despliegue militar","c":"estados","f":"2026-11-22T06:50","r":"En Guasave, Sinaloa, donde se mantiene un amplio despliegue militar tras el operativo contra ‘El Chapo Isidro’, se reportó el hallazgo de cuerpos calcinados y de tres hombres asesinados, según UnoTV.","b":"","img":"ultimahora","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/sinaloa/guasave-bajo-fuerte-despliegue-militar-hallan-cuerpos-calcinados-y-tres-hombres-asesinados/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-frente-frio-8-trae-lluvias-a-31-estados-y-minimas-de-hasta-10-grados-e","t":"Frente frío 8 trae lluvias a 31 estados y mínimas de hasta -10 grados este domingo","c":"estados","f":"2026-11-22T06:49","r":"El Servicio Meteorológico Nacional prevé lluvias en 31 estados por el frente frío 8, con acumulados de 50 a 75 milímetros en Tamaulipas y de 25 a 50 en Nuevo León, San Luis Potosí y Veracruz. En sierras de Baja California y Durango se esperan mínimas de -10 a -5 grados, y rachas de 40 a 60 km/h en Coahuila y Tamaulipas. En contraste, Michoacán, Guerrero, Oaxaca y Chiapas tendrán máximas de 35 a 40 grados.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/pronostico-clima-mexico-22-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-domingo-lluvioso-en-la-capital-chubascos-por-la-tarde-y-alerta-amarill","t":"Domingo lluvioso en la capital: chubascos por la tarde y alerta amarilla por frío en seis alcaldías","c":"cdmx","f":"2026-11-22T06:48","r":"Para la Ciudad de México se pronostica una mínima de 10 a 12 grados y una máxima de 23 a 25, con chubascos y descargas eléctricas por la tarde. Las autoridades activaron la alerta amarilla por frío en seis alcaldías, donde la temperatura podría bajar hasta 4 grados.","b":"","img":"zocalo","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/pronostico-clima-mexico-22-noviembre/"],["UnoTV","https://www.unotv.com/clima/alerta-amarilla-por-frio-para-6-alcaldias-cdmx-temperaturas-bajaran-hasta-4-grados/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-ssc-detiene-a-17-personas-por-presunta-reventa-de-boletos-en-el-corona","t":"SSC detiene a 17 personas por presunta reventa de boletos en el Corona Capital","c":"cdmx","f":"2026-11-22T06:47","r":"La Secretaría de Seguridad Ciudadana capitalina detuvo a 17 personas señaladas por revender boletos en el festival Corona Capital 2026, que se realiza en el Autódromo Hermanos Rodríguez, informó UnoTV.","b":"","img":"autodromo","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/ciudad-de-mexico/detencion-reventa-boletos-corona-capital/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-caso-joselyn-rocha-detienen-a-israel-n-por-el-atropellamiento","t":"Caso Joselyn Rocha: detienen a Israel ‘N’ por el atropellamiento","c":"cdmx","f":"2026-11-22T06:46","r":"Fue detenido Israel ‘N’, señalado como presunto responsable del atropellamiento de Joselyn Rocha en la Ciudad de México; se le acusa de homicidio doloso, según UnoTV.","b":"","img":"zocalo","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/ciudad-de-mexico/detienen-conductor-atropello-joselyn-rocha/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-ataque-ruso-con-drones-derrumba-parte-de-un-edificio-cerca-de-kiev-14","t":"Ataque ruso con drones derrumba parte de un edificio cerca de Kiev; 14 personas siguen sin localizar","c":"internacional","f":"2026-11-22T06:45","r":"Un ataque nocturno destruyó una sección de un edificio de cinco pisos en Dymer, en la región de Kiev. Los rescatistas sacaron a nueve personas, entre ellas un niño, y el presidente Volodímir Zelenski informó que 14 personas no han sido localizadas. Rusia lanzó 186 drones durante la noche; la defensa ucraniana neutralizó 161, de acuerdo con el reporte.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Ukraine desk note","https://oskarhallgrimsson.substack.com/p/ukraine-desk-note-22-november-2026"],["Kyiv Independent","https://kyivindependent.com/apartment-building-destroyed-in-kyiv-oblast-following-russian-drone-attack/"],["Euronews","https://es.euronews.com/video/2026/11/22/ucrania-hasta-7-atrapados-bajo-los-escombros-tras-un-ataque-de-dron-ruso-cerca-de-kiev"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-reino-unido-financiara-y-fabricara-drones-ucranianos-de-ataque-de-larg","t":"Reino Unido financiará y fabricará drones ucranianos de ataque de largo alcance","c":"internacional","f":"2026-11-22T06:44","r":"El ministro de Defensa de Ucrania, Yevhenii Khmara, y el secretario de Defensa británico, Wes Streeting, firmaron acuerdos para producir en territorio británico drones ucranianos de ataque de medio y largo alcance, con financiamiento del Reino Unido.","b":"","img":"tech","foto":"","cred":"","src":[["Kyiv Independent","https://kyivindependent.com/uk-to-produce-middle-strike-long-range-drones-for-ukraine-in-britain/"],["Ukraine desk note","https://oskarhallgrimsson.substack.com/p/ukraine-desk-note-22-november-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-incendio-en-una-fabrica-de-indonesia-deja-al-menos-tres-muertos-y-36-d","t":"Incendio en una fábrica de Indonesia deja al menos tres muertos y 36 desaparecidos","c":"internacional","f":"2026-11-22T06:43","r":"El fuego comenzó el sábado por la tarde en una planta de la empresa PT Fonusa Agung Mulia, en Cikande, provincia de Banten, al oeste de Yakarta. El responsable del operativo, Rizky Dwianto, reportó tres muertos, 36 desaparecidos y cuatro heridos; la policía dijo que 42 personas no han podido ser contactadas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/22/al-menos-tres-muertos-y-36-desaparecidos-tras-el-incendio-en-una-fabrica-de-indonesia/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-monterrey-vence-2-0-a-pumas-en-cu-y-se-queda-con-el-ultimo-boleto-a-la","t":"Monterrey vence 2-0 a Pumas en CU y se queda con el último boleto a la Liguilla","c":"deportes","f":"2026-11-22T06:42","r":"Con dos goles de Luca Orellano, al minuto 74 y en tiempo de compensación, Rayados ganó en el Olímpico Universitario pese a jugar con diez por la expulsión de Carlos Salcedo; Álvaro Angulo también fue expulsado. Pumas terminó el Apertura 2026 en el undécimo lugar con 21 puntos y quedó eliminado; su técnico, Esteban Solari, pidió disculpas a la afición.","b":"","img":"unam","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/11/22/fracaso-de-pumas-en-la-liga-mx-esteban-solari-pide-perdon-a-la-aficion-tras-perder-2-0-ante-monterrey-quedar-fuera-de-la-liguilla/"],["La Razón","https://www.razon.com.mx/deportes/2026/11/21/monterrey-derrota-a-pumas-y-se-convierte-en-el-ultimo-invitado-a-la-liguilla-del-apertura-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-verstappen-gana-el-gran-premio-de-las-vegas-checo-perez-abandona-tras","t":"Verstappen gana el Gran Premio de Las Vegas; Checo Pérez abandona tras un choque","c":"deportes","f":"2026-11-22T06:41","r":"Max Verstappen ganó en Las Vegas por tercera vez en cuatro años, 0.639 segundos delante de Lando Norris, en una carrera con 35 cambios de líder; Oscar Piastri fue tercero tras salir 17. Sergio Pérez, de Cadillac, chocó con Rafael Câmara y abandonó en la vuelta 17. Restan los grandes premios de Qatar y Abu Dabi.","b":"","img":"autodromo","foto":"","cred":"","src":[["Al Jazeera","https://www.aljazeera.com/sports/2026/11/22/max-verstappen-las-vegas-grand-prix-f1-norris-piastri-russell-antonelli"],["El Imparcial","https://www.elimparcial.com/deporte/2026/11/21/quien-gano-el-gp-de-las-vegas-2026-resultados-completos-de-la-carrera-de-formula-1/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-22-boca-juniors-gana-la-copa-sudamericana-en-barranquilla-su-capitan-pare","t":"Boca Juniors gana la Copa Sudamericana en Barranquilla; su capitán Paredes se desvanece en una entrevista","c":"deportes","f":"2026-11-22T06:40","r":"Boca Juniors se coronó en la final ante Atlético Mineiro en el estadio Metropolitano Roberto Meléndez. Su capitán, Leandro Paredes, se desvaneció mientras daba una entrevista, fue atendido de inmediato y caminó por su cuenta al vestidor; el técnico Rodolfo Arruabarrena explicó que se sentía mareado desde el medio tiempo, con cerca de 30 grados y 80% de humedad.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/deportes/2026/11/22/leandro-paredes-se-descompenso-en-medio-de-una-entrevista-tras-ganar-la-copa-sudamericana-con-boca-juniors-en-barranquilla/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-captura-de-el-chapo-isidro-deja-11-muertos-en-guasave-cuatro-militares","t":"Captura de ‘El Chapo Isidro’ deja 11 muertos en Guasave: cuatro militares y siete agresores","c":"seguridad","f":"2026-11-21T18:59","r":"La Defensa informó que el operativo para detener a Fausto Isidro Meza Flores, ‘El Chapo Isidro’, en Guasave, Sinaloa, dejó 11 personas muertas: cuatro integrantes del Ejército y siete presuntos agresores. En total hubo ocho detenidos y se aseguraron un fusil Barrett calibre .50, diez armas de distintos calibres, un lanzagranadas y dos granadas de mano. Omar García Harfuch lamentó la muerte de los soldados y dijo que su “valentía y heroísmo” merecen reconocimiento.","b":"","img":"ultimahora","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/captura-del-chapo-isidro-deja-11-muertos-en-sinaloa-cuatro-eran-militares/"],["Récord","https://www.record.com.mx/historia/captura-de-el-chapo-isidro-deja-11-muertos-en-sinaloa-defensa-confirma-bajas-militares-2026112121261861839"]],"dest":true,"a":"Redacción"},{"id":"2026-11-21-la-dea-llama-victoria-significativa-la-captura-de-el-chapo-isidro-harf","t":"La DEA llama “victoria significativa” la captura de ‘El Chapo Isidro’; Harfuch habla de un paso hacia la pacificación de Sinaloa","c":"nacional","f":"2026-11-21T18:58","r":"La agencia antidrogas de Estados Unidos calificó la detención de Meza Flores como una victoria importante contra una de las redes criminales más violentas de México. El secretario de Seguridad, Omar García Harfuch, la describió como un paso para pacificar Sinaloa. El operativo de Fuerzas Especiales del Ejército y la Guardia Nacional contó con apoyo de inteligencia estadounidense; el detenido figuraba entre los 10 más buscados del FBI, con una recompensa de hasta 5 millones de dólares.","b":"","img":"palacio","foto":"","cred":"","src":[["Mexico News Daily","https://mexiconewsdaily.com/news/chapo-isidro-capture-sinaloa/"],["SinEmbargo","https://sinembargo.mx/4907585/del-rumor-a-la-resistencia-armada-asi-derrotaron-a-el-chapo-isidro-cronologia"]],"dest":true,"a":"Redacción"},{"id":"2026-11-21-el-dolar-se-vende-en-19-62-pesos-en-ventanilla-su-nivel-mas-alto-desde","t":"El dólar se vende en 19.62 pesos en ventanilla, su nivel más alto desde junio del año pasado","c":"economia","f":"2026-11-21T18:57","r":"Al cierre del viernes, Banamex vendió el dólar en 19.62 pesos, BBVA en 19.66 y Banorte en 19.55, mientras que en el mercado de mayoreo la paridad terminó en 19.18, tras tres alzas seguidas. En la semana, la divisa estadounidense ganó 3.5%, su mayor avance desde agosto de 2024. Analistas consultados por El Universal atribuyen el movimiento al cambio de expectativas sobre las tasas en EU y México, y uno de ellos no descarta que llegue a 20 pesos si surgen nuevas tensiones comerciales.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Universal (vía Yahoo Noticias)","https://es-us.noticias.yahoo.com/d%C3%B3lar-toma-vuelo-amenaza-llegar-060000552.html"]],"dest":true,"a":"Redacción"},{"id":"2026-11-21-eu-acusa-a-21-integrantes-de-la-nueva-familia-michoacana-senala-que-co","t":"EU acusa a 21 integrantes de La Nueva Familia Michoacana; señala que controlan minas en Guerrero","c":"seguridad","f":"2026-11-21T18:56","r":"La Fiscalía Federal del Distrito Oeste de Texas presentó en Del Río una acusación contra 21 presuntos miembros de La Nueva Familia Michoacana, entre ellos los hermanos Johnny y José Alfredo Hurtado Olascoaga, ‘El Pez’ y ‘El Fresa’. Los cargos incluyen narcotráfico, tráfico de personas, lavado de dinero y apoyo material a una organización terrorista. Cinco están bajo custodia y 16 siguen prófugos; según la acusación, el grupo controla minas como Campo Morado, en Guerrero, y cambia minerales por precursores químicos de empresas chinas.","b":"","img":"texas","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/20/eu-anuncia-acusaciones-contra-21-la-nueva-familia-michoacana"],["La Razón","https://www.razon.com.mx/mexico/2026/11/20/eu-presenta-acusacion-contra-21-integrantes-de-la-nueva-familia-michoacana/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-21-el-chapo-isidro-llega-a-la-femdo-en-la-cdmx-otros-cinco-detenidos-qued","t":"‘El Chapo Isidro’ llega a la FEMDO en la CDMX; otros cinco detenidos quedan en Culiacán","c":"nacional","f":"2026-11-21T18:55","r":"Meza Flores, junto con Germán ‘N’, alias ‘Serafín’, señalado como su segundo al mando, y José ‘N’, presunto operador financiero, llegó a la Ciudad de México hacia las 5:20 horas del sábado en una aeronave de la Fuerza Aérea y fue llevado a la Fiscalía Especializada en Delincuencia Organizada. Los otros cinco detenidos del operativo quedaron a disposición de la FGR en Culiacán. En México tiene orden de aprehensión por delincuencia organizada y delitos contra la salud, y EU pide su extradición.","b":"","img":"palacio","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/captura-del-chapo-isidro-deja-11-muertos-en-sinaloa-cuatro-eran-militares/"],["Infobae","https://www.infobae.com/mexico/2026/11/21/el-chapo-isidro-llega-a-la-femdo-bajo-fuerte-operativo-militar-tras-su-captura-en-guasave/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-sinaloa-reabre-90-de-sus-vialidades-tras-la-noche-de-bloqueos-en-guasa","t":"Sinaloa reabre 90% de sus vialidades tras la noche de bloqueos en Guasave, Ahome y Navolato","c":"estados","f":"2026-11-21T18:54","r":"El gobierno de Sinaloa informó a las 14:18 horas que el 90% de las vialidades afectadas ya estaba reabierto, luego de los narcobloqueos, balaceras e incendios de vehículos y comercios que siguieron a la captura de ‘El Chapo Isidro’. La primera alerta para que la población se resguardara se emitió a las 21:07 del viernes, y durante la madrugada la gobernadora interina Graciela Domínguez Nava reportó personas varadas en carreteras.","b":"","img":"carretera","foto":"","cred":"","src":[["SinEmbargo","https://sinembargo.mx/4907585/del-rumor-a-la-resistencia-armada-asi-derrotaron-a-el-chapo-isidro-cronologia"],["Mexico News Daily","https://mexiconewsdaily.com/news/chapo-isidro-capture-sinaloa/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-sheinbaum-encabeza-la-entrega-de-becas-para-el-bienestar-en-villanueva","t":"Sheinbaum encabeza la entrega de Becas para el Bienestar en Villanueva, Zacatecas","c":"nacional","f":"2026-11-21T18:53","r":"La presidenta Claudia Sheinbaum realizó este sábado un evento de Becas para el Bienestar, dirigido a estudiantes de escuelas públicas, en la Unidad Deportiva Domingo González de Villanueva, Zacatecas. Es su tercera gira por el estado en 2026, después de las de julio y septiembre. Las autoridades no detallaron el número de beneficiarios.","b":"","img":"palacio","foto":"","cred":"","src":[["Por Esto!","https://www.poresto.com/mexico/2026/11/21/sheinbaum-visita-zacatecas-noviembre-encabezar-entrega-becas-bienestar-villanueva-vivo.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-morena-cierra-hoy-el-registro-para-sus-coordinaciones-distritales-loca","t":"Morena cierra hoy el registro para sus coordinaciones distritales locales en 31 estados","c":"politica","f":"2026-11-21T18:52","r":"El registro en línea de aspirantes a las coordinaciones distritales locales de Morena, abierto el 18 de noviembre, concluye este sábado 21. Se definirán perfiles para 664 distritos locales en 31 entidades, todas excepto Coahuila, rumbo a las elecciones de diputados locales de 2027. El partido aclaró que inscribirse no garantiza la selección y que la coordinación no equivale a una candidatura; los registros aprobados se publicarán a más tardar el 31 de enero de 2027.","b":"","img":"senado","foto":"","cred":"","src":[["Por Esto!","https://www.poresto.com/mexico/2026/11/18/morena-abre-registro-rumbo-elecciones-fechas-requisitos-participar.html"],["Zeta Tijuana","https://zetatijuana.com/2026/11/morena-se-alista-para-definir-mas-de-600-coordinaciones-distritales-a-nivel-local/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-encuesta-citi-analistas-suben-a-3-96-la-inflacion-esperada-para-el-cie","t":"Encuesta Citi: analistas suben a 3.96% la inflación esperada para el cierre de 2026 y ven el dólar en 18.67","c":"economia","f":"2026-11-21T18:51","r":"La Encuesta Citi de Expectativas del 20 de noviembre, con 34 participantes, elevó la mediana de inflación general para fin de año de 3.90% a 3.96%, y la subyacente de 3.80% a 3.86%. El tipo de cambio esperado al cierre de 2026 pasó de 18.50 a 18.67 pesos por dólar. El pronóstico de crecimiento se mantuvo en 1.8% para 2026 y 1.9% para 2027, y la tasa de Banxico esperada al cierre de año bajó a 6.25%.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/economia/2026/11/20/economistas-esperan-inflacion-alta-y-depreciacion-del-peso-para-el-cierre-de-2026-encuesta-citi/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-la-cop31-sigue-sin-acuerdo-en-su-dia-extra-panama-amenaza-con-bloquear","t":"La COP31 sigue sin acuerdo en su día extra; Panamá amenaza con bloquear un texto sin salida de los fósiles","c":"internacional","f":"2026-11-21T18:50","r":"La cumbre climática de Antalya, Turquía, que debía terminar el viernes, continuó este sábado sin consenso sobre los combustibles fósiles y el financiamiento para países en desarrollo. La cifra de 120 mil millones de dólares anuales desde 2035, incluida en el primer borrador, desapareció de la nueva versión. El comisario europeo Wopke Hoekstra advirtió que no habrá acuerdo si el texto no cambia, y Panamá dijo que bloqueará cualquier documento que no incluya el abandono de los fósiles.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Tiempo (AFP)","https://www.eltiempo.com/vida/medio-ambiente/cop31-se-prolonga-sin-acuerdo-por-diferencias-sobre-combustibles-fosiles-y-financiacion-climatica-3602986"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-trump-dice-que-es-pronto-para-hablar-de-garantias-de-seguridad-para-uc","t":"Trump dice que es pronto para hablar de garantías de seguridad para Ucrania sin un acuerdo de paz","c":"internacional","f":"2026-11-21T18:49","r":"En una conferencia en la Casa Blanca, el presidente de EU afirmó que las garantías para Kiev deben esperar a que exista un acuerdo de paz. Respondía al viceministro ruso Serguéi Riabkov, quien reiteró que Moscú considera inaceptable una cuasiadhesión de Ucrania a la OTAN. Trump dijo que Vladímir Putin quiere resolver el conflicto y señaló como principal obstáculo la enemistad entre Putin y Volodímir Zelenski.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/20/trump-es-pronto-para-hablar-de-garantias-de-seguridad-para-kiev-sin-un-acuerdo-de-paz"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-ataque-ruso-en-krivoi-rog-deja-dos-muertos-y-52-heridos-rusia-dice-hab","t":"Ataque ruso en Krivói Rog deja dos muertos y 52 heridos; Rusia dice haber derribado 275 drones","c":"internacional","f":"2026-11-21T18:48","r":"Un ataque ruso durante la noche contra la ciudad ucraniana de Krivói Rog causó dos muertos y 52 heridos, según la agenda internacional de EFE. Por su parte, Rusia informó que sus defensas antiaéreas derribaron 275 drones ucranianos sobre once regiones, Crimea y el mar Negro. Además, dos drones ucranianos atacaron un carguero ruso en el golfo de Finlandia que se dirigía a Kaliningrado.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/21/temas-del-dia-de-efe-internacional-del-sabado-21-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-tres-sismos-de-entre-4-1-y-4-3-se-registran-frente-a-las-costas-de-oax","t":"Tres sismos de entre 4.1 y 4.3 se registran frente a las costas de Oaxaca y Chiapas","c":"estados","f":"2026-11-21T18:47","r":"El Servicio Sismológico Nacional reportó este sábado un sismo de magnitud 4.3 a 148 kilómetros al suroeste de Ciudad Hidalgo, Chiapas, con profundidad de 10 kilómetros. Más tarde se registraron dos movimientos de magnitud 4.2 y 4.1 a 47 y 45 kilómetros al sureste de Crucecita, Oaxaca. No se reportaron daños.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Nación","https://www.lanacion.com.ar/estados-unidos/temblor-en-mexico-ultimos-reportes-de-sismos-hoy-sabado-21-de-noviembre-nid21112026/"],["Infobae","https://www.infobae.com/mexico/2026/11/21/temblor-hoy-en-mexico-noticias-actividad-sismica-21-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-gta-vi-habria-vendido-unos-17-millones-de-copias-en-su-estreno-segun","t":"GTA VI habría vendido unos 17 millones de copias en su estreno, según estimaciones de Sensor Tower","c":"tecnologia","f":"2026-11-21T18:46","r":"El videojuego Grand Theft Auto VI, lanzado el jueves 19 de noviembre, 13 años después de la entrega anterior, habría generado cerca de 1,650 millones de dólares y unos 17.07 millones de copias vendidas en su arranque, de acuerdo con cifras no oficiales de Sensor Tower. PlayStation 5 concentraría 75% de las unidades y Xbox Series X|S el 25% restante.","b":"","img":"tech","foto":"","cred":"","src":[["La Crónica de Hoy","https://www.cronica.com.mx/tendencias/2026/11/19/gta-vi-confirma-record-de-ganancias-el-dia-de-su-estreno-cuanto-dinero-ha-recaudado-para-rockstar/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-paises-acuerdan-in-extremis-abrir-negociaciones-formales-sobre-armas","t":"Países acuerdan in extremis abrir negociaciones formales sobre armas autónomas en Ginebra","c":"tecnologia","f":"2026-11-21T18:45","r":"Los 128 Estados parte de la Convención sobre Ciertas Armas Convencionales acordaron en Ginebra iniciar negociaciones formales sobre los sistemas de armas autónomas. El Comité Internacional de la Cruz Roja lamentó que no hubiera consenso para avanzar hacia un acuerdo jurídicamente vinculante.","b":"","img":"tech2","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/21/temas-del-dia-de-efe-internacional-del-sabado-21-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-gabriel-zucman-reune-en-paris-a-economistas-contra-la-concentracion-de","t":"Gabriel Zucman convoca en París una “Cumbre contra la Oligarquía Internacional” con un manifiesto firmado por cuatro Nobel","c":"economia","f":"2026-11-21T18:44","r":"El economista francés Gabriel Zucman encabezó este sábado en París una “Cumbre contra la Oligarquía Internacional”, donde presentó un manifiesto respaldado por cerca de un centenar de economistas, cuatro de ellos ganadores del Premio Nobel.","b":"","img":"paris","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/21/temas-del-dia-de-efe-internacional-del-sabado-21-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-la-ue-prohibe-exportar-desechos-plasticos-fuera-de-la-ocde-y-busca-rec","t":"La UE prohíbe exportar desechos plásticos fuera de la OCDE y busca recuperar materias primas de sus residuos","c":"internacional","f":"2026-11-21T18:43","r":"La comisaria europea de Medio Ambiente, Jessika Roswall, impulsa que la Unión Europea recupere materias primas a partir de sus residuos, en paralelo a la nueva prohibición de exportar desechos plásticos a países que no forman parte de la OCDE.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/21/temas-del-dia-de-efe-internacional-del-sabado-21-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-espanoles-en-el-extranjero-empiezan-a-votar-en-consulados-para-las-ele","t":"Españoles en el extranjero empiezan a votar en consulados para las elecciones generales del 29 de noviembre","c":"internacional","f":"2026-11-21T18:42","r":"Los españoles residentes en el exterior pueden votar en consulados desde este sábado hasta el jueves, de cara a las elecciones generales del 29 de noviembre. En Argentina hay más de medio millón de personas habilitadas, en medio de una polémica por una disposición judicial sobre los nacionalizados mediante la llamada ley de nietos.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/21/temas-del-dia-de-efe-internacional-del-sabado-21-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-la-piedra-oscura-regresa-a-los-teatros-de-la-cdmx-diez-anos-despues-de","t":"“La piedra oscura” regresa a los teatros de la CDMX diez años después de su estreno","c":"entretenimiento","f":"2026-11-21T18:41","r":"La obra “La piedra oscura” vuelve a la cartelera de la Ciudad de México una década después, con las actuaciones de Sergio Velasco y Jesús Zabala, informó la agencia EFE.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/21/temas-del-dia-de-efe-internacional-del-sabado-21-de-noviembre-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-suspenden-el-juego-venados-de-mazatlan-algodoneros-de-guasave-por-la","t":"Suspenden el juego Venados de Mazatlán-Algodoneros de Guasave por la violencia tras la captura de ‘El Chapo Isidro’","c":"deportes","f":"2026-11-21T18:40","r":"El partido de la Liga Mexicana del Pacífico entre Algodoneros de Guasave y Venados de Mazatlán, programado el viernes en el estadio Kuroda, fue suspendido por los disparos y bloqueos que se registraron en la ciudad durante el operativo federal.","b":"","img":"beisbol","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/estados/2026/11/21/balacera-guasave-en-vivo-violencia-sinaloa-ultimas-noticias/"],["Mexico News Daily","https://mexiconewsdaily.com/news/chapo-isidro-capture-sinaloa/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-la-defensa-confirma-la-captura-de-el-chapo-isidro-en-guasave-tambien-c","t":"La Defensa confirma la captura de ‘El Chapo Isidro’ en Guasave; también caen su segundo al mando y un operador financiero","c":"nacional","f":"2026-11-21T07:20","r":"La Secretaría de la Defensa Nacional confirmó que Fausto Isidro Meza Flores, ‘El Chapo Isidro’, señalado como jefe de la organización Beltrán Leyva y aliado de la facción de ‘Los Mayos’, fue detenido el viernes 20 en Guasave, Sinaloa, junto con Germán ‘N’, alias ‘Serafín’, y José ‘N’, presunto operador financiero. Según la dependencia, el operativo derivó de trabajo de inteligencia coordinado con Estados Unidos, el personal fue atacado con armas de fuego y explosivos, y los detenidos fueron trasladados a la Ciudad de México en un avión de la Fuerza Aérea. Meza Flores figura desde febrero de 2025 entre los diez más buscados del FBI, que ofrece hasta 5 millones de dólares por él.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/video-defensa-confirma-captura-chapo-isidro-sinaloa"],["Proceso","https://www.proceso.com.mx/nacional/estados/2026/11/21/reportan-la-captura-de-el-chapo-isidro-en-guasave-sinaloa-384102.html"]],"dest":true,"a":"Redacción"},{"id":"2026-11-21-trump-asegura-que-le-dijo-a-sheinbaum-que-los-carteles-manejan-mexico","t":"Trump asegura que le dijo a Sheinbaum que “los cárteles manejan México” y dice estar cerca de un acuerdo comercial","c":"politica","f":"2026-11-21T07:19","r":"En una conferencia de casi dos horas en la Casa Blanca, Donald Trump afirmó que en su reunión con la presidenta Claudia Sheinbaum en Shenzhen, al margen de la APEC, le dijo que no se puede permitir que los cárteles controlen a un país vecino. También sostuvo que Estados Unidos está cerca de cerrar un acuerdo comercial con México, aunque se quejó del superávit que México mantiene con su país, y dijo que ambos gobiernos trabajan juntos contra los cárteles.","b":"","img":"palacio","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/internacional/2026/11/20/los-carteles-manejan-mexico-se-lo-dije-trump-sobre-su-reunion-con-sheinbaum-en-china-384063.html"],["Infobae","https://www.infobae.com/mexico/2026/11/20/eeuu-esta-por-cerrar-acuerdo-comercial-con-mexico-pero-aun-preocupan-los-carteles-de-droga-dice-trump-tras-reunion-con-sheinbaum-en-apec/"],["CBS News","https://www.cbsnews.com/live-updates/trump-press-conference-live-stream-2026-11-20/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-21-mexico-rechaza-en-la-oea-que-se-use-el-tiar-contra-los-carteles-encina","t":"México rechaza en la OEA que se use el TIAR contra los cárteles; Encinas advierte que solo la ONU puede autorizar el uso de la fuerza","c":"politica","f":"2026-11-21T07:18","r":"En una sesión extraordinaria del Consejo Permanente de la OEA, 14 de los 18 países que siguen en el Tratado Interamericano de Asistencia Recíproca aprobaron convocar a su órgano de consulta para analizar medidas sin uso de fuerza armada contra el crimen organizado; Brasil y Uruguay votaron en contra. México, que abandonó el TIAR en 2002, no votó, y su representante Alejandro Encinas rechazó el término “narcoterrorismo” y recordó que solo el Consejo de Seguridad de la ONU puede autorizar el uso de la fuerza en otro país. La iniciativa surge de países del llamado ‘Escudo de las Américas’, encabezado por Estados Unidos.","b":"","img":"palacio","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/11/21/politica/009n2pol"]],"dest":true,"a":"Redacción"},{"id":"2026-11-21-entra-en-vigor-la-reforma-que-permite-a-la-cnie-condicionar-o-frenar-i","t":"Entra en vigor la reforma que permite a la CNIE condicionar o frenar inversiones extranjeras por seguridad nacional","c":"economia","f":"2026-11-21T07:17","r":"La reforma a la Ley de Inversión Extranjera, publicada el 19 de noviembre en el Diario Oficial, entró en vigor el día 20 y faculta a la Comisión Nacional de Inversiones Extranjeras para autorizar, condicionar o impedir adquisiciones en sectores como inteligencia artificial, semiconductores, ciberseguridad, energía, telecomunicaciones, minería y defensa. La Comisión tendrá 45 días hábiles para resolver y hasta el 18 de mayo de 2027 para fijar el umbral de activos que hará obligatoria la notificación; las multas irán de 5,000 a 200,000 veces la UMA. Morena defendió la reforma, mientras PAN, PRI y MC cuestionaron la certidumbre jurídica.","b":"","img":"bolsa","foto":"","cred":"","src":[["Publimetro","https://www.publimetro.com.mx/nacional/2026/11/19/mexico-control-inversion-extranjera-seguridad-nacional/"],["Expansión","https://expansion.mx/tecnologia/2026/11/19/gobierno-podra-frenar-inversion-extranjera-tecnologia"]],"dest":true,"a":"Redacción"},{"id":"2026-11-21-noche-de-bloqueos-y-balaceras-en-sinaloa-tras-el-operativo-en-guasave","t":"Noche de bloqueos y balaceras en Sinaloa tras el operativo en Guasave; la gobernadora interina pide a la población resguardarse","c":"estados","f":"2026-11-21T07:16","r":"Tras el ataque contra personal federal la noche del viernes en Guasave se reportaron balaceras, vehículos incendiados y narcobloqueos que se extendieron a Ahome, Guamúchil, Angostura, Salvador Alvarado y Navolato, incluidos cierres en la carretera México 15 entre Guasave y Los Mochis. La gobernadora interina, Graciela Domínguez Nava, y la Secretaría de Seguridad Pública estatal pidieron evitar La Costera y la carretera libre, y el juego entre Algodoneros de Guasave y Venados de Mazatlán de la Liga Mexicana del Pacífico fue suspendido. Al cierre de las notas consultadas no había un informe oficial de víctimas.","b":"","img":"carretera","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/estados/2026/11/21/balacera-guasave-en-vivo-violencia-sinaloa-ultimas-noticias/"],["La Jornada","https://www.jornada.com.mx/2026/11/21/estados/021n1est"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-quien-es-el-chapo-isidro-acusado-en-eu-desde-2012-y-detenido-cuatro-ve","t":"Quién es ‘El Chapo Isidro’: acusado en EU desde 2012 y detenido cuatro veces entre 2011 y 2015","c":"seguridad","f":"2026-11-21T07:15","r":"Fausto Isidro Meza Flores nació el 19 de junio de 1982 y, tras la ruptura de los Beltrán Leyva con el Cártel de Sinaloa en 2008, formó su propia organización, conocida como Cártel de Guasave o Los Mazatlecos. En Estados Unidos enfrenta una acusación iniciada en 2012 en el Distrito de Columbia y ampliada en 2019 por conspiración para distribuir cocaína, heroína, metanfetamina y mariguana. Según un oficio del CENAPI citado por Proceso, había sido detenido cuatro veces entre 2011 y 2015.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/quien-es-chapo-isidro-uno10-mas-buscados-fbi"],["Proceso","https://www.proceso.com.mx/nacional/estados/2026/11/21/reportan-la-captura-de-el-chapo-isidro-en-guasave-sinaloa-384102.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-detienen-en-juchitan-a-cuatro-presuntos-integrantes-de-los-cromos-liga","t":"Detienen en Juchitán a cuatro presuntos integrantes de Los Cromos, ligados a homicidios y extorsiones en el Istmo","c":"seguridad","f":"2026-11-21T07:14","r":"Un operativo de la Secretaría de Marina, el Ejército, la Guardia Nacional y la Policía Estatal en Juchitán de Zaragoza, Oaxaca, terminó con la detención de cuatro presuntos miembros de Los Cromos, grupo señalado por homicidios, extorsiones y cobro de piso en el Istmo de Tehuantepec. Entre ellos están un hombre de 32 años identificado como ‘El Migue’ y un adolescente de 17 años, a quienes se relaciona con dos homicidios recientes, entre ellos el de un policía municipal asesinado el 12 de noviembre en la colonia Tierra y Libertad.","b":"","img":"carretera","foto":"","cred":"","src":[["Quadratín","https://chihuahua.quadratin.com.mx/seguridad/detienen-marina-y-fuerzas-federales-a-4-de-los-cromos-en-juchitan/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-gaseros-piden-actualizar-el-margen-del-gas-lp-acusan-un-rezago-de-79-c","t":"Gaseros piden actualizar el margen del gas LP: acusan un rezago de 79 centavos por kilo","c":"economia","f":"2026-11-21T07:13","r":"La Asociación Mexicana de Distribuidores de Gas Licuado (Amexgas) pidió a la Secretaría de Energía y a la Comisión Nacional de Energía revisar el margen operativo del esquema de precios máximos. Según la asociación, entre el 8 y el 14 de noviembre el margen fue de 5.27 pesos por kilo, frente a 6.06 pesos que correspondería por la metodología del acuerdo, un rezago cercano a 13%. Las distribuidoras afirmaron que seguirán respetando los precios máximos vigentes.","b":"","img":"pemex","foto":"","cred":"","src":[["El Siglo de Torreón","https://www.elsiglodetorreon.com.mx/noticia/2026/gaseras-piden-revisar-precios.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-venezuela-ha-recibido-mas-de-12-mil-millones-de-dolares-por-venta-de-p","t":"Venezuela ha recibido más de 12 mil millones de dólares por venta de petróleo en 2026, según un reporte de EU","c":"economia","f":"2026-11-21T07:12","r":"Un reporte de Estados Unidos, que funge como custodio de esos ingresos, indica que Venezuela ha recibido desde enero más de 12,000 millones de dólares, principalmente por la venta de crudo. Expertos consultados por la agencia EFE señalan dudas sobre las empresas que participan, el destino de los fondos y el volumen de petróleo comercializado.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/21/sabado-21-de-noviembre-de-2026-0200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-frente-frio-8-avanza-por-el-norte-preven-lluvias-fuertes-en-guerrero-y","t":"Frente frío 8 avanza por el norte; prevén lluvias fuertes en Guerrero y Veracruz y heladas en zonas serranas","c":"nacional","f":"2026-11-21T07:11","r":"El Servicio Meteorológico Nacional prevé para este sábado lluvias fuertes puntuales en Guerrero y en Veracruz durante la noche y madrugada, chubascos en Oaxaca, Chiapas, Tabasco y la península de Yucatán, y lluvias aisladas en el Estado de México, Hidalgo, Puebla, Tlaxcala y la capital. El frente frío número 8 recorre el noroeste y norte con rachas de viento de hasta 60 km/h en Baja California, y en zonas serranas se esperan mínimas de entre -10 y 5 grados.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/21/en-vivo-clima-cdmx-y-resto-de-mexico-hoy-sabado-21-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-familias-de-desaparecidos-rastrean-terrenos-en-huitzilac-morelos-con-f","t":"Familias de desaparecidos rastrean terrenos en Huitzilac, Morelos, con fotos y herramientas para remover la tierra","c":"estados","f":"2026-11-21T07:10","r":"Familias de personas desaparecidas recorren predios en Huitzilac, Morelos, y otras zonas del centro del país con las fotografías de sus seres queridos y herramientas para excavar, en jornadas de búsqueda que realizan por su cuenta, según un reportaje de la agencia EFE.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/21/sabado-21-de-noviembre-de-2026-0200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-trump-amenaza-con-un-impuesto-tremendo-a-las-empresas-de-eu-que-constr","t":"Trump amenaza con un “impuesto tremendo” a las empresas de EU que construyan centros de datos fuera del país","c":"tecnologia","f":"2026-11-21T07:09","r":"Durante su conferencia del viernes en la Casa Blanca, Donald Trump dijo que no permitirá que compañías estadounidenses levanten centros de datos en el extranjero y que las castigaría con un fuerte impuesto. También afirmó que acordó con Xi Jinping “salvaguardas conjuntas” sobre inteligencia artificial durante su viaje a Asia, que calificó como uno de los más exitosos de un presidente estadounidense.","b":"","img":"tech","foto":"","cred":"","src":[["CBS News","https://www.cbsnews.com/live-updates/trump-press-conference-live-stream-2026-11-20/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-trump-defiende-su-relacion-con-putin-y-dice-que-rusia-no-habria-invadi","t":"Trump defiende su relación con Putin y dice que Rusia no habría invadido Ucrania si él hubiera sido presidente","c":"internacional","f":"2026-11-21T07:08","r":"De regreso de la cumbre con Xi Jinping y Vladímir Putin, Donald Trump afirmó que el mandatario ruso le dijo que no habría invadido Ucrania en 2022 si él hubiera estado en la Casa Blanca, y describió su relación con Putin como una fuente de fortaleza adicional. Sobre Irán, aseguró que Estados Unidos no permitirá una “bomba sucia” en Washington, aunque calificó esa versión como un rumor.","b":"","img":"ultimahora","foto":"","cred":"","src":[["CBS News","https://www.cbsnews.com/live-updates/trump-press-conference-live-stream-2026-11-20/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-la-cop31-se-alarga-sin-acuerdo-el-borrador-final-ya-no-menciona-el-aba","t":"La COP31 se alarga sin acuerdo: el borrador final ya no menciona el abandono de los combustibles fósiles","c":"internacional","f":"2026-11-21T07:07","r":"Negociadores de casi 200 países seguían reunidos en Antalya, Turquía, tras el cierre previsto del viernes, en busca de una decisión final. El texto reducido que se discute reconoce que el calentamiento podría superar 1.5 grados y pide recortes profundos y sostenidos de emisiones, pero eliminó las referencias a los combustibles fósiles que tenía el primer borrador; un grupo de países y ONG exige recuperarlas. Australia encabeza las negociaciones en una presidencia compartida con Turquía.","b":"","img":"ultimahora","foto":"","cred":"","src":[["bdnews24 (Reuters)","https://bdnews24.com/environment/yueexumr06"],["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/21/sabado-21-de-noviembre-de-2026-0200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-francia-despliega-70-mil-policias-ante-el-sexto-fin-de-semana-de-prote","t":"Francia despliega 70 mil policías ante el sexto fin de semana de protestas por el costo de vida","c":"internacional","f":"2026-11-21T07:06","r":"Unos 70,000 policías y gendarmes vigilan este sábado en Francia las movilizaciones de sindicatos, estudiantes y ‘chalecos amarillos’, que suman seis fines de semana seguidos de protestas por el poder adquisitivo y coinciden con el octavo aniversario de ese movimiento. En Lisboa, la central sindical CGTP también convocó a marchar contra el aumento del costo de vida.","b":"","img":"paris","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/21/sabado-21-de-noviembre-de-2026-0200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-burnham-dice-que-el-nuevo-acuerdo-con-la-ue-elevara-0-5-el-pib-britani","t":"Burnham dice que el nuevo acuerdo con la UE elevará 0.5% el PIB británico; recibe las primeras críticas","c":"internacional","f":"2026-11-21T07:05","r":"El primer ministro británico, Andy Burnham, afirmó que el acuerdo firmado el viernes en Bruselas entre el Reino Unido y la Unión Europea aumentará 0.5% el producto interno bruto de su país, aunque el pacto ya enfrenta cuestionamientos internos, informó la agencia EFE.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/21/sabado-21-de-noviembre-de-2026-0200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-la-ue-e-indonesia-formalizan-su-tratado-de-libre-comercio-tras-una-dec","t":"La UE e Indonesia formalizan su tratado de libre comercio tras una década de negociaciones","c":"internacional","f":"2026-11-21T07:04","r":"Ursula von der Leyen y el comisario Maroš Šefčovič se reúnen este sábado en Bruselas con los ministros indonesios Airlangga Hartarto y Budi Santoso para ratificar el acuerdo de libre comercio firmado en septiembre de 2025. En la misma jornada, el presidente del Consejo Europeo, António Costa, presenta un nuevo borrador del presupuesto de la UE para 2028-2034.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/21/sabado-21-de-noviembre-de-2026-0200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-la-nfl-vuelve-a-la-cdmx-vikings-y-49ers-se-enfrentan-el-domingo-en-el","t":"La NFL vuelve a la CDMX: Vikings y 49ers se enfrentan el domingo en el Estadio Azteca","c":"deportes","f":"2026-11-21T07:03","r":"Minnesota y San Francisco juegan este domingo 22 a las 19:00 horas del centro de México, en el regreso de la NFL a la capital tras cuatro años. Su historial está empatado con 25 triunfos por bando y un empate; los 49ers, con la segunda mejor ofensiva de la liga (31 puntos por juego), llegan como favoritos por tres puntos ante la mejor defensa (14 puntos permitidos). Los Vikings tienen marca de 5-1 fuera de Estados Unidos y los 49ers no han perdido en sus cuatro juegos internacionales.","b":"","img":"estadio","foto":"","cred":"","src":[["Telemundo","https://www.telemundo.com/deportes/nfl/vikings-vs-49ers-una-vieja-rivalidad-que-no-podria-estar-mas-nivelada-rcna610062"],["Récord","https://www.record.com.mx/nfl/nfl-mexico-como-les-ha-ido-a-vikings-y-49ers-cuando-juegan-fuera-de-usa-2026111901405680821"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-pumas-recibe-a-monterrey-en-cu-obligado-a-ganar-para-seguir-con-vida-e","t":"Pumas recibe a Monterrey en CU obligado a ganar para seguir con vida en el Apertura 2026","c":"deportes","f":"2026-11-21T07:02","r":"Pumas, undécimo con 21 puntos, enfrenta este sábado a las 19:00 horas a Monterrey, séptimo con 24, en el Estadio Olímpico Universitario por la jornada 17. El equipo de Esteban Solari necesita la victoria y otros resultados; un triunfo por tres goles lo pondría delante de Rayados. Pedro Vite, de Pumas, y Ricardo Chávez, de Monterrey, no jugarán por suspensión. El partido se transmite por TUDN, ViX y Canal 5.","b":"","img":"unam","foto":"","cred":"","src":[["Publimetro","https://www.publimetro.com.mx/deportes/2026/11/18/pumas-va-por-el-milagro-ante-monterrey-donde-y-a-que-hora-ver-el-partido/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-21-corona-capital-vive-su-segundo-dia-twenty-one-pilots-encabeza-este-sab","t":"Corona Capital vive su segundo día: Twenty One Pilots encabeza este sábado en el Autódromo","c":"entretenimiento","f":"2026-11-21T07:01","r":"El festival sigue este sábado en la Curva 4 del Autódromo Hermanos Rodríguez, con actividades desde alrededor de las 15:20 horas en cinco escenarios. Twenty One Pilots cierra el escenario Corona de 23:00 a 1:00, y entre 21:30 y 23:00 coinciden The Offspring y Underworld. El domingo 22 el cierre estará a cargo de The Strokes.","b":"","img":"autodromo","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/espectaculos/revelan-horarios-oficiales-corona-capital-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-sheinbaum-en-el-desfile-de-la-revolucion-la-oposicion-va-a-volver-a-fr","t":"Sheinbaum, en el desfile de la Revolución: la oposición “va a volver a fracasar” si intenta deslegitimar la elección de 2027","c":"politica","f":"2026-11-20T18:40","r":"Durante el desfile cívico-militar por el 116 aniversario de la Revolución Mexicana, la presidenta Claudia Sheinbaum afirmó que sus opositores intentarán desacreditar los comicios de 2027 y que volverán a fracasar. Recordó los fraudes electorales de 1988 y 2006, dijo que los intentos de injerencia extranjera también fallaron y reivindicó a Madero, Zapata y Villa. La mandataria estuvo acompañada por los titulares de Defensa, Ricardo Trevilla, y de Marina, Raymundo Morales.","b":"","img":"zocalo","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/2026/11/20/en-desfile-de-la-revolucion-mexicana-sheinbaum-advierte-que-oposicion-busca-deslegitimar-elecciones-de-2027-384062.html"],["Uno TV","https://www.unotv.com/nacional/no-nos-someteremos-a-ningun-poder-extranjero-sheinbaum-defiende-soberania-en-desfile-de-la-revolucion/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-20-detienen-en-la-cdmx-a-lili-campos-exalcaldesa-de-playa-del-carmen-y-fi","t":"Detienen en la CDMX a Lili Campos, exalcaldesa de Playa del Carmen y fiscal antinarcomenudeo capitalina","c":"seguridad","f":"2026-11-20T18:39","r":"Roxana Lili Campos Miranda, quien gobernó Solidaridad (Playa del Carmen) de 2021 a 2024 y desde septiembre encabezaba la Fiscalía de Investigación del Delito de Narcomenudeo de la CDMX, fue detenida la noche del jueves en la alcaldía Venustiano Carranza. La Fiscalía de Quintana Roo la señala por un presunto daño de más de 62 millones de pesos en licitaciones para lavado de vehículos municipales entre 2022 y 2024. Este viernes ingresó al penal de Cancún, donde espera a un juez de control.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/2026/11/20/detienen-a-lili-campos-fiscal-antinarcomenudeo-de-cdmx-por-presunto-desfalco-millonario-384075.html"],["Infobae","https://www.infobae.com/mexico/2026/11/20/detienen-en-cdmx-a-lili-campos-ex-alcaldesa-de-playa-del-carmen-queda-a-disposicion-de-la-fgr/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-20-viernes-negro-en-wall-street-el-s-p-500-cae-3-70-y-entra-en-correccion","t":"Viernes negro en Wall Street: el S&P 500 cae 3.70% y entra en corrección; la BMV resiste con alza de 0.11%","c":"economia","f":"2026-11-20T18:38","r":"Las acciones ligadas a la inteligencia artificial arrastraron a Wall Street: el Nasdaq perdió 5.28%, el S&P 500 bajó 3.70%, su peor caída desde 2020, y el Dow Jones cedió 1.93%. El S&P 500 ya acumula más de 10% de retroceso desde su máximo de octubre, lo que lo coloca en corrección, y el índice de volatilidad VIX saltó a 38.37 puntos. En México, el S&P/BMV IPC subió 0.11%, apoyado en Gruma y Grupo México.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión","https://expansion.mx/mercados/2026/11/20/viernes-negro-acciones-tecnologicas-wall-street-peor-racha"]],"dest":true,"a":"Redacción"},{"id":"2026-11-20-el-peso-cierra-en-19-17-por-dolar-la-divisa-estadounidense-sube-3-63","t":"El peso cierra en 19.17 por dólar; la divisa estadounidense sube 3.63% en la semana","c":"economia","f":"2026-11-20T18:37","r":"El peso mexicano terminó el viernes con una depreciación de 0.48%, en 19.17 unidades por dólar, en medio de la aversión al riesgo por la caída de las tecnológicas en Wall Street. Con datos de Dow Jones, Infobae reporta que el dólar avanzó 3.63% frente al peso en la última semana. Analistas consultados por Banxico estiman que la moneda cerrará 2026 entre 20.00 y 20.50 pesos por dólar.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión","https://expansion.mx/mercados/2026/11/20/viernes-negro-acciones-tecnologicas-wall-street-peor-racha"],["Infobae","https://www.infobae.com/mexico/2026/11/20/dolar-hoy-en-mexico-cotizacion-de-cierre-del-20-de-noviembre/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-20-morena-decidira-el-miercoles-25-si-lanza-ya-la-convocatoria-para-elegi","t":"Morena decidirá el miércoles 25 si lanza ya la convocatoria para elegir a la nueva presidenta del INE","c":"politica","f":"2026-11-20T18:36","r":"Ricardo Monreal, coordinador de Morena en San Lázaro, informó que su bancada resolverá el 25 de noviembre si emite la convocatoria o espera el fallo del Tribunal Electoral sobre la demanda que el PAN presentó el 18 de noviembre. Estimó que el proceso tomaría unos 58 días, por lo que la nueva titular se elegiría hacia finales de enero de 2027. Mientras tanto, Blanca Cruz García sigue como presidenta provisional tras la renuncia de Guadalupe Taddei el 19 de octubre.","b":"","img":"ine","foto":"","cred":"","src":[["La Silla Rota","https://lasillarota.com/nacion/2026/11/20/morena-definira-el-miercoles-ruta-para-elegir-presidenta-del-ine-538079.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-desfile-de-la-revolucion-reune-a-2-911-elementos-486-caballos-y-14-aer","t":"Desfile de la Revolución reúne a 2,911 elementos, 486 caballos y 14 aeronaves en el Centro Histórico","c":"nacional","f":"2026-11-20T18:35","r":"El desfile por el 116 aniversario de la Revolución arrancó poco después de las 10:00 horas en la Plaza de la Constitución y avanzó por 5 de Mayo, Eje Central, avenida Juárez y avenida de la República hasta el Monumento a la Revolución. Según la Defensa, participaron 2,911 integrantes del Ejército, la Fuerza Aérea y la Guardia Nacional, con 69 vehículos, 100 charros y nueve contingentes con escenas históricas como la huelga de Cananea. El acto sustituyó a la conferencia matutina.","b":"","img":"zocalo","foto":"","cred":"","src":[["Crónica","https://www.cronica.com.mx/nacional/2026/11/20/sheinbaum-encabeza-desfile-por-el-116-aniversario-de-la-revolucion-mexicana/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-capturan-en-cancun-a-pancho-senalado-por-eu-como-lider-de-una-red-de-t","t":"Capturan en Cancún a “Pancho”, señalado por EU como líder de una red de tráfico de cocaína","c":"seguridad","f":"2026-11-20T18:34","r":"El Gabinete de Seguridad informó la detención de Francisco Gerardo N, alias “Pancho”, en un domicilio de Puerto Cancún, Quintana Roo. El Departamento de Justicia de Estados Unidos lo identifica como líder de una organización que traficó cocaína y otras drogas entre ambos países, sobre todo entre 2002 y 2006. Según las autoridades, entró a México en marzo de 2021 con una identidad falsa; en el operativo participaron Marina, SSPC y FGR.","b":"","img":"ultimahora","foto":"","cred":"","src":[["ABC Color / EFE","https://www.abc.com.py/internacionales/2026/11/20/autoridades-mexicanas-detienen-a-lider-de-grupo-dedicado-al-trafico-de-cocaina-en-cancun/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-sin-consenso-en-san-lazaro-el-relevo-en-el-ine-se-perfila-para-2027-y","t":"Sin consenso en San Lázaro, el relevo en el INE se perfila para 2027 y por mayoría; el PAN prepara otra acción legal","c":"politica","f":"2026-11-20T18:33","r":"Monreal reconoció que se perdió la opción de pactar con la oposición la convocatoria para presidir el INE y que la designación tendría que salir por mayoría calificada. La consejera Carla Humphrey dijo que, si no hay nombramiento antes de fin de año, el Consejo General decidiría quién sigue en la presidencia provisional. El líder del PAN, Jorge Romero, anunció una segunda acción legal y cuestionó la independencia de Blanca Cruz García.","b":"","img":"ine","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/20/se-cae-acuerdo-para-relevo-en-ine-por-consenso-lo-ven-en-2027-y-via-mayoria/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-nvidia-se-desploma-14-y-acumula-siete-semanas-a-la-baja-su-peor-racha","t":"Nvidia se desploma 14% y acumula siete semanas a la baja, su peor racha desde 2008","c":"tecnologia","f":"2026-11-20T18:32","r":"La acción de Nvidia cerró el viernes en 125.53 dólares, con una caída de 14% en la sesión y de 22.9% en la semana. La empresa atraviesa una crisis de liderazgo tras la salida de Jensen Huang, a lo que se sumó una investigación del New York Times sobre vínculos de una directiva con empresas chinas de defensa, además de dudas sobre la rentabilidad de la inversión en IA. Colette Kress funge como directora interina.","b":"","img":"tech","foto":"","cred":"","src":[["El Financiero / EFE","https://www.elfinanciero.com.mx/mundo/2026/11/20/nvidia-se-desploma-en-wall-street-sus-acciones-pierden-229-en-una-semana-en-su-peor-racha-desde-2008/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-el-brent-repunta-a-92-57-dolares-pero-el-petroleo-acumula-tres-semanas","t":"El Brent repunta a 92.57 dólares, pero el petróleo acumula tres semanas de pérdidas","c":"economia","f":"2026-11-20T18:31","r":"El barril de Brent para enero subió 0.64% y cerró en 92.57 dólares, mientras que el WTI para diciembre avanzó 0.93% a 83.98 dólares. Pese al rebote, ambos referenciales suman su tercera semana consecutiva a la baja por la expectativa de más exportaciones de Medio Oriente y un posible exceso de oferta al cierre de 2026. Las tensiones entre Arabia Saudita y los hutíes, y entre EU e Irán, siguen pesando en el mercado.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae / AFP","https://www.infobae.com/america/mundo/2026/11/20/el-petroleo-acumula-tres-semanas-de-perdidas-pese-al-repunte-registrado-este-viernes/"],["Expansión","https://expansion.mx/mercados/2026/11/20/viernes-negro-acciones-tecnologicas-wall-street-peor-racha"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-ataque-masivo-ruso-deja-sin-luz-a-parte-de-kiev-zelenski-dice-que-solo","t":"Ataque masivo ruso deja sin luz a parte de Kiev; Zelenski dice que solo derribaron 3 de 27 misiles balísticos","c":"internacional","f":"2026-11-20T18:30","r":"Rusia lanzó un ataque masivo con misiles y drones que dejó sin electricidad a parte de Kiev y provocó cortes en el oeste de Ucrania. Volodímir Zelenski denunció el uso de munición de racimo y pidió a EU más sistemas Patriot, al señalar que sus fuerzas derribaron solo 3 de 27 misiles balísticos. El ministro de Defensa polaco informó que dos misiles rusos y un dron cayeron en territorio de Polonia.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/20/temas-del-dia-de-efe-internacional-del-viernes-20-de-noviembre-de-2026-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-asesinan-en-una-emboscada-al-director-de-la-policia-municipal-de-puebl","t":"Asesinan en una emboscada al director de la Policía Municipal de Pueblo Nuevo, Guanajuato","c":"estados","f":"2026-11-20T18:29","r":"Rafael Galván Navarro, director de la Policía Municipal de Pueblo Nuevo, Guanajuato, murió en el lugar tras un ataque armado contra la patrulla en la que viajaba. Su escolta, Eduardo Casiano, resultó herido.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-20-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-anthropic-cae-8-5-en-su-segundo-dia-en-bolsa-tras-un-debut-record","t":"Anthropic cae 8.5% en su segundo día en bolsa tras un debut récord","c":"tecnologia","f":"2026-11-20T18:28","r":"Las acciones de Anthropic retrocedieron 8.5% este viernes, en su segunda jornada en el Nasdaq, arrastradas por la venta generalizada de tecnológicas. La empresa colocó 980 millones de acciones a 83 dólares cada una, con lo que recaudó 81,340 millones de dólares, y el jueves cerró su primera sesión en 97.17 dólares tras abrir en 111.50.","b":"","img":"tech","foto":"","cred":"","src":[["Expansión","https://expansion.mx/mercados/2026/11/20/viernes-negro-acciones-tecnologicas-wall-street-peor-racha"],["Merca2.0","https://www.merca20.com/acciones-inteligencia-artificial-caen-wall-street-anthropic-nvidia-amd/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-caro-quintero-comparece-ante-un-tribunal-de-nueva-york-su-juicio-se-pr","t":"Caro Quintero comparece ante un tribunal de Nueva York; su juicio se prevé para marzo de 2027","c":"seguridad","f":"2026-11-20T18:27","r":"Rafael Caro Quintero compareció este viernes ante la justicia estadounidense en Nueva York. Su juicio está previsto para el 8 de marzo de 2027 en una corte de Brooklyn, según la agenda informativa de la agencia EFE.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/20/temas-del-dia-de-efe-internacional-del-viernes-20-de-noviembre-de-2026-1200-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-detienen-en-zihuatanejo-a-cinco-presuntos-integrantes-de-la-familia-mi","t":"Detienen en Zihuatanejo a cinco presuntos integrantes de La Familia Michoacana","c":"estados","f":"2026-11-20T18:26","r":"Fuerzas federales y estatales detuvieron a cinco presuntos miembros de una célula ligada a La Familia Michoacana en la comunidad de Calabazalito, en Zihuatanejo, Guerrero. Les aseguraron tres armas largas, 20 cargadores, 650 cartuchos, marihuana y una camioneta, según el informe del Gabinete de Seguridad sobre las acciones del jueves 19.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Quadratín Guerrero","https://guerrero.quadratin.com.mx/caen-5-presuntos-miembros-de-la-familia-michoacana-en-zihuatanejo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-huties-denuncian-41-civiles-muertos-por-bombardeos-saudies-la-coalicio","t":"Hutíes denuncian 41 civiles muertos por bombardeos saudíes; la coalición pide evacuar el puerto de Hodeida","c":"internacional","f":"2026-11-20T18:25","r":"Los hutíes de Yemen reportaron al menos 41 civiles muertos en ataques aéreos saudíes en varias provincias durante las últimas 24 horas. La coalición encabezada por Arabia Saudita pidió a la población civil abandonar el puerto de Hodeida, en el mar Rojo, por su seguridad.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / Europa Press","https://www.infobae.com/america/agencias/2026/11/20/resumen-de-las-principales-noticias-transmitidas-este-viernes-20-de-noviembre-por-el-servicio-de-internacional/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-mc-denuncia-ante-la-fgr-a-la-diputada-lorena-de-la-garza-por-la-fumiga","t":"MC denuncia ante la FGR a la diputada Lorena de la Garza por la fumigación de un parque con mariposas monarca","c":"estados","f":"2026-11-20T18:24","r":"La bancada de Movimiento Ciudadano en Nuevo León presentó una denuncia ante la Fiscalía General de la República contra la diputada local Lorena de la Garza Venecia y quien resulte responsable por la presunta fumigación de un parque del sur de Monterrey donde habitan mariposas monarca.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Quadratín","https://guerrero.quadratin.com.mx/mc-presenta-denuncia-por-fumigacion-en-parque-de-mariposas-monarca/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-eu-sanciona-a-los-comancheros-por-llevar-cocaina-del-cartel-de-sinaloa","t":"EU sanciona a Los Comancheros por llevar cocaína del Cártel de Sinaloa y el CJNG a Oceanía","c":"seguridad","f":"2026-11-20T18:23","r":"El Departamento del Tesoro de Estados Unidos sancionó el 19 de noviembre a Los Comancheros, una pandilla de motociclistas con sede en Australia, por facilitar el tráfico de cocaína del Cártel de Sinaloa y del CJNG hacia Oceanía. La medida bloquea los activos de cinco de sus líderes.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-20-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-dinamarca-expulsa-al-agregado-de-defensa-ruso-por-un-complot-para-ases","t":"Dinamarca expulsa al agregado de Defensa ruso por un complot para asesinar a un músico ucraniano-estadounidense","c":"internacional","f":"2026-11-20T18:22","r":"El gobierno danés expulsó al agregado de Defensa de la embajada de Rusia, al que vincula con una conspiración para matar a un músico ucraniano-estadounidense durante un concierto cerca de Copenhague.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / Europa Press","https://www.infobae.com/america/agencias/2026/11/20/resumen-de-las-principales-noticias-transmitidas-este-viernes-20-de-noviembre-por-el-servicio-de-internacional/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-sismo-de-magnitud-4-1-sacude-atoyac-de-alvarez-guerrero","t":"Sismo de magnitud 4.1 sacude Atoyac de Álvarez, Guerrero","c":"estados","f":"2026-11-20T18:21","r":"El Servicio Sismológico Nacional registró este viernes un temblor de magnitud 4.1 con epicentro a 7 kilómetros al noreste de Atoyac de Álvarez, Guerrero, a 50 kilómetros de profundidad.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/temblor-hoy-en-mexico-noticias-actividad-sismica-20-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-sheinbaum-aterriza-en-el-aicm-tras-cinco-dias-de-gira-por-la-apec-y-en","t":"Sheinbaum aterriza en el AICM tras cinco días de gira por la APEC y encabeza hoy el desfile de la Revolución","c":"nacional","f":"2026-11-20T06:59","r":"La presidenta Claudia Sheinbaum llegó al Aeropuerto Internacional de la Ciudad de México la madrugada de este viernes, de regreso de la cumbre APEC en Shenzhen, China. La gira duró cinco días y sumó cerca de 40 horas en vuelos comerciales en clase económica. Sheinbaum dijo que la negociación sobre los aranceles de la sección 232 va muy avanzada y que lo tratará en Mar-a-Lago en diciembre; hoy encabeza el desfile cívico-militar y no habrá mañanera.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/sheinbaum-llega-a-mexico-tras-visita-a-china-hoy-encabezara-desfile-del-20-de-noviembre-por-la-revolucion-mexicana/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-20-recapturan-en-mocorito-a-el-chendo-y-detienen-a-el-pagador-senalados-c","t":"Recapturan en Mocorito a ‘El Chendo’ y detienen a ‘El Pagador’, señalados como operadores de Los Mayos","c":"seguridad","f":"2026-11-20T06:58","r":"Fuerzas federales detuvieron el jueves en El Mazate de los López, Mocorito, Sinaloa, a Jesús Miguel ‘N’, alias ‘El Chendo’, y a Irvin Eduardo ‘N’, alias ‘El Pagador’, presuntos integrantes de Los Mayos, informó la SSPC. ‘El Chendo’ ya había sido capturado el 10 de agosto de 2025 en Los Mochis y quedó libre por una suspensión provisional. Se aseguraron ocho kilos de cocaína, medio kilo de metanfetamina y tres armas largas; el secretario Omar García Harfuch vinculó a su grupo, las Fuerzas Especiales Avendaño, con el hallazgo de 20 cuerpos en Culiacán y la masacre de 19 personas en La Concordia, Chiapas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["NoticiasPV","https://www.noticiaspv.com.mx/recaptura-el-chendo-los-mayos-sinaloa/"],["Quiero TV","https://quierotv.mx/2026/11/20/fea-harfuch-responsabiliza-a-celula-criminal-por-los-20-cuerpos-en-culiacan"]],"dest":true,"a":"Redacción"},{"id":"2026-11-20-diputados-aprueban-la-ley-general-de-bienestar-animal-con-469-votos-re","t":"Diputados aprueban la Ley General de Bienestar Animal con 469 votos; reconoce a los animales como seres sintientes","c":"politica","f":"2026-11-20T06:57","r":"La Cámara de Diputados aprobó con 469 votos a favor la Ley General de Bienestar Animal, que reconoce a los animales como seres sintientes. La norma prohíbe vender mascotas en la vía pública, mercados y tianguis, y establece que la eutanasia solo procede bajo criterio veterinario. Durante la discusión se debatió el tema de las corridas de toros; el dictamen fue enviado al Ejecutivo federal.","b":"","img":"senado","foto":"","cred":"","src":[["Imagen Radio","https://www.imagenradio.com.mx/programas/imagen-informativa-primera-emision/diputados-aprueban-ley-bienestar-animal-469-votos"]],"dest":true,"a":"Redacción"},{"id":"2026-11-20-minutas-de-banxico-exhiben-division-dos-miembros-temen-que-la-caida-de","t":"Minutas de Banxico exhiben división: dos miembros temen que la caída del peso presione la inflación","c":"economia","f":"2026-11-20T06:56","r":"Las minutas de la decisión del 5 de noviembre muestran que Victoria Rodríguez, Gabriel Cuadra y Omar Mejía votaron por recortar la tasa, mientras Galia Borja y Jonathan Heath pidieron mantenerla en 6.50%. Heath advirtió que el efecto de la depreciación en el precio de las mercancías llega con unos seis meses de rezago y anticipó un aumento de 11% al salario mínimo. El peso acumula una depreciación cercana a 13% desde inicios de septiembre, según El Financiero.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/economia/2026/11/20/banxico-se-divide-por-minutas-de-politica-monetaria-impacta-la-depreciacion-sobre-inflacion/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-20-desfile-por-el-116-aniversario-de-la-revolucion-sale-a-las-10-00-del-z","t":"Desfile por el 116 aniversario de la Revolución sale a las 10:00 del Zócalo rumbo al Monumento a la Revolución","c":"nacional","f":"2026-11-20T06:55","r":"El desfile cívico-militar por el 116 aniversario del inicio de la Revolución Mexicana arranca a las 10:00 horas en el Zócalo y avanzará por 5 de Mayo, avenida Juárez y Paseo de la Reforma hasta el Monumento a la Revolución. La SSC recomienda usar como alternativas el Eje 1 Norte, el Eje 1 Oriente, Insurgentes, avenida Chapultepec y Fray Servando Teresa de Mier. Además, la dependencia tiene registradas 12 concentraciones y tres rodadas en la capital.","b":"","img":"zocalo","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4906611/calles-cerradas-por-desfile-del-dia-de-la-revolucion-y-marchas-en-la-cdmx-hoy-viernes/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-senado-aprueba-por-unanimidad-reforma-para-sancionar-la-violencia-doce","t":"Senado aprueba por unanimidad reforma para sancionar la violencia docente y el acoso sexual en escuelas","c":"politica","f":"2026-11-20T06:54","r":"El Senado aprobó por unanimidad cambios a la Ley General de Acceso de las Mujeres a una Vida Libre de Violencias y a la Ley General para la Igualdad Sustantiva para prevenir, atender y sancionar la violencia docente y el acoso sexual en planteles. La minuta pasó a la Cámara de Diputados. Según datos de REDIM citados en la discusión, 223 personas de 1 a 17 años ingresaron a hospitales en 2025 por agresiones sexuales ocurridas en escuelas.","b":"","img":"senado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/19/senado-avala-reforma-contra-violencia-sexual-en-escuelas-establece-sancionar-a-agresores-y-erradicar-estereotipos-sexistas/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-el-dolar-abre-el-viernes-en-19-07-pesos-ligeramente-abajo-del-cierre-p","t":"El dólar abre el viernes en 19.07 pesos, ligeramente abajo del cierre previo; sube 3% en una semana","c":"economia","f":"2026-11-20T06:53","r":"El tipo de cambio abrió este viernes en un promedio de 19.07 pesos por dólar, 0.1% por debajo del cierre anterior de 19.08, con datos de Dow Jones citados por Infobae. En la última semana el dólar avanza 3% frente al peso y en un año 6.01%. Para el cierre de 2026, Hacienda estima 19.70 pesos y Banorte 19.30.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/dolar-hoy-en-mexico-cotizacion-de-apertura-del-20-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-trump-pospone-hasta-2027-la-decision-sobre-nuevos-ataques-contra-iran","t":"Trump pospone hasta 2027 la decisión sobre nuevos ataques contra Irán; mantiene el bloqueo naval","c":"internacional","f":"2026-11-20T06:52","r":"El presidente Donald Trump dijo que decidirá sobre nuevos ataques contra Irán después de inicios de 2027, mientras sigue el bloqueo naval y la presión económica sobre Teherán. Un funcionario del Pentágono estimó el costo de la operación en 48,300 millones de dólares hasta el 13 de noviembre. El Senado de EU rechazó por 51 votos contra 48 una propuesta demócrata para poner fin al conflicto.","b":"","img":"ultimahora","foto":"","cred":"","src":[["10 Things Global News","https://www.10things.news/p/10-things-global-news-20th-november-0cb"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-detienen-a-ocho-mexicanos-tras-desmantelar-dos-narcolaboratorios-en-la","t":"Detienen a ocho mexicanos tras desmantelar dos narcolaboratorios en Lancaster y Palmdale, California","c":"seguridad","f":"2026-11-20T06:51","r":"La DEA y autoridades del condado de Kern desmantelaron laboratorios de metanfetamina en Lancaster y Palmdale, California, y detuvieron a ocho personas originarias de Michoacán, Zacatecas y la Ciudad de México. El caso comenzó el 16 de noviembre con una revisión de tránsito en la carretera I-5, donde hallaron cinco libras de droga. En cuatro cateos aseguraron 258.9 libras de metanfetamina procesada y 405 libras en solución líquida.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/detienen-a-ocho-mexicanos-ligados-a-dos-narcolaboratorios-desmantelados-en-california/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-cierran-estacion-zocalo-del-metro-y-suspenden-tramos-de-cuatro-lineas","t":"Cierran estación Zócalo del Metro y suspenden tramos de cuatro líneas del Metrobús por el desfile","c":"cdmx","f":"2026-11-20T06:50","r":"La estación Zócalo/Tenochtitlan de la Línea 2 del Metro permanece cerrada desde el inicio del servicio por el desfile; Allende, Pino Suárez, San Juan de Letrán y Bellas Artes son las alternativas. De 9:00 a 14:00 horas no habrá servicio del Metrobús en Hidalgo, Juárez y Balderas (Línea 3), entre Plaza de la República y Pino Suárez y entre Buenavista y Bellas Artes (Línea 4), ni en Hidalgo, El Caballito y Amajac (Línea 7).","b":"","img":"metro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/que-esta-pasando-en-el-metro-y-metrobus-hoy-viernes-20-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-frente-frio-8-entra-por-el-noroeste-preven-lluvias-fuertes-en-veracruz","t":"Frente frío 8 entra por el noroeste; prevén lluvias fuertes en Veracruz y Guerrero y rachas de hasta 70 km/h en Tehuantepec","c":"estados","f":"2026-11-20T06:49","r":"El Servicio Meteorológico Nacional prevé la llegada del frente frío número 8 al noroeste del país, mientras el sistema frontal 6 se mantiene en el golfo de México. Se esperan lluvias fuertes puntuales en Veracruz y Guerrero y chubascos en Oaxaca, Chiapas, Tabasco y la península de Yucatán. En el istmo y golfo de Tehuantepec habrá rachas de 50 a 70 km/h; en la capital, mínimas de 7 a 10 grados.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/20/en-vivo-clima-cdmx-y-resto-de-mexico-hoy-viernes-20-de-noviembre-frente-frio-8-traera-lluvias-y-fuertes-rachas-de-viento/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-la-corte-internacional-de-justicia-declara-a-myanmar-responsable-de-ge","t":"La Corte Internacional de Justicia declara a Myanmar responsable de genocidio contra los rohinyás","c":"internacional","f":"2026-11-20T06:48","r":"La Corte Internacional de Justicia, en La Haya, determinó que Myanmar cometió genocidio durante la represión de 2017 contra la minoría rohinyá, en la que murieron unas 10,000 personas y más de 700,000 huyeron a Bangladés. Es la primera vez que un tribunal internacional declara a un Estado responsable de genocidio. Myanmar rechazó el fallo y el Reino Unido expulsó a su agregado de defensa.","b":"","img":"ultimahora","foto":"","cred":"","src":[["10 Things Global News","https://www.10things.news/p/10-things-global-news-20th-november-0cb"],["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/20/viernes-20-de-noviembre-de-2026-0800-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-el-fmi-advierte-que-la-deuda-publica-mundial-pronto-llegara-a-100-del","t":"El FMI advierte que la deuda pública mundial pronto llegará a 100% del PIB, su mayor nivel desde la Segunda Guerra","c":"economia","f":"2026-11-20T06:47","r":"La directora gerente del FMI, Kristalina Georgieva, dijo en la cumbre APEC de Shenzhen que la deuda pública global alcanzará pronto el equivalente a 100% del PIB mundial. Estimó una inflación global cercana a 4.7% este año, impulsada por el choque energético en Medio Oriente y la demanda ligada a la inteligencia artificial, con un crecimiento económico de 3.1%.","b":"","img":"bolsa","foto":"","cred":"","src":[["10 Things Global News","https://www.10things.news/p/10-things-global-news-20th-november-0cb"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-presas-de-monterrey-se-mantienen-altas-la-boca-al-97-5-cerro-prieto-al","t":"Presas de Monterrey se mantienen altas: La Boca al 97.5%, Cerro Prieto al 83.4% y El Cuchillo al 50%","c":"estados","f":"2026-11-20T06:46","r":"Las presas que abastecen al área metropolitana de Monterrey almacenaban en conjunto 851.167 millones de metros cúbicos al corte del jueves 19, con datos de Conagua. La Boca está al 97.54% de su capacidad y Cerro Prieto al 83.42%, ambas con ligeros aumentos, mientras El Cuchillo bajó a 50.07%. En 24 horas el volumen total disminuyó 0.411 millones de metros cúbicos.","b":"","img":"lluvia","foto":"","cred":"","src":[["MVS Noticias","https://mvsnoticias.com/nuevo-leon/2026/11/20/nivel-de-las-presas-en-nuevo-leon-hoy-viernes-20-de-noviembre-del-2026-754132.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-un-misil-huti-impacta-la-torre-mas-alta-de-riad-sede-del-fondo-soberan","t":"Un misil hutí impacta la torre más alta de Riad, sede del fondo soberano saudí; no hay heridos","c":"internacional","f":"2026-11-20T06:45","r":"Un misil lanzado por los hutíes alcanzó el jueves la torre más alta de Riad, donde tiene su sede el fondo soberano PIF, en el distrito financiero de la capital saudí. El impacto rompió ventanas de varios pisos y dañó edificios cercanos, sin reportes de heridos. Arabia Saudita advirtió que se reserva el derecho a responder; el 8 de noviembre ya había sido atacado un edificio de Aramco en la misma zona.","b":"","img":"ultimahora","foto":"","cred":"","src":[["10 Things Global News","https://www.10things.news/p/10-things-global-news-20th-november-0cb"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-putin-invita-a-lideres-europeos-a-moscu-pero-rechaza-un-alto-el-fuego","t":"Putin invita a líderes europeos a Moscú pero rechaza un alto el fuego; Kushner ve a Rusia abierta a garantías para Ucrania","c":"internacional","f":"2026-11-20T06:44","r":"El enviado estadounidense Jared Kushner afirmó, tras reunirse en Berlín con líderes europeos y ucranianos, que Rusia es receptiva a garantías de seguridad para Ucrania similares al artículo 5 de la OTAN. Vladímir Putin invitó a los europeos a Moscú, aunque rechazó un alto el fuego y la presencia de tropas extranjeras en Ucrania tras la guerra. El canciller alemán Friedrich Merz dijo que Europa participará en la próxima ronda, pero prefiere una sede neutral.","b":"","img":"ultimahora","foto":"","cred":"","src":[["10 Things Global News","https://www.10things.news/p/10-things-global-news-20th-november-0cb"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-astros-vence-a-soles-en-el-quinto-juego-y-obliga-a-un-sexto-partido-de","t":"Astros vence a Soles en el quinto juego y obliga a un sexto partido de la final de la LNBP en Mexicali","c":"deportes","f":"2026-11-20T06:43","r":"Astros de Jalisco remontó en los últimos minutos y venció a Soles de Mexicali en el quinto juego de la Gran Final de la LNBP, disputado el jueves en Guadalajara, para recortar la serie a 3-2. Soles iba arriba 71-67 a dos minutos del final, pero Astros cerró con una racha de ocho puntos. El sexto juego será el domingo por la noche en el Auditorio del Estado, en Mexicali.","b":"","img":"estadio","foto":"","cred":"","src":[["El Informador","https://www.informador.mx/deportes/lnbp-astros-se-quedan-con-dramatico-partido-y-mantienen-viva-la-final-20261119-0185.html"],["PSN","https://psn.si/astros-vencio-soles-rm-2/2026/11/19/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-corona-capital-arranca-hoy-en-el-autodromo-con-aforo-de-120-mil-person","t":"Corona Capital arranca hoy en el Autódromo con aforo de 120 mil personas; Dimash y Los Ángeles Azules, en la agenda","c":"entretenimiento","f":"2026-11-20T06:42","r":"El festival Corona Capital 2026 abre sus puertas este viernes a las 14:00 horas en el Autódromo Hermanos Rodríguez, con un aforo previsto de 120,000 asistentes, según la SSC. Por la noche, Dimash Qudaibergen se presenta en el Palacio de los Deportes y Los Ángeles Azules en el Auditorio Nacional, mientras Time Warp 2026 se realiza en Expo Santa Fe.","b":"","img":"autodromo","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4906611/calles-cerradas-por-desfile-del-dia-de-la-revolucion-y-marchas-en-la-cdmx-hoy-viernes/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-la-onu-podria-quedarse-sin-secretario-general-ocho-rondas-en-el-consej","t":"La ONU podría quedarse sin secretario general: ocho rondas en el Consejo de Seguridad sin sucesor de Guterres","c":"internacional","f":"2026-11-20T06:41","r":"António Guterres deja el cargo el 31 de diciembre y, tras ocho rondas de votación, el Consejo de Seguridad aún no acuerda a su sucesor por diferencias entre los cinco miembros permanentes. Rebeca Grynspan y la diplomática emiratí Lana Nusseibeh figuran entre las favoritas. La Carta de la ONU no contempla un procedimiento para una vacante en el puesto.","b":"","img":"ultimahora","foto":"","cred":"","src":[["10 Things Global News","https://www.10things.news/p/10-things-global-news-20th-november-0cb"]],"dest":false,"a":"Redacción"},{"id":"2026-11-20-la-aie-preve-que-las-emisiones-de-los-centros-de-datos-suban-70-hacia","t":"La AIE prevé que las emisiones de los centros de datos suban 70% hacia 2030 por la inteligencia artificial","c":"tecnologia","f":"2026-11-20T06:40","r":"La Agencia Internacional de la Energía proyecta que las emisiones de los centros de datos aumenten 70% para 2030 y que su consumo eléctrico se duplique en cuatro años, con la inteligencia artificial como responsable de tres cuartas partes del alza. Los centros de IA requerirán 350 teravatios hora adicionales al año, más de lo que hoy consume Gran Bretaña.","b":"","img":"tech","foto":"","cred":"","src":[["10 Things Global News","https://www.10things.news/p/10-things-global-news-20th-november-0cb"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-sheinbaum-califica-de-productiva-su-gira-por-el-apec-nueva-era-con-chi","t":"Sheinbaum califica de productiva su gira por el APEC: «nueva era» con China, pero sin tratado de libre comercio","c":"nacional","f":"2026-11-19T18:44","r":"La presidenta dijo que el viaje a Shenzhen fue muy productivo y exitoso y que afianza una nueva etapa en la relación con China. Aclaró que México no busca un tratado de libre comercio con ese país, pero ampliará la cooperación mediante los memorandos de entendimiento firmados en la visita. Sostuvo siete reuniones bilaterales, entre ellas con Trump, Carney y Xi Jinping.","b":"","img":"palacio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/19/sheinbaum-participacion-en-apec-fue-productiva-y-exitosa-afianza-nueva-era-con-china/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-19-el-peso-se-hunde-1-43-y-el-dolar-cierra-en-19-12-su-peor-nivel-desde-j","t":"El peso se hunde 1.43% y el dólar cierra en 19.12, su peor nivel desde junio de 2025","c":"economia","f":"2026-11-19T18:43","r":"Con datos de cierre del Banco de México, la moneda pasó de 18.85 a 19.12 unidades por dólar y fue la divisa emergente con mayor pérdida del día; acumula una caída de más de 10% desde inicios de septiembre. Pesaron las minutas de la Fed, que anticipan más alzas, y la minuta de Banxico, que reafirmó la postura acomodaticia de la mayoría de su Junta. En ventanilla de Banamex el dólar se vendió en 19.44 pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/19/la-bolsa-mexicana-pierde-064-liga-cinco-sesiones-negativas-y-baja-a-687136-unidades/"],["El Financiero","https://www.elfinanciero.com.mx/mercados/2026/11/19/peso-dolar-tipo-de-cambio-precio-hoy-19-de-noviembre-de-2026/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-19-woldenberg-ugalde-valdes-y-cordova-piden-a-san-lazaro-elegir-por-conse","t":"Woldenberg, Ugalde, Valdés y Córdova piden a San Lázaro elegir por consenso al nuevo titular del INE; Monreal no ve prisa","c":"politica","f":"2026-11-19T18:42","r":"Los cuatro expresidentes del IFE e INE, en un pronunciamiento firmado por 16 exconsejeros, pidieron a la Cámara de Diputados un relevo consensuado tras la renuncia de Guadalupe Taddei. Ricardo Monreal descartó por ahora reformar el artículo 45, condición de Movimiento Ciudadano, y dijo que no hay plazo constitucional. La crisis suma 60 salidas de mandos en 26 días, según La Razón.","b":"","img":"ine","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/19/urgen-expresidentes-del-ine-relevo-y-por-consenso-en-camara-su-idea-no-anima-a-4t/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-19-sheinbaum-emprende-el-regreso-desde-shenzhen-y-llegara-de-madrugada-pa","t":"Sheinbaum emprende el regreso desde Shenzhen y llegará de madrugada para encabezar el desfile de la Revolución","c":"nacional","f":"2026-11-19T18:41","r":"La presidenta tomó un vuelo comercial en el aeropuerto de Shenzhen, informó la secretaria de Gobernación, Rosa Icela Rodríguez, quien encabezó la mañanera de este jueves. Se prevé que llegue a la Ciudad de México en los primeros minutos del viernes 20 para presidir el desfile por el 116 aniversario de la Revolución Mexicana.","b":"","img":"zocalo","foto":"","cred":"","src":[["Tribuna","https://tribuna.com.mx/mexico/2026/11/19/sheinbaum-regresa-de-china-a-que-hora-llegara-a-mexico-y-encabezara-el-desfile-del-20-de-noviembre_717484/"],["La Razón","https://www.razon.com.mx/mexico/2026/11/19/mananera-del-gobierno-19-de-noviembre-del-2026-la-encabeza-la-titular-de-segob/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-19-trump-xi-y-putin-firman-en-shenzhen-una-declaracion-de-paz-y-pactan-un","t":"Trump, Xi y Putin acuerdan en Shenzhen una «declaración de paz» y pactan un diálogo para reducir riesgos nucleares","c":"internacional","f":"2026-11-19T18:40","r":"Tras más de una hora de reunión al margen del APEC, los tres líderes difundieron una declaración que reafirma la importancia de flujos estables de energía y compromete un diálogo sobre riesgos nucleares y no proliferación. Xi afirmó que una guerra nuclear no puede ganarse y no debe librarse. El texto también pide a la Corte Penal Internacional no abusar de su posición; la guerra con Irán apenas se mencionó.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Al Jazeera","https://www.aljazeera.com/news/2026/11/19/groundbreaking-trump-xi-putin-summit-five-key-takeaways"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-sheinbaum-celebra-el-compromiso-de-estabilidad-estrategica-de-trump-xi","t":"Sheinbaum celebra el compromiso de «estabilidad estratégica» de Trump, Xi y Putin; en el APEC defiende una IA contra la pobreza","c":"politica","f":"2026-11-19T18:39","r":"La presidenta dio la bienvenida al encuentro de los tres líderes y dijo que debe traducirse en paz y prosperidad para todos los países. En la Cumbre de Directores Ejecutivos del APEC presentó el Plan México y sostuvo que el desarrollo de la inteligencia artificial debe servir para reducir la pobreza y la desigualdad.","b":"","img":"palacio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/19/sheinbaum-celebra-posible-acuerdo-de-estabilidad-tras-reunion-entre-trump-putin-y-jinping/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-mexico-y-peru-restablecen-formalmente-sus-relaciones-diplomaticas-en-e","t":"México y Perú restablecen formalmente sus relaciones diplomáticas en el marco del APEC","c":"politica","f":"2026-11-19T18:38","r":"El restablecimiento se concretó durante la gira de la presidenta Claudia Sheinbaum por Shenzhen, China, donde sostuvo un encuentro con Keiko Fujimori. Fue una de sus siete reuniones bilaterales, junto con las que tuvo con Donald Trump, Mark Carney, Xi Jinping, To Lam, Lawrence Wong y Kristalina Georgieva, del FMI.","b":"","img":"palacio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/19/sheinbaum-participacion-en-apec-fue-productiva-y-exitosa-afianza-nueva-era-con-china/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-el-dow-jones-se-desploma-1-101-puntos-y-el-s-p-500-suma-seis-caidas-se","t":"El Dow Jones se desploma 1,101 puntos y el S&P 500 suma seis caídas seguidas, su peor racha desde 2024","c":"economia","f":"2026-11-19T18:37","r":"Los tres principales índices de Wall Street perdieron más de 2% y más de 90% de las acciones del S&P 500 cerraron en rojo; el Nasdaq cedió 550.69 puntos tras subir cerca de 2% en la mañana. Pesaron las preocupaciones por restricciones a la exportación de chips, posibles reglas más estrictas para centros de datos y un escándalo que involucra a Nvidia y a su exdirector Jensen Huang. El S&P 500 quedó 8.2% debajo de su récord de octubre.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión","https://expansion.mx/mercados/2026/11/19/acciones-anthropic-sube-17-en-su-debut-pero-wall-street-cae"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-anthropic-sube-17-en-su-debut-en-el-nasdaq-y-cierra-en-97-17-dolares-v","t":"Anthropic sube 17% en su debut en el Nasdaq y cierra en 97.17 dólares; vale cerca de 1.8 billones","c":"tecnologia","f":"2026-11-19T18:36","r":"La creadora de Claude abrió en 111.50 dólares, 34.3% arriba del precio de colocación de 83, y terminó la jornada 12.9% por debajo de su primera operación. Vendió 980 millones de acciones y recaudó 81,300 millones de dólares, por encima del récord de SpaceX de junio. En el día se negociaron más de 846 millones de títulos con la clave ANT.","b":"","img":"tech","foto":"","cred":"","src":[["Expansión","https://expansion.mx/mercados/2026/11/19/acciones-anthropic-sube-17-en-su-debut-pero-wall-street-cae"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-la-bolsa-mexicana-cae-0-64-a-68-713-puntos-y-suma-cinco-sesiones-a-la","t":"La Bolsa mexicana cae 0.64% a 68,713 puntos y suma cinco sesiones a la baja","c":"economia","f":"2026-11-19T18:35","r":"El S&P/BMV IPC acumula una pérdida de 3.48% en la semana y de 1.5% en noviembre. Frisco se desplomó 9.93%, Peñoles 4.52% y Grupo México 3.87%; en cambio, Grupo Carso subió 4.51% y ASUR 3.41%. Se negociaron 242 millones de acciones por 21,935 millones de pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/19/la-bolsa-mexicana-pierde-064-liga-cinco-sesiones-negativas-y-baja-a-687136-unidades/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-el-brent-cierra-casi-sin-cambios-en-91-98-dolares-acumula-una-caida-ce","t":"El Brent cierra casi sin cambios en 91.98 dólares; acumula una caída cercana a 20% en noviembre","c":"economia","f":"2026-11-19T18:34","r":"El crudo de referencia internacional subió 0.03% tras moverse en un rango de unos 2 dólares por la incertidumbre en Medio Oriente. El WTI para diciembre, que vence el viernes, bajó 0.06% a 83.21 dólares, mientras el contrato de enero subió 0.2% a 82.44.","b":"","img":"pemex","foto":"","cred":"","src":[["Rigzone / Bloomberg","https://www.rigzone.com/news/wire/oil_prices_swing_on_middle_east_uncertainty-19-nov-2026-185129-article/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-cae-en-ometepec-beto-zacualpan-presunto-integrante-de-los-rusos-ligado","t":"Cae en Ometepec «Beto Zacualpan», presunto integrante de Los Rusos ligado al asesinato de un líder amuzgo","c":"seguridad","f":"2026-11-19T18:33","r":"Heriberto «N» fue detenido el 18 de noviembre en un operativo en Ometepec, Guerrero, donde se aseguraron armas, cartuchos y droga. Se le vincula con el homicidio de Remigio «N», líder amuzgo asesinado el 1 de enero de 2023 en Zacualpan. Las autoridades lo identifican como generador de violencia en la Costa Chica.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/19/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-19-de-noviembre-detienen-en-guerrero-a-presunto-integrante-de-los-rusos-por-homicidio-de-lider-amuzgo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-detienen-a-cuatro-hombres-por-el-ataque-a-la-casa-del-alcalde-de-tepeh","t":"Detienen a cuatro hombres por el ataque a la casa del alcalde de Tepehuacán, Hidalgo, en el que murieron dos policías","c":"seguridad","f":"2026-11-19T18:32","r":"El gabinete de seguridad de Hidalgo informó que la línea principal de investigación es el robo y que el ataque del sábado 14 contra la vivienda de Francisco Martínez Enríquez no tendría motivos políticos. Los policías municipales Samuel Flores Santiago y Luis Alfredo Bautista Ortiz murieron en la agresión. El conductor del vehículo usado fue detenido en Tepeapulco con dos armas y otros tres hombres cayeron en un operativo con la Guardia Nacional.","b":"","img":"ultimahora","foto":"","cred":"","src":[["88.9 Noticias","https://889noticias.mx/noticias/seguridad-y-justicia/detienen-a-cuatro-hombres-por-el-ataque-armado-contra-la-casa-de-un-alcalde-en-hidalgo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-detienen-a-seis-personas-tras-un-triple-homicidio-en-cancun-dos-estari","t":"Detienen a seis personas tras un triple homicidio en Cancún; dos estarían ligadas directamente al ataque","c":"estados","f":"2026-11-19T18:31","r":"La policía detuvo el miércoles a seis personas en el fraccionamiento Villas Otoch, en la Región 247, después de un ataque armado contra una camioneta Mazda CX-5 que recibió 28 disparos. Murieron tres personas; hasta ahora solo se ha identificado a una víctima, de 29 años. Las autoridades señalan que dos de los detenidos estarían relacionados de forma directa con el crimen.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Noticaribe","https://noticaribe.com.mx/2026/11/19/detienen-a-6-por-triple-homicidio-en-cancun/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-la-sep-confirma-el-ultimo-puente-del-ano-no-habra-clases-el-viernes-27","t":"La SEP confirma el último puente del año: no habrá clases el viernes 27 de noviembre","c":"nacional","f":"2026-11-19T18:30","r":"Los alumnos de educación básica descansarán del 27 al 29 de noviembre porque ese viernes se realiza la sesión mensual del Consejo Técnico Escolar, y volverán a las aulas el lunes 30. Es el último puente del calendario de 2026; las vacaciones de invierno irán del 21 de diciembre al 6 de enero de 2027.","b":"","img":"palacio","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/sociedad/educacion/proximo-puente-ultimo-2026-cuando-es-sep-confirma-dia-sin-clases-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-marchan-en-reforma-contra-el-plan-general-de-desarrollo-de-la-cdmx-pid","t":"Marchan en Reforma contra el Plan General de Desarrollo de la CDMX; piden repetir la consulta","c":"cdmx","f":"2026-11-19T18:29","r":"El Comité de Lucha contra el Plan General de Desarrollo y Ordenamiento Territorial salió a las 9:00 horas de Insurgentes Sur y Paseo de la Reforma, en la colonia Juárez. Exige reponer el proceso de consulta del plan capitalino y del programa de ordenamiento de la zona metropolitana del Valle de México. En la misma jornada hubo actos en la capital por el Día Nacional contra el Abuso Sexual Infantil.","b":"","img":"angel","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/19/en-vivo-bloqueos-accidentes-y-manifestaciones-hoy-19-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-michoacan-realiza-su-ultima-feria-del-empleo-de-2026-con-1-090-vacante","t":"Michoacán realiza su última feria del empleo de 2026 con 1,090 vacantes en seis municipios","c":"estados","f":"2026-11-19T18:28","r":"La Secretaría de Desarrollo Económico estatal, con la STPS y el Servicio Nacional de Empleo, organizó la feria este jueves de 9:00 a 14:00 horas con 125 empresas. Morelia concentró 280 vacantes en la explanada del IMSS y Lázaro Cárdenas 170; La Piedad, Uruapan, Zamora y Zitácuaro ofrecieron 160 cada uno.","b":"","img":"palacio","foto":"","cred":"","src":[["Esfera Noticias","https://esferanoticias.mx/2026/11/18/ofertaran-mas-de-mil-vacantes-en-la-ultima-feria-de-empleo-de-2026-en-michoacan/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-piden-destituir-a-la-diputada-lorena-de-la-garza-tras-la-fumigacion-de","t":"Piden destituir a la diputada Lorena de la Garza tras la fumigación de un parque con mariposas monarca en Monterrey","c":"estados","f":"2026-11-19T18:27","r":"Personal de la legisladora local del PRI fumigó árboles de un parque junto a la iglesia de la Natividad, donde descansaban mariposas monarca en migración, antes de un evento que ella organizó. Una petición en Change.org para su destitución superó las 15 mil firmas, y el activista Arturo Islas Allende anunció denuncias ante Profepa y la FGR. De la Garza reconoció en Instagram que la fumigación fue un error y dijo que revisará los protocolos de su equipo.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/estados/nuevo-leon/exigen-destituir-a-diputada-de-nuevo-leon-tras-fumigacion-en-parque-con-mariposas-monarca/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-caifanes-y-diego-luna-reunen-a-mas-de-3-mil-personas-en-un-concierto-p","t":"Caifanes y Diego Luna reúnen a más de 3 mil personas en un concierto por los desaparecidos y los pueblos originarios","c":"entretenimiento","f":"2026-11-19T18:26","r":"El «Concierto por un Abrazo» se realizó el miércoles en el Teatro Metropólitan de la Ciudad de México. Lo recaudado financiará la estancia de familias de personas desaparecidas en diciembre y la «Gira por la Vida» del EZLN. Diego Luna dijo que el país tiene dos grandes deudas: con los pueblos indígenas y con las familias de desaparecidos. También participaron Vivir Quintana, Ely Guerra, Kevin Kaarl y Meme del Real.","b":"","img":"estudio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/19/caifanes-y-diego-luna-exigen-justicia-por-desaparecidos-y-pueblos-originarios-en-el-concierto-por-un-abrazo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-soles-busca-esta-noche-en-guadalajara-su-quinta-estrella-lidera-3-1-la","t":"Soles busca esta noche en Guadalajara su quinta estrella; lidera 3-1 la final de la LNBP ante Astros","c":"deportes","f":"2026-11-19T18:25","r":"Soles de Mexicali visita a Astros de Jalisco en la Arena Astros para el quinto juego de la Gran Final, programado a las 18:15 horas de Baja California. Soles ganó el cuarto partido 76-75 con un triple de Phillip Scrubb a 1.7 segundos del final, y al término del encuentro aficionados locales encararon a jugadores visitantes y hubo una riña entre ambos equipos. El club busca su quinto título de liga.","b":"","img":"estadio","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/mxl/mexicali/2026/11/19/soles-de-mexicali-busca-conquistar-la-quinta-estrella-en-casa-de-astros/"],["Récord","https://www.record.com.mx/historia/soles-y-astros-protagonizan-pelea-tras-dramatico-cierre-en-la-gran-final-de-la-lnbp-2026111901543231793"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-sheinbaum-cierra-su-gira-por-la-apec-en-shenzhen-y-regresa-a-mexico-pa","t":"Sheinbaum cierra su gira por la APEC en Shenzhen y regresa a México para el desfile del 20 de noviembre","c":"nacional","f":"2026-11-19T06:59","r":"La presidenta participó el miércoles en la sesión plenaria de la 33 Reunión de Líderes de la APEC, en Shenzhen, China, donde presentó el Plan México ante empresarios. Durante la gira se reunió con Xi Jinping, Donald Trump, Mark Carney y el vietnamita To Lam; con Trump acordó volver a verse en el G20 de diciembre en Mar-a-Lago. Este jueves inicia su regreso para encabezar el desfile por el 116 aniversario de la Revolución.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/19/claudia-sheinbaum-llega-al-segundo-dia-de-apec-en-china-para-presentar-la-postura-de-mexico-ante-lideres-mundiales/"],["Prensa Latina","https://www.prensa-latina.cu/2026/11/19/sheinbaum-regresara-a-mexico-tras-participar-en-cumbre-de-apec/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-19-cae-en-zapopan-el-topo-senalado-lider-de-los-deltas-del-cjng-tres-muer","t":"Cae en Zapopan “El Topo”, señalado líder de Los Deltas del CJNG; tres muertos y ocho detenidos en el operativo","c":"seguridad","f":"2026-11-19T06:58","r":"La Marina, con apoyo de la FGR y la SSPC, detuvo el miércoles a César Daniel de la Cruz Ortega, “El Topo”, acusado del secuestro del periodista Jaime Barrera. Al cumplir órdenes de cateo en los límites de Ciudad del Sol y Jardines del Sol, los agentes fueron agredidos a balazos y murieron tres presuntos integrantes del grupo. En total hubo ocho detenidos, entre ellos un menor; el gobernador Pablo Lemus dijo que la situación quedó controlada.","b":"","img":"jalisco","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/sube-a-ocho-la-cifra-de-detenidos-en-operativos-contra-el-topo-lider-de-los-deltas-del-cjng-entre-ellos-hay-un-menor/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-19-el-peso-pierde-0-93-y-el-dolar-cierra-en-18-85-tras-minutas-de-la-fed","t":"El peso pierde 0.93% y el dólar cierra en 18.85 tras minutas de la Fed que anticipan más alzas","c":"economia","f":"2026-11-19T06:57","r":"El tipo de cambio de referencia de Banxico cerró el miércoles en 18.8456 pesos por dólar, desde 18.6723 un día antes. Las minutas de la Reserva Federal mostraron que casi todos sus funcionarios ven necesarias nuevas alzas de tasas. Banco Base advirtió que el diferencial de tasas entre México y EU, de 225 puntos base, está en su nivel más bajo, lo que resta atractivo al peso.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Mañana","https://elmanana.com.mx/nacional/2026/11/18/tipo-de-cambio-pesodolar-al-cierre-hoy-miercoles-18-de-noviembre-184660.html"]],"dest":true,"a":"Redacción"},{"id":"2026-11-19-segob-acusa-que-el-bloqueo-en-santa-fe-fue-pagado-por-un-grupo-crimina","t":"Segob acusa que el bloqueo en Santa Fe fue pagado por un grupo criminal y anuncia acciones legales","c":"nacional","f":"2026-11-19T06:56","r":"La secretaria de Gobernación, Rosa Icela Rodríguez, dijo en la mañanera del miércoles que algunos participantes del bloqueo del martes en la México-Toluca recibieron pago de un grupo delictivo ligado a una persona en prisión. La protesta la hicieron familiares de internos del penal federal número 4 de Tepic, Nayarit. Rodríguez informó que se abrió una investigación y que el derecho a protestar no puede encubrir actividades ilegales.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/denuncian-que-manifestaciones-para-cerrar-santa-fe-fueron-pagadas-segob-iniciara-proceso-legal-y-llama-al-dialogo/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-19-trump-xi-y-putin-celebran-hoy-en-shenzhen-una-cumbre-trilateral-sobre","t":"Trump, Xi y Putin celebran hoy en Shenzhen una cumbre trilateral sobre control nuclear, Ucrania e Irán","c":"internacional","f":"2026-11-19T06:55","r":"Los líderes de las tres mayores potencias nucleares se reúnen este jueves en Shenzhen, al cierre de la APEC. Trump busca un nuevo pacto de control de armas que incluya a China, tras el vencimiento en febrero del tratado New START con Rusia; Pekín se ha resistido. El Kremlin prevé hablar de Ucrania, y expertos anticipan pocos acuerdos concretos.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/19/trump-xi-y-putin-se-reunen-en-una-historica-cumbre-trilateral-con-la-guerra-en-ucrania-iran-y-el-control-nuclear-en-la-agenda/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-la-bolsa-mexicana-cae-1-75-a-69-154-puntos-su-cuarta-baja-seguida-peno","t":"La Bolsa mexicana cae 1.75% a 69,154 puntos, su cuarta baja seguida; Peñoles y Grupo México se hunden","c":"economia","f":"2026-11-19T06:54","r":"El S&P/BMV IPC cerró el miércoles en 69,154.17 unidades, su peor nivel desde el 19 de octubre. Peñoles perdió 8.37% y Grupo México 6.36%, en un día en que el oro bajó más de 3% y la plata cerca de 5%. Volaris fue la emisora con mayor avance, con 3.24%.","b":"","img":"bolsa","foto":"","cred":"","src":[["El CEO","https://elceo.com/mercados/bmv-ipc-wall-street-hoy-18-de-noviembre-de-2026-cierre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-el-ine-nombra-encargados-en-asuntos-juridicos-fiscalizacion-y-comunica","t":"El INE nombra encargados en Asuntos Jurídicos, Fiscalización y Comunicación Social en plena crisis interna","c":"politica","f":"2026-11-19T06:53","r":"El instituto designó a Michell Jaramillo Gumecindo en la Dirección de Asuntos Jurídicos, a Nely Zarahit Pérez Martínez en la Unidad de Fiscalización y a Israel Fernández Alonso en Comunicación Social, como encargados de despacho. Los relevos llegan tras la salida de funcionarios en medio del escándalo de contrataciones que involucra a la expresidenta Guadalupe Taddei. Otras dos unidades técnicas cambiarán de titular el 30 de noviembre.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/19/llegan-los-relevos-al-ine-y-nombran-a-titulares-de-areas-estrategicas-como-asuntos-juridicos-y-fiscalizacion/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-anthropic-fija-su-opi-en-83-dolares-por-accion-arriba-del-rango-previs","t":"Anthropic fija su OPI en 83 dólares por acción, arriba del rango previsto, y debuta hoy en el Nasdaq","c":"tecnologia","f":"2026-11-19T06:52","r":"La empresa de inteligencia artificial colocó sus acciones en 83 dólares, por encima del rango de 70 a 78 dólares, lo que la valúa en alrededor de 1.5 billones de dólares. Empezará a cotizar este jueves en el Nasdaq con la clave ANT.","b":"","img":"tech","foto":"","cred":"","src":[["Yahoo Finance","https://finance.yahoo.com/markets/stocks/articles/stock-market-today-nasdaq-p-125812319.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-el-frente-frio-6-traera-lluvias-fuertes-al-sur-de-veracruz-oaxaca-chia","t":"El frente frío 6 traerá lluvias fuertes al sur de Veracruz, Oaxaca, Chiapas y Tabasco; heladas en la sierra del norte","c":"nacional","f":"2026-11-19T06:51","r":"El Servicio Meteorológico Nacional prevé para este jueves lluvias de 25 a 50 mm en esas zonas y rachas de viento de hasta 80 km/h en el Istmo y el Golfo de Tehuantepec. En sierras de Baja California, Chihuahua y Durango habrá mínimas de -5 a 0 grados. Un nuevo frente frío se acerca al noroeste con chubascos en Baja California.","b":"","img":"lluvia","foto":"","cred":"","src":[["López-Dóriga Digital","https://lopezdoriga.com/nacional/clima-en-mexico-hoy-jueves-19-de-noviembre-de-2026-frente-frio-6-ocasionara-lluvias-fuertes-en-al-menos-4-estados/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-el-dow-jones-cae-1-11-y-nvidia-baja-2-89-pese-a-superar-expectativas-e","t":"El Dow Jones cae 1.11% y Nvidia baja 2.89% pese a superar expectativas; el Nasdaq rompe su racha negativa","c":"economia","f":"2026-11-19T06:50","r":"El Dow cerró el miércoles en 50,198 puntos y el S&P 500 bajó 0.23%, su quinta caída seguida, mientras el Nasdaq subió 0.42%. Nvidia perdió 2.89% tras reportar ingresos de 115,800 millones de dólares, 103% más que hace un año, en su primer informe sin Jensen Huang como director. Chevron y Exxon bajaron más de 4%.","b":"","img":"bolsa","foto":"","cred":"","src":[["El CEO","https://elceo.com/mercados/bmv-ipc-wall-street-hoy-18-de-noviembre-de-2026-cierre/"],["Expansión","https://expansion.mx/mercados/2026/11/18/nvidia-borra-su-repunte-y-la-bmv-cae-por-debajo-de-los-70-000-puntos"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-eu-ofrece-hasta-10-millones-de-dolares-por-informacion-sobre-redes-de","t":"EU ofrece hasta 10 millones de dólares por información sobre redes de lavado de cárteles mexicanos","c":"seguridad","f":"2026-11-19T06:49","r":"El Departamento de Estado difundió por su programa Recompensas por la Justicia un cartel que busca datos sobre el dinero del narcotráfico, el robo de combustible y el secuestro. Menciona a los cárteles de Sinaloa, Jalisco Nueva Generación, del Noreste, del Pacífico y a La Nueva Familia Michoacana. Los avisos pueden enviarse de forma anónima.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/eeuu-vs-carteles-mexicanos-ofrecen-recompensa-de-10-millones-de-dolares-por-redes-de-lavado-de-dinero/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-el-wti-cae-3-10-a-83-34-dolares-por-un-alza-inesperada-en-inventarios","t":"El WTI cae 3.10% a 83.34 dólares por un alza inesperada en inventarios de EU; el Brent cierra en 91.65","c":"economia","f":"2026-11-19T06:48","r":"Los inventarios de crudo de Estados Unidos subieron 3.4 millones de barriles, a 417.8 millones, muy por encima de lo que esperaban los analistas. El Brent para enero bajó 1.60% en la sesión del miércoles.","b":"","img":"pemex","foto":"","cred":"","src":[["El CEO","https://elceo.com/mercados/bmv-ipc-wall-street-hoy-18-de-noviembre-de-2026-cierre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-rescatan-con-vida-a-cinco-personas-secuestradas-en-bacum-sonora-detien","t":"Rescatan con vida a cinco personas secuestradas en Bácum, Sonora; detienen a un hombre de 26 años","c":"estados","f":"2026-11-19T06:47","r":"Agentes de la Fiscalía de Sonora liberaron el martes a las cinco víctimas en un inmueble de Loma de Bácum y detuvieron a Samuel “N”, señalado como integrante de un grupo rival. Aseguraron un fusil tipo AK-47. Según la fiscalía, el caso estaría ligado a una disputa por la venta de drogas; las víctimas también son investigadas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/19/fiscalia-de-sonora-rescata-a-cinco-personas-secuestradas-en-bacum-rapto-estaria-vinculado-con-disputa-entre-grupos-por-narcomenudeo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-inteligencia-de-eu-afirma-que-las-amenazas-de-iran-contra-estadouniden","t":"Inteligencia de EU afirma que las amenazas de Irán contra estadounidenses aumentaron “sustancialmente”","c":"internacional","f":"2026-11-19T06:46","r":"El director de Inteligencia Nacional, Jay Clayton, lo dijo el miércoles ante un comité de la Cámara de Representantes. El secretario de Estado, Marco Rubio, señaló que no considera inminente una amenaza contra Washington. Irán calificó los reportes como una campaña de desinformación y negó planear un ataque con una bomba sucia.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mundo/2026/11/19/aumentan-las-amenazas-de-iran-contra-eu/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-eu-descarta-un-ciberataque-detras-de-las-fallas-de-outlook-apple-banco","t":"EU descarta un ciberataque detrás de las fallas de Outlook, Apple, bancos y aerolíneas de la última semana","c":"tecnologia","f":"2026-11-19T06:45","r":"Jay Clayton dijo que la investigación encontró problemas aislados por mantenimiento y cambios técnicos, sin evidencia de una operación coordinada; Rubio coincidió desde Manila. El responsable de la FAA, Bryan Bedford, asumió la culpa por la suspensión de vuelos del viernes que afectó a más de un millón de pasajeros.","b":"","img":"tech","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mundo/2026/11/19/estados-unidos-descarta-un-ciberataque-en-fallas/"],["Infobae","https://www.infobae.com/estados-unidos/2026/11/18/rubio-descarto-que-las-fallas-tecnologicas-en-eeuu-respondan-a-un-ciberataque-coordinado-no-tenemos-ninguna-evidencia/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-detienen-en-mexicali-a-un-hombre-que-se-identifico-como-sobrino-de-fel","t":"Detienen en Mexicali a un hombre que se identificó como sobrino de Félix Gallardo, con un rifle y una camioneta robada","c":"estados","f":"2026-11-19T06:44","r":"La Fuerza Estatal de Seguridad Ciudadana de Baja California detuvo el martes a Eusebio Armando Vaca Gallardo, de 50 años, cerca de la comunidad Nuevo Milenio. Llevaba un rifle de uso exclusivo del Ejército, 31 cartuchos y una camioneta con reporte de robo; tenía una orden de aprehensión por homicidio de 2024. Fue puesto a disposición de la FGR.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/cae-en-mexicali-sobrino-de-miguel-angel-felix-gallardo-con-arma-del-ejercito-y-camioneta-robada/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-el-aicm-cambiara-sus-rutas-de-despegue-en-2027-para-reducir-el-ruido-s","t":"El AICM cambiará sus rutas de despegue en 2027 para reducir el ruido sobre la Ciudad de México y el Edomex","c":"cdmx","f":"2026-11-19T06:43","r":"Según el movimiento Aeronáutica Segura, Menos Ruido, Seneam rediseña las salidas para que los aviones giren antes, cerca del Viaducto, y eviten zonas como Santa Fe e Interlomas; los nuevos procedimientos podrían operar en marzo o abril. El colectivo calcula que el cambio reducirá el ruido para 1.3 millones de personas. La nota no incluye postura oficial del AICM.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/aicm-cambiara-sus-rutas-de-despegue-en-2027-para-reducir-el-ruido-aereo-en-cdmx-y-edomex/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-christie-s-retira-de-su-subasta-un-cuadro-de-frida-kahlo-tras-una-soli","t":"Christie's retira de su subasta un cuadro de Frida Kahlo tras una solicitud del INBAL","c":"entretenimiento","f":"2026-11-19T06:42","r":"La casa de subastas sacó de su venta del martes en Nueva York la obra “Congreso de los pueblos por la paz”, estimada entre 2.5 y 3.5 millones de dólares, para investigar su procedencia. El INBAL pidió documentos que acrediten su origen y propiedad; la obra de Kahlo es monumento artístico desde 1984 y su exportación definitiva está restringida.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/cuanto-vale-asi-es-la-obra-de-frida-kahlo-que-christies-retiro-de-su-subasta-tras-la-peticion-de-mexico/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-mexico-sale-del-top-10-del-ranking-fifa-baja-al-lugar-13-tras-cuatro-m","t":"México sale del top 10 del ranking FIFA: baja al lugar 13 tras cuatro meses","c":"deportes","f":"2026-11-19T06:41","r":"La Selección Mexicana cayó tres posiciones en la última actualización del año y suma 1,723.64 puntos. Estaba en el décimo sitio desde el 20 de julio. España encabeza la clasificación, seguida de Argentina.","b":"","img":"estadio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/deportes/2026/11/19/mexico-sale-del-top-10-de-la-fifa-despues-de-cuatro-meses/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-19-cadillac-confirma-a-valtteri-bottas-como-companero-de-checo-perez-para","t":"Cadillac confirma a Valtteri Bottas como compañero de Checo Pérez para la temporada 2027 de F1","c":"deportes","f":"2026-11-19T06:40","r":"El equipo anunció la continuidad del finlandés, de 37 años, un día antes de las prácticas del Gran Premio de Las Vegas, y dejó fuera por ahora a Colton Herta. Bottas no ha sumado puntos en 20 carreras este año y Cadillac es el único equipo sin unidades en 2026.","b":"","img":"autodromo","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/deportes/2026/11/19/cadillac-confirma-a-bottas-como-coequipero-de-perez/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-sheinbaum-y-trump-se-reunen-en-shenzhen-el-t-mec-tema-central-del-brev","t":"Sheinbaum y Trump se reúnen en Shenzhen; el T-MEC, tema central del breve encuentro","c":"nacional","f":"2026-11-18T06:39","r":"La presidenta Claudia Sheinbaum se reunió con Donald Trump en el hotel The Langham de Shenzhen, China, al margen de la cumbre del APEC, antes de la cena de líderes. La acompañaron el secretario de Economía, Marcelo Ebrard, y el canciller Roberto Velasco; el tema principal fue el avance de la revisión del T-MEC. Es su tercer encuentro en persona; Sheinbaum no dio declaraciones al salir y no se informaron acuerdos concretos.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/sheinbaum-y-trump-se-reunieron-en-shenzhen-para-hablar-del-t-mec/"],["MVS Noticias","https://mvsnoticias.com/nacional/2026/11/18/dialogan-sheinbaum-y-trump-sobre-el-t-mec-en-cumbre-apec-753866.html"]],"dest":true,"a":"Redacción"},{"id":"2026-11-18-maiceros-rechazan-el-apoyo-de-950-pesos-por-tonelada-y-mantienen-bloqu","t":"Maiceros rechazan el apoyo de 950 pesos por tonelada y mantienen bloqueos en Jalisco; hoy negocian en Gobernación","c":"nacional","f":"2026-11-18T06:38","r":"El gobierno federal anunció un incentivo de 950 pesos por tonelada de maíz blanco, pero productores de Jalisco lo consideran insuficiente y piden reglas por escrito, compras prioritarias de grano nacional y control de importaciones. Seguían cerradas la autopista Guadalajara-Colima a la altura del kilómetro 40, la Guadalajara-Morelia en Ocotlán y la carretera a Tepatitlán. Este miércoles continúan las negociaciones con la secretaria de Gobernación, Rosa Icela Rodríguez.","b":"","img":"carretera","foto":"","cred":"","src":[["Yahoo Noticias","https://es-us.noticias.yahoo.com/productores-ma%C3%ADz-mantienen-bloqueos-carreteros-013555744.html"],["La Jornada","https://www.jornada.com.mx/2026/11/18/estados/025n1est?partner=rss"]],"dest":true,"a":"Redacción"},{"id":"2026-11-18-mier-propone-que-blanca-cruz-siga-al-frente-del-ine-hasta-la-eleccion","t":"Mier propone que Blanca Cruz siga al frente del INE hasta la elección de 2027; PAN y PRI lo rechazan","c":"politica","f":"2026-11-18T06:37","r":"El coordinador de Morena en el Senado, Ignacio Mier, planteó que la presidenta provisional del INE, Blanca Yassahara Cruz, se quede en el cargo y conduzca los comicios de 2027 si la Cámara de Diputados no logra acuerdo para nombrar a un titular. Ricardo Anaya (PAN) rechazó extender el interinato y Manuel Añorve (PRI) acusó a Morena de retrasar el nombramiento. La convocatoria aún no se emite.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/lider-de-morena-plantea-que-blanca-cruz-siga-al-frente-del-ine-hasta-la-eleccion-de-2027/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-18-mexico-vence-1-0-a-jamaica-en-monterrey-y-avanza-al-final-four-de-la-n","t":"México vence 1-0 a Jamaica en Monterrey y avanza al Final Four de la Nations League por goles de visitante","c":"deportes","f":"2026-11-18T06:36","r":"La Selección Mexicana ganó 1-0 a Jamaica en el Estadio BBVA y empató 3-3 el global de los cuartos de final; avanzó gracias a los dos goles que marcó como visitante en Kingston. Es el primer triunfo de Rafael Márquez como técnico. El pase a semifinales también da boleto directo a la Copa Oro 2027; las finales se jugarán en marzo de 2027.","b":"","img":"estadio","foto":"","cred":"","src":[["Grupo Animal","https://grupoanimal.mx/deportes/mexico-vence-jamaica-primer-triunfo-rafa-marquez-semifinales-nations-league"]],"dest":true,"a":"Redacción"},{"id":"2026-11-18-sheinbaum-se-reune-con-el-lider-de-vietnam-to-lam-mexico-organizara-el","t":"Sheinbaum se reúne con el líder de Vietnam, To Lam; México organizará el APEC en 2028","c":"politica","f":"2026-11-18T06:35","r":"En Shenzhen, la presidenta sostuvo una reunión bilateral con To Lam sobre comercio y la organización del APEC, que Vietnam recibirá en 2027 y México en 2028. Vietnam es el cuarto país del que México más importa, según datos del INEGI a julio. Sheinbaum también visitó un hospital que usa inteligencia artificial en diagnósticos y dijo que quiere llevar ese modelo a México.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/sheinbaum-y-trump-se-reunieron-en-shenzhen-para-hablar-del-t-mec/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-guanajuato-levanta-los-bloqueos-agricolas-tras-un-acuerdo-de-hasta-1-2","t":"Guanajuato levanta los bloqueos agrícolas tras un acuerdo de hasta 1,250 pesos por tonelada de maíz","c":"estados","f":"2026-11-18T06:34","r":"El secretario de Gobierno de Guanajuato, Jorge Jiménez Lona, informó que los productores retiraron los cierres tras una mesa con autoridades federales y estatales: habrá 950 pesos por tonelada de maíz blanco más 300 pesos de flete si el grano va a consumo pecuario. Con el precio de referencia de 5,226 pesos, el ingreso llegaría a 6,176 pesos por tonelada, por debajo de los 6,500 que piden. La jornada dejó 10 cierres totales y 2 parciales.","b":"","img":"carretera","foto":"","cred":"","src":[["Quadratín Bajío","https://bajio.quadratin.com.mx/acuerdan-levantar-bloqueos-carreteros-en-guanajuato-tras-acuerdo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-campesinos-toman-el-pleno-del-congreso-de-zacatecas-exigen-mantener-el","t":"Campesinos toman el pleno del Congreso de Zacatecas; exigen mantener el frijol en 27 pesos por kilo","c":"estados","f":"2026-11-18T06:33","r":"Decenas de productores ocuparon el pleno y la tribuna del Congreso local para exigir que el precio de garantía del frijol se mantenga en 27 pesos por kilo y no baje a 20. Tras más de diez horas de reunión con la secretaria de Agricultura, Columba Jazmín López, no hubo acuerdo. En Campeche, unos 200 productores de maíz protestaron seis horas ante la oficina de la Sader.","b":"","img":"ganado","foto":"","cred":"","src":[["La Jornada","https://www.jornada.com.mx/2026/11/18/estados/025n1est?partner=rss"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-el-brent-baja-0-87-a-92-34-dolares-en-la-manana-el-wti-cae-1-69","t":"El Brent baja 0.87% a 92.34 dólares en la mañana; el WTI cae 1.69%","c":"economia","f":"2026-11-18T06:32","r":"El crudo Brent cotizaba en 92.34 dólares por barril este miércoles, con una baja de 0.87%, y el WTI en 84.56 dólares, 1.69% menos. El oro retrocedía 2.16% a 3,780 dólares por onza. Los mercados siguen la escalada entre Irán y Estados Unidos en el estrecho de Ormuz y esperan las minutas de la Reserva Federal.","b":"","img":"pemex","foto":"","cred":"","src":[["Bolsamanía","https://www.bolsamania.com/noticias/mercados/wall-street-miercoles-18-noviembre-rebote-nasadaq-nvidia-ia--24216726.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-detienen-en-acapulco-a-un-presunto-homicida-del-periodista-eduardo-flo","t":"Detienen en Acapulco a un presunto homicida del periodista Eduardo Flores Salado","c":"seguridad","f":"2026-11-18T06:31","r":"La Fiscalía de Guerrero cumplió el 17 de noviembre una orden de aprehensión contra Jonathan \"N\" por el homicidio calificado del comunicador, asesinado el 14 de noviembre en Acapulco. La fiscalía dijo que hasta ahora no hay elementos que vinculen el crimen con su trabajo periodístico; Amnistía Internacional pidió investigar esa línea de forma prioritaria.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/caso-eduardo-flores-salado-detienen-en-guerrero-a-presunto-homicida-del-periodista/"],["El Universal","https://www.eluniversal.com.mx/estados/detienen-a-presunto-homicida-del-periodista-eduardo-flores-autoridades-de-guerrero-descartan-movil-con-su-labor-periodistica/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-fiscalia-de-puebla-confirma-un-detenido-por-el-asesinato-del-hijo-del","t":"Fiscalía de Puebla confirma un detenido por el asesinato del hijo del alcalde de Tecamachalco","c":"seguridad","f":"2026-11-18T06:30","r":"La fiscal Idamis Pastor Betancourt informó que hay una persona aprehendida por el secuestro y homicidio de Mateo Hernández Gutiérrez, estudiante de preparatoria de la BUAP e hijo del edil Mateo Hernández López. El joven salió de su casa el 19 de septiembre y su cuerpo fue hallado el 23. La fiscal no dio el nombre del detenido, pero dijo que su captura permitió identificar a otros integrantes de la banda.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/fiscal-de-puebla-revela-que-hay-una-persona-detenida-por-el-asesinato-de-mateo-hernandez-gutierrez-hijo-del-alcalde-de-tecamachalco/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-detienen-a-tres-presuntos-integrantes-de-la-union-tepito-con-177-dosis","t":"Detienen a tres presuntos integrantes de La Unión Tepito con 177 dosis de droga en la Cuauhtémoc","c":"cdmx","f":"2026-11-18T06:29","r":"Policías de la SSC capturaron en la colonia Paulino Navarro a tres hombres de 33, 38 y 42 años con 97 bolsitas de marihuana, 52 de metanfetamina y 28 envoltorios de cocaína, además de dinero en efectivo. Uno de ellos ya había estado en prisión en 2024 por delitos contra la salud. Quedaron a disposición de la fiscalía de narcomenudeo.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/18/detienen-a-tres-integrantes-de-la-union-tepito-con-177-dosis-de-droga-en-la-alcaldia-cuauhtemoc/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-brugada-anuncia-300-nuevos-espacios-de-educacion-inicial-gratuita-en-l","t":"Brugada anuncia 300 nuevos espacios de educación inicial gratuita en la capital","c":"cdmx","f":"2026-11-18T06:28","r":"La jefa de Gobierno presentó una política para niñas y niños de cero a tres años que busca multiplicar por seis la capacidad de atención hacia 2030. En la ciudad viven unos 273 mil menores de esa edad y cerca de 37 mil reciben educación inicial. El secretario de Educación, Pedro Moctezuma, dijo que en 2027 se duplicará la cobertura; ese año servirá para formar educadoras.","b":"","img":"zocalo","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/brugada-anuncia-300-nuevos-espacios-de-educacion-inicial-gratuita-en-cdmx-asi-funcionara-el-programa-rumbo-a-2030"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-frentes-frios-6-y-7-lluvias-de-hasta-75-mm-en-veracruz-oaxaca-chiapas","t":"Frentes fríos 6 y 7: lluvias de hasta 75 mm en Veracruz, Oaxaca, Chiapas y Tabasco y Norte de 90 km/h","c":"nacional","f":"2026-11-18T06:27","r":"El frente frío 6 sigue estacionario en el Golfo de México y el 7 avanza por el norte del país. Se prevén lluvias muy fuertes en cuatro estados del sureste, rachas de 70 a 90 km/h en el istmo de Tehuantepec y temperaturas de -5 a 0 grados en la sierra de Baja California, Chihuahua y Durango. En la Ciudad de México habrá lluvias aisladas y mínimas de 0 a 5 grados en zonas altas.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/clima-mexico-hoy-18-de-noviembre-2026-frentes-frios-mantendran-las-lluvias-y-el-ambiente-fresco-en-la-mayor-parte-del-pais/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-soles-gana-76-75-a-astros-con-otro-triple-de-scrubb-y-queda-a-un-triun","t":"Soles gana 76-75 a Astros con otro triple de Scrubb y queda a un triunfo del título de la LNBP","c":"deportes","f":"2026-11-18T06:26","r":"Phillip Scrubb anotó un triple a 1.7 segundos del final cuando Mexicali perdía 73-75 y puso la serie final 3-1. Scrubb y Rigoberto Mendoza, de Astros, terminaron con 23 puntos cada uno. El quinto juego será el jueves 19 de noviembre a las 20:15 horas en la Arena Astros de Guadalajara.","b":"","img":"jalisco","foto":"","cred":"","src":[["En Juego Deportes","https://www.enjuegodeportes.com/mas-deportes/soles-vence-76-75-astros-juego-4-gran-final-lnbp-2026/"],["El Imparcial","https://www.elimparcial.com/mxl/mexicali/2026/11/17/phillip-scrubb-vuelve-a-ser-el-heroe-y-pone-a-soles-a-un-triunfo-del-titulo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-iran-dice-haber-atacado-con-drones-una-base-aerea-de-eu-en-kuwait-tras","t":"Irán dice haber atacado con drones una base aérea de EU en Kuwait tras el bombardeo a Qeshm","c":"internacional","f":"2026-11-18T06:25","r":"El Ejército iraní anunció en la madrugada un ataque con drones contra sistemas Patriot en la base Ali al Salem, en Kuwait, como respuesta a los bombardeos estadounidenses en la isla de Qeshm. Según Teherán, EU ha atacado la isla al menos cuatro veces en las últimas semanas. Un día antes, Irán se atribuyó un ataque contra un radar en la base de Sheij Isa, en Baréin.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/18/iran-dice-haber-atacado-una-base-en-kuwait-tras-nuevos-bombardeos-de-eeuu-en-qeshm/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-un-tripulante-desaparecido-y-11-heridos-tras-el-ataque-a-un-buque-de-l","t":"Un tripulante desaparecido y 11 heridos tras el ataque a un buque de la petrolera emiratí ADNOC en Ormuz","c":"internacional","f":"2026-11-18T06:24","r":"Un proyectil de origen desconocido impactó un barco de la empresa estatal de Emiratos a unas 13 millas náuticas de Jasab, Omán, y provocó un incendio que ya fue sofocado, según la agencia británica UKMTO. La compañía informó que un marinero sigue sin ser localizado y que el resto de la tripulación fue evacuada. Por separado, la Guardia Revolucionaria reportó un cuarto petrolero incendiado por una mina en menos de 24 horas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/18/un-tripulante-de-un-buque-de-la-petrolera-emirati-adnoc-permanece-desaparecido-tras-un-ataque-en-el-estrecho-de-ormuz/"],["Prensa Latina","https://www.prensa-latina.cu/2026/11/18/iran-reporta-cuarto-petroleros-incendiados-en-el-estrecho-de-ormuz/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-xi-recibe-a-trump-en-shenzhen-y-putin-ya-esta-en-china-para-la-cumbre","t":"Xi recibe a Trump en Shenzhen y Putin ya está en China para la cumbre tripartita del jueves","c":"internacional","f":"2026-11-18T06:23","r":"Xi Jinping recibió a Donald Trump al pie del avión a su llegada desde Manila; Vladímir Putin aterrizó en la madrugada, en su primera cumbre presencial del APEC desde 2017. Los tres líderes se reunirán el jueves para hablar de control de armas nucleares, Ucrania e Irán; Washington descartó acuerdos inmediatos. Trump también busca prorrogar la tregua comercial con China, que vence el 10 de enero.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Nación","https://www.lanacion.com.ar/estados-unidos/xi-jinping-recibe-a-trump-con-un-abrazo-antes-de-la-cumbre-tripartita-sin-precedentes-con-putin-todo-nid18112026/"],["Info7","https://www.info7.mx/internacional/putin-llega-a-china-para-cumbre-trilateral-con-trump-y-xi-jinping/6383039493"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-wall-street-apunta-a-un-rebote-nvidia-sube-cerca-de-5-tras-duplicar-su","t":"Wall Street apunta a un rebote: Nvidia sube cerca de 5% tras duplicar sus ingresos","c":"economia","f":"2026-11-18T06:22","r":"Las acciones de Nvidia ganaban alrededor de 5%, cerca de 163 dólares, después de reportar ingresos por unos 115,800 millones de dólares, 103% más que hace un año, y elevar su pronóstico de crecimiento a 75%. También subían CoreWeave, Nebius e Iren. Este miércoles se publican las minutas de la última reunión de la Reserva Federal.","b":"","img":"bolsa","foto":"","cred":"","src":[["Bolsamanía","https://www.bolsamania.com/noticias/mercados/wall-street-miercoles-18-noviembre-rebote-nasadaq-nvidia-ia--24216726.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-anthropic-perfila-fijar-hoy-el-precio-de-su-opi-por-encima-de-78-dolar","t":"Anthropic perfila fijar hoy el precio de su OPI por encima de 78 dólares por acción","c":"economia","f":"2026-11-18T06:21","r":"La empresa de inteligencia artificial daría a conocer este miércoles el precio definitivo de su salida a bolsa, con un rango de 70 a 78 dólares; según Bloomberg, comunicó a inversionistas que podría superar el tope. Ofrecerá 825 millones de acciones y, al precio máximo, recaudaría unos 64,350 millones de dólares. Debutará el jueves en el Nasdaq con la clave ANT.","b":"","img":"tech","foto":"","cred":"","src":[["Demócrata","https://www.democrata.es/economia/anthropic-apunta-a-rebasar-el-rango-de-70-a-78-dolares-marcado-para-su-debut-en-bolsa/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-18-openai-lanza-gpt-6-2-astra-y-sol-modelos-que-prometen-mas-rendimiento","t":"OpenAI lanza GPT-6.2 Astra y Sol, modelos que prometen más rendimiento con menor costo","c":"tecnologia","f":"2026-11-18T06:20","r":"OpenAI presentó dos modelos: Astra, para las tareas más complejas, y Sol, más eficiente, que sustituye a GPT-6.1 Sol. La empresa asegura que ambos logran mejores resultados con menos tokens; Astra cuesta 8 dólares por millón de tokens de entrada y 40 de salida, 20% menos que su antecesor. Están disponibles en ChatGPT para usuarios de pago y en la API. Además, OpenAI anunció un acuerdo de ciberdefensa con la OTAN.","b":"","img":"tech2","foto":"","cred":"","src":[["Diario Siglo XXI (Europa Press)","https://diariosigloxxi.com/texto-ep/mostrar/20261118110859/openai-lanza-gpt-62-astra-sol-mayor-rendimiento-utilizando-menos-tokens-garantizar-menor-coste"],["Euronews","https://es.euronews.com/2026/11/18/otan-openai-acuerdan-cooperar-ciberdefensa-herramientas-inteligencia-artificial"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-sheinbaum-y-carney-se-reunen-en-shenzhen-reafirman-el-t-mec-y-acuerdan","t":"Sheinbaum y Carney se reúnen en Shenzhen, reafirman el T-MEC y acuerdan ampliar la relación México-Canadá","c":"nacional","f":"2026-11-17T18:44","r":"En el marco del APEC, la presidenta y el primer ministro canadiense revisaron el plan de acción bilateral puesto en marcha hace poco más de un año; Sheinbaum dijo que se han cumplido 120 de sus iniciativas y que el comercio y la inversión entre ambos países han crecido. Acordaron ampliar la cooperación, incluidas seguridad y minerales críticos, mientras avanza la revisión del tratado con Estados Unidos.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/17/sheinbaum-y-mark-carney-se-reunen-en-china-revisan-plan-de-accion-mexico-canada/"],["El Financiero","https://elfinanciero.com.mx/mundo/2026/11/17/sheinbaum-y-carney-impulsan-a-mexico-y-canada-ampliaran-cooperacion-en-seguridad-y-minerales-criticos"]],"dest":true,"a":"Redacción"},{"id":"2026-11-17-sheinbaum-confirma-un-encuentro-breve-con-trump-este-miercoles-en-la-c","t":"Sheinbaum confirma un encuentro breve con Trump este miércoles en la cena de líderes del APEC","c":"nacional","f":"2026-11-17T18:43","r":"La presidenta dijo que será «una reunión muy muy breve» durante la cena de líderes en Shenzhen, sin carácter de bilateral formal. Será su primer encuentro en persona desde julio, aunque en 2026 han tenido 21 llamadas sobre comercio y frontera. Sheinbaum señaló que en su reunión con Xi Jinping se habló de Estados Unidos, pero que el tema central fue el tratado comercial.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/17/sheinbaum-confirma-que-tendra-un-encuentro-breve-con-trump-en-cena-de-lideres-de-la-apec-en-china/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-17-agricultura-propone-fijar-el-frijol-en-18-pesos-y-promete-el-viernes-u","t":"Agricultura propone fijar el frijol en 18 pesos y promete el viernes una oferta de precio de garantía; los bloqueos siguen","c":"nacional","f":"2026-11-17T18:42","r":"La titular de la Sader, Columba López, planteó a los productores un precio de 18 pesos para el frijol y se comprometió a presentar el viernes una propuesta definitiva de precio de garantía; los campesinos advirtieron que, si no les convence, llevarán sus bloqueos a la Ciudad de México. La secretaria de Gobernación, Rosa Icela Rodríguez, dijo que hay mesas abiertas en cuatro estados y 26 mil millones de pesos en apoyos directos al campo.","b":"","img":"carretera","foto":"","cred":"","src":[["Uno TV","https://unotv.com/nacional/bloqueos-carreteros-hoy-17-noviembre-minuto-a-minuto-protesta-nacional-campesinos"],["Zócalo","https://www.zocalo.com.mx/segob-descarta-necesidad-de-bloqueos-carreteros-de-agricultores-asegura-que-hay-dialogo-abierto/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-17-la-suprema-corte-valida-la-geolocalizacion-de-celulares-en-tiempo-real","t":"La Suprema Corte valida la geolocalización de celulares en tiempo real y la retención de datos para investigar delitos","c":"politica","f":"2026-11-17T18:41","r":"Al resolver el amparo en revisión 193/2026, el pleno avaló el artículo 183 de la Ley en Materia de Telecomunicaciones y Radiodifusión: la retención de datos, la localización en tiempo real de equipos, la entrega de información a autoridades y el bloqueo de señales. La Corte precisó que la obligación cubre datos del servicio, no el contenido de las comunicaciones, y que el acceso requiere orden fundada y, en su caso, autorización de un juez federal.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/17/la-suprema-corte-valida-la-geolocalizacion-de-telefonos-en-tiempo-real-y-entrega-de-informacion-a-autoridades/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-17-ante-empresarios-del-apec-sheinbaum-pide-confiar-en-mexico-y-destaca-i","t":"Ante empresarios del APEC, Sheinbaum pide confiar en México y destaca inversiones del Plan México","c":"economia","f":"2026-11-17T18:40","r":"En la cumbre empresarial del APEC en Shenzhen, la presidenta llamó a los inversionistas a ver a México como destino en varios sectores bajo el Plan México, que según dijo contempla inversión pública y privada de 432 mil millones de dólares en el sexenio. Habló de incentivos, certeza regulatoria, simplificación de trámites y nuevos polos de desarrollo regionales.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/17/sheinbaum-llama-a-confiar-en-mexico-como-destino-de-inversion-durante-apec-en-china-destaca-plan-por-432-mil-millones-de-dolares/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-el-peso-gana-0-45-y-el-dolar-cierra-en-18-43-pesos","t":"El peso gana 0.45% y el dólar cierra en 18.43 pesos","c":"economia","f":"2026-11-17T18:39","r":"El tipo de cambio cerró en 18.4298 pesos por dólar con datos de Banxico, una apreciación de 8.26 centavos frente a la referencia previa, mientras el índice dólar bajó 0.10%. El mercado estuvo atento a las señales de funcionarios de la Reserva Federal, que mencionaron posibles nuevas alzas de tasas para contener la inflación.","b":"","img":"bolsa","foto":"","cred":"","src":[["Potosinoticias (El Economista)","https://potosinoticias.com/2026/11/17/peso-mexicano-gana-terreno-y-dolar-cierra-en-18-42-pesos/"],["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/17/la-bolsa-mexicana-retrocede-un-115-liga-tres-caidas-y-baja-a-7038896-unidades/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-la-bolsa-mexicana-cae-1-15-y-cierra-en-70-388-puntos-su-mayor-baja-des","t":"La Bolsa mexicana cae 1.15% y cierra en 70,388 puntos, su mayor baja desde el 30 de septiembre","c":"economia","f":"2026-11-17T18:38","r":"El S&P/BMV IPC hiló su tercera sesión a la baja y terminó en 70,388.96 unidades. Gabriela Siller, de Banco Base, atribuyó la caída al nerviosismo previo al reporte de Nvidia. De 740 emisoras, 602 bajaron; las mayores pérdidas fueron de Frisco (-11.43%), Cemex (-4.48%) y Grupo México (-3.47%), mientras Televisa ganó 2.79%. En el año el índice aún sube 9.62%, según Actinver.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/17/la-bolsa-mexicana-retrocede-un-115-liga-tres-caidas-y-baja-a-7038896-unidades/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-wall-street-cae-por-fallas-tecnologicas-y-la-espera-de-nvidia-el-dow-j","t":"Wall Street cae por fallas tecnológicas y la espera de Nvidia: el Dow Jones pierde 848 puntos","c":"economia","f":"2026-11-17T18:37","r":"El Dow Jones retrocedió 1.64% a 50,759 puntos, el S&P 500 bajó 1.03% a 7,340 y el Nasdaq cedió 0.74% a 24,328. Pesaron las caídas de Microsoft (-2.27%), tras dos días con fallas en Teams y Outlook, y de JPMorgan (-2.44%), por un error de software que afectó cuentas en línea; las empresas descartaron un ciberataque. Nvidia perdió 0.44% antes de publicar resultados.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Informador","https://www.informador.mx/economia/wall-street-cierra-en-rojo-tras-fallas-tecnologicas-espera-resultados-de-nvidia-20261117-0192.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-el-brent-sube-0-76-y-cierra-en-93-14-dolares-por-los-ataques-entre-eu","t":"El Brent sube 0.76% y cierra en 93.14 dólares por los ataques entre EU e Irán en Ormuz","c":"economia","f":"2026-11-17T18:36","r":"El crudo de referencia europeo para enero ganó 0.76% y el WTI para diciembre avanzó 0.34%, a 86.01 dólares por barril, ante la escalada militar en el estrecho de Ormuz y el ataque de los hutíes contra un oleoducto saudí. Aun así, el Brent acumula una caída cercana a 20% en el mes, frenado por la previsión de la Agencia Internacional de Energía de que la oferta superará a la demanda en el cuarto trimestre.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/17/el-brent-sube-a-9314-dolares-aunque-acumula-una-caida-mensual-del-20/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-nvidia-supera-expectativas-en-su-primer-reporte-sin-jensen-huang-ingre","t":"Nvidia supera expectativas en su primer reporte sin Jensen Huang: ingresa 115,800 millones de dólares, 103% más","c":"tecnologia","f":"2026-11-17T18:35","r":"En el trimestre cerrado el 25 de octubre, la empresa facturó unos 115,800 millones de dólares, por encima de los 109,110 millones que esperaba el mercado; su negocio de centros de datos aportó 107,600 millones. Para el siguiente trimestre prevé 130,000 millones, sin contar ventas de chips a China. Sus acciones subían más de 4% fuera de horario. Colette Kress dirige la compañía de forma interina tras la renuncia de Huang el 12 de noviembre.","b":"","img":"tech","foto":"","cred":"","src":[["Expansión","https://expansion.mx/mercados/2026/11/17/nvidia-supera-expectativas-con-sus-resultados-financieros-y-acciones-suben"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-estados-unidos-bombardea-una-base-de-misiles-en-la-isla-irani-de-qeshm","t":"Estados Unidos bombardea una base de misiles en la isla iraní de Qeshm tras un tercer ataque de Irán contra Baréin","c":"internacional","f":"2026-11-17T18:34","r":"Cazas estadounidenses atacaron una base de lanzamiento de misiles de la Guardia Revolucionaria en Qeshm, en el estrecho de Ormuz, horas después de que Irán dijera haber golpeado con drones un radar de EU en la base de Sheikh Isa, en Baréin; Washington lo presentó como defensa propia. Un funcionario iraní reportó cinco o seis explosiones sin daños, y Catar pidió moderación ante el riesgo de una escalada.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Swissinfo (AFP)","https://www.swissinfo.ch/spa/eeuu-bombardea-la-isla-de-qeshm-tras-ataques-iran%C3%ADes-contra-bar%C3%A9in/92396474"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-vinculan-a-proceso-a-el-r2-lider-de-los-r-s-del-cjng-cuatro-de-sus-aco","t":"Vinculan a proceso a «El R2», líder de Los R's del CJNG; cuatro de sus acompañantes siguen en prisión preventiva","c":"seguridad","f":"2026-11-17T18:33","r":"Un juez federal en Puente Grande, Jalisco, abrió proceso a Rafael Álvarez Ayala por delitos contra la salud, portación de armas y posesión de cartuchos de uso exclusivo del Ejército. Fue detenido herido el 8 de noviembre en un operativo de la Marina en un restaurante de la zona metropolitana de Guadalajara y sigue hospitalizado; un amparo impide trasladarlo hasta su alta médica. García Harfuch vincula a esa célula con el asesinato de Carlos Manzo.","b":"","img":"jalisco","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/17/el-r2-se-queda-en-la-carcel-y-le-abren-juicio-formal-juez-da-presion-preventiva-a-cuatro-sicarios-del-lider-del-cjng/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-dejan-una-cabeza-humana-frente-a-un-supermercado-de-culiacan-sinaloa-s","t":"Dejan una cabeza humana frente a un supermercado de Culiacán; Sinaloa suma 91 muertes violentas en noviembre","c":"seguridad","f":"2026-11-17T18:32","r":"El lunes por la tarde fue abandonada una cubeta con una cabeza humana en el acceso a un estacionamiento sobre el bulevar Doctor Mora, en la colonia La Campiña de Culiacán. Ese día hubo al menos cuatro homicidios en el estado, según la Fiscalía, en Culiacán, Escuinapa y Mazatlán. Con datos del SESNSP, noviembre acumula 91 muertes violentas, un promedio de 5.7 al día, y desde el 9 de septiembre de 2024 suman 4,224 homicidios.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Noroeste","https://www.noroeste.com.mx/seguridad/informe-diario-dejan-cabeza-humana-en-culiacan-5-homicidios-y-6-vehiculos-robados-el-lunes-PA27419413"],["Infobae","https://www.infobae.com/mexico/2026/11/17/violencia-en-culiacan-dejan-una-cabeza-humana-dentro-de-una-cubeta-frente-a-un-centro-comercial/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-guanajuato-concentra-la-protesta-del-campo-cierres-totales-en-penjamo","t":"Guanajuato concentra la protesta del campo: cierres totales en Pénjamo, Irapuato y San Luis de la Paz","c":"estados","f":"2026-11-17T18:31","r":"La Secretaría de Seguridad estatal confirmó al mediodía bloqueos totales en la federal 90 en Pénjamo e Irapuato y en la federal 57 en San Luis de la Paz, además de cierres parciales en la caseta León-Aguascalientes y en Tarimoro; por la tarde las autoridades contaban 11 bloqueos totales. Los productores piden 6,500 pesos por tonelada de maíz, frente a los 5,200 que ofrece el mercado, y el pago de trigo y maíz de ciclos anteriores.","b":"","img":"carretera","foto":"","cred":"","src":[["AM","https://am.com.mx/guanajuato/2026/11/17/vigilan-carreteras-por-bloqueos-campesinos-en-guanajuato-1867435.html"],["Uno TV","https://unotv.com/nacional/bloqueos-carreteros-hoy-17-noviembre-minuto-a-minuto-protesta-nacional-campesinos"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-productores-de-maiz-bloquean-de-forma-indefinida-cinco-carreteras-de-j","t":"Productores de maíz bloquean de forma indefinida cinco carreteras de Jalisco, entre ellas la Guadalajara-Nogales","c":"estados","f":"2026-11-17T18:30","r":"Como parte de la protesta nacional de campesinos, productores de maíz cerraron por completo y por tiempo indefinido la Guadalajara-Nogales, la Guadalajara-Colima a la altura del kilómetro 40, la caseta de Ocotlán en la Guadalajara-México, la La Barca-Atotonilco y la caseta de Tepatitlán en la Carretera Federal 80. Exigen que la Sader cumpla los acuerdos firmados el 22 de octubre, incluidos pagos pendientes de maíz y trigo.","b":"","img":"carretera","foto":"","cred":"","src":[["Uno TV","https://unotv.com/nacional/bloqueos-carreteros-hoy-17-noviembre-minuto-a-minuto-protesta-nacional-campesinos"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-apple-sufre-una-falla-global-en-icloud-apple-pay-y-app-store-en-medio","t":"Apple sufre una falla global en iCloud, Apple Pay y App Store en medio de una racha de caídas tecnológicas en EU","c":"tecnologia","f":"2026-11-17T18:29","r":"Desde las 8:00 horas del Este se reportaron problemas para iniciar sesión en iCloud y fallas en Apple Pay, App Store, Apple Music y soporte técnico; el pico llegó cerca de las 13:00 con casi 1,800 reportes en Downdetector. Apple confirmó las interrupciones sin precisar la causa. Un día antes, JPMorgan Chase atribuyó a un error de software una falla en sus cuentas en línea, y el viernes cayeron Teams y Outlook de Microsoft 365.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/tecno/2026/11/17/apple-tiene-fallas-globales-icloud-apple-pay-apple-store-apple-tv-y-otros-servicios-sufren-caida/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-trump-pacta-con-tailandia-que-elimine-todos-sus-aranceles-a-productos","t":"Trump pacta con Tailandia que elimine todos sus aranceles a productos de Estados Unidos","c":"internacional","f":"2026-11-17T18:28","r":"Desde Manila, donde participa en la cumbre de la ASEAN, el presidente estadounidense anunció un acuerdo con el primer ministro Anutin Charnvirakul para que Tailandia quite todos los aranceles a bienes de EU; el acuerdo de comercio recíproco se firmaría pronto. Bangkok se comprometió a comprar productos agrícolas estadounidenses por 2,600 millones de dólares y a reducir barreras en vehículos, equipo médico, etanol y aves. La Casa Blanca no detalló qué concede Washington.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/estados-unidos/2026/11/17/donald-trump-pacto-con-tailandia-eliminar-todos-los-aranceles-a-los-bienes-de-estados-unidos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-brugada-defiende-el-programa-gallinas-en-casa-que-dara-15-aves-ponedor","t":"Brugada defiende el programa Gallinas en Casa, que dará 15 aves ponedoras por familia, y rechaza comparaciones con Maduro","c":"cdmx","f":"2026-11-17T18:27","r":"La jefa de Gobierno respondió a las críticas contra el programa, que entregará 15 gallinas por hogar seleccionado, alimento para el primer mes y asesoría técnica; las familias deberán contar con al menos 10 metros cuadrados y un corral protegido. Clara Brugada dijo que no se repartirán aves de forma indiscriminada y lo ligó a la estrategia de casas ecológicas y soberanía alimentaria. La convocatoria aún no se publica, por lo que no hay fechas ni número de beneficiarios.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/17/clara-brugada-enfrenta-criticas-por-regalar-gallinas-ponedoras-en-cdmx-y-rechaza-comparaciones-con-maduro/"],["Proceso","https://www.proceso.com.mx/nacional/cdmx/2026/11/17/clara-brugada-defiende-entrega-de-gallinas-ponedoras-en-alvaro-obregon-ante-criticas-del-pan-383872.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-astros-vence-75-74-a-soles-en-el-tercer-juego-y-recorta-a-2-1-la-final","t":"Astros vence 75-74 a Soles en el tercer juego y recorta a 2-1 la final de la LNBP; hoy se juega el cuarto","c":"deportes","f":"2026-11-17T18:26","r":"Astros de Jalisco consiguió en Guadalajara su primer triunfo en la final de la Liga Nacional de Baloncesto Profesional ante Soles de Mexicali, que sigue arriba 2-1 en la serie. Francisco Cruz anotó 18 puntos y Michale Kyser resolvió el cierre con un tiro libre a dos décimas del final. El cuarto juego es este martes a las 20:15 horas; si hace falta un quinto, será el jueves en Guadalajara.","b":"","img":"jalisco","foto":"","cred":"","src":[["El Informador","https://www.informador.mx/deportes/astros-gana-a-soles-en-cierre-de-alarido-y-recorta-distancia-en-la-final-de-la-lnbp-20261116-0173.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-don-omar-anuncia-tres-conciertos-en-mexico-para-noviembre-de-2027-mont","t":"Don Omar anuncia tres conciertos en México para noviembre de 2027: Monterrey, Guadalajara y CDMX","c":"entretenimiento","f":"2026-11-17T18:25","r":"El cantante puertorriqueño incluyó a México en su gira The Last King World Tour Latam 2027, que recorrerá 13 países con 18 fechas entre octubre y noviembre del próximo año. Se presentará el 9 de noviembre en Monterrey, el 10 en Guadalajara y el 14 en la Ciudad de México. La preventa arranca el 19 de noviembre a las 10:00 horas en su sitio oficial; a finales de octubre había pospuesto tres shows en Estados Unidos por una infección respiratoria.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/entretenimiento/2026/11/17/don-omar-vuelve-a-los-escenarios-de-latinoamerica-estas-son-las-fechas-de-sus-proximos-conciertos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-sheinbaum-se-reune-con-xi-jinping-en-shenzhen-lo-invita-a-mexico-para","t":"Sheinbaum se reúne con Xi Jinping en Shenzhen, lo invita a México para el APEC 2028 y habla de una «nueva era»","c":"nacional","f":"2026-11-17T06:39","r":"La presidenta sostuvo este martes su primer encuentro con Xi Jinping desde que asumió el cargo, en la sede Villa Kylin de Shenzhen, un día antes de la cumbre de líderes del APEC. Le propuso cooperar en ciencia, agricultura, energías limpias, agua y salud —con interés en hospitales inteligentes, incineración de residuos para generar energía y paneles solares— y lo invitó al APEC de 2028, que México organizará; Xi pidió una relación basada en la estabilidad y el beneficio mutuo. Horas antes, ante más de mil empresarios, Sheinbaum presentó el Plan México, que prevé 432 mil millones de dólares en infraestructura, y ofreció el Corredor Interoceánico como opción frente al Canal de Panamá. El comercio bilateral supera los 100 mil millones de dólares al año, con un fuerte déficit para México.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/17/sheinbaum-se-reune-con-xi-jinping-en-china-lo-invita-a-mexico-y-plantea-nueva-era-de-cooperacion/"],["Infobae","https://www.infobae.com/mexico/2026/11/17/sheinbaum-presenta-el-plan-mexico-ante-la-apec-en-china/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-17-campesinos-bloquean-desde-las-8-00-horas-25-puntos-en-cinco-estados-ac","t":"Campesinos bloquean desde las 8:00 horas 25 puntos en cinco estados; acusan a Agricultura de incumplir acuerdos","c":"nacional","f":"2026-11-17T06:38","r":"La Confederación Agropecuaria de México y organizaciones de Guanajuato, Querétaro, Michoacán, Jalisco y Campeche convocaron a movilizaciones a partir de las 8:00 de este martes. Guanajuato concentra 16 puntos en las carreteras 45, 57 y 90, Irapuato-Silao y León-Aguascalientes; en Jalisco habrá cinco, en Michoacán dos (México-Morelia y Vistahermosa-La Piedad), uno en la caseta de Palmillas, Querétaro, y en Campeche la protesta será en las oficinas de la Sader. Los productores acusan el incumplimiento de los acuerdos del 22 de octubre y presentan ocho demandas, entre ellas apoyo directo al maíz, el pago de adeudos de trigo y maíz y seguro para zonas siniestradas.","b":"","img":"carretera","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/nacional/bloqueos-de-campesinos-el-17-de-noviembre-estos-son-los-25-puntos-donde-habra-movilizaciones-en-cinco-estados/"],["N+","https://www.nmas.com.mx/movilidad/bloqueo-de-campesinos-en-mexico-martes-17-de-noviembre-2026-que-carreteras-estaran-afectadas/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-17-entra-el-frente-frio-7-lluvias-en-27-estados-aguaceros-de-hasta-75-mm","t":"Entra el frente frío 7: lluvias en 27 estados, aguaceros de hasta 75 mm en el sureste y heladas de -5 grados en el norte","c":"nacional","f":"2026-11-17T06:37","r":"El Servicio Meteorológico Nacional prevé para este martes la entrada del frente frío 7 mientras el 6 sigue activo, junto con una masa de aire polar y un evento de Norte. Habrá lluvias en 27 estados, muy fuertes (50 a 75 mm) en Veracruz, Oaxaca, Chiapas y Tabasco, y chubascos aislados en la Ciudad de México y el Estado de México. Las mínimas llegarán a entre -5 y 0 grados en zonas serranas de Baja California, Chihuahua y Durango, y se esperan rachas de 70 a 90 km/h en Veracruz, Oaxaca, Chiapas y Tamaulipas.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/lluvias-mexico-martes-17-noviembre/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-17-la-delincuencia-costo-a-las-empresas-115-mil-millones-de-pesos-en-2025","t":"La delincuencia costó a las empresas 115 mil millones de pesos en 2025; casi una de cada cinco víctimas redujo el uso de efectivo","c":"economia","f":"2026-11-17T06:36","r":"Según la Encuesta Nacional de Victimización de Empresas 2026 del INEGI, con datos de 2025, el delito costó al país 115,100 millones de pesos. Entre las empresas víctimas, 19.2% redujo o dejó el uso de efectivo, 17.6% recortó horarios de producción o venta y 14.5% canceló planes de crecimiento; 52.3% instaló cámaras o nuevas cerraduras. Tabasco, Morelos y Puebla son los estados con más afectaciones, y Coahuila, Sonora y Nuevo León los que menos.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/estados/2026/11/16/inseguridad-empresas-mexico-sin-efectivo-pararon-crecimiento"]],"dest":true,"a":"Redacción"},{"id":"2026-11-17-monreal-convocara-esta-semana-a-las-bancadas-para-definir-el-perfil-y","t":"Monreal convocará esta semana a las bancadas para definir el perfil y la convocatoria del relevo de Taddei en el INE","c":"politica","f":"2026-11-17T06:35","r":"El coordinador de Morena en San Lázaro y presidente de la Junta de Coordinación Política, Ricardo Monreal, dijo que buscará reunir esta semana a los líderes parlamentarios para acordar el perfil de quien presidirá el INE y los términos de la convocatoria. La Jucopo ha aplazado varias veces el acuerdo por falta de consenso entre los grupos; Monreal sostuvo que la presidencia provisional funciona bien, aunque eso no justifica retrasar la designación.","b":"","img":"ine","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/17/alistan-reunion-de-bancadas-hacia-el-relevo-en-el-ine/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-el-presupuesto-de-salud-2027-crece-11-3-pero-sigue-lejos-de-lo-necesar","t":"El presupuesto de salud 2027 crece 11.3%, pero sigue lejos de lo necesario, advierte el CIEP","c":"politica","f":"2026-11-17T06:34","r":"El gasto en salud aprobado por la Cámara de Diputados para 2027 ronda 1.1 billones de pesos, 11.3% más que lo ejercido en 2026, y equivale a 2.9% del PIB, frente al 6% que la OMS considera mínimo. Judith Senyacen Méndez, directora del Centro de Investigación Económica y Presupuestaria, señaló que el aumento no alcanza para cubrir el rezago en atención y que el reto del Servicio Universal de Salud, que arranca en enero, será convertir los recursos en servicios; el IMSS concentra más de 600 mil millones de pesos.","b":"","img":"imss","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/16/presupuesto-salud-2027-aumento-positivo-pero-insuficiente"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-nvidia-reporta-hoy-sus-primeros-resultados-sin-jensen-huang-el-mercado","t":"Nvidia reporta hoy sus primeros resultados sin Jensen Huang; el mercado espera ingresos de unos 109 mil millones de dólares","c":"economia","f":"2026-11-17T06:33","r":"La fabricante de chips dará a conocer tras el cierre de Wall Street sus cifras del tercer trimestre fiscal, las primeras desde la salida de Jensen Huang el 12 de noviembre; Colette Kress ocupa la dirección de forma interina. Los analistas esperan ingresos de alrededor de 109 mil millones de dólares y una ganancia de 2.48 dólares por acción, y el mercado de opciones anticipa un movimiento de cerca de 9% en la acción. El lunes, el Nasdaq cayó 2.49% y Nvidia 4%, en medio de dudas sobre el gasto en inteligencia artificial.","b":"","img":"tech2","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/tecno/2026/11/16/nvidia-presentara-el-17-de-noviembre-sus-primeros-resultados-sin-jensen-huang-como-director-ejecutivo/"],["El Financiero","https://www.elfinanciero.com.mx/economia/2026/11/17/venta-de-acciones-tech-golpea-a-bolsas-globales-nvidia-y-antrhopic-influyen-en-extender-caida/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-tras-el-puente-festivo-el-fix-para-pagar-obligaciones-en-dolares-queda","t":"Tras el puente festivo, el FIX para pagar obligaciones en dólares queda en 18.55 pesos; bancos venden en 18.73","c":"economia","f":"2026-11-17T06:32","r":"Los mercados y bancos reanudan operaciones este martes. El tipo de cambio FIX publicado en el Diario Oficial quedó en 18.5525 pesos por dólar y el de obligaciones en dólares en 18.6188, según datos de Banxico recogidos por N+. En ventanilla bancaria, el dólar se compra en 18.32 y se vende en 18.73 pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/economia/dolar/como-esta-tipo-de-cambio-peso-dolar-estadounidense-mexico-martes-17-noviembre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-el-brent-se-mantiene-cerca-de-92-dolares-pese-a-que-iran-dice-haber-al","t":"El Brent se mantiene cerca de 92 dólares pese a que Irán dice haber alcanzado cuatro petroleros en 24 horas","c":"economia","f":"2026-11-17T06:31","r":"El crudo de referencia internacional cotizaba en la sesión asiática ligeramente por debajo de 92 dólares por barril, con un descenso moderado, de acuerdo con datos de Reuters citados por Euribor.com.es. El mercado no ha reaccionado con fuerza a los reportes de la Armada iraní sobre cuatro buques tanque dañados en el estrecho de Ormuz. El lunes, el Brent cerró en 92.44 dólares tras caer 3.55%.","b":"","img":"pemex","foto":"","cred":"","src":[["Euribor.com.es","https://www.euribor.com.es/2026/11/17/precio-petroleo-hoy-17-noviembre-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-la-fgr-asegura-18-vehiculos-y-un-arsenal-con-fusil-barrett-en-un-inmue","t":"La FGR asegura 18 vehículos y un arsenal con fusil Barrett en un inmueble de Ocotlán, Jalisco","c":"seguridad","f":"2026-11-17T06:30","r":"Tras un aviso de la Defensa, la Fiscalía General de la República cateó una casa en la colonia Riveras de Zula, en Ocotlán, donde aseguró 18 vehículos, cartuchos de uso exclusivo del Ejército, equipo táctico y armas, entre ellas un fusil Barrett calibre .50 y granadas de 40 mm. La FGR dijo que lo asegurado estaría ligado a un grupo criminal, sin precisar cuál. El 12 de noviembre, militares fueron atacados en ese municipio; murieron dos agresores y un hombre fue detenido.","b":"","img":"jalisco","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/17/cateo-en-ocotlan-fgr-asegura-18-vehiculos-que-estarian-vinculados-con-el-cjng/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-el-ejercito-asegura-casi-dos-toneladas-de-mariguana-en-la-yesca-nayari","t":"El Ejército asegura casi dos toneladas de mariguana en La Yesca, Nayarit","c":"seguridad","f":"2026-11-17T06:29","r":"La Defensa informó que militares de la 13 Zona Militar localizaron el domingo 1,910 kilos de mariguana cerca de Puente de Camotlán, en el municipio de La Yesca, durante patrullajes. La droga se presume del CJNG y quedó a disposición de la FGR en Tepic. En lo que va de la administración, Ejército, Fuerza Aérea y Guardia Nacional suman 140,378 kilos de mariguana asegurados.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/ejercito-asegura-mariguana-nayarit"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-emboscada-en-jolalpan-puebla-deja-tres-muertos-entre-ellos-dos-policia","t":"Emboscada en Jolalpan, Puebla, deja tres muertos, entre ellos dos policías de Morelos","c":"estados","f":"2026-11-17T06:28","r":"Civiles armados atacaron a policías morelenses que perseguían una camioneta con reporte de robo en la comunidad de Huachinantla, municipio de Jolalpan. Murieron Jairo N., mando operativo en Axochiapan, su escolta Carlos Alberto N. y una mujer aún sin identificar. Las autoridades investigan si la mujer fue víctima colateral o participó en los hechos.","b":"","img":"carretera","foto":"","cred":"","src":[["Cinco Radio","https://cincoradio.com.mx/ataque-armado-en-jolalpan-deja-tres-muertos-entre-ellos-dos-polic-as-de-morelos-cr-bd1f692d8e7893bf74ddd206cd86ef71/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-dos-ataques-a-balazos-en-el-norte-de-culiacan-dejan-un-joven-de-18-ano","t":"Dos ataques a balazos en el norte de Culiacán dejan un joven de 18 años muerto y otro herido","c":"estados","f":"2026-11-17T06:27","r":"Con minutos de diferencia, dos agresiones armadas en el sector norte de la capital sinaloense dejaron un muerto y un herido, ambos de 18 años. El primer ataque ocurrió poco después de las 13:00 del lunes en la avenida Carmen Serdán, en la colonia El Mirador, donde Irving Gerardo perdió la vida.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Quadratín","https://mexico.quadratin.com.mx/ataques-a-balazos-en-2-colonias-de-culiacan-dejan-un-muerto-y-un-herido/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-ucrania-golpea-por-segunda-noche-el-puente-de-crimea-y-derriba-un-tram","t":"Ucrania golpea por segunda noche el puente de Crimea y derriba un tramo; Rusia dice haber derribado 1,441 drones","c":"internacional","f":"2026-11-17T06:26","r":"El gobernador de Crimea, Serguéi Aksiónov, confirmó un nuevo ataque contra el puente de Kerch, que obligó a suspender el tráfico; según un bloguero militar ruso, colapsaron unos 200 metros de la calzada. El Ministerio de Defensa ruso reportó 1,441 drones derribados en más de 20 regiones, un récord para una sola noche, y al menos dos personas murieron en Leninski. Zelensky dijo que los ataques responden a los bombardeos rusos contra la red energética ucraniana.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/agencias/2026/11/17/rusia-confirma-un-nuevo-ataque-contra-el-puente-de-crimea-en-la-mayor-oleada-de-drones-de-la-guerra-con-ucrania/"],["El Español","https://www.elespanol.com/mundo/europa/20261117/ataque-ucraniano-masivo-puente-crimea-destruye-tramo-carretera-corta-trafico-maritimo/1003744460864_0.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-iran-reporta-un-cuarto-petrolero-incendiado-en-ormuz-en-24-horas-tras","t":"Irán reporta un cuarto petrolero incendiado en Ormuz en 24 horas tras chocar con una mina","c":"internacional","f":"2026-11-17T06:25","r":"La Armada iraní informó que un buque tanque que navegaba con sus sistemas apagados se incendió en la parte oriental del estrecho tras golpear una mina naval, el cuarto en un día. Teherán sostiene que mantiene cerrado el paso desde la ofensiva de EU e Israel de febrero y culpa a barcos que cruzan sin su autorización; Washington niega que exista un bloqueo efectivo y asegura que escolta a buques comerciales.","b":"","img":"ultimahora","foto":"","cred":"","src":[["BioBioChile","https://www.biobiochile.cl/noticias/internacional/mediooriente/2026/11/17/iran-informa-de-otro-petrolero-incendiado-en-ormuz-el-cuarto-en-24-horas.shtml"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-trump-llega-a-manila-para-la-cumbre-de-la-asean-y-una-reunion-del-quad","t":"Trump llega a Manila para la cumbre de la ASEAN y una reunión del Quad antes de ir a Shenzhen","c":"internacional","f":"2026-11-17T06:24","r":"El presidente estadounidense aterrizó en Filipinas este martes, acompañado por Marco Rubio, Scott Bessent y Howard Lutnick. En Manila se reunirá con los líderes de Japón, India y Australia en el primer encuentro del Quad desde 2024, firmará un acuerdo comercial con Tailandia y verá a Ferdinand Marcos Jr. El miércoles participará en el APEC en Shenzhen, el jueves tendrá su tercera bilateral del año con Xi Jinping y cerrará la gira con la reunión con Xi y Vladimir Putin.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Yahoo Noticias","https://es-us.noticias.yahoo.com/trump-llega-asia-d%C3%ADas-cargados-121205440.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-francia-vive-una-nueva-jornada-de-huelga-general-contra-el-alza-del-co","t":"Francia vive una nueva jornada de huelga general contra el alza del costo de vida","c":"internacional","f":"2026-11-17T06:23","r":"Los sindicatos CGT y CFDT convocaron a paros y marchas en todo el país este 17 de noviembre para exigir aumentos salariales reales y rechazar el proyecto de presupuesto de 2027. El gobierno adelantó a diciembre un alza de 1.6% al salario mínimo, hasta 1,502 euros netos, que la líder de la CGT, Sophie Binet, calificó de «migajas»; según la central, 850 mil empleados públicos ganan por debajo del mínimo.","b":"","img":"paris","foto":"","cred":"","src":[["Telesur","https://www.telesurtv.net/sindicatos-convocan-huelga-17-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-se-instala-en-serbia-el-parlamento-con-mayoria-de-la-lista-estudiantil","t":"Se instala en Serbia el parlamento con mayoría de la Lista Estudiantil, que puso fin a 14 años del partido de Vucic","c":"internacional","f":"2026-11-17T06:22","r":"La Asamblea Nacional serbia celebra este martes su sesión constitutiva tras las elecciones del 25 de octubre. La Lista Estudiantil obtuvo 140 de los 250 escaños, frente a 103 de la alianza encabezada por el Partido Progresista Serbio de Aleksandar Vucic y siete de minorías nacionales. El gobierno saliente seguirá en funciones hasta que se forme uno nuevo; el parlamento tiene hasta 90 días para elegirlo.","b":"","img":"ultimahora","foto":"","cred":"","src":[["N1","https://n1info.rs/english/news/brnabic-announces-november-17-opening-session-of-serbias-new-parliament/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-mexico-busca-remontar-ante-jamaica-esta-noche-en-monterrey-marquez-pre","t":"México busca remontar ante Jamaica esta noche en Monterrey; Márquez prevé cambios en la defensa y el ataque","c":"deportes","f":"2026-11-17T06:21","r":"El Tricolor recibe a las 20:30 horas en el Estadio BBVA a Jamaica en la vuelta de los cuartos de final de la Liga de Naciones de la Concacaf, tras perder 3-2 en Kingston. Necesita ganar para avanzar; Jamaica se clasifica si gana, empata o pierde por un gol anotando tres o más. Rafael Márquez alista a Rodrigo Huescas como lateral derecho y a Armando González en la delantera; desde el Mundial, México suma dos empates y tres derrotas.","b":"","img":"estadio","foto":"","cred":"","src":[["Código Qro","https://codigoqro.mx/nota/deportes/2026/11/16/mexico-enfrenta-este-martes-a-jamaica-obligado-a-remontar-en-monterrey"]],"dest":false,"a":"Redacción"},{"id":"2026-11-17-anthropic-fija-su-salida-a-bolsa-cotizara-en-el-nasdaq-el-jueves-con-u","t":"Anthropic fija su salida a bolsa: cotizará en el Nasdaq el jueves con un rango de 70 a 78 dólares por acción","c":"tecnologia","f":"2026-11-17T06:20","r":"La empresa de inteligencia artificial prevé fijar el precio de su oferta pública inicial el 18 de noviembre y debutar el 19 en el Nasdaq con la clave ANT. Ofrecerá 825 millones de acciones clase A y buscaría una valoración cercana a 1.4 billones de dólares; además, colocará 26 mil millones de dólares en acciones sin voto entre grandes tecnológicas. El Financiero reporta que la expectativa por la operación pesa en el ánimo de las bolsas.","b":"","img":"tech","foto":"","cred":"","src":[["DiarioBitcoin","https://www.diariobitcoin.com/startups-verticales/anthropic-debutara-en-wall-street-esta-semana-todo-lo-que-debes-saber-de-la-ipo/"],["El Financiero","https://www.elfinanciero.com.mx/economia/2026/11/17/venta-de-acciones-tech-golpea-a-bolsas-globales-nvidia-y-antrhopic-influyen-en-extender-caida/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-trump-vuelve-a-amagar-con-aranceles-altos-a-mexico-si-no-frena-la-cara","t":"Trump vuelve a amagar con aranceles altos a México si no frena la caravana migrante que salió de Tapachula","c":"nacional","f":"2026-11-16T18:44","r":"Antes de abordar el Marine One en la Casa Blanca, Donald Trump advirtió que impondrá aranceles fuertes a México si no detiene las caravanas de migrantes que buscan llegar a Estados Unidos; cinco días antes había dicho que duplicaría los gravámenes por el mismo motivo. La caravana, de unas 1,500 personas en su mayoría centroamericanas, salió de Tapachula, Chiapas, el 10 de noviembre y se dirige a la Ciudad de México. La presidenta Sheinbaum ha dicho que ninguna caravana ha llegado a la frontera norte desde que Trump asumió el cargo.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Expansión","https://expansion.mx/mundo/2026/11/16/trump-imponer-aranceles-mexico-detiene-caravana"],["El Universal","https://www.eluniversal.com.mx/mundo/trump-vuelve-a-amenazar-a-mexico-con-fuertes-aranceles-si-no-frena-caravana-de-migrantes-si-cruzan-ilegalmente-enfrentaran-consecuencias/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-16-sheinbaum-se-reunira-con-xi-jinping-y-mark-carney-en-shenzhen-esta-noc","t":"Sheinbaum se reunirá con Xi Jinping y Mark Carney en Shenzhen; esta noche presenta el Plan México ante empresarios del APEC","c":"nacional","f":"2026-11-16T18:43","r":"La secretaria de Gobernación, Rosa Icela Rodríguez, informó que la presidenta tendrá el martes 17 un encuentro bilateral con Xi Jinping a las 16:00 de China (02:00 en el centro de México) y otro con el primer ministro canadiense Mark Carney a las 18:00 (04:00 en México). Antes, a las 22:00 de este lunes, hora de México, dará un mensaje a líderes empresariales del APEC sobre el Plan México. En su primera actividad en Shenzhen se reunió con unos 20 mexicanos que viven en China y entregó el distintivo Hecho en México a un restaurante.","b":"","img":"palacio","foto":"","cred":"","src":[["MVS Noticias","https://mvsnoticias.com/nacional/2026/11/16/se-reunira-sheinbaum-con-xi-jinping-y-mark-carney-en-china-753645.html"],["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/sheinbaum-llega-a-china-para-la-apec-2026-la-reciben-en-shenzhen-con-bailes-se-reune-con-mexicanos"]],"dest":true,"a":"Redacción"},{"id":"2026-11-16-banco-mundial-estima-que-17-3-millones-de-mexicanos-salieron-de-la-pob","t":"Banco Mundial estima que 17.3 millones de mexicanos salieron de la pobreza por ingresos entre 2018 y 2026","c":"nacional","f":"2026-11-16T18:42","r":"Según un informe del Banco Mundial de octubre, presentado en la mañanera de este lunes, la población en pobreza por ingresos pasaría de 43.9 millones en 2018 a 26.6 millones en 2026, y la tasa bajaría de 35.3% a un estimado de 20%. El organismo proyecta 18.7% para 2028. La cifra de 2026 es una proyección, no una medición definitiva. La conferencia la encabezó Rosa Icela Rodríguez, en ausencia de la presidenta, que está en China.","b":"","img":"palacio","foto":"","cred":"","src":[["Por Esto","https://www.poresto.com/mexico/2026/11/16/pobreza-mexico-baja-puntos-banco-mundial-estima-millones-personas-salieron-condicion.html"],["IMER Noticias","https://noticias.imer.mx/blog/mas-de-17-millones-de-personas-salieron-de-la-pobreza-entre-2018-y-2026-banco-mundial/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-16-el-fmi-advierte-que-mexico-debilita-su-credibilidad-fiscal-y-calcula-u","t":"El FMI advierte que México debilita su credibilidad fiscal y calcula un déficit de 4.2% del PIB en 2026","c":"economia","f":"2026-11-16T18:41","r":"En su revisión anual del Artículo IV, el Fondo Monetario Internacional señala que el aumento del gasto recurrente, incluidos los programas sociales, y los cambios en las reglas presupuestarias minan la credibilidad de las finanzas públicas. Estima un déficit de 4.2% del PIB este año, frente a la meta oficial de 4.1%, y de 3.9% en 2027, por encima del 3.5% previsto antes; anticipa que la deuda bruta seguirá subiendo y prevé un crecimiento de 1.5% en 2026 y 1.8% en 2027. Califica como moderado el riesgo de problemas de deuda soberana.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/dinero/2026/11/16/fmi-advierte-que-mexico-esta-perdiendo-credibilidad-fiscal-por-el-aumento-del-gasto-social-y-alerta-que-la-deuda-publica-seguira-creciendo-en-2027/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-16-jesus-seade-deja-la-embajada-de-mexico-en-china-para-ocupar-una-silla","t":"Jesús Seade deja la Embajada de México en China para ocupar una silla en el directorio del FMI","c":"politica","f":"2026-11-16T18:40","r":"La presidenta Sheinbaum confirmó en China que propuso a Jesús Seade para un cargo en el directorio del Fondo Monetario Internacional y que la propuesta fue aceptada; el directorio tiene 24 directores ejecutivos y México cuenta con un asiento. Seade dijo que los demás miembros votaron a favor. La mandataria adelantó que se reunirá con la directora gerente del FMI, Kristalina Georgieva. No se ha informado quién lo relevará en Pekín.","b":"","img":"palacio","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/nacional/2026/11/16/jesus-seade-deja-embajada-de-mexico-en-china-y-entra-al-fmi-lo-propuse-y-fue-aceptado-dice-sheinbaum/"],["Milenio","https://www.milenio.com/politica/jesus-seade-deja-embajada-china-director-ejecutivo-fmi"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-san-lazaro-analiza-un-periodo-extraordinario-para-elegir-a-quien-presi","t":"San Lázaro analiza un periodo extraordinario para elegir a quien presidirá el INE por falta de acuerdos","c":"politica","f":"2026-11-16T18:39","r":"La Cámara de Diputados aún no aprueba la convocatoria para relevar a Guadalupe Taddei en la presidencia del INE, un proceso que toma alrededor de un mes, por lo que se analiza un periodo extraordinario si no se vota antes del 15 de diciembre. El pleno podría votar la convocatoria el martes 17. Ricardo Monreal, presidente de la Jucopo, dijo que Morena tiene los votos, pero busca consenso con las demás fuerzas; el PAN presentó ocho propuestas para el proceso.","b":"","img":"ine","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/politica/riesgo-eleccion-nueva-presidencia-ine-periodo-ordinario-analizan-extraordinario"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-el-tope-a-gasolinas-y-diesel-ya-le-costo-al-fisco-unos-171-mil-millone","t":"El tope a gasolinas y diésel ya le costó al fisco unos 171 mil millones de pesos desde marzo","c":"economia","f":"2026-11-16T18:38","r":"Un análisis del especialista en energía Ramsés Pech calcula que el control de precios de combustibles implicó, de marzo al 20 de noviembre, unos 163,820 millones de pesos de IEPS no cobrado y un apoyo adicional al diésel de cerca de 7,214 millones, para un total aproximado de 171,034 millones. Del total, unos 92,280 millones corresponden al diésel, 61,791 millones a la Magna y 9,748 millones a la Premium. Los topes vigentes son de 24 pesos para la Magna y 27 para el diésel.","b":"","img":"pemex","foto":"","cred":"","src":[["AM","https://www.am.com.mx/nacional/2026/11/16/tope-a-gasolinas-sale-caro-subsidio-cuesta-mas-de-171-mil-millones-a-los-mexicanos-1867092.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-productores-agricolas-anuncian-bloqueos-carreteros-el-martes-en-cinco","t":"Productores agrícolas anuncian bloqueos carreteros el martes en cinco estados; Guanajuato concentra 16 puntos","c":"estados","f":"2026-11-16T18:37","r":"La Confederación Agropecuaria de México (Coagromex) y otras organizaciones convocaron a bloqueos desde las 8:00 del martes 17 en Guanajuato, Jalisco, Michoacán, Querétaro y Campeche, con unos 25 puntos; en Guanajuato se prevén cierres en las carreteras federales 45, 57 y 90. Exigen pagos pendientes a productores de trigo y maíz, un apoyo directo para la rentabilidad del maíz y seguro agrícola en zonas afectadas. Acusan a la Sader de no cumplir los acuerdos del 22 de octubre.","b":"","img":"carretera","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/16/bloqueo-carretero-del-17-de-noviembre-estos-seran-los-estados-afectados/"],["TV4 Noticias","https://tv4noticias.com/anuncian-bloqueos-en-cinco-estados-guanajuato-tendra-16-cierres-carreteros-el-proximo-martes/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-eu-ofrece-hasta-20-millones-de-dolares-por-dos-lideres-del-cartel-chia","t":"EU ofrece hasta 20 millones de dólares por dos líderes del Cártel Chiapas y Guatemala, aliado del CJNG","c":"seguridad","f":"2026-11-16T18:36","r":"El Departamento de Estado ofreció hasta 10 millones de dólares por cada uno: Axel Bladimir Montejo Sáenz, «El Mosh», detenido en San Diego y con audiencia el 17 de noviembre, y Walfre Donaldo Calderón Calderón, «El Teniente Jr.», que sigue prófugo y operaría en el noroeste de Guatemala, cerca de la frontera con México. Ambos están acusados en California de conspirar para distribuir cocaína; enfrentan hasta cadena perpetua.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/eeuu-ofrece-hasta-20-millones-de-dolares-por-informacion-sobre-dos-lideres-del-cartel-chiapas-y-guatemala-socios-del-cjng/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-ataque-armado-en-galeana-nuevo-leon-deja-tres-muertos-de-una-familia-e","t":"Ataque armado en Galeana, Nuevo León, deja tres muertos de una familia, entre ellos una niña de 7 años","c":"seguridad","f":"2026-11-16T18:35","r":"Hacia la 1:00 del lunes, hombres armados dispararon contra una vivienda en Boca del Refugio, en el sur de Galeana; murieron un hombre de 35 años, una niña de 7 y un joven de 17, y un niño de 12 resultó herido en las piernas. La familia vivía en Ramos Arizpe, Coahuila, y estaba de visita. La Fiscalía de Nuevo León investiga; no hay detenidos ni se ha establecido el móvil.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Universal vía Yahoo","https://es-us.noticias.yahoo.com/ataque-armado-nl-deja-hombre-105936051.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-explosion-por-acumulacion-de-gas-derrumba-una-casa-en-la-miguel-hidalg","t":"Explosión por acumulación de gas derrumba una casa en la Miguel Hidalgo; muere una mujer y hay cuatro heridos","c":"cdmx","f":"2026-11-16T18:34","r":"Alrededor de las 8:20, una vivienda en la calle Lago Peypus, colonia Lago Norte, cerca de Marina Nacional, colapsó parcialmente tras una explosión que el alcalde Mauricio Tabe atribuyó a la acumulación de gas LP. Una mujer de unos 70 años murió y cuatro personas, entre ellas adultos mayores y un menor, fueron rescatadas de los escombros; al menos cinco inmuebles cercanos resultaron dañados.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/explosion-en-lago-peypus-cdmx-una-mujer-murio-y-cuatro-personas-resultaron-heridas-en-la-miguel-hidalgo"],["Reforma","https://www.reforma.com/deja-un-muerto-y-4-heridos-explosion-por-gas-en-alcaldia-mh/ar3315581?v=2"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-wall-street-cae-y-el-nasdaq-pierde-2-49-por-la-crisis-en-nvidia-antes","t":"Wall Street cae y el Nasdaq pierde 2.49% por la crisis en Nvidia antes de su reporte trimestral","c":"economia","f":"2026-11-16T18:33","r":"El Nasdaq cerró en 24,509 puntos (-2.49%), el S&P 500 en 7,416 (-1.92%) y el Dow Jones en 51,608 (-1.41%). Nvidia bajó 4.12% y acumula una caída cercana a 13% en una semana tras la renuncia de su director Jensen Huang; su consejo no contempla reinstalarlo y realiza una investigación independiente. Micron, Intel y AMD cayeron entre 5.6% y 7.6%. Nvidia presenta resultados el martes tras el cierre.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/16/wall-street-cierra-en-rojo-y-el-nasdaq-pierde-el-249-pendiente-de-la-crisis-de-nvidia/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-el-brent-se-desploma-3-55-y-cierra-en-92-44-dolares-por-la-recuperacio","t":"El Brent se desploma 3.55% y cierra en 92.44 dólares por la recuperación de exportaciones en Oriente Medio","c":"economia","f":"2026-11-16T18:32","r":"El crudo de referencia europeo para enero perdió 3.40 dólares en Londres frente al cierre de 95.84 del viernes. Pesaron señales de que los envíos desde Oriente Medio se recuperan y la proyección de la Agencia Internacional de Energía de un excedente en el cuarto trimestre: oferta de 105 millones de barriles diarios, unos 1.7 millones por encima de la demanda.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/16/el-brent-baja-un-355-hasta-9244-dolares-por-el-auge-de-exportaciones-en-oriente-medio/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-el-dolar-cierra-el-dia-festivo-en-18-53-pesos-con-un-alza-de-0-11","t":"El dólar cierra el día festivo en 18.53 pesos, con un alza de 0.11%","c":"economia","f":"2026-11-16T18:31","r":"Con los mercados mexicanos cerrados por el aniversario de la Revolución, el tipo de cambio terminó la jornada en 18.53 pesos por dólar en operaciones internacionales, dos centavos más que el cierre previo de 18.51, según datos de Dow Jones citados por Infobae. Banxico no publicó tipo de cambio fix este lunes.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/16/precio-del-dolar-hoy-en-mexico-cotizacion-de-cierre-del-16-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-desde-madrid-felipe-calderon-acusa-a-la-4t-de-un-homicidio-contra-la-d","t":"Desde Madrid, Felipe Calderón acusa a la 4T de un «homicidio» contra la democracia en México","c":"politica","f":"2026-11-16T18:30","r":"El expresidente habló en la Casa de América, durante la presentación de un libro en homenaje al expresidente chileno Sebastián Piñera. Dijo que el deterioro democrático ya está consumado, criticó la reforma judicial que llevó a elegir jueces por voto popular y el escándalo de contratos en el INE. Sus declaraciones coinciden con la propuesta de Morena de revisar la elección de 2006.","b":"","img":"palacio","foto":"","cred":"","src":[["Uniradio Informa","https://www.uniradioinforma.com/sociedad/felipe-calderon-lamenta-homicidio-democracia-mexico-n914649"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-delfina-gomez-reporta-una-baja-de-16-en-el-promedio-diario-de-homicidi","t":"Delfina Gómez reporta una baja de 16% en el promedio diario de homicidios en el oriente del Edomex","c":"estados","f":"2026-11-16T18:29","r":"La gobernadora informó que en los primeros 15 días de noviembre el promedio diario de homicidios dolosos en la zona del Mando Unificado Oriente bajó alrededor de 16% frente al de octubre. La estrategia abarca 15 municipios, entre ellos Ecatepec, Nezahualcóyotl, Chalco, Chimalhuacán, Naucalpan y Tlalnepantla; no se dieron cifras absolutas.","b":"","img":"palacio","foto":"","cred":"","src":[["El Universal Edomex","https://www.eluniversaledomex.com.mx/seguridad/cae-16-el-homicidio-doloso-en-la-zona-oriente-del-edomex-durante-noviembre-delfina-gomez/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-llega-el-portaaviones-theodore-roosevelt-y-eu-ya-tiene-tres-en-oriente","t":"Llega el portaaviones Theodore Roosevelt y EU ya tiene tres en Oriente Medio por la tensión con Irán","c":"internacional","f":"2026-11-16T18:28","r":"El USS Theodore Roosevelt, que zarpó de San Diego en septiembre, se suma al George H.W. Bush y al George Washington en la región. Trump afirma que la guerra está prácticamente terminada, pero no descarta reanudar ataques; las negociaciones sobre el programa nuclear iraní siguen estancadas. La Guardia Revolucionaria dice que minas han dañado seis buques petroleros desde el domingo en Ormuz.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Nación","https://www.lanacion.com.ar/estados-unidos/tercer-portaaviones-de-eeuu-llega-a-oriente-medio-mientras-trump-sopesa-opciones-en-guerra-con-iran-nid16112026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-trasladan-al-destituido-expresidente-de-paraguay-santiago-pena-a-una-c","t":"Trasladan al destituido expresidente de Paraguay Santiago Peña a una cárcel militar tras denuncias de privilegios","c":"internacional","f":"2026-11-16T18:27","r":"Un juez ordenó llevar a Peña a la prisión militar de Viñas Cue, en Asunción, después de que se descubriera un equipo de gimnasio en el regimiento donde estuvo diez días detenido; el comandante de esa unidad fue removido. Peña fue destituido por el Senado el 6 de noviembre y enfrenta cargos de lesión de confianza y asociación criminal por el colapso de Ueno Bank.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/america-latina/2026/11/16/esposado-y-con-casco-santiago-pena-ingreso-a-una-carcel-militar-de-paraguay-tras-las-denuncias-de-privilegios/"],["Proceso","https://proceso.com.mx/internacional/2026/11/16/ordenan-trasladar-a-expresidente-de-paraguay-a-prision-militar-tras-polemica-por-lujos-en-su-celda-383804.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-robert-pattinson-sera-el-nuevo-james-bond-en-la-pelicula-que-dirigira","t":"Robert Pattinson será el nuevo James Bond en la película que dirigirá Denis Villeneuve","c":"entretenimiento","f":"2026-11-16T18:26","r":"Amazon MGM Studios anunció que el actor británico interpretará al agente 007. El guion es de Steven Knight y la producción de Amy Pascal y David Heyman; Tanya Lapointe será productora ejecutiva. No se ha anunciado fecha de estreno.","b":"","img":"estudio","foto":"","cred":"","src":[["Amazon","https://www.aboutamazon.com/news/entertainment/james-bond-robert-pattinson-cast-amazon-mgm-film"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-checo-perez-y-cadillac-llegan-a-las-vegas-donde-el-mexicano-subio-al-p","t":"Checo Pérez y Cadillac llegan a Las Vegas, donde el mexicano subió al podio en 2023; la carrera es el sábado","c":"deportes","f":"2026-11-16T18:25","r":"El Gran Premio de Las Vegas arranca el jueves 19 con prácticas a las 18:30 y 22:00, hora del centro de México; la clasificación será el viernes a las 22:00 y la carrera, a 50 vueltas en el circuito de 6.201 km, el sábado 21 a las 22:00. Pérez corre su primera temporada con Cadillac; en 2023, con Red Bull, terminó en el podio en esa pista.","b":"","img":"autodromo","foto":"","cred":"","src":[["De Cero a Cien","https://www.deceroacien.com.mx/f1/2026/11/16/gp-de-las-vegas-2026-fechas-horarios-y-donde-ver-a-checo-perez-en-vivo-desde-mexico-23191.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-sheinbaum-llega-a-shenzhen-para-la-cumbre-del-apec-hoy-se-reune-con-la","t":"Sheinbaum llega a Shenzhen para la cumbre del APEC; hoy se reúne con la comunidad mexicana","c":"nacional","f":"2026-11-16T06:50","r":"La presidenta aterrizó en el aeropuerto internacional de Shenzhen a las 11:32 del lunes, hora de China (21:32 del domingo en el centro de México), donde la recibió Huang Chuping, director del Comité Permanente del Congreso Popular de Guangdong. Este lunes tiene previsto un encuentro con mexicanos que viven en esa ciudad; a partir del martes tendrá reuniones con empresas y encuentros bilaterales, entre ellos uno con Xi Jinping, y el 18 y 19 participará en la reunión de líderes del APEC. La acompañan el secretario de Economía, Marcelo Ebrard, y el canciller Roberto Velasco; su regreso está previsto para el viernes 20 de noviembre.","b":"","img":"palacio","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/15/presidenta-sheinbaum-llega-a-china-para-participar-en-cumbre-de-apec-se-reunira-con-xi-jinping"],["UnoTV","https://www.unotv.com/nacional/sheinbaum-llega-a-china-para-participar-en-la-reunion-de-la-apec-regresara-a-mexico-el-viernes/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-16-muere-miguel-angel-felix-gallardo-fundador-del-cartel-de-guadalajara-a","t":"Muere Miguel Ángel Félix Gallardo, fundador del Cártel de Guadalajara, a los 80 años","c":"seguridad","f":"2026-11-16T06:49","r":"La Secretaría de Seguridad de Jalisco confirmó la muerte de Félix Gallardo, conocido como «El Jefe de Jefes», ocurrida el domingo alrededor de las 14:00 en un hospital privado de Guadalajara, al que fue trasladado de urgencia el 13 de noviembre desde el complejo penitenciario de Puente Grande. De acuerdo con los reportes, presentaba falla orgánica múltiple. Cumplía dos condenas que suman 77 años, entre ellas la del asesinato del agente de la DEA Enrique Camarena; los jueces le negaron al menos tres veces la prisión domiciliaria que su familia solicitaba desde 2016.","b":"","img":"jalisco","foto":"","cred":"","src":[["Entorno Informativo","https://entornoinformativo.com.mx/muere-el-narcotraficante-miguel-angel-felix-gallardo-a-los-80-anos-de-edad/"],["Reforma","https://www.reforma.com/murio-miguel-angel-felix-gallardo-ex-lider-del-narco/ar3315196"]],"dest":true,"a":"Redacción"},{"id":"2026-11-16-la-fgr-va-otra-vez-contra-10-exfuncionarios-del-issste-por-contratos-d","t":"La FGR va otra vez contra 10 exfuncionarios del ISSSTE por contratos del «Cártel de la Sangre»","c":"nacional","f":"2026-11-16T06:48","r":"La Fiscalía General de la República pidió a un juez federal del Reclusorio Oriente fijar una nueva audiencia inicial para imputar a 10 exfuncionarios del ISSSTE por uso ilícito de atribuciones, relacionado con contratos de análisis clínicos que suman más de 3,675 millones de pesos entre julio de 2018 y junio de 2020. Según la acusación, la adjudicación directa se basó en un estudio de mercado hecho solo con datos de las empresas participantes. En julio, un juez se negó a vincularlos a proceso por deficiencias en la imputación; la FGR no apeló y reforzó la carpeta. Los señalados se presumen inocentes.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/fgr-va-de-nuevo-contra-10-exfuncionarios-del-issste-por-el-cartel-de-la-sangre-contratos-por-3-mil-675-millones-de-pesos/"],["Reforma","https://www.reforma.com/va-la-fgr-de-nuevo-por-cartel-de-la-sangre/ar3315000"]],"dest":true,"a":"Redacción"},{"id":"2026-11-16-expertos-piden-a-san-lazaro-un-comite-de-evaluacion-ya-para-elegir-a-q","t":"Expertos piden a San Lázaro un comité de evaluación ya para elegir a quien presidirá el INE","c":"politica","f":"2026-11-16T06:47","r":"Diez especialistas en derecho constitucional y electoral, entre ellos Diego Valadés y José Ramón Cossío, pidieron a la Cámara de Diputados integrar de inmediato un Comité Técnico de Evaluación con consenso de los partidos para sustituir a Guadalupe Taddei, quien dejó el INE el 26 de octubre; la ley no fija plazo y la presidenta interina, Blanca Cruz, podría seguir en el cargo. El dirigente del PAN, Jorge Romero, habló de una «crisis de confianza» en el instituto, mientras que el morenista Ignacio Mier propuso auditar los procedimientos de compras del INE desde la gestión de Lorenzo Córdova.","b":"","img":"ine","foto":"","cred":"","src":[["Plaza de Armas (Reforma)","https://plazadearmas.com.mx/piden-a-diputados-apresurar-comite-para-presidencia-de-ine/"],["Zeta Tijuana","https://zetatijuana.com/2026/11/pan-urge-a-esclarecer-presuntas-irregularidades-en-el-ine-mier-pide-auditar-procedimientos-anteriores/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-16-frente-frio-6-lluvias-en-29-estados-este-lunes-festivo-y-minimas-bajo","t":"Frente frío 6: lluvias en 29 estados este lunes festivo y mínimas bajo cero en sierras del norte","c":"nacional","f":"2026-11-16T06:46","r":"El Servicio Meteorológico Nacional prevé lluvias en 29 entidades, con acumulados de 75 a 150 milímetros en Puebla, Oaxaca y Veracruz, por el frente frío 6 que se extiende sobre el noroeste. Habrá temperaturas de -5 a 0 grados en zonas serranas de Baja California, Chihuahua, Zacatecas y Durango, y rachas de 50 a 70 km/h en Tamaulipas y Veracruz. En la Ciudad de México se esperan una máxima de 22 a 24 grados y lluvias aisladas por la tarde.","b":"","img":"lluvia","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/clima/lluvia-mexico-16-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-china-confirma-que-xi-trump-y-putin-se-reuniran-el-jueves-en-shenzhen","t":"China confirma que Xi, Trump y Putin se reunirán el jueves en Shenzhen; hablarán de armas nucleares","c":"internacional","f":"2026-11-16T06:45","r":"La cancillería china confirmó este lunes que los tres líderes se verán el jueves 19 de noviembre al margen de la cumbre del APEC, con el control de armas nucleares como tema principal. Un funcionario estadounidense rebajó las expectativas y dijo que no prevén alcanzar ningún acuerdo, pues será una primera conversación. Trump también planea una reunión bilateral con Xi, en medio de la tregua arancelaria entre ambos países extendida hasta enero de 2027.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/16/china-confirma-la-reunion-entre-xi-trump-y-putin-este-jueves-en-shenzhen/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-sin-fix-de-banxico-por-el-dia-festivo-el-peso-ronda-18-58-por-dolar-el","t":"Sin fix de Banxico por el día festivo, el peso ronda 18.58 por dólar; el jueves salen las minutas","c":"economia","f":"2026-11-16T06:44","r":"Con el mercado mexicano cerrado por el aniversario de la Revolución, el peso cotizaba temprano en 18.58 unidades por dólar en operaciones internacionales; el viernes cerró en 18.5273, con una ganancia de 0.34%. Banxico no publica tipo de cambio fix este lunes. En la semana destacan las minutas de la Reserva Federal el miércoles, las de Banxico el jueves y las ventas minoristas de México de septiembre el viernes.","b":"","img":"bolsa","foto":"","cred":"","src":[["N+","https://www.nmas.com.mx/economia/dolar/precio-del-dolar-hoy-lunes-16-de-noviembre-de-2026-como-esta-el-tipo-de-cambio/"],["La Razón","https://www.razon.com.mx/negocios/2026/11/15/dolar-acumula-tres-semanas-de-ganancias-que-esperar-del-peso-mexicano-del-16-al-20-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-el-brent-abre-la-semana-a-la-baja-y-cae-por-debajo-de-95-dolares-ante","t":"El Brent abre la semana a la baja y cae por debajo de 95 dólares ante el exceso de oferta","c":"economia","f":"2026-11-16T06:43","r":"En sus primeras operaciones del lunes, el crudo Brent se ubicaba cerca de 94.86 dólares por barril, alrededor de 1% menos que su cierre del viernes, y el WTI en torno a 87.90 dólares. Pesan la estimación de la Agencia Internacional de Energía de que la producción superará a la demanda en 1.7 millones de barriles diarios en el cuarto trimestre, la recuperación parcial del tránsito por el estrecho de Ormuz y una baja de 8.1% anual en el procesamiento de las refinerías chinas en octubre.","b":"","img":"pemex","foto":"","cred":"","src":[["Diario Neuquino","https://diarioneuquino.com.ar/el-petroleo-abrio-la-semana-en-baja-el-brent-cayo-por-debajo-de-los-us-95-y-el-mercado-anticipa-mayor-oferta/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-videos-muestran-que-siguieron-al-regidor-gabriel-rivas-desde-el-ayunta","t":"Videos muestran que siguieron al regidor Gabriel Rivas desde el Ayuntamiento de Cuernavaca antes de matarlo","c":"seguridad","f":"2026-11-16T06:42","r":"Grabaciones difundidas este fin de semana, cuya autenticidad confirmaron autoridades, muestran que un motociclista siguió durante cerca de media hora el auto del regidor de Morena y activista desde que salió del Ayuntamiento de Cuernavaca con su esposa el 4 de noviembre; después se habría sumado otro motociclista antes del ataque en la colonia Ejidos de Acapatzingo. El 8 de noviembre fue detenido un hombre identificado como Ricardo Alejandro «N», a quien se le aseguró una motocicleta.","b":"","img":"ultimahora","foto":"","cred":"","src":[["SDP Noticias","https://www.sdpnoticias.com/estados/morelos/gabriel-rivas-rios-video-revela-que-atacante-lo-siguio-desde-el-ayuntamiento/"],["Reforma","https://www.reforma.com/siguieron-a-regidor-de-morelos-media-hora-antes-de-matarlo/ar3315339"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-vuelca-un-autobus-en-la-carretera-tala-san-marcos-en-teuchitlan-muere","t":"Vuelca un autobús en la carretera Tala-San Marcos, en Teuchitlán; muere una joven y hay nueve heridos","c":"estados","f":"2026-11-16T06:41","r":"Un autobús de Auto Transportes Etzatlán salió del camino y volcó a la altura de La Estanzuela, en Teuchitlán, Jalisco. Una joven murió mientras recibía atención médica y nueve personas fueron llevadas a un hospital. Cuerpos de Protección Civil de Teuchitlán, Tala, Ahualulco de Mercado y El Arenal atendieron la emergencia; las autoridades investigan por qué el conductor perdió el control.","b":"","img":"carretera","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/jalisco/volcadura-autobus-teuchitlan-jalisco/"],["Potosinoticias","https://potosinoticias.com/2026/11/16/volcadura-de-autobus-en-teuchitlan-deja-nueve-personas-heridas-y-una-joven-fallecida/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-vecinos-de-guadalajara-vuelven-a-protestar-por-falta-de-agua-y-por-el","t":"Vecinos de Guadalajara vuelven a protestar por falta de agua y por el suministro contaminado","c":"estados","f":"2026-11-16T06:40","r":"Habitantes del área metropolitana de Guadalajara realizaron el domingo una nueva jornada de protestas. Denuncian que por los tandeos algunas zonas pasan hasta un mes sin servicio y que donde sí llega el agua sale visiblemente sucia. Exigen agua potable limpia, una alerta sanitaria, atención médica gratuita para los afectados, transparencia y que no se privatice el servicio.","b":"","img":"jalisco","foto":"","cred":"","src":[["UnoTV","https://www.unotv.com/estados/jalisco/persiste-crisis-agua-potable-jalisco-ciudadanos-vuelven-manifestarse/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-los-vuelos-en-eu-se-normalizan-tras-el-paro-aereo-el-domingo-hubo-mas","t":"Los vuelos en EU se normalizan tras el paro aéreo; el domingo hubo más de 2,800 cancelaciones","c":"internacional","f":"2026-11-16T06:39","r":"A las 5 de la mañana del lunes (hora del este), FlightAware registraba unos 6,500 retrasos y 491 cancelaciones en Estados Unidos, frente a 26,195 retrasos y 2,855 cancelaciones del domingo. El secretario de Transporte, Sean Duffy, atribuyó la falla del viernes a un cambio de cableado hecho por la contratista L3Harris en Arkansas que sobrecargó routers de control aéreo; la FAA dice que la causa de fondo aún se investiga y no hay indicios de ciberataque.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Telemundo Houston","https://www.telemundohouston.com/noticias/eeuu/eeuu-aerolineas-faa-retrasos-normalizacion-operaciones-parada-en-tierra/2591013/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-la-bolsa-de-corea-del-sur-se-desploma-3-59-por-nuevas-dudas-sobre-la-i","t":"La bolsa de Corea del Sur se desploma 3.59% por nuevas dudas sobre la inteligencia artificial","c":"economia","f":"2026-11-16T06:38","r":"El índice Kospi cerró este lunes en 5,100.5 puntos tras perder 3.59%, presionado por ventas de inversionistas extranjeros en tecnológicas; el Kosdaq cayó 4.86%. SK hynix bajó 7.89% y Samsung Electronics 4.47%. La caída se suma a la incertidumbre de la semana pasada tras la salida de Jensen Huang de la dirección de Nvidia.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae (EFE)","https://www.infobae.com/america/agencias/2026/11/16/el-kospi-surcoreano-cae-un-359-en-medio-de-las-renovadas-preocupaciones-sobre-la-ia/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-la-marina-hunde-la-exfragata-victoria-frente-a-matamoros-para-ampliar","t":"La Marina hunde la exfragata Victoria frente a Matamoros para ampliar un arrecife artificial","c":"estados","f":"2026-11-16T06:37","r":"La Secretaría de Marina realizó el hundimiento controlado del casco del ex buque Victoria frente a las costas de Matamoros, Tamaulipas, para reforzar el sistema de arrecifes artificiales del estado, al que ya se habían sumado otros cuatro exbuques de la Armada. Según la dependencia, el proyecto busca favorecer los ecosistemas marinos, la investigación científica y el ecoturismo.","b":"","img":"palacio","foto":"","cred":"","src":[["La Crónica de Hoy","https://www.cronica.com.mx/nacional/2026/11/15/marina-hunde-exbuque-en-tamaulipas-para-fortalecer-sistema-de-arrecifes-artificiales/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-brugada-arranca-la-ruta-del-maiz-de-rtp-en-topilejo-con-autobuses-elec","t":"Brugada arranca la Ruta del Maíz de RTP en Topilejo con autobuses eléctricos","c":"cdmx","f":"2026-11-16T06:36","r":"La jefa de Gobierno, Clara Brugada, puso en marcha la nueva ruta de la Red de Transporte de Pasajeros entre San Miguel Topilejo y La Joya, en Tlalpan, con unidades eléctricas. El director de RTP, Daniel Arcos, dijo que el tiempo de espera bajará de hasta 90 minutos a entre 10 y 15. La ciudad destinó 2 mil millones de pesos para unos 400 autobuses eléctricos y en diciembre iniciará la repavimentación de 21 vialidades en 27 pueblos originarios.","b":"","img":"metrobus","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/ciudad/2026/11/15/clara-brugada-pone-en-marcha-la-ruta-del-maiz-de-la-rtp-en-topilejo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-china-defiende-el-libre-comercio-en-la-cumbre-de-la-asean-en-manila-un","t":"China defiende el libre comercio en la cumbre de la ASEAN en Manila, un día antes de la llegada de Trump","c":"internacional","f":"2026-11-16T06:35","r":"El primer ministro chino, Li Qiang, afirmó ante los líderes del sudeste asiático que su país mantiene un compromiso pleno con el libre comercio pese al aumento de restricciones, en un mensaje leído como dirigido a Washington. Las partes nombraron 2027 como el Año de la Cooperación en Inteligencia Artificial China-ASEAN. Trump llegará a Manila el martes 17 y se reunirá con la ASEAN y con los líderes del Quad.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Unitel (EFE)","https://unitel.bo/noticias/agencias/china-defiende-el-libre-comercio-en-una-cumbre-en-manila-antes-de-la-llegada-de-trump-GM24829528"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-leon-xiv-cierra-hoy-en-lima-su-gira-por-sudamerica-con-una-misa-en-la","t":"León XIV cierra hoy en Lima su gira por Sudamérica con una misa en la Base Aérea Las Palmas","c":"internacional","f":"2026-11-16T06:34","r":"El papa visitará por la mañana la casa de las Hermanitas de los Ancianos Desamparados y a las 12:30 (hora de Perú) oficiará una misa campal de despedida en la Base Aérea Las Palmas, en Santiago de Surco. Por la tarde tendrá una ceremonia oficial en el Callao, desde donde partirá rumbo a Roma. La gira incluyó Uruguay, Argentina y Perú.","b":"","img":"vaticano","foto":"","cred":"","src":[["C5N","https://www.c5n.com/mundo/leon-XIV-ultimo-dia-gira-peru-misa-lima-lunes-16-noviembre-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-america-pumas-y-rayadas-chivas-las-semifinales-de-la-liga-mx-femenil-p","t":"América-Pumas y Rayadas-Chivas, las semifinales de la Liga MX Femenil; Pumas llega por primera vez","c":"deportes","f":"2026-11-16T06:33","r":"América goleó 3-0 a Toluca en el Nemesio Díez (6-0 global) con goles de Geyse, Scarlett Camberos y Priscila Flor Da Silva; Rayadas venció 3-2 a Pachuca (4-2 global), Pumas eliminó a Tigres 7-3 en el global y Chivas avanzó por posición tras empatar 1-1 con Juárez. Para Pumas es su primera semifinal. Las series se jugarán después de una pausa por los compromisos de la Selección Mexicana Femenil.","b":"","img":"estadio","foto":"","cred":"","src":[["Soy Referee","https://soyreferee.com/futbolmx/2026/11/15/semifinales-liga-mx-femenil-apertura-2026-asi-quedaron-los-cruces-60979.html"],["En Juego Deportes","https://www.enjuegodeportes.com/liga-mx-femenil/america-golea-3-0-toluca-semifinales-liga-mx-femenil-apertura-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-mas-de-165-mil-personas-entre-ellas-musk-firman-una-carta-para-que-jen","t":"Más de 165 mil personas, entre ellas Musk, firman una carta para que Jensen Huang vuelva a Nvidia","c":"tecnologia","f":"2026-11-16T06:32","r":"Huang dejó la dirección de Nvidia el jueves 12 de noviembre tras reportes sobre relaciones extramaritales, una de ellas con una ejecutiva de la empresa singapurense Megaspeed. Una carta abierta que pide su regreso suma más de 165 mil firmas, entre ellas las de Elon Musk, Travis Kalanick y Tim Sweeney; unas 7,500 son de empleados de Nvidia. El secretario del Tesoro, Scott Bessent, pidió una reorganización de la dirección y respuestas sobre si chips avanzados llegaron a China.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/tecno/2026/11/16/todos-los-que-importan-en-el-sector-tecnologico-fuera-de-los-laboratorios-admiran-a-jensen-lideres-piden-regreso-a-nvidia/"],["UnoTV","https://www.unotv.com/negocios/con-carta-abierta-157-mil-personas-piden-que-jensen-huang-vuelva-a-nvidia-entre-ellos-elon-musk/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-16-karol-g-pospone-por-salud-su-concierto-del-domingo-en-el-estadio-gnp-s","t":"Karol G pospone por salud su concierto del domingo en el Estadio GNP; será el martes 17","c":"entretenimiento","f":"2026-11-16T06:31","r":"Ocesa informó la tarde del domingo que el tercer concierto de la cantante colombiana en la Ciudad de México se reprogramó para el martes 17 de noviembre, para priorizar su salud y bienestar. Los boletos siguen siendo válidos para la nueva fecha; quien prefiera el reembolso puede pedirlo desde su cuenta de Ticketmaster.","b":"","img":"estadio","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/entretenimiento/2026/11/15/karol-g-reprograma-concierto-en-cdmx-nueva-fecha-y-reembolso/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-sheinbaum-sale-rumbo-a-china-con-escala-en-tijuana-la-mananera-del-lun","t":"Sheinbaum sale rumbo a China con escala en Tijuana; la mañanera del lunes será a distancia","c":"nacional","f":"2026-11-15T18:35","r":"La presidenta partió este domingo hacia Shenzhen para la cumbre del APEC, con una escala en Tijuana, según anunció en un video en redes sociales. La gira dura del 15 al 20 de noviembre, con actividades oficiales del 17 al 19; la conferencia matutina del lunes 16 se hará de forma remota y Rosa Icela Rodríguez conducirá las del 16 al 19. De acuerdo con Presidencia, será la única jefa de Estado, además del anfitrión Xi Jinping, que dará un mensaje en la sesión plenaria de líderes.","b":"","img":"palacio","foto":"","cred":"","src":[["El Independiente","https://elindependiente.mx/nacional/2026/11/15/sheinbaum-parte-rumbo-a-china-para-participar-en-la-cumbre-apec-2026/"],["La Silla Rota","https://lasillarota.com/nacion/2026/11/15/sheinbaum-parte-rumbo-a-china-para-participar-en-apec-2026-537501.html"]],"dest":true,"a":"Redacción"},{"id":"2026-11-15-la-sict-asegura-que-ya-comenzaron-las-inversiones-para-reforzar-la-nav","t":"La SICT asegura que ya comenzaron las inversiones para reforzar la navegación aérea","c":"nacional","f":"2026-11-15T18:34","r":"La Secretaría de Infraestructura, Comunicaciones y Transportes respondió a reportes de que la modernización del control aéreo se concretaría entre 2031 y 2035, y afirmó que las acciones inmediatas ya están en marcha aunque la nueva Política Aeronáutica aún no se publica en el DOF. El Plan Nacional de Navegación Aérea, a 15 años, se publicó el 13 de noviembre en el portal de la OACI; contempla una red privada de telecomunicaciones que enlazaría 63 torres de control, 4 centros de control y 12 subcentros de aproximación radar, y una red satelital de 40 estaciones. La dependencia no dio montos ni calendario de instalación.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/politica-aeronautica-mexicana-comunicaciones-y-transporte-asegura-que-las-inversiones-para-reforzar-la-navegacion-aerea-ya-comenzaron/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-15-asesinan-al-periodista-eduardo-flores-salado-en-acapulco-la-fiscalia-d","t":"Asesinan al periodista Eduardo Flores Salado en Acapulco; la Fiscalía de Guerrero abre investigación","c":"seguridad","f":"2026-11-15T18:33","r":"El periodista Eduardo Flores Salado, colaborador de Enfoque Informativo y extrabajador de Novedades de Acapulco, fue asesinado la noche del sábado 14 de noviembre en la colonia Canuto Noguera, cerca de La Sabana, en Acapulco. La Fiscalía General del Estado abrió una carpeta por homicidio calificado; hasta ahora no hay detenidos ni se ha establecido si el crimen se relaciona con su labor informativa. La Federación de Periodistas de Acapulco confirmó su identidad.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/asesinan-al-periodista-eduardo-flores-salado-en-acapulco-fiscalia-de-guerrero-abre-carpeta-de-investigacion/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-15-profeco-suma-72-quejas-en-los-dos-primeros-dias-del-buen-fin-y-recuper","t":"Profeco suma 72 quejas en los dos primeros días del Buen Fin y recupera casi 400 mil pesos","c":"economia","f":"2026-11-15T18:32","r":"La Procuraduría Federal del Consumidor recibió 72 quejas en los primeros dos días de El Buen Fin, la mayoría por promociones o precios no respetados; al cierre del sábado había conciliado 70 y recuperado 399,666 pesos para los consumidores. Sam's Club acumula más reclamos (8), seguido de Walmart y Soriana (5 cada una); por entidad, encabezan Ciudad de México (13) y Estado de México (12). Ropa y calzado es la categoría con más inconformidades.","b":"","img":"centro","foto":"","cred":"","src":[["Crónica","https://www.cronica.com.mx/nacional/2026/11/15/en-dos-dias-profeco-recibe-72-quejas-durante-el-buen-fin-incumplir-promociones-y-precios-encabezan-reclamos/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-15-morena-preve-publicar-antes-de-que-acabe-noviembre-sus-encuestas-para","t":"Morena prevé publicar antes de que acabe noviembre sus encuestas para coordinaciones municipales","c":"politica","f":"2026-11-15T18:31","r":"Alfonso Ramírez Cuéllar, vicecoordinador de Morena en San Lázaro, dijo que el partido dará a conocer este mes los resultados de las encuestas en las principales ciudades para definir a quienes encabezarán las coordinaciones municipales rumbo a 2027; entre las primeras plazas está Acapulco, además de capitales y zonas metropolitanas. El compromiso lo planteó la dirigente Ariadna Montiel ante legisladores. El PT ha pedido repetir encuestas en algunas entidades, y la dirigencia descartó una nueva medición en Michoacán pese a los cuestionamientos de Raúl Morón.","b":"","img":"ine","foto":"","cred":"","src":[["Peninsular Digital","https://peninsulardigital.com/2026/11/15/preve-morena-definir-coordinaciones-municipales-antes-de-terminar-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-detienen-a-excandidato-de-mc-en-jiquipilco-por-presunta-red-de-huachic","t":"Detienen a excandidato de MC en Jiquipilco por presunta red de huachicol; aseguran 79 mil litros","c":"seguridad","f":"2026-11-15T18:30","r":"Fuerzas federales encabezadas por la FGR detuvieron a Sandro Iván Hernández Rivas, empresario y excandidato de Movimiento Ciudadano a la alcaldía de Jiquipilco en 2024, señalado de operar una red de robo y venta de combustible. En diez cateos en Jiquipilco y Calimaya se aseguraron 79,516 litros de hidrocarburo, decenas de vehículos de carga, armas y 535 mil pesos en efectivo; hay 11 órdenes de aprehensión, una contra un elemento activo de la Guardia Nacional. Se investiga además su posible vínculo con una toma clandestina en Polotitlán.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/detienen-a-excandidato-de-jiquipilco-por-presunta-red-de-huachicol-en-edomex-investigan-conexion-con-polotitlan/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-bancos-y-bolsa-cierran-el-lunes-16-por-el-aniversario-de-la-revolucion","t":"Bancos y Bolsa cierran el lunes 16 por el aniversario de la Revolución; cajeros y SPEI operan","c":"economia","f":"2026-11-15T18:29","r":"El lunes 16 de noviembre es día de descanso obligatorio por el aniversario de la Revolución Mexicana, por lo que la mayoría de las sucursales bancarias y la Bolsa Mexicana de Valores no operarán; Banco Azteca abrirá de 9:00 a 21:00. Cajeros, banca en línea y SPEI funcionan con normalidad, aunque algunos movimientos podrían reflejarse hasta el martes 17. Para el SAT es día inhábil, pero los plazos de pago no se amplían; quien trabaje ese día tiene derecho a salario triple.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/puente-de-noviembre-2026-que-bancos-supermercados-y-servicios-abriran-y-cuales-cerraran-este-lunes-16-en-mexico/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-grecia-quiroz-reconoce-la-captura-de-el-mike-pero-exige-llegar-a-quien","t":"Grecia Quiroz reconoce la captura de El Mike, pero exige llegar a quien ordenó el asesinato de Carlos Manzo","c":"politica","f":"2026-11-15T18:28","r":"La presidenta municipal de Uruapan, Grecia Quiroz, agradeció al secretario de Seguridad, Omar García Harfuch, y a las fuerzas federales la detención en Atotonilco el Alto, Jalisco, de Miguel Ángel Rodríguez Aravizo, El Mike, presunto integrante de la célula Los R's del CJNG. Quiroz insistió en que la investigación debe alcanzar al autor intelectual del homicidio de su esposo, el exalcalde Carlos Manzo, asesinado el 1 de noviembre de 2025 durante el Festival de las Velas.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/en-vivo-seguridad-narcotrafico-y-crimen-en-mexico-hoy-15-de-noviembre-grecia-quiroz-reconoce-captura-de-el-mike-pero-exige-llegar-hasta-quien-ordeno-el-asesinato-de-carlos-manzo/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-explota-un-carro-bomba-en-un-peaje-de-huila-colombia-derriban-tres-tor","t":"Explota un carro bomba en un peaje de Huila, Colombia; derriban tres torres eléctricas","c":"internacional","f":"2026-11-15T18:27","r":"Un carro bomba estalló este domingo en la caseta de peaje de la vía Neiva-Aipe, en el departamento colombiano de Huila, y en Los Cauchos se desactivó otro vehículo con explosivos. Hombres armados derribaron además tres torres de transmisión en El Pital, lo que dejó sin luz a zonas de Huila y Caquetá desde la madrugada. No se reportan víctimas ni se ha atribuido la autoría; en la región operan disidencias de alias Iván Mordisco y alias Calarcá.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Tiempo","https://www.eltiempo.com/colombia/otras-ciudades/ataques-contra-tres-torres-de-energia-deja-sin-servicio-electrico-a-zonas-del-huila-y-caqueta-se-suman-a-los-atentados-contra-peajes-con-carros-bomba-3601315"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-cinco-presuntos-escoltas-de-el-r2-enfrentan-audiencia-de-vinculacion-a","t":"Cinco presuntos escoltas de El R2 enfrentan audiencia de vinculación a proceso en Jalisco","c":"estados","f":"2026-11-15T18:26","r":"Cinco hombres señalados como escoltas de Rafael Álvarez Ayala, El R2, presunto operador del CJNG detenido el 8 de noviembre por la Marina en un restaurante de Guadalajara, enfrentan una audiencia para definir si son vinculados a proceso; permanecen en prisión preventiva en Puente Grande. Se les imputa pandillerismo, narcomenudeo y portación de armas de uso exclusivo de las Fuerzas Armadas. Otras 15 personas detenidas en el mismo operativo quedaron libres el 12 de noviembre y seguirán su proceso sin prisión.","b":"","img":"jalisco","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/cinco-presuntos-escoltas-del-r2-enfrentan-hoy-audiencia-de-vinculacion-a-proceso-en-jalisco/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-ataque-armado-en-un-bar-de-la-zona-dorada-de-mazatlan-deja-un-guardia","t":"Ataque armado en un bar de la Zona Dorada de Mazatlán deja un guardia muerto y un herido","c":"estados","f":"2026-11-15T18:25","r":"Un hombre armado disparó la noche del sábado contra un guardia de seguridad y un cliente del bar La Malinche, sobre la avenida Camarón Sábalo, en Mazatlán, Sinaloa. El guardia murió en el acceso y el cliente, de 32 años, fue hospitalizado con dos heridas de bala en un brazo. Guardia Nacional, Marina y policías desplegaron un operativo; el establecimiento pidió a las autoridades garantizar la seguridad en el puerto.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Zócalo","https://www.zocalo.com.mx/pide-bar-seguridad-tras-ataque-armado-en-mazatlan/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-cierran-hasta-nuevo-aviso-la-estacion-zocalo-de-la-linea-2-del-metro","t":"Cierran hasta nuevo aviso la estación Zócalo de la Línea 2 del Metro","c":"cdmx","f":"2026-11-15T18:24","r":"El Sistema de Transporte Colectivo informó este domingo el cierre de la estación Zócalo/Tenochtitlan de la Línea 2, sin fecha de reapertura ni explicación del motivo. Como alternativas para llegar al Centro Histórico sugirió Pino Suárez, Allende, San Juan de Letrán y Bellas Artes. El lunes 16, día festivo, el Metro dará servicio de 7:00 a 24:00.","b":"","img":"metro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/metro-cdmx-anuncia-cierre-de-la-estacion-zocalo-de-la-linea-2-hasta-nuevo-aviso/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-el-buen-fin-2026-apunta-a-ventas-de-235-mil-millones-de-pesos-y-crece","t":"El Buen Fin 2026 apunta a ventas de 235 mil millones de pesos y crecería menos que en 2025","c":"economia","f":"2026-11-15T18:23","r":"Concanaco Servytur estima que El Buen Fin, que corre del 13 al 17 de noviembre, deje ventas por 235 mil millones de pesos, 7.3% más que los 219 mil 200 millones de 2025; el año pasado el alza había sido de 26.1%. Participan más de 200 mil negocios y cerca de 79% de las ventas se esperan en tiendas físicas. El sorteo fiscal para compras con tarjeta de al menos 250 pesos será el 4 de diciembre.","b":"","img":"centro","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/negocios/buen-fin-2026-concanaco-estima-ventas-235-mil-millones-de-pesos-menor-crecimiento/"],["The Rio Times","https://www.riotimesonline.com/the-big-read-mexico-15-november-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-ucrania-intensifica-sus-ataques-a-refinerias-rusas-moscu-dice-haber-de","t":"Ucrania intensifica sus ataques a refinerías rusas; Moscú dice haber derribado 533 drones","c":"internacional","f":"2026-11-15T18:22","r":"Las fuerzas ucranianas reivindicaron un ataque contra el complejo petroquímico Nizhnekamskneftekhim y una refinería cercana en Tatarstán, donde el alcalde reportó seis heridos. En dos semanas, los drones de Kiev han alcanzado cinco de las mayores refinerías de Rusia; autoridades rusas y prorrusas informaron de tres muertos, uno en Taganrog y dos en Lugansk ocupada. El Ministerio de Defensa ruso afirmó haber derribado 533 drones en la noche del sábado al domingo.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/15/ucrania-intensifica-los-ataques-contra-refinerias-rusas-para-elevar-la-presion-sobre-moscu-en-las-negociaciones/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-chavismo-y-oposicion-siguen-en-caracas-la-cuarta-ronda-de-dialogo-rumb","t":"Chavismo y oposición siguen en Caracas la cuarta ronda de diálogo rumbo a elecciones","c":"internacional","f":"2026-11-15T18:21","r":"Delegaciones del gobierno venezolano y de la oposición, encabezada por Dinorah Figuera, continúan a puerta cerrada en el hotel Gran Meliá Caracas la cuarta ronda de diálogo impulsada por Estados Unidos, la primera desde el regreso de María Corina Machado al país. En la agenda están reformas a las leyes de partidos y de la Contraloría, la situación de exiliados y la renovación del TSJ; Foro Penal contabiliza 321 presos políticos. La ruta prevé renovar primero el CNE.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/venezuela/2026/11/14/el-chavismo-y-la-oposicion-abrieron-el-cuarto-ciclo-de-dialogo-para-allanar-el-camino-a-las-elecciones-en-venezuela/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-leon-xiv-oficia-en-pucallpa-la-primera-misa-de-un-papa-en-la-amazonia","t":"León XIV oficia en Pucallpa la primera misa de un papa en la Amazonía peruana","c":"internacional","f":"2026-11-15T18:20","r":"El papa León XIV visitó Cusco por la mañana y luego viajó a Pucallpa, donde se reunió con indígenas y celebró una misa ante decenas de miles de personas, la primera de un pontífice en la Amazonía de Perú. En su homilía vinculó la explotación laboral con el daño al medio ambiente y criticó la violencia contra los pueblos amazónicos. Regresa a Lima, donde cerrará su gira latinoamericana con una misa para la que se espera un millón de asistentes.","b":"","img":"vaticano","foto":"","cred":"","src":[["EFE vía Yahoo Noticias","https://es-us.noticias.yahoo.com/papa-denuncia-explotaci%C3%B3n-laboral-medio-224359145.html"],["EWTN Noticias","https://www.ewtnnews.com/es/vaticano/leon-xiv-peru-andes-amazonia-cusco-pucallpa"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-filipinas-y-australia-firman-un-acuerdo-de-defensa-durante-la-cumbre-d","t":"Filipinas y Australia firman un acuerdo de defensa durante la cumbre de la ASEAN","c":"internacional","f":"2026-11-15T18:19","r":"En el marco de la cumbre de la ASEAN en Manila, Filipinas y Australia firmaron este domingo un acuerdo de cooperación en defensa, en presencia del primer ministro australiano Anthony Albanese y del secretario filipino de Defensa, Gilberto Teodoro. El pacto busca facilitar ejercicios militares y formalizar reuniones anuales de sus ministros de Defensa; aún no se conocen todos sus detalles. Manila mantiene disputas con China en el mar de China Meridional.","b":"","img":"ultimahora","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/15/filipinas-y-australia-firman-un-acuerdo-de-cooperacion-en-defensa-durante-la-asean/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-mexico-recibe-a-jamaica-el-martes-en-monterrey-obligado-a-remontar-el","t":"México recibe a Jamaica el martes en Monterrey obligado a remontar el 3-2 de la ida","c":"deportes","f":"2026-11-15T18:18","r":"La vuelta de los cuartos de final de la Liga de Naciones de la Concacaf será el martes 17 de noviembre a las 20:30 horas en el Estadio BBVA. En Kingston, Jamaica llegó a ganar 3-0 con un autogol de Jesús Gallardo y tantos de Renaldo Cephas y Richard King; Gilberto Mora y Julián Quiñones descontaron para el Tricolor, que necesita superar el global para avanzar a las Finales.","b":"","img":"estadio","foto":"","cred":"","src":[["Soy Referee","https://soyreferee.com/futbolinternacional/2026/11/15/cuando-juega-mexico-vs-jamaica-en-monterrey-fecha-y-horario-60970.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-sergio-ramirez-ingresa-a-la-rae-en-la-silla-que-dejo-vargas-llosa","t":"Sergio Ramírez ingresa a la RAE en la silla que dejó Vargas Llosa","c":"entretenimiento","f":"2026-11-15T18:17","r":"El escritor nicaragüense Sergio Ramírez, Premio Cervantes 2017, tomó posesión de la silla L de la Real Academia Española, vacante desde la muerte de Mario Vargas Llosa en abril de 2025. Su discurso de ingreso estuvo dedicado al autor peruano, a quien definió como un novelista \"ecuménico\", y le respondió el académico Luis Mateo Díez. Ramírez afirmó que nunca se ha sentido extranjero en España.","b":"","img":"bellas","foto":"","cred":"","src":[["EFE vía Infobae","https://www.infobae.com/espana/agencias/2026/11/15/sergio-ramirez-ingresa-en-la-rae-nunca-he-sido-extranjero-en-espana/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-los-despidos-en-el-sector-tecnologico-superan-los-200-mil-en-2026-segu","t":"Los despidos en el sector tecnológico superan los 200 mil en 2026, según TrueUp","c":"tecnologia","f":"2026-11-15T18:16","r":"El rastreador TrueUp contabiliza 206,877 despidos en empresas tecnológicas en lo que va de 2026, cerca de los 211 mil de todo 2025; al ritmo actual el año cerraría en torno a 237 mil. Layoffs.fyi registra 135,446 hasta el 29 de octubre. Entre los mayores recortes del año figuran Amazon, con unos 16 mil puestos corporativos, y Meta, con cerca de 8 mil.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://infobae.com/tecno/2026/11/15/el-sector-tecnologico-ya-despidio-a-mas-de-200000-personas-en-2026-casi-tantas-como-en-todo-2025"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-sheinbaum-viaja-este-domingo-a-china-para-la-cumbre-del-apec-preve-reu","t":"Sheinbaum viaja este domingo a China para la cumbre del APEC; prevé reunirse con Xi Jinping","c":"nacional","f":"2026-11-15T06:59","r":"La presidenta parte este domingo rumbo a Shenzhen, donde participará del 17 al 19 de noviembre en el foro de Cooperación Económica Asia-Pacífico. Hablará ante el Consejo Consultivo Empresarial del APEC, que agrupa a más de mil empresarios de 21 economías, y en la sesión plenaria de líderes; tiene previstas reuniones bilaterales con Xi Jinping y con los líderes de Canadá, Australia y Vietnam. Viajará en vuelos comerciales y Rosa Icela Rodríguez encabezará las mañaneras en su ausencia.","b":"","img":"palacio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/sheinbaum-viajara-china-primeras-horas-domingo"],["EFE vía Unitel","https://unitel.bo/noticias/agencias/domingo-15-de-noviembre-de-2026-0200-gmt-NO24808401"]],"dest":true,"a":"Redacción"},{"id":"2026-11-15-capturan-en-jalisco-a-el-mike-presunto-operador-de-los-r-ligado-al-cas","t":"Capturan en Jalisco a «El Mike», presunto operador de Los R ligado al caso del alcalde Carlos Manzo","c":"seguridad","f":"2026-11-15T06:58","r":"Fuerzas federales detuvieron en Milpillas, Atotonilco el Alto, a Miguel Ángel Rodríguez Aravizo, alias «Diego» o «Mike», señalado como operador logístico y jefe de plaza de Los R, facción del CJNG, en el corredor Zapotlanejo-Uruapan. Omar García Harfuch informó que la captura ocurrió tras una agresión armada contra elementos federales; también fue detenida una segunda persona. Fuentes federales lo vinculan con el homicidio del alcalde de Uruapan, aunque eso aún debe acreditarse ante el Ministerio Público.","b":"","img":"jalisco","foto":"","cred":"","src":[["Zócalo","https://www.zocalo.com.mx/cae-presunto-lider-de-los-r-tras-enfrentamiento-en-jalisco-lo-ligan-al-crimen-del-edil-de-uruapan/"],["Infobae","https://www.infobae.com/mexico/2026/11/15/siguen-los-golpes-contra-los-rs-del-cjng-capturan-en-atotonilco-el-alto-a-el-mike-tras-agresion-a-elementos-federales/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-15-jamaica-vence-3-2-a-mexico-en-kingston-el-tri-necesita-remontar-el-mar","t":"Jamaica vence 3-2 a México en Kingston; el Tri necesita remontar el martes en Monterrey","c":"deportes","f":"2026-11-15T06:57","r":"La selección cayó en la ida de cuartos de final de la Nations League: un autogol de Jesús Gallardo (28'), Renaldo Cephas (46') y un penal de Richard King (63') pusieron 3-0 a Jamaica, y Gilberto Mora (70') y Julián Quiñones (81') descontaron. Es la tercera derrota seguida de México y Rafael Márquez aún no gana como técnico. A los jamaiquinos les basta el empate en la vuelta del martes en Monterrey; el ganador enfrentará a Estados Unidos o Haití.","b":"","img":"estadio","foto":"","cred":"","src":[["ABC News / AP","https://abcnews.com/Sports/wireStory/jamaica-stuns-mexico-3-2-closing-nations-league-138151617"],["El Financiero","https://www.elfinanciero.com.mx/deportes/2026/11/14/jamaica-vs-mexico-en-vivo-resultado-de-cuartos-de-final-de-ida-en-concacaf-nations-league/"],["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/15/3-2-jamaica-vence-a-mexico-que-llega-a-tres-derrotas-consecutivas/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-15-frentes-frios-5-y-6-traen-lluvias-a-24-estados-y-heladas-de-hasta-5-gr","t":"Frentes fríos 5 y 6 traen lluvias a 24 estados y heladas de hasta -5 grados en sierras del norte","c":"nacional","f":"2026-11-15T06:56","r":"El Servicio Meteorológico Nacional prevé este domingo chubascos de 5 a 25 milímetros en 12 estados, entre ellos Nuevo León, Tamaulipas, Veracruz, Oaxaca, Chiapas y la península de Yucatán, y lluvias aisladas en otros 12. En zonas serranas de Baja California, Chihuahua, Durango y Zacatecas la mínima bajará a entre -5 y 0 grados. En la CDMX se espera una mañana fría con chubascos y posibles descargas eléctricas por la tarde, con máxima de 23 a 25 grados.","b":"","img":"lluvia","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/clima/lluvia-mexico-15-noviembre/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-15-iran-dice-que-ataco-con-seis-drones-un-radar-de-eu-en-barein-y-da-por","t":"Irán dice que atacó con seis drones un radar de EU en Baréin y da por «cerrado» el estrecho de Ormuz","c":"internacional","f":"2026-11-15T06:55","r":"La Guardia Revolucionaria iraní afirmó que lanzó seis drones contra un radar de una instalación de defensa estadounidense en la base de helicópteros de Al-Riffa, en Baréin, como segunda ronda de respuesta tras otro ataque que se atribuyó el viernes. También calificó de fracaso el programa de escoltas de EU en Ormuz. El Ministerio del Interior de Baréin emitió dos alertas y pidió a la población dirigirse al lugar seguro más cercano.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Tiempo / EFE","https://eltiempo.com/mundo/medio-oriente/iran-anuncio-ataque-con-seis-drones-contra-un-radar-militar-de-estados-unidos-en-barein-y-lanzo-advertencia-sobre-el-estrecho-de-ormuz-3601222"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-mc-denuncia-a-morena-y-al-bloque-pri-pan-por-presuntos-actos-anticipad","t":"MC denuncia a Morena y al bloque PRI-PAN por presuntos actos anticipados de campaña rumbo a 2027","c":"politica","f":"2026-11-15T06:54","r":"La vicecoordinadora de Movimiento Ciudadano en la Cámara de Diputados, Laura Ballesteros, informó que su partido presentó denuncias contra Morena y contra la alianza PRI-PAN por presuntos actos anticipados de campaña en Querétaro, uso indebido de recursos públicos y posible financiamiento ilícito, vinculados con actividades de ambos bloques de cara a la elección de 2027.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://infobae.com/mexico/2026/11/14/mc-denuncia-al-prian-y-morena-por-presuntos-actos-anticipados-de-campana-rumbo-a-2027"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-pedro-salmeron-acusa-a-la-dirigencia-de-morena-de-proteger-a-expriista","t":"Pedro Salmerón acusa a la dirigencia de Morena de proteger a expriistas y pide salir del Consejo","c":"politica","f":"2026-11-15T06:53","r":"El historiador y militante cuestionó en redes y en un chat interno los perfiles de Cruz Pérez Cuéllar, alcalde de Ciudad Juárez; Clara Luz Flores; Arturo Martínez Núñez y Camila Martínez, y escribió que Morena estaba «dejando de ser mi partido». Pidió ser retirado del chat y del Consejo. Camila Martínez, secretaria de Comunicación, publicó una captura de la conversación y lo acusó de mentir y de intentar extorsionar al partido, sin detallar esa acusación.","b":"","img":"palacio","foto":"","cred":"","src":[["Proceso","https://www.proceso.com.mx/nacional/2026/11/14/pedro-salmeron-acusa-a-morena-de-proteger-a-expriistas-383737.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-gabito-ballesteros-sale-de-la-fgr-en-queretaro-sigue-abierta-la-invest","t":"Gabito Ballesteros sale de la FGR en Querétaro; sigue abierta la investigación por portación de arma","c":"seguridad","f":"2026-11-15T06:52","r":"El cantante dejó la delegación de la Fiscalía General de la República en Querétaro a las 21:10 horas del sábado, luego de ser detenido junto con otras cuatro personas tras la suspensión de su concierto en la Feria Ganadera. La FGR los investiga por portación de arma de uso exclusivo de las Fuerzas Armadas, desobediencia y resistencia; se aseguraron una pistola, dos cargadores y 34 cartuchos. Su situación jurídica sigue abierta.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/15/liberan-a-gabito-ballesteros-tras-ser-detenido-en-queretaro/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-eu-cancela-mas-de-5-500-vuelos-el-sabado-por-la-falla-de-control-aereo","t":"EU cancela más de 5,500 vuelos el sábado por la falla de control aéreo; la FAA espera normalizar el domingo","c":"internacional","f":"2026-11-15T06:51","r":"Hasta las 17:30 del sábado, FlightAware contabilizaba más de 5,500 vuelos cancelados y 6,900 retrasados en Estados Unidos, y Cirium estimó en 1.5 millones los pasajeros varados. El secretario de Transporte, Sean Duffy, atribuyó la falla al cambio de cableado de cobre por fibra óptica a cargo de la contratista L3Harris y descartó un ciberataque. El jefe de la FAA, Bryan Bedford, prevé que la normalidad comience a restablecerse este domingo, aunque advirtió que el sistema seguirá fallando hasta que se reemplace.","b":"","img":"texas","foto":"","cred":"","src":[["teleSUR","https://www.telesurtv.net/aviacion-eeuu-mas-de-5000-vuelos-cancelados/"],["El Litoral","https://www.ellitoral.com.ar/internacional/2026-11-14-20-21-0-estados-unidos-los-aeropuertos-vuelven-a-la-normalidad-este-domingo"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-buen-fin-sam-s-club-encabeza-las-quejas-del-primer-dia-ante-profeco-ro","t":"Buen Fin: Sam's Club encabeza las quejas del primer día ante Profeco; ropa y pantallas, lo más reclamado","c":"economia","f":"2026-11-15T06:50","r":"Sam's Club acumuló seis de las 32 quejas conciliadas por la Profeco en la primera jornada, seguido de Walmart, First Cash y Elektra con dos cada una. Los motivos principales fueron incumplir promociones (7) y ofertas (6) y no respetar el precio anunciado (5); por producto, ropa y calzado sumó seis y tecnología y pantallas cinco. La Procuraduría revisó 1,004 anuncios en línea y detectó incumplimientos en 49 sitios.","b":"","img":"centro","foto":"","cred":"","src":[["Expansión","https://expansion.mx/empresas/2026/11/14/sams-club-walmart-first-cash-elektra-quejas-un-dia-buen-fin"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-la-mezcla-mexicana-de-petroleo-cierra-la-semana-en-82-7-dolares-por-ba","t":"La mezcla mexicana de petróleo cierra la semana en 82.7 dólares por barril","c":"economia","f":"2026-11-15T06:49","r":"El precio estimado de la mezcla mexicana de exportación terminó el viernes 13 de noviembre en 82.7 dólares por barril, según los datos diarios de Pemex. La cotización es una referencia calculada con fórmulas por región geográfica a partir de los cierres de los crudos marcadores.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/14/cierre-de-la-mezcla-mexicana-de-petroleo-de-este-viernes-13-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-banxico-publicara-el-jueves-las-minutas-de-su-recorte-de-octubre-el-vi","t":"Banxico publicará el jueves las minutas de su recorte de octubre; el viernes llegan las ventas minoristas","c":"economia","f":"2026-11-15T06:48","r":"En la semana del 16 al 20 de noviembre, el Banco de México dará a conocer el jueves las minutas de la reunión en la que bajó la tasa 25 puntos básicos, a 6.25%, en una decisión dividida; analistas esperan que refuercen la idea de una pausa prolongada. El martes inicia en la CDMX la Conferencia de Inversores Públicos del BIS, el Banco Mundial y Banxico, el miércoles se publican las reservas internacionales y el viernes las ventas minoristas de septiembre, con un alza anual esperada de 3.5%.","b":"","img":"bolsa","foto":"","cred":"","src":[["Bloomberg Línea","https://www.bloomberglinea.com/economia/agenda-de-la-semana-pib-de-colombia-y-chile-minutas-de-la-fed-y-resultados-de-nvidia/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-samuel-garcia-preve-que-nuevo-leon-cierre-2026-con-la-cifra-de-homicid","t":"Samuel García prevé que Nuevo León cierre 2026 con la cifra de homicidios más baja en 23 años","c":"estados","f":"2026-11-15T06:47","r":"Tras una reunión de seguridad en Salinas Victoria con su gabinete y mandos federales y estatales, el gobernador informó que la entidad suma siete homicidios en lo que va de noviembre y atribuyó la baja a la coordinación entre los tres niveles de gobierno. También anunció un operativo especial de vigilancia durante el puente y el Buen Fin.","b":"","img":"carretera","foto":"","cred":"","src":[["MVS Noticias","https://mvsnoticias.com/nuevo-leon/2026/11/14/preve-samuel-garcia-cerrar-2026-con-menos-homicidios-753519.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-edomex-despliega-3-mil-policias-en-sus-125-municipios-por-el-buen-fin","t":"Edomex despliega 3 mil policías en sus 125 municipios por el Buen Fin","c":"estados","f":"2026-11-15T06:46","r":"El gobierno de Delfina Gómez puso en marcha un operativo con unos 3 mil policías, 354 vehículos, drones, 25 binomios caninos y 25 equinos para vigilar zonas comerciales de los 125 municipios del Estado de México durante El Buen Fin.","b":"","img":"carretera","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/edomex-despliega-megaoperativo-para-buen-fin-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-mas-de-90-mil-personas-asisten-al-concierto-gratuito-de-garbage-en-el","t":"Más de 90 mil personas asisten al concierto gratuito de Garbage en el Zócalo","c":"cdmx","f":"2026-11-15T06:45","r":"La banda abrió con «There's No Future In Optimism», tocó «I Think I'm Paranoid» con Paulina Villarreal, de The Warning, e incluyó «Stupid Girl», «Push It» y «Only Happy When It Rains»; cerró con «The World Is Not Enough» acompañada por el Mariachi Fiesta de México. El concierto forma parte de la programación cultural del gobierno capitalino.","b":"","img":"zocalo","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/ciudad/2026/11/15/asisten-mas-de-90-mil-personas-a-concierto-de-garbage-en-el-zocalo-de-la-cdmx/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-rusia-dice-que-derribo-1-198-drones-ucranianos-en-una-noche-ataques-cr","t":"Rusia dice que derribó 1,198 drones ucranianos en una noche; ataques cruzados dejan 12 muertos","c":"internacional","f":"2026-11-15T06:44","r":"El Ministerio de Defensa ruso informó que interceptó 1,198 drones sobre una veintena de regiones, incluida Moscú; gobernadores reportaron nueve muertos en zonas industriales de Volgogrado y Samara y en Briansk. En Ucrania murieron dos personas en Odesa y un joven de 17 años en Zaporiyia, y un ataque ruso incendió un hospital en Kiev. Los ataques ocurren tras las reuniones de los enviados de EU con Putin en Moscú y con Zelensky en Dublín.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Yahoo Noticias / AFP","https://es-us.noticias.yahoo.com/rusia-reporta-nueve-muertos-ucrania-143811841.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-monterrey-vence-1-0-a-queretaro-en-partido-pendiente-y-se-mete-al-sept","t":"Monterrey vence 1-0 a Querétaro en partido pendiente y se mete al séptimo lugar del Apertura 2026","c":"deportes","f":"2026-11-15T06:43","r":"Rayados ganó en el Estadio Corregidora el duelo pendiente de la jornada 7 y subió tres posiciones, al séptimo sitio con 24 puntos, por encima de León (23) y detrás de Santos Laguna (25).","b":"","img":"estadio","foto":"","cred":"","src":[["Soy Referee","https://soyreferee.com/futbolmx/2026/11/14/tabla-liga-mx-apertura-2026-asi-quedo-tras-el-queretaro-vs-monterrey-60946.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-eu-y-china-definiran-en-el-apec-una-linea-directa-para-crisis-tecnolog","t":"EU y China definirán en el APEC una línea directa para crisis tecnológicas pese al escándalo de Nvidia","c":"tecnologia","f":"2026-11-15T06:42","r":"Donald Trump y Xi Jinping coincidirán el 18 y 19 de noviembre en Shenzhen, donde se espera precisar la línea directa para crisis de inteligencia artificial acordada en septiembre. Analistas consultados por AFP ven poco probable que la renuncia de Jensen Huang a Nvidia domine la agenda; Trump ha rechazado frenar el desarrollo de sus sistemas más potentes, mientras Xi ha pedido que la tecnología esté «siempre bajo control humano».","b":"","img":"tech","foto":"","cred":"","src":[["Infobae / AFP","https://infobae.com/america/mundo/2026/11/14/el-escandalo-de-nvidia-ensombrece-las-conversaciones-entre-estados-unidos-y-china-sobre-inteligencia-artificial"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-es-falso-el-rumor-de-un-apagon-mundial-el-17-de-noviembre-provocado-po","t":"Es falso el rumor de un apagón mundial el 17 de noviembre provocado por una inteligencia artificial","c":"tecnologia","f":"2026-11-15T06:41","r":"Circula en TikTok, X y YouTube que una IA fuera de control causará un apagón global de tres días desde el 17 de noviembre, supuestamente predicho por Los Simpson. No existe tal episodio y especialistas explican que las redes eléctricas tienen sistemas de redundancia que hacen inviable un colapso así; la confusión mezcla guías europeas de protección civil de 72 horas con una prueba del Sistema de Alerta de Emergencia de EU programada para ese día.","b":"","img":"tech","foto":"","cred":"","src":[["Potosinoticias","https://potosinoticias.com/2026/11/14/habra-un-apagon-mundial-el-17-de-noviembre-por-una-inteligencia-artificial-anatomia-de-un-rumor-viral/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-15-glenn-close-y-ridley-scott-reciben-hoy-el-oscar-honorifico-en-los-gove","t":"Glenn Close y Ridley Scott reciben hoy el Óscar honorífico en los Governors Awards","c":"entretenimiento","f":"2026-11-15T06:40","r":"La Academia entrega este domingo en el Ray Dolby Ballroom de Ovation Hollywood, en Los Ángeles, sus 17 Governors Awards. Glenn Close, Ridley Scott y el animador Floyd Norman recibirán el Óscar honorífico, y las productoras Christine Vachon y Pamela Koffler, fundadoras de Killer Films, el premio Irving G. Thalberg.","b":"","img":"estudio","foto":"","cred":"","src":[["Academia (comunicado)","https://press.oscars.org/news/academy-honor-glenn-close-floyd-norman-ridley-scott-and-christine-vachon-pamela-koffler-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-sheinbaum-califica-de-inmorales-las-liquidaciones-de-cordova-y-edmundo","t":"Sheinbaum califica de inmorales las liquidaciones de Córdova y Edmundo Jacobo al salir del INE","c":"politica","f":"2026-11-14T18:59","r":"La presidenta criticó las liquidaciones que recibieron exconsejeros del INE: dijo que Lorenzo Córdova habría cobrado unos 11 millones de pesos y que Edmundo Jacobo, secretario ejecutivo durante 15 años, fue quien más se llevó. «Puede ser legal, pero también es inmoral», afirmó. Pidió a la ASF revisar los contratos de material electoral de 2014 a 2025 y sostuvo que el presunto monopolio de proveedores no comenzó con Guadalupe Taddei.","b":"","img":"ine","foto":"","cred":"","src":[["La Jornada","https://web.jornada.com.mx/2026/11/14/politica/004n1pol"]],"dest":true,"a":"Redacción"},{"id":"2026-11-14-mas-de-50-personas-y-empresas-aparecen-en-las-denuncias-de-la-fgr-por","t":"Más de 50 personas y empresas aparecen en las denuncias de la FGR por el caso INE; hay 15 carpetas abiertas","c":"politica","f":"2026-11-14T18:58","r":"Las denuncias presentadas ante la Fiscalía General de la República por presuntos ilícitos en el INE señalan a más de 50 personas físicas y morales, en su mayoría familiares de Guadalupe Taddei y del contratista Alfredo Hernández Casillas, además de empresas de material electoral. Las 15 indagatorias están en las fiscalías de Delincuencia Organizada, Anticorrupción y Control Regional; las denuncias provienen del PRI, el PAN, el Órgano Interno de Control del INE, la ASF y ciudadanos. La identidad de los investigados se mantendrá en reserva.","b":"","img":"ine","foto":"","cred":"","src":[["La Jornada","https://web.jornada.com.mx/2026/11/14/politica/005n3pol"]],"dest":true,"a":"Redacción"},{"id":"2026-11-14-mexico-tiene-seis-casos-activos-de-sarampion-y-salud-preve-cerrar-el-b","t":"México tiene seis casos activos de sarampión y Salud prevé cerrar el brote en 2027","c":"nacional","f":"2026-11-14T18:57","r":"El secretario de Salud, David Kershenobich, informó que quedan seis casos activos de sarampión: cinco en Chiapas y uno en Quintana Roo. La cobertura de vacunación es de 90% y la meta es llegar a 95% en tres meses; se han aplicado 4.9 millones de dosis con más de 30 mil brigadistas. Las autoridades esperan certificar la interrupción de la transmisión en 2027 y obtener la recertificación internacional en 2028.","b":"","img":"imss","foto":"","cred":"","src":[["La Jornada","https://web.jornada.com.mx/2026/11/14/politica/009n1pol"]],"dest":true,"a":"Redacción"},{"id":"2026-11-14-el-ascenso-de-stephen-miller-en-la-casa-blanca-preocupa-a-negociadores","t":"El ascenso de Stephen Miller en la Casa Blanca preocupa a negociadores mexicanos del T-MEC","c":"economia","f":"2026-11-14T18:56","r":"Funcionarios mexicanos temen que la llegada de Stephen Miller como jefe de gabinete de Trump alargue la revisión del T-MEC y presione a México a ceder más en migración y seguridad, según Bloomberg. Los acuerdos para reducir aranceles al acero y actualizar el tratado siguen sin concretarse, y México busca mantener el diálogo a través del secretario de Comercio, Howard Lutnick. No está claro si Miller influyó en la amenaza de Trump de duplicar aranceles; la Secretaría de Economía no comentó.","b":"","img":"palacio","foto":"","cred":"","src":[["El Financiero / Bloomberg","https://www.elfinanciero.com.mx/economia/2026/11/14/renegociacion-del-t-mec-la-nueva-y-nada-amistosa-cara-que-perturba-las-negociaciones-entre-mexico-y-eu/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-14-tres-petroleros-chocan-con-minas-iranies-y-se-incendian-en-el-estrecho","t":"Tres petroleros chocan con minas iraníes y se incendian en el estrecho de Ormuz","c":"internacional","f":"2026-11-14T18:55","r":"La televisión estatal de Irán informó que tres buques petroleros golpearon minas navales y se incendiaron en torno al estrecho de Ormuz: dos dentro del paso y uno al este. No se reportaron víctimas ni la nacionalidad de los barcos. La Guardia Revolucionaria y la Armada iraní advirtieron que los barcos que crucen sin su autorización correrán la misma suerte, en medio de la guerra con Estados Unidos y el bloqueo estadounidense a los puertos iraníes.","b":"","img":"ultimahora","foto":"","cred":"","src":[["The Washington Post / AP","https://www.washingtonpost.com/national/2026/11/14/mideast-news-israel-gaza-iran-november-14/da5d8e60-e032-11f1-912c-4fbb80d73f7f_story.html"],["WSLS / AP","https://www.wsls.com/news/2026/11/14/israeli-drone-strike-kills-2-palestinians-in-gaza-and-other-mideast-news/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-chiapas-reactiva-el-empleo-temporal-para-migrantes-mientras-la-caravan","t":"Chiapas reactiva el empleo temporal para migrantes mientras la caravana avanza hacia Arriaga","c":"estados","f":"2026-11-14T18:54","r":"El gobernador Eduardo Ramírez Aguilar anunció este sábado la reactivación de un programa de empleo temporal para personas migrantes en tránsito por Chiapas, coordinado por la Secretaría de la Frontera Sur. La medida llega mientras la caravana «Dios con nosotros», que salió de Honduras el 3 de noviembre, avanza por la costa del estado tras pasar Huixtla y Escuintla, con rumbo a Arriaga.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/14/gobierno-de-chiapas-ofrece-empleo-a-quienes-integran-la-caravana-migrante-que-de-se-dirige-a-la-frontera-norte/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-militares-repelen-una-agresion-en-silao-guanajuato-seis-presuntos-inte","t":"Militares repelen una agresión en Silao, Guanajuato; seis presuntos integrantes del CJNG mueren","c":"seguridad","f":"2026-11-14T18:53","r":"La Defensa informó que elementos del Ejército y la Guardia Nacional fueron atacados desde un inmueble en La Aldea, Silao, al atender una denuncia ciudadana; seis presuntos integrantes del Cártel Jalisco Nueva Generación murieron. Se aseguraron 13 armas de fuego, cargadores, cartuchos, equipo táctico, vehículos, motocicletas y droga, que fueron entregados a la FGR en Irapuato.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/14/fuerzas-armadas-repelen-ataque-en-centro-de-mexico-y-abaten-a-seis-presuntos-delincuentes/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-buen-fin-2026-profeco-recibe-32-quejas-en-el-primer-dia-y-recupera-229","t":"Buen Fin 2026: Profeco recibe 32 quejas en el primer día y recupera 229 mil pesos","c":"economia","f":"2026-11-14T18:52","r":"La Procuraduría Federal del Consumidor reportó 32 inconformidades en el arranque del Buen Fin y recuperó 229,749 pesos para consumidores mediante conciliaciones. Sam's Club acumuló seis quejas; Walmart, First Cash y Elektra, dos cada una. Las causas principales fueron promociones y ofertas no respetadas y precios distintos a los anunciados; ropa, calzado y tecnología fueron los productos con más reclamos.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión","https://expansion.mx/empresas/2026/11/14/sams-club-walmart-first-cash-elektra-quejas-un-dia-buen-fin"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-salud-comprara-semaglutida-para-el-sector-publico-en-2027-y-2028","t":"Salud comprará semaglutida para el sector público en 2027 y 2028","c":"nacional","f":"2026-11-14T18:51","r":"David Kershenobich anunció que las instituciones públicas de salud adquirirán semaglutida, el principio activo de medicamentos como Ozempic y Wegovy, en las compras consolidadas 2027-2028 que coordina el subsecretario Eduardo Clark. Aún se define qué pacientes podrán recibirla; entre los ejemplos citados están personas con diabetes y obesidad con índice de masa corporal superior a 30 o 40.","b":"","img":"imss","foto":"","cred":"","src":[["La Jornada","https://web.jornada.com.mx/2026/11/14/politica/009n1pol"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-la-fgr-investiga-a-gabito-ballesteros-y-a-cuatro-hombres-por-un-arma-d","t":"La FGR investiga a Gabito Ballesteros y a cuatro hombres por un arma de uso exclusivo del Ejército","c":"seguridad","f":"2026-11-14T18:50","r":"El cantante sonorense fue puesto a disposición del Ministerio Público Federal junto con cuatro hombres en la madrugada de este sábado, luego de que policías de Querétaro vieran un arma en la camioneta en la que viajaban; se hallaron una pistola, dos cargadores y 34 cartuchos. Horas antes, su concierto en la Feria Internacional Ganadera fue suspendido porque, según los organizadores, interpretó dos canciones fuera del repertorio acordado. La FGR indicó que definirá su situación jurídica.","b":"","img":"ganado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/14/fgr-investiga-a-gabito-ballesteros-y-a-cuatro-personas-mas-por-portacion-de-arma-de-uso-exclusivo-del-ejercito-y-resistencia/"],["Expansión Política","https://politica.expansion.mx/estados/2026/11/14/apologia-delito-detienen-a-gabito-ballesteros-en-queretaro"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-eu-investiga-si-la-contratista-l3harris-provoco-la-falla-que-paralizo","t":"EU investiga si la contratista L3Harris provocó la falla que paralizó los vuelos; prevén hasta 5 mil cancelaciones este sábado","c":"internacional","f":"2026-11-14T18:49","r":"El secretario de Transporte, Sean Duffy, dijo que se investiga si hubo incompetencia de L3Harris, que cambiaba una línea de cobre por fibra óptica en una instalación de la FAA cuando un enrutador saturó las comunicaciones. Unos 12 mil vuelos no operaron el viernes y la FAA estimó entre 4 mil y 5 mil cancelaciones de los 41 mil programados para el sábado. Duffy pedirá al Congreso 50 mil millones de dólares de emergencia para modernizar el control aéreo.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Bloomberg Línea","https://www.bloomberglinea.com/mundo/estados-unidos/eeuu-investiga-si-la-contratista-l3harris-causo-la-falla-que-paralizo-los-vuelos-en-todo-el-pais/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-un-petrolero-choca-y-hunde-un-crucero-fluvial-en-nueva-orleans-rescata","t":"Un petrolero choca y hunde un crucero fluvial en Nueva Orleans; rescatan a casi 200 personas","c":"internacional","f":"2026-11-14T18:48","r":"El buque tanque Atlantic Asphalt golpeó de costado al barco de vapor American Heritage, atracado cerca del puerto de Nueva Orleans, que se hundió y volcó en el río Misisipi. Las autoridades confirmaron que las casi 200 personas a bordo fueron localizadas; 30 pasajeros y dos agentes fueron hospitalizados sin lesiones graves. La Guardia Costera señaló una aparente pérdida de dirección del petrolero y la NTSB investiga.","b":"","img":"ultimahora","foto":"","cred":"","src":[["ABC News","https://abcnews.com/US/vessel-collision-port-new-orleans-emergency-crews-responding/story?id=138119847"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-el-comercio-de-puebla-preve-una-derrama-de-6-223-millones-de-pesos-en","t":"El comercio de Puebla prevé una derrama de 6,223 millones de pesos en el Buen Fin","c":"economia","f":"2026-11-14T18:47","r":"La Canaco Puebla calcula que el Buen Fin dejará 6,223 millones de pesos en la entidad, 7.3% más que en 2025, con más de 7,200 negocios participantes. Los 74 centros comerciales de la zona metropolitana esperan unos 3.5 millones de visitantes en cinco días. El primer día hubo saturación en Angelópolis y el gobierno municipal desplegó casi mil policías.","b":"","img":"bolsa","foto":"","cred":"","src":[["Intolerancia Diario","https://intoleranciadiario.com/articles/ciudad/2026/11/14/1060435-buen-fin-arranca-con-plazas-saturadas-y-primeras-quejas-en-puebla.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-el-ejercito-destruye-38-plantios-en-cuatro-estados-e-inhabilita-dos-la","t":"El Ejército destruye 38 plantíos en cuatro estados e inhabilita dos laboratorios en Degollado, Jalisco","c":"seguridad","f":"2026-11-14T18:46","r":"Elementos del Ejército y la Fuerza Aérea destruyeron 20 plantíos de amapola y 18 de marihuana en Chihuahua, Oaxaca, Durango y Sinaloa, con una superficie de 4.9 hectáreas. En Degollado, Jalisco, se inhabilitaron dos laboratorios y dos invernaderos de marihuana vinculados a un grupo encabezado por un líder regional del CJNG.","b":"","img":"jalisco","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/14/fuerzas-armadas-repelen-ataque-en-centro-de-mexico-y-abaten-a-seis-presuntos-delincuentes/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-michoacan-suma-271-robos-a-cuentahabientes-bancos-y-cajeros-en-2026-mo","t":"Michoacán suma 271 robos a cuentahabientes, bancos y cajeros en 2026; Morelia concentra 45%","c":"estados","f":"2026-11-14T18:45","r":"Datos de la Fiscalía de Michoacán de enero a octubre registran 258 robos a cuentahabientes, 11 a bancos y 2 a cajeros automáticos. Morelia encabeza con 116 robos a cuentahabientes, seguida de Uruapan (28) y Lázaro Cárdenas (24). A nivel nacional, el SESNSP reportó una baja de 9% en este delito entre enero y septiembre.","b":"","img":"palacio","foto":"","cred":"","src":[["Quadratín Michoacán","https://www.quadratin.com.mx/justicia/suman-271-robos-a-cuentahabientes-bancos-y-cajeros-en-michoacan-en-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-tres-palestinos-mueren-en-gaza-por-ataques-israelies-pese-al-alto-el-f","t":"Tres palestinos mueren en Gaza por ataques israelíes pese al alto el fuego","c":"internacional","f":"2026-11-14T18:44","r":"Un dron israelí mató a dos personas en una rotonda de Yabalia, en el norte de Gaza, y un hombre murió en Rafá por heridas de un bombardeo de hace dos semanas. El Ministerio de Sanidad gazatí contabiliza 1,643 muertos desde la entrada en vigor del alto el fuego. En Cisjordania, cinco palestinos resultaron heridos por un ataque de colonos en Beit Fayar.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / Europa Press","https://www.infobae.com/america/agencias/2026/11/14/tres-palestinos-muertos-en-gaza-en-nuevos-ataques-israelies-a-pesar-del-alto-el-fuego/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-garbage-da-esta-noche-un-concierto-gratuito-en-el-zocalo-la-telonera-c","t":"Garbage da esta noche un concierto gratuito en el Zócalo; la telonera canceló de último momento","c":"cdmx","f":"2026-11-14T18:43","r":"La banda estadounidense se presenta este sábado a las 20:00 horas en la Plaza de la Constitución, con acceso peatonal desde las 14:30. Muñeki77a canceló su participación como acto de apertura. El concierto se transmite por el canal de YouTube del Gobierno capitalino, Capital 21, Canal 14, Canal 22 y Reactor 105.7; la SSC pidió no llevar mochilas, cinturones ni botellas de vidrio.","b":"","img":"zocalo","foto":"","cred":"","src":[["SinEmbargo","https://www.sinembargo.mx/4903934/garbage-en-el-zocalo-de-cdmx-horario-donde-ver-la-transmision-en-vivo-y-otros-tips/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-leon-xiv-oficia-misa-ante-unas-20-mil-personas-en-cajamarca-y-cierra-e","t":"León XIV oficia misa ante unas 20 mil personas en Cajamarca y cierra el Año Jubilar de Santo Toribio","c":"internacional","f":"2026-11-14T18:42","r":"En su cuarto día en Perú, el papa coronó la imagen de la Virgen Inmaculada en la catedral de Chiclayo, celebró una misa al aire libre en Santa Cruz de Succhabamba, Cajamarca, con unas 20 mil personas, y clausuró el Año Jubilar de Santo Toribio de Mogrovejo en Zaña. Afirmó que la violencia «nunca será el camino del progreso y de la paz».","b":"","img":"vaticano","foto":"","cred":"","src":[["EWTN Noticias","https://www.ewtnnews.com/es/vaticano/cuarto-dia-leon-xiv-peru"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-chatgpt-cambia-su-modo-de-voz-por-gpt-live-que-puede-escuchar-y-hablar","t":"ChatGPT cambia su modo de voz por GPT-Live, que puede escuchar y hablar al mismo tiempo","c":"tecnologia","f":"2026-11-14T18:41","r":"OpenAI convirtió GPT-Live en el sistema principal de conversación por voz de ChatGPT; permite interrumpir respuestas y cambiar de tema sin esperar turnos. Los modos Advanced y Standard dejarán de aparecer el 11 de diciembre y quienes los usen pasarán al nuevo sistema de forma automática. Los chats guardados se conservan y las grabaciones de voz se almacenan 30 días.","b":"","img":"tech","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/tecnologia/chatgpt-cambia-su-funcion-voz-que-pasa-tu-historial-y-como-funciona-el-nuevo-sistema-gpt-live-n6344947"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-el-ganador-del-goncourt-2026-philippe-jaenada-admite-que-uso-chatgpt-e","t":"El ganador del Goncourt 2026, Philippe Jaenada, admite que usó ChatGPT en su novela","c":"entretenimiento","f":"2026-11-14T18:40","r":"Un día después de recibir el premio por «L'Inconnue du quai de Javel», Jaenada reconoció que empleó ChatGPT tres veces: para insertar una frase generada por IA, para burlarse de una respuesta errónea del sistema y para investigar, y dijo que informó al jurado. El caso contrasta con el del finalista Thélyson Orélien, excluido en septiembre por sospechas de uso de IA.","b":"","img":"bellas","foto":"","cred":"","src":[["Almomento","https://almomento.mx/el-ganador-del-premio-literario-goncourt-admite-haber-utilizado-inteligencia-artificial/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-la-suspension-de-vuelos-en-eu-afecta-a-18-mil-pasajeros-en-mexico-en-e","t":"La suspensión de vuelos en EU afecta a 18 mil pasajeros en México; en el AICM se cancelaron 44 vuelos","c":"nacional","f":"2026-11-14T06:59","r":"La Agencia Federal de Aviación Civil contabilizó 193 vuelos modificados y 18,002 pasajeros afectados en aeropuertos mexicanos el viernes por la falla en el control aéreo de Estados Unidos. Solo en el AICM hubo 73 vuelos afectados, 44 cancelados y 29 demorados, con 10,293 pasajeros. La AFAC prevé que las operaciones entre ambos países se normalicen de forma gradual.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/14/suspension-de-vuelos-deja-18-mil-afectados-en-mexico/"],["Infobae","https://www.infobae.com/mexico/2026/11/14/reabren-espacio-aereo-de-eeuu-pero-continuan-afectaciones-en-el-aicm-mas-de-10-mil-pasajeros-afectados/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-14-sheinbaum-niega-en-puebla-que-las-becas-aumenten-la-desercion-escolar","t":"Sheinbaum niega en Puebla que las becas aumenten la deserción escolar: «Es completamente falso»","c":"nacional","f":"2026-11-14T06:58","r":"Al entregar Becas Benito Juárez en San Martín Texmelucan, la presidenta respondió a un informe de la UNESCO citado en la prensa y aseguró que este año hay 400 mil estudiantes más en educación media superior. Dijo que el próximo año se destinarán cerca de 190 mil millones de pesos a programas para familias con estudiantes y anunció nuevos bachilleratos y ampliaciones de planteles en Puebla.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/claudia-sheinbaum-entrega-becas-benito-juarez-en-puebla-y-desmiente-que-aumente-la-desercion-escolar-es-completamente-falso/"],["El Universal","https://www.eluniversal.com.mx/nacion/las-becas-estan-haciendo-un-mexico-mejor-dice-sheinbaum-desde-puebla-asegura-que-llevara-el-tema-a-la-apec/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-14-bolivia-pide-a-mexico-informacion-oficial-sobre-el-asilo-politico-al-e","t":"Bolivia pide a México información oficial sobre el asilo político al exvicepresidente Álvaro García Linera","c":"politica","f":"2026-11-14T06:57","r":"La Cancillería boliviana solicitó a México detallar si concedió asilo a García Linera, así como su naturaleza jurídica y alcance; el exvicepresidente de Evo Morales confirmó a EFE que está en México con asilo político. Bolivia dijo respetar las decisiones de otros Estados, pero aclaró que el asilo no suspende los procesos judiciales en su contra, entre ellos una investigación por un operativo de 2009 en Santa Cruz.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/13/bolivia-pide-informacion-a-mexico-por-el-asilo-politico-al-exvicepresidente-garcia-linera/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-14-farmacias-del-ahorro-acuerda-comprar-96-56-de-farmacias-benavides-la-r","t":"Farmacias del Ahorro acuerda comprar 96.56% de Farmacias Benavides; la red sumaría unas 3 mil sucursales","c":"economia","f":"2026-11-14T06:56","r":"Comercializadora Farmacéutica de Chiapas, dueña de Farmacias del Ahorro, firmó el acuerdo con subsidiarias de The Boots Group, accionista mayoritario de Benavides, que opera 1,132 farmacias en 24 estados. No se reveló el monto. La operación requiere la autorización de la Comisión Nacional Antimonopolio; mientras tanto, Benavides seguirá operando con su administración actual.","b":"","img":"bolsa","foto":"","cred":"","src":[["Expansión","https://expansion.mx/empresas/2026/11/13/farmacias-del-ahorro-acuerda-comprar-a-farmacias-benavides"],["El Financiero","https://www.elfinanciero.com.mx/empresas/2026/11/13/farmacias-del-ahorro-compra-9656-de-benavides-y-suma-mas-de-3-mil-sucursales/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-14-morena-dara-a-conocer-a-finales-de-noviembre-sus-encuestas-para-alcald","t":"Morena dará a conocer a finales de noviembre sus encuestas para alcaldías de capitales y zonas metropolitanas","c":"politica","f":"2026-11-14T06:55","r":"El vicecoordinador de Morena en San Lázaro, Alfonso Ramírez Cuéllar, dijo que la dirigente nacional Ariadna Montiel informó a los legisladores que antes de que termine el mes se publicarán los resultados de las encuestas para coordinadores municipales rumbo a 2027, incluido Acapulco. La alianza con PT y Verde definirá perfiles en todo el país.","b":"","img":"palacio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/morena-candidaturas-ciudades-elecciones-2027-finales-noviembre-ganadores-encuestas"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-la-falla-de-control-aereo-en-eu-frena-despegues-en-todo-el-pais-por-un","t":"La falla de control aéreo en EU frena despegues en todo el país por unas siete horas y afecta a más de 7 mil vuelos","c":"internacional","f":"2026-11-14T06:54","r":"La Administración Federal de Aviación suspendió el viernes los despegues en Estados Unidos por una interrupción en sus telecomunicaciones que alcanzó a los 22 centros de control de ruta. El secretario de Transporte, Sean Duffy, lo atribuyó a equipos antiguos que se sobrecargaron, y el secretario de Seguridad Nacional dijo que no hay indicios de un ataque. Las operaciones se reanudan de forma gradual.","b":"","img":"ultimahora","foto":"","cred":"","src":[["El Cronista","https://cronista.com/internacionales/suspenden-todos-los-vuelos-en-eeuu-una-falla-de-comunicacion-paraliza-los-aeropuertos"],["CNN en Español","https://cnnespanol.cnn.com/2026/11/13/eeuu/live-news/ultima-hora-suspension-vuelos-eeuu-noticias-retrasos-trax"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-detienen-en-matamoros-a-cuatro-presuntos-integrantes-de-los-ciclones-c","t":"Detienen en Matamoros a cuatro presuntos integrantes de Los Ciclones con un rifle Barrett y una granada","c":"seguridad","f":"2026-11-14T06:53","r":"Elementos de la Guardia Nacional y del Ejército detuvieron en la colonia Eva Sámano, en Matamoros, Tamaulipas, a cuatro personas señaladas como parte del círculo de seguridad de un operador de esa facción del Cártel del Golfo, tras ser agredidos a balazos. Les aseguraron un rifle calibre .50, tres armas largas, 1,200 cartuchos, una granada y 50 ponchallantas. Quedaron a disposición de la FGR en Reynosa.","b":"","img":"ultimahora","foto":"","cred":"","src":[["La Silla Rota","https://lasillarota.com/estados/2026/11/13/caen-4-integrantes-de-los-ciclones-del-cartel-del-golfo-en-tamaulipas-537383.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-el-gabinete-de-seguridad-inhabilita-un-laboratorio-en-aquila-michoacan","t":"El Gabinete de Seguridad inhabilita un laboratorio en Aquila, Michoacán, y asegura 149 kilos de metanfetamina en Culiacán","c":"seguridad","f":"2026-11-14T06:52","r":"En su reporte de acciones del 12 de noviembre, el Gabinete de Seguridad informó del desmantelamiento de un laboratorio clandestino en Cachán de Echeverría, Aquila, con más de 7,200 litros y 2,400 kilos de sustancias químicas, con una afectación estimada de 2,540 millones de pesos. También reportó el aseguramiento de 149 kilos de metanfetamina en Culiacán y seis detenidos en Chihuahua, Puebla y Sinaloa.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Argon México","https://argonmexico.com/2026/11/13/golpe-al-crimen-organizado-aseguran-armas-drogas-y-un-laboratorio-clandestino-en-cinco-estados/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-el-indep-recauda-407-9-millones-de-pesos-entre-enero-y-octubre-por-sub","t":"El INDEP recauda 407.9 millones de pesos entre enero y octubre por subastas y adjudicaciones","c":"economia","f":"2026-11-14T06:51","r":"En la conferencia presidencial del 13 de noviembre se informó que el Instituto para Devolver al Pueblo lo Robado obtuvo 405.3 millones de pesos por subastas y 2.6 millones por adjudicaciones directas en lo que va del año. En una subasta reciente vendió 57 de 62 motocicletas por 70.9 millones de pesos.","b":"","img":"palacio","foto":"","cred":"","src":[["Eje Central","https://www.ejecentral.com.mx/nuestro-eje/mananera-de-claudia-sheinbaum-en-vivo-resumen-de-la-conferencia-matutina-del-13-de-noviembre-de-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-frente-frio-5-preven-lluvias-en-19-estados-aguanieve-en-el-noroeste-y","t":"Frente frío 5: prevén lluvias en 19 estados, aguanieve en el noroeste y hasta -5 grados en sierras del norte","c":"nacional","f":"2026-11-14T06:50","r":"El Servicio Meteorológico Nacional prevé para este sábado lluvias fuertes en Baja California, Campeche, Yucatán y Quintana Roo, y posible caída de aguanieve en zonas de Baja California, Sonora y Chihuahua. Las temperaturas mínimas podrían ir de -5 a 0 grados en las sierras de Baja California, Chihuahua y Durango, con rachas de viento de 40 a 60 km/h en el noroeste y un nuevo frente que se aproxima al país.","b":"","img":"lluvia","foto":"","cred":"","src":[["Uno TV","https://www.unotv.com/clima/pronostico-clima-mexico-14-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-la-gasolina-magna-se-vende-en-promedio-a-23-82-pesos-por-litro-en-la-c","t":"La gasolina Magna se vende en promedio a 23.82 pesos por litro en la CDMX este sábado","c":"economia","f":"2026-11-14T06:49","r":"Con datos de la Comisión Nacional de Energía y la Profeco, el precio promedio de la gasolina Magna en la Ciudad de México es de 23.816 pesos por litro este 14 de noviembre. La Premium se ubica en 28.703 pesos y el diésel en 26.975 pesos por litro.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/14/ciudad-de-mexico-asi-quedo-el-precio-de-la-gasolina-hoy-sabado-14-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-morena-pt-y-verde-registran-en-guerrero-la-coalicion-sigamos-haciendo","t":"Morena, PT y Verde registran en Guerrero la coalición «Sigamos Haciendo Historia» para 2027","c":"estados","f":"2026-11-14T06:48","r":"Los tres partidos presentaron ante el instituto electoral de Guerrero la solicitud de registro de su coalición para la gubernatura, las diputaciones locales y los ayuntamientos. El acuerdo llegó después de que el PT cuestionara la designación de Beatriz Mojica como virtual candidata de Morena al gobierno estatal. En el acto estuvo la comisionada de elecciones de Morena, Citlalli Hernández.","b":"","img":"palacio","foto":"","cred":"","src":[["Luces del Siglo","https://lucesdelsiglo.com/2026/11/13/firman-tras-jaloneo-alianza-en-guerrero-nacional/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-samuel-garcia-anuncia-mas-de-50-escuelas-nuevas-en-nuevo-leon-en-los-p","t":"Samuel García anuncia más de 50 escuelas nuevas en Nuevo León en los próximos seis meses","c":"estados","f":"2026-11-14T06:47","r":"Durante la entrega de un jardín de niños en Salinas Victoria, con capacidad para más de 100 alumnos, el gobernador de Nuevo León proyectó construir más de 50 planteles en el estado en medio año. No informó el monto de la inversión. En el acto se entregaron mochilas, útiles, uniformes y tenis a 1,172 estudiantes de Salinas Victoria, El Carmen y Escobedo.","b":"","img":"estudio","foto":"","cred":"","src":[["Código Magenta","https://codigomagenta.com.mx/anuncia-gobernador-de-nuevo-leon-construccion-de-50-escuelas-en-6-meses/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-chavismo-y-oposicion-abren-en-caracas-el-cuarto-ciclo-de-dialogo-impul","t":"Chavismo y oposición abren en Caracas el cuarto ciclo de diálogo impulsado por EU para encaminar elecciones","c":"internacional","f":"2026-11-14T06:46","r":"Delegados del gobierno de la presidenta encargada Delcy Rodríguez y de la oposición, encabezada por Dinorah Figuera, iniciaron a puerta cerrada en un hotel de Caracas una nueva ronda de conversaciones que durará alrededor de una semana. En la mesa están la reforma a las leyes de partidos y de financiamiento al terrorismo, las inhabilitaciones políticas y la renovación del Tribunal Supremo y del CNE. Foro Penal contabiliza 321 presos políticos.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/venezuela/2026/11/14/el-chavismo-y-la-oposicion-abrieron-el-cuarto-ciclo-de-dialogo-para-allanar-el-camino-a-las-elecciones-en-venezuela/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-azcapotzalco-publica-las-reglas-de-un-apoyo-unico-de-mil-pesos-para-ad","t":"Azcapotzalco publica las reglas de un apoyo único de mil pesos para adultos en diciembre","c":"cdmx","f":"2026-11-14T06:45","r":"La Gaceta Oficial de la Ciudad de México publicó las reglas del programa «BienEstar para el pueblo», a cargo de la alcaldía Azcapotzalco, que entregará un pago directo de 1,000 pesos en diciembre a residentes mayores de 18 años, con prioridad para 56 unidades territoriales con más carencias. No pueden recibirlo trabajadores de la alcaldía ni beneficiarios de otro de sus programas; las fechas de registro se darán a conocer en los próximos días.","b":"","img":"zocalo","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/economia/clara-brugada-anuncia-nuevo-apoyo-1000-hombres-y-mujeres-mayores-18-anos-cdmx-diciembre-2026-requisitos-y-registro-n6344960"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-arranca-en-manila-la-cumbre-de-la-asean-trump-llegara-el-martes-antes","t":"Arranca en Manila la cumbre de la ASEAN; Trump llegará el martes antes de viajar al APEC en Shenzhen","c":"internacional","f":"2026-11-14T06:44","r":"La 49.ª cumbre de líderes del Sudeste Asiático se celebra de domingo a martes en Manila, con cerca de 20 mil elementos de seguridad. Asistirán, entre otros, el primer ministro chino Li Qiang, la japonesa Sanae Takaichi, el indio Narendra Modi y Lula da Silva como invitado. Trump llegará el martes para una reunión especial ASEAN-Estados Unidos y después partirá a Shenzhen; el bloqueo de Ormuz y la crisis energética dominan la agenda.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Libre Online / EFE","https://libreonline.com/una-veintena-de-lideres-seguridad-y-comercio-claves-de-la-cumbre-de-la-asean-en-manila/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-mexico-visita-hoy-a-jamaica-en-kingston-en-la-ida-de-cuartos-de-la-nat","t":"México visita hoy a Jamaica en Kingston en la ida de cuartos de la Nations League, primer duelo oficial de Rafael Márquez","c":"deportes","f":"2026-11-14T06:43","r":"La Selección Mexicana enfrenta a Jamaica este sábado a las 19:00 horas (centro de México) en el Estadio Nacional de Kingston, en el partido de ida de los cuartos de final de la Liga de Naciones de la Concacaf. La vuelta será el martes 17 de noviembre en el estadio de Rayados, en Monterrey. Julián Quiñones, Santiago Giménez y Roberto Alvarado se perfilan para el ataque.","b":"","img":"estadio","foto":"","cred":"","src":[["Claro Sports","https://www.clarosports.com/en-vivo/jamaica-vs-mexico-en-vivo-cuartos-de-final-nations-league-transmision-resultado-y-goles-hoy-14-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-starship-llega-a-orbita-y-despliega-26-satelites-pero-spacex-desvia-al","t":"Starship llega a órbita y despliega 26 satélites, pero SpaceX desvía al Golfo de México el propulsor que iba a atrapar","c":"tecnologia","f":"2026-11-14T06:42","r":"El vuelo 15 de Starship despegó el 13 de noviembre desde Starbase, en el sur de Texas, alcanzó una órbita baja de unos 275 kilómetros y liberó 26 satélites Starlink V3. SpaceX canceló la captura del propulsor Super Heavy con la torre y lo dirigió al Golfo de México, sin explicar la causa. Para este sábado está previsto el intento de atrapar la nave con los brazos de la torre, si sus sistemas lo permiten.","b":"","img":"texas","foto":"","cred":"","src":[["Astro Vanguardia","https://astrovanguardia.com.ar/lanzamientos/starship-flight-15-llego-a-orbita-y-solto-26-starlink-pero-el-super-heavy-no-fue-atrapado/"],["Infobae","https://www.infobae.com/america/ciencia-america/2026/11/13/spacex-buscara-por-primera-vez-atrapar-con-dos-pinzas-de-su-torre-de-lanzamiento-al-cohete-orbital-starship/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-match-group-prohibe-que-asistentes-de-ia-revisen-perfiles-y-escriban-m","t":"Match Group prohíbe que asistentes de IA revisen perfiles y escriban mensajes en Tinder y Hinge","c":"tecnologia","f":"2026-11-14T06:41","r":"El director de Match Group, Spencer Rascoff, informó que sus aplicaciones de citas no permitirán que agentes de inteligencia artificial elijan perfiles ni envíen mensajes en nombre de los usuarios, aunque representen a personas reales. Argumentó que cierta fricción es necesaria para que las conexiones sean auténticas y pidió a otras empresas moderar la apertura a estos agentes. La empresa no precisó cómo detectará su uso.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/tecno/2026/11/14/tinder-y-hinge-prohibieron-que-asistentes-de-ia-elijan-perfiles-y-escriban-mensajes-por-los-usuarios/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-14-karol-g-abre-en-el-estadio-gnp-seguros-su-serie-de-tres-conciertos-en","t":"Karol G abre en el Estadio GNP Seguros su serie de tres conciertos en la CDMX; Thalía, invitada sorpresa","c":"entretenimiento","f":"2026-11-14T06:40","r":"La cantante colombiana dio el viernes 13 de noviembre el primero de tres conciertos con localidades agotadas de su gira «Viajando por el Mundo, Tropitour». Becky G abrió el espectáculo y Thalía subió al escenario para interpretar con ella «Amor a la mexicana» y «Piel morena». Las otras dos fechas son este sábado y el domingo, con inicio a las 21:00 horas.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/14/karol-g-conquista-el-estadio-gnp-de-cdmx-con-su-tropitour-thalia-es-la-invitada-especial/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-sheinbaum-asegura-que-no-hay-ninguna-caravana-en-transito-y-que-24-se","t":"Sheinbaum asegura que no hay ninguna caravana en tránsito y que 24 se han disuelto desde el regreso de Trump","c":"nacional","f":"2026-11-13T19:55","r":"La presidenta dijo en su conferencia del viernes que, según la Secretaría de Gobernación, 24 caravanas migrantes se han desintegrado en México desde que Donald Trump inició su segundo mandato en enero de 2025; corrigió que no fueron \"detenidas\". Afirmó que una caravana reciente se disolvió y la mayoría de sus integrantes regresó a sus países, y que otra apenas se formaba. La respuesta llega un día después de que Trump amenazó en Truth Social con duplicar los aranceles a México si no frena las caravanas.","b":"","img":"palacio","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/presidencia/2026/11/13/mexico-frena-24-caravanas-migrantes-desde-regreso-trump"]],"dest":true,"a":"Redacción"},{"id":"2026-11-13-anticorrupcion-investiga-a-broxel-la-empresa-que-entrego-monederos-a-2","t":"Anticorrupción investiga a Broxel, la empresa que entregó monederos a 254 diputados de Morena, por pagos en exceso","c":"politica","f":"2026-11-13T19:53","r":"La Secretaría Anticorrupción y Buen Gobierno determinó en un oficio del 10 de noviembre que Servicios Broxel tiene pendientes 29.4 millones de pesos por reintegrar a 39 dependencias federales por pagos en exceso en contratos de vales de despensa de 2025, y recomendó no autorizarle un crédito de hasta 4,200 millones de pesos con Bancomext. El documento señala un posible conflicto de interés porque el representante legal de la firma es hermano del titular de la Unidad de Inversiones de Hacienda, aunque no acredita que este interviniera. Broxel sostiene que cumplió la licitación y que no ha sido notificada formalmente.","b":"","img":"senado","foto":"","cred":"","src":[["El Imparcial","https://www.elimparcial.com/dinero/2026/11/13/secretaria-anticorrupcion-investiga-a-broxel-empresa-que-entrego-monederos-electronicos-a-254-diputados-de-morena-por-presuntos-pagos-irregulares-y-adeudos-millonarios-con-39-dependencias-federales/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-13-el-tribunal-de-justicia-administrativa-abre-procedimientos-contra-exfu","t":"El Tribunal de Justicia Administrativa abre procedimientos contra exfuncionarios del INE hoy dirigentes de Somos por 563 millones","c":"politica","f":"2026-11-13T19:51","r":"Una sala del TFJA especializada en faltas graves abrió dos procedimientos contra Edmundo Jacobo Molina, Roberto Heycher Cardiel Soto y Ana Laura Martínez de Lara por presuntas irregularidades en el INE por más de 563 millones de pesos. Los casos son una obra en Nuevo León por 149.9 millones y un convenio de 413.2 millones con Talleres Gráficos de México de 2017, en el que se pagó por adelantado el total del contrato. Cardiel y Martínez de Lara ocupan hoy cargos en la dirigencia nacional del partido Somos.","b":"","img":"ine","foto":"","cred":"","src":[["MVS Noticias","https://mvsnoticias.com/nacional/2026/11/13/tribunal-indagara-a-ex-cupula-del-ine-por-anomalias-en-contratos-753442.html"]],"dest":true,"a":"Redacción"},{"id":"2026-11-13-la-asf-encuentra-a-personas-fallecidas-cobrando-en-nominas-de-colima-y","t":"La ASF encuentra a personas fallecidas cobrando en nóminas de Colima y observa a otros seis estados","c":"estados","f":"2026-11-13T19:49","r":"En la segunda entrega de la revisión de la Cuenta Pública 2025, la Auditoría Superior de la Federación detectó en Colima pagos a personas fallecidas, plazas en centros de trabajo geográficamente incompatibles y maestros sin el perfil requerido, con más de 25 millones de pesos por aclarar en la nómina educativa. También hubo observaciones en Sinaloa, Baja California Sur, Chiapas, Nuevo León, Aguascalientes y Baja California; Chiapas tiene 99.1 millones por aclarar.","b":"","img":"palacio","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/cobran-hasta-muertos-nominas-estatales"]],"dest":true,"a":"Redacción"},{"id":"2026-11-13-trasladan-a-miguel-angel-felix-gallardo-de-puente-grande-a-un-hospital","t":"Trasladan a Miguel Ángel Félix Gallardo de Puente Grande a un hospital privado de Guadalajara","c":"seguridad","f":"2026-11-13T19:47","r":"El fundador del Cártel de Guadalajara, de 80 años, fue llevado del penal de Puente Grande al hospital Country 2000 por un problema respiratorio que requirió vigilancia médica, según El Financiero. Habitualmente era atendido en el Hospital Civil de Guadalajara. Lleva más de tres décadas preso, entre otros delitos, por el asesinato del agente de la DEA Enrique Camarena.","b":"","img":"jalisco","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/estados/2026/11/13/trasladan-a-felix-gallardo-fundador-del-cartel-de-guadalajara-a-un-hospital-que-le-paso/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-el-exfiscal-de-chihuahua-guillermo-zuany-huyo-a-eu-y-esta-bajo-su-prot","t":"El exfiscal de Chihuahua Guillermo Zuany huyó a EU y está bajo su protección tras colaborar con la CIA, según el NYT","c":"estados","f":"2026-11-13T19:45","r":"The New York Times reportó que Guillermo Zuany Portillo, exfiscal de Operaciones Estratégicas de Chihuahua, fue durante más de seis meses el principal enlace de la CIA en el estado y que salió de México con protección del gobierno estadounidense, que le había devuelto su visa. Tiene órdenes de aprehensión vigentes; el secretario de Seguridad, Omar García Harfuch, dijo el 10 de noviembre que ambas fiscalías tienen una en su contra. El gobierno estatal niega que la gobernadora Maru Campos supiera de la presencia de la agencia.","b":"","img":"chihuahua","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/nacional/exfiscal-chihuahua-guillermo-zuany-proteccion-eu-cia-nyt"],["Zeta Tijuana","https://zetatijuana.com/2026/11/harfuch-confirma-ordenes-de-aprehension-contra-el-ex-fiscal-chihuahuense-que-ayudo-a-la-cia/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-rosa-icela-rodriguez-conducira-la-mananera-del-16-al-19-de-noviembre-m","t":"Rosa Icela Rodríguez conducirá la mañanera del 16 al 19 de noviembre mientras Sheinbaum viaja al APEC","c":"politica","f":"2026-11-13T19:43","r":"La presidenta viajará a China del 15 al 20 de noviembre en vuelo comercial para la cumbre del APEC en Shenzhen, donde tendrá una reunión bilateral con Xi Jinping. En su ausencia, la secretaria de Gobernación encabezará la conferencia matutina y Sheinbaum planea conectarse a distancia casi todos los días; el viernes 20 no habrá mañanera por el desfile del aniversario de la Revolución.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://infobae.com/mexico/2026/11/13/segob-se-encargara-de-la-mananera-la-proxima-semana-pero-sheinbaum-se-conectara-desde-china-para-informar-sobre-la-apec"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-arranca-el-buen-fin-2026-cinco-dias-de-ofertas-y-ventas-esperadas-por","t":"Arranca el Buen Fin 2026: cinco días de ofertas y ventas esperadas por 235 mil millones de pesos","c":"nacional","f":"2026-11-13T19:41","r":"La edición 16 del Buen Fin corre del viernes 13 al martes 17 de noviembre e incluye por primera vez el puente del Día de la Revolución; se esperan unos 200 mil comercios participantes y ventas cercanas a 235 mil millones de pesos. La Profeco desplegará más de mil servidores públicos en 350 brigadas y monitorea 490 productos. El SAT sorteará 500 millones de pesos en premios entre compras con tarjeta de 250 pesos o más.","b":"","img":"centro","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/inicia-el-buen-fin-2026-guia-para-encontrar-ofertas-comercios-participantes-y-apoyo-de-profeco/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-el-peso-cierra-la-semana-en-18-53-por-dolar-y-suma-dos-sesiones-de-gan","t":"El peso cierra la semana en 18.53 por dólar y suma dos sesiones de ganancias","c":"economia","f":"2026-11-13T19:39","r":"La moneda mexicana se apreció 0.44% el viernes, equivalente a 8.21 centavos, y terminó en torno a 18.53 pesos por dólar, con lo que ganó 0.51% en la semana, según El Financiero. El avance se apoyó en datos de precios al productor de Estados Unidos ligeramente por debajo de lo esperado. En ventanillas bancarias el dólar se vendió en alrededor de 19.02 pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/mercados/2026/11/13/peso-dolar-tipo-de-cambio-precio-hoy-13-de-noviembre-de-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-la-bolsa-mexicana-cae-0-84-y-cierra-en-71-204-puntos-pierde-0-26-en-la","t":"La Bolsa Mexicana cae 0.84% y cierra en 71,204 puntos; pierde 0.26% en la semana","c":"economia","f":"2026-11-13T19:37","r":"El S&P/BMV IPC terminó el viernes en 71,204.98 unidades, su segunda baja semanal en tres semanas, luego de marcar un máximo de 72,002 puntos a inicios de la semana, según EFE. Entre las mayores caídas del día estuvieron el Club América (-3.47%) y Banorte (-3.33%), mientras que Sitios Latinoamérica subió 4.89%. El peso se apreció 0.48% frente al dólar.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/13/la-bolsa-de-mexico-pierde-026-en-la-semana-y-se-ubica-en-las-7120498-unidades/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-el-brent-cierra-sin-cambios-en-95-84-dolares-por-barril-ante-la-calma","t":"El Brent cierra sin cambios en 95.84 dólares por barril ante la calma en el frente con Irán","c":"economia","f":"2026-11-13T19:35","r":"El crudo Brent para entrega en enero terminó el viernes en 95.84 dólares, apenas dos centavos más que la víspera, después del repunte de 3.3% del jueves. En la semana acumuló una baja de 1.57 dólares desde los 97.39 con que abrió, y se mantiene lejos de los 116 dólares que llegó a cotizar el 23 de octubre.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/13/el-brent-cierra-hoy-sin-variaciones-en-9584-el-barril-ante-calma-en-la-guerra-de-iran/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-las-divisas-por-turismo-internacional-suben-1-4-a-septiembre-y-suman-2","t":"Las divisas por turismo internacional suben 1.4% a septiembre y suman 26,096 millones de dólares","c":"economia","f":"2026-11-13T19:33","r":"De enero a septiembre llegaron a México 35.98 millones de turistas internacionales, 3.8% más que un año antes, aunque los que llegaron por avión, que aportan cerca de 80% de las divisas, cayeron 4.3%, informó el Inegi. Solo en septiembre, el gasto de los visitantes internacionales creció 5.7% a 1,943.7 millones de dólares, y la llegada de cruceristas en nueve meses aumentó 12.3%.","b":"","img":"angel","foto":"","cred":"","src":[["Yahoo Noticias","https://es-us.noticias.yahoo.com/divisas-tur%C3%ADsticas-sumaron-26-096-173041540.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-la-sener-preve-141-centrales-electricas-en-construccion-a-finales-de-2","t":"La Sener prevé 141 centrales eléctricas en construcción a finales de 2027, 41 más de lo planteado en septiembre","c":"economia","f":"2026-11-13T19:31","r":"La secretaria de Energía, Luz Elena González, dijo en su comparecencia ante el Senado que los proyectos requieren 460 mil millones de pesos y forman parte de la meta de sumar 32 mil megawatts hacia 2030, 70% de ellos renovables. Hasta ahora se han seleccionado 102 proyectos mixtos y 19 privados de generación solar y eólica; la participación de energías limpias pasaría de 23% en 2024 a 38% en 2030.","b":"","img":"pemex","foto":"","cred":"","src":[["Expansión","https://expansion.mx/empresas/2026/11/12/sener-mexico-141-centrales-electricas-construccion-2027"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-detienen-a-otros-dos-implicados-en-el-ataque-en-que-murio-una-nina-de","t":"Detienen a otros dos implicados en el ataque en que murió una niña de 6 años en Ciudad Obregón","c":"seguridad","f":"2026-11-13T19:29","r":"La Fiscalía de Sonora informó la captura de Juan Ramón \"N\", de 26 años, y José Fernando \"N\", de 21, tras una persecución en la que dispararon contra policías estatales la madrugada del jueves; los agentes no resultaron heridos. Las autoridades los relacionan con el ataque del 10 de noviembre contra una familia en el que murió una niña de 6 años; con ellos suman cuatro detenidos y se preparan órdenes de aprehensión por homicidio.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Tribuna","https://tribuna.com.mx/seguridad/2026/11/13/tras-persecucion-y-balacera-caen-otros-dos-implicados-en-asesinato-de-nina-de-6-anos-en-ciudad-obregon_715065/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-brugada-conecta-al-c5-las-camaras-de-mercados-publicos-el-bramadero-de","t":"Brugada conecta al C5 las cámaras de mercados públicos; el Bramadero de Iztacalco es el primero","c":"cdmx","f":"2026-11-13T19:27","r":"La jefa de Gobierno anunció que los mercados que reciben apoyo de la ciudad tendrán videovigilancia enlazada al C5 dentro del programa \"Ojos que te cuidan\", empezando por el mercado Bramadero, en Iztacalco. Citó datos del Inegi según los cuales los delitos contra negocios en la capital bajaron 37% entre 2023 y 2025.","b":"","img":"zocalo","foto":"","cred":"","src":[["Quadratín México","https://mexico.quadratin.com.mx/anuncia-clara-brugada-videovigilancia-de-c5-en-mercados/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-trump-dice-que-consideraria-una-accion-militar-contra-cuba-y-quiere-re","t":"Trump dice que consideraría una acción militar contra Cuba y quiere resolver el tema antes de dejar el cargo","c":"internacional","f":"2026-11-13T19:25","r":"En una entrevista, el presidente estadounidense calificó a Cuba como un país fallido, dijo que una intervención militar \"sería considerada\" y que busca dejar resuelto el asunto antes de que concluya su mandato en enero de 2029. Destacó el papel del secretario de Estado, Marco Rubio, en la estrategia hacia la isla.","b":"","img":"habana","foto":"","cred":"","src":[["MiMorelia","https://mimorelia.com/mundo/trump-consideraria-una-intervencion-militar-cuba-antes-2029-n5597287"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-lideres-europeos-discuten-en-dublin-quien-representara-a-europa-en-las","t":"Líderes europeos discuten en Dublín quién representará a Europa en las negociaciones de paz para Ucrania","c":"internacional","f":"2026-11-13T19:23","r":"En la cumbre de la Comunidad Política Europea, con 47 países, la UE aún no define a su representante para las próximas conversaciones con Rusia; Kaja Kallas y António Costa son los nombres más mencionados, mientras el canciller alemán Friedrich Merz da por hecha la presencia de Alemania. Los enviados estadounidenses Steve Witkoff y Jared Kushner, que se reunieron con Putin en Moscú y con Zelenski en Dublín, aseguraron que los europeos estarán en la mesa.","b":"","img":"paris","foto":"","cred":"","src":[["Yahoo Noticias","https://es-us.noticias.yahoo.com/l%C3%ADderes-ue-debaten-dubl%C3%ADn-enviar-153700058.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-el-senado-de-eu-cita-a-jensen-huang-el-3-de-diciembre-por-su-relacion","t":"El Senado de EU cita a Jensen Huang el 3 de diciembre por su relación con una presunta espía china","c":"tecnologia","f":"2026-11-13T19:21","r":"El senador Tim Scott, presidente de la Comisión de Banca, formalizó la citación del exdirector de Nvidia por su vínculo con Alice Huang, exdirectiva de Megaspeed, a quien agencias estadounidenses señalan como operadora del Ministerio de Seguridad del Estado chino; Pekín lo rechaza. Una comisión de la Cámara de Representantes también lo llamó a una sesión a puerta cerrada el 1 de diciembre. Megaspeed está acusada de ayudar a firmas chinas a evadir los controles de exportación de chips.","b":"","img":"tech","foto":"","cred":"","src":[["Imagen Radio","https://www.imagenradio.com.mx/finanzas/congreso-eu-cita-declarar-jensen-huang-por-escandalo-espionaje-chino"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-rafael-marquez-mantiene-a-tala-rangel-como-portero-titular-para-el-due","t":"Rafael Márquez mantiene a Tala Rangel como portero titular para el duelo ante Jamaica","c":"deportes","f":"2026-11-13T19:19","r":"En conferencia en Kingston, el técnico de la selección dijo que Tala Rangel sigue siendo el arquero titular pese a los dos errores que cometió en la derrota 3-0 ante Estados Unidos, y aseguró que ha mejorado. México visita a Jamaica este sábado 14 de noviembre en la ida de cuartos de final de la Liga de Naciones de la Concacaf.","b":"","img":"estadio","foto":"","cred":"","src":[["TV Azteca","https://www.tvazteca.com/aztecadeportes/ultima-hora-rafa-marquez-confirma-al-portero-titular-vs-jamaica-tras-los-errores-del-tala-rangel/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-karol-g-inicia-hoy-tres-conciertos-agotados-en-el-estadio-gnp-seguros","t":"Karol G inicia hoy tres conciertos agotados en el Estadio GNP Seguros con Becky G como invitada","c":"entretenimiento","f":"2026-11-13T19:17","r":"La colombiana presenta del viernes 13 al domingo 15 de noviembre su gira Viajando por el Mundo Tropitour, con la que promueve su álbum No Me Arrepiento de Sentir Tanto; las puertas abren a las 17:00 y el show empieza a las 21:00. El recinto tiene capacidad para 65 mil personas por función y no se permiten mochilas grandes, alimentos, paraguas ni vapeadores.","b":"","img":"autodromo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/karol-g-en-el-estadio-gnp-seguros-horarios-objetos-prohibidos-canciones-y-todo-sobre-sus-shows-en-cdmx/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-la-fgr-catea-durante-dos-dias-las-oficinas-de-compras-del-ine-por-cont","t":"La FGR catea durante dos días las oficinas de compras del INE por contratos de la gestión de Taddei","c":"politica","f":"2026-11-13T06:59","r":"Agentes federales revisaron desde la mañana del miércoles 11 hasta la tarde del jueves 12 la Dirección de Recursos Materiales y Servicios del INE, en Torre Zafiro, en busca de documentos y equipos de cómputo, en una investigación por presunto cohecho, peculado y tráfico de influencias en contratos con proveedores de material electoral. Al concluir, la FGR no informó qué obtuvo ni si hay órdenes de aprehensión.","b":"","img":"ine","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/13/en-ine-cateo-de-fgr-en-camara-relevo-atorado/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-13-el-fmi-reduce-a-18-mil-millones-de-dolares-la-linea-de-credito-flexibl","t":"El FMI reduce a 18 mil millones de dólares la línea de crédito flexible de México y prevé un crecimiento de 1.5% en 2026","c":"economia","f":"2026-11-13T06:58","r":"A petición de las autoridades mexicanas, el directorio del FMI aprobó bajar el acceso de 24 mil a unos 18 mil millones de dólares, 150% de la cuota del país, al considerar que los riesgos externos extremos se moderaron. El organismo estima que el PIB crecerá 1.5% este año y 1.8% en 2027, y advirtió que la revisión del T-MEC y las reformas internas siguen pesando sobre la actividad.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/economia/2026/11/12/fmi-reduce-a-18-mil-mdd-la-linea-de-credito-flexible-a-mexico-destaca-dinamismo-en-economia/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-13-la-ocde-reporta-una-caida-de-87-en-los-registros-de-migrantes-irregula","t":"La OCDE reporta una caída de 87% en los registros de migrantes irregulares en México en 2025","c":"nacional","f":"2026-11-13T06:57","r":"Según el informe Perspectivas de la Migración Internacional 2026, publicado el jueves, los eventos de personas en situación irregular bajaron de 1.2 millones en 2024 a 155,700 en 2025; la OCDE aclara que son registros administrativos y no personas distintas. México recibió 70,482 solicitudes de asilo en 2025, 11% menos que el año previo, encabezadas por cubanos, venezolanos y haitianos.","b":"","img":"carretera","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/13/cae-87-cifra-de-migrantes-irregulares-en-mexico-ocde/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-13-publican-en-el-dof-la-ley-de-ingresos-2027-preve-10-6-billones-de-peso","t":"Publican en el DOF la Ley de Ingresos 2027: prevé 10.6 billones de pesos y limita deducciones a grandes empresas","c":"economia","f":"2026-11-13T06:56","r":"El paquete publicado este viernes estima ingresos por 10.6 billones de pesos, de los cuales 6.26 billones serán impuestos, y autoriza endeudamiento neto interno de hasta 1.7 billones. La reforma al ISR crea un control de deducciones y pérdidas fiscales para empresas con ingresos de más de 50 millones de pesos y elimina el régimen opcional para grupos de sociedades. Entra en vigor el 1 de enero de 2027.","b":"","img":"senado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/publican-en-el-dof-la-ley-de-ingresos-2027-y-reformas-al-isr-y-a-la-ley-federal-de-derechos/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-13-se-atora-en-san-lazaro-la-convocatoria-para-relevar-a-taddei-en-el-ine","t":"Se atora en San Lázaro la convocatoria para relevar a Taddei en el INE: el PRI votará en contra y PAN y MC piden garantías","c":"politica","f":"2026-11-13T06:55","r":"Ricardo Monreal reconoció que aún no hay acuerdo y dijo que busca un consenso con todas las fuerzas para que la nueva presidencia del INE no nazca cuestionada; dejó abierta la posibilidad de que siga la presidenta provisional, Blanca Cruz García. Rubén Moreira anunció el voto en contra del PRI, el PAN exige un comité técnico independiente e Ivonne Ortega condicionó el apoyo de MC a reducir las facultades de la presidencia del instituto.","b":"","img":"ine","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/13/se-atora-relevo-en-el-ine-por-la-falta-de-consenso/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-garcia-harfuch-pone-a-disposicion-de-los-municipios-la-inteligencia-de","t":"García Harfuch pone a disposición de los municipios la inteligencia del CNI para combatir el delito","c":"nacional","f":"2026-11-13T06:54","r":"En la primera asamblea plenaria de 2026 de la Conferencia Nacional de Seguridad Pública Municipal, el secretario de Seguridad anunció que los ayuntamientos podrán apoyarse en las capacidades de investigación e inteligencia federales, incluido el Centro Nacional de Inteligencia, mediante intercambio confidencial de información. Como ejemplo citó acuerdos en Sinaloa con una inversión de 900 millones de pesos para fortalecer a las policías de Culiacán, Mazatlán y la estatal.","b":"","img":"palacio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/13/harfuch-amplia-plan-anticrimen-a-los-municipios/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-liberan-a-15-de-los-19-detenidos-con-el-r2-la-audiencia-de-vinculacion","t":"Liberan a 15 de los 19 detenidos con «El R2»; la audiencia de vinculación de los demás seguirá el domingo","c":"seguridad","f":"2026-11-13T06:53","r":"Tras una audiencia que se prolongó hasta la madrugada del jueves en Puente Grande, un juez impuso medidas no privativas de la libertad a 15 de los hombres capturados junto a Rafael Álvarez Ayala, líder de la célula Los Rs del CJNG, entre ellos músicos y empleados y comensales del restaurante de Guadalajara donde ocurrió el operativo de la Marina. Los que siguen presos enfrentan cargos por portación de armas y cartuchos de uso militar y narcomenudeo; la audiencia se reanudará el domingo 15.","b":"","img":"jalisco","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/liberan-a-15-personas-de-las-19-detenidas-en-jalisco-junto-al-r2-lider-de-una-celula-del-cjng/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-la-secretaria-de-energia-afirma-que-la-refinacion-subio-18-8-y-que-mex","t":"La secretaria de Energía afirma que la refinación subió 18.8% y que México evitó el alza de combustibles por la crisis en Ormuz","c":"economia","f":"2026-11-13T06:52","r":"Luz Elena González Escobar dijo ante la Comisión de Energía del Senado que la refinación pasó de 925 mil a 1.107 millones de barriles diarios y que la refinería Olmeca produce 270 mil barriles al día. Aseguró que la gasolina regular se mantiene debajo de 24 pesos por litro y el diésel de 27, y que la deuda financiera de Pemex bajó a 77,600 millones de dólares, su menor nivel desde 2014.","b":"","img":"pemex","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/13/sener-contiene-estrategia-alza-de-combustibles-ante-crisis-en-ormuz/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-la-caravana-dios-con-nosotros-avanza-por-chiapas-con-unas-1-500-person","t":"La caravana «Dios con Nosotros» avanza por Chiapas con unas 1,500 personas; suman 24 caravanas desde Tapachula en este sexenio","c":"estados","f":"2026-11-13T06:51","r":"El contingente salió de Tapachula el martes 10 con alrededor de 1,500 migrantes, según el gobierno de Chiapas, y busca llegar a la Ciudad de México para pedir documentos; camina de noche y de madrugada por temperaturas de hasta 40 grados. Luis García Villagrán, del Centro de Dignificación Humana, calcula que han partido unas 24 caravanas en la actual administración. Médicos Sin Fronteras atendió a más de 1,400 personas de siete caravanas en 2025 y 2026.","b":"","img":"carretera","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/13/suman-24-caravanas-que-salen-de-tapachula-con-el-actual-gobierno/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-el-ine-alista-nuevas-salidas-de-funcionarios-cercanos-a-taddei-la-titu","t":"El INE alista nuevas salidas de funcionarios cercanos a Taddei; la titular de lo Contencioso Electoral, entre ellas","c":"politica","f":"2026-11-13T06:50","r":"La consejera presidenta provisional, Blanca Cruz García, podría anunciar cinco renuncias más, de acuerdo con reportes periodísticos retomados por Infobae; entre los nombres con mayor consenso está Jessica Alarcón Góngora, titular de la Unidad Técnica de lo Contencioso Electoral. Las renuncias voluntarias y solicitadas suman 30 desde el 3 de noviembre. El INE afirmó que el proceso se apega a la legalidad.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/ine-alista-salida-de-mas-funcionarios-cercanos-a-guadalupe-taddei-rumbo-a-las-elecciones-de-2027/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-el-peso-abre-el-viernes-en-18-55-por-dolar-y-gana-0-28-frente-al-cierr","t":"El peso abre el viernes en 18.55 por dólar y gana 0.28% frente al cierre previo","c":"economia","f":"2026-11-13T06:49","r":"El tipo de cambio promedio se ubicó en 18.55 pesos por dólar en la apertura de este viernes, por debajo de los 18.60 del cierre anterior, según datos de Dow Jones citados por Infobae. La semana pasada el dólar había retrocedido 0.42% frente al peso.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/precio-del-dolar-hoy-en-mexico-cotizacion-de-apertura-del-13-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-una-falla-global-de-microsoft-365-deja-sin-correo-a-tribunales-bancos","t":"Una falla global de Microsoft 365 deja sin correo a tribunales, bancos y gobiernos en Asia-Pacífico","c":"tecnologia","f":"2026-11-13T06:48","r":"La interrupción, que comenzó el jueves, afectó Outlook, Exchange, Teams, Copilot y OneDrive; Downdetector acumuló más de 36 mil reportes en 72 países. En Tailandia cuatro grandes bancos suspendieron servicios que dependen del correo, en Japón el gobierno reportó fallas en su infraestructura y en Australia se vieron afectadas la Policía Federal y otras agencias. Microsoft dijo no tener indicios de actividad maliciosa y que la recuperación es gradual.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/13/tribunales-bancos-e-instituciones-de-asia-pacifico-se-paralizan-por-la-caida-de-microsoft/"],["El Tiempo","https://www.eltiempo.com/tecnosfera/novedades-tecnologia/ultimas-noticias-de-la-caida-mundial-de-outlook-365-microsoft-y-mas-la-compania-descarto-indicios-de-un-ataque-informatico-como-origen-de-las-fallas-3600724"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-wall-street-cierra-a-la-baja-por-el-desplome-de-nvidia-tras-la-salida","t":"Wall Street cierra a la baja por el desplome de Nvidia tras la salida de Jensen Huang; el WTI sube 2.55%","c":"economia","f":"2026-11-13T06:47","r":"El Dow Jones perdió 0.36% y terminó el jueves en 52,297 puntos; el S&P 500 bajó 0.35% a 7,592 y el Nasdaq cedió 0.39% a 25,366, según EFE. Las acciones de Nvidia cayeron 4.34% al cierre, después de llegar a desplomarse hasta 15% antes de la apertura, por la renuncia de su director. El crudo WTI avanzó 2.55% a 88.74 dólares por barril luego de que Trump dijo que un acuerdo con Irán no es necesario.","b":"","img":"bolsa","foto":"","cred":"","src":[["El Informador / EFE","https://www.informador.mx/economia/wall-street-cierra-en-rojo-tras-el-terremoto-en-nvidia-y-la-subida-del-petroleo-20261112-0186.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-capturan-en-iguala-a-el-chuy-y-la-rosi-senalados-como-integrantes-de-l","t":"Capturan en Iguala a «El Chuy» y «La Rosi», señalados como integrantes de Los Tlacos, con 50 dosis de presunto cristal","c":"seguridad","f":"2026-11-13T06:46","r":"La Fiscalía de Guerrero, con apoyo de la Defensa, la Guardia Nacional y la policía estatal, detuvo el 12 de noviembre en la colonia Luis Quintero de Iguala a Juan de Jesús «N» y Rosalinda «N», a quienes vio intercambiando paquetes en la vía pública. Les aseguraron 50 dosis de una sustancia con características de cristal y dos motocicletas; fueron puestos a disposición del Ministerio Público.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/caen-con-droga-el-chuy-y-la-rosi-presuntos-miembros-de-los-tlacos-en-guerrero/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-detienen-en-chapultepec-edomex-a-dos-presuntos-integrantes-de-la-nueva","t":"Detienen en Chapultepec, Edomex, a dos presuntos integrantes de La Nueva Familia Michoacana con gorras alusivas a sus líderes","c":"estados","f":"2026-11-13T06:45","r":"La Secretaría de Seguridad del Estado de México informó la captura de Jorge «N», de 29 años, y Marco «N», de 35, en el Camino Viejo a Chapultepec, tras una revisión a la motocicleta en la que viajaban, marcada con las letras «FM». Les aseguraron una réplica de pistola, un cuchillo y gorras con un pez y una fresa, en alusión a los hermanos Hurtado Olascoaga; las autoridades los vinculan con la venta de droga en Chapultepec, San Mateo Atenco, Mexicaltzingo y Metepec.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/13/con-gorras-alusivas-a-el-pez-y-el-fresa-capturan-a-dos-presuntos-integrantes-de-la-nueva-familia-michoacana-en-edomex/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-repartidores-marchan-hoy-en-la-cdmx-para-exigir-que-se-cancele-de-form","t":"Repartidores marchan hoy en la CDMX para exigir que se cancele de forma definitiva el plan de placas para motos de reparto","c":"cdmx","f":"2026-11-13T06:44","r":"Las agrupaciones Repartidores Unidos de México y Ni Un Repartidor Menos convocaron a una movilización a partir de las 12:00 horas con cierres intermitentes de 20 a 30 minutos en Reforma, Insurgentes, Calzada de Tlalpan, Bucareli y Circuito Interior. Piden cancelar, y no solo suspender como anunció la Semovi, las placas mercantiles y licencias de carga para motocicletas de reparto, así como transparencia en el cobro de 2% por uso de infraestructura.","b":"","img":"angel","foto":"","cred":"","src":[["Ámbito","https://www.ambito.com/mexico/informacion-general/estas-son-todas-las-marchas-confirmadas-cdmx-hoy-13-noviembre-2026-cortes-bloqueos-y-alternativas-viales-alcaldias-n6344760"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-leon-xiv-vuelve-hoy-a-chiclayo-la-diocesis-que-dirigio-ocho-anos-tras","t":"León XIV vuelve hoy a Chiclayo, la diócesis que dirigió ocho años, tras reunir a unos 60 mil jóvenes en Lima","c":"internacional","f":"2026-11-13T06:43","r":"El papa viaja este viernes de Lima a Chiclayo, en el norte de Perú, donde fue obispo de 2015 a 2023, para oficiar una misa multitudinaria en las Pampas de Pimentel y reunirse con el clero local y con universitarios. La noche del jueves encabezó en el Estadio Nacional de Lima una vigilia con cerca de 60 mil jóvenes, según EWTN. El sábado coronará a la Virgen Inmaculada en la catedral chiclayana.","b":"","img":"vaticano","foto":"","cred":"","src":[["EWTN Noticias","https://www.ewtnnews.com/es/vaticano/leon-xiv-peru-regreso-chiclayo"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-el-tri-llega-a-kingston-para-el-primer-partido-oficial-de-rafael-marqu","t":"El Tri llega a Kingston para el primer partido oficial de Rafael Márquez como técnico, ante Jamaica en la Nations League","c":"deportes","f":"2026-11-13T06:42","r":"La selección mexicana aterrizó el jueves en la capital jamaicana para la ida de cuartos de final de la Liga de Naciones de la Concacaf, que se jugará en el Estadio Nacional de Kingston a las 19:00 horas del centro de México. Será el debut oficial de Rafael Márquez, quien suma cuatro amistosos sin ganar; la vuelta será el martes 17 en el Estadio BBVA de Monterrey. El ganador avanza al Final Four de marzo de 2027 y obtiene boleto directo a la Copa Oro.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/11/13/seleccion-mexicana-llega-a-kingston-para-enfrentar-a-jaimaica-en-la-concacaf-nations-league/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-latin-grammy-2026-rosalia-gana-album-del-ano-con-lux-milo-j-se-lleva-g","t":"Latin Grammy 2026: Rosalía gana álbum del año con «LUX»; Milo J se lleva grabación del año y Aria Vega, mejor nuevo artista","c":"entretenimiento","f":"2026-11-13T06:41","r":"En la 27.ª entrega de los Latin Grammy, celebrada el jueves en Las Vegas, «LUX», de Rosalía, fue elegido álbum del año y «La perla», que grabó con Yahritza y Su Esencia, ganó canción del año. Milo J obtuvo grabación del año con «Niño» y Aria Vega fue reconocida como mejor nuevo artista. En los géneros de música mexicana resultaron premiados, entre otros, Grupo Frontera, Camila Fernández y Edén Muñoz.","b":"","img":"bellas","foto":"","cred":"","src":[["La Nación","https://www.lanacion.com.ar/espectaculos/musica/latin-grammy-2026-todos-los-ganadores-nid13112026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-13-ebrard-mexico-presidira-el-apec-en-2028-sheinbaum-estara-en-shenzhen-d","t":"Ebrard: México presidirá el APEC en 2028; Sheinbaum estará en Shenzhen del 17 al 19 de noviembre","c":"politica","f":"2026-11-13T06:40","r":"La presidenta viajará a la cumbre del APEC en Shenzhen, China, del 17 al 19 de noviembre; su agenda incluye una reunión bilateral con Xi Jinping, la presentación del Plan México a empresarios y un discurso ante el Consejo Consultivo Empresarial del foro. El secretario de Economía, Marcelo Ebrard, informó que México fue elegido por unanimidad para presidir el APEC en 2028 y ser sede de la cumbre de líderes; agregó que 52% de la inversión extranjera directa que llega al país proviene de economías del bloque; el funcionario permanecerá en China para dar seguimiento a temas comerciales.","b":"","img":"palacio","foto":"","cred":"","src":[["El Independiente","https://elindependiente.mx/nacional/2026/11/13/sheinbaum-viaja-a-china-para-reunion-de-alto-nivel-con-xi-jinping-no-tiene-previsto-encuentro-con-trump/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-trump-amenaza-con-duplicar-los-aranceles-a-mexico-si-no-frena-las-cara","t":"Trump amenaza con duplicar los aranceles a México si no frena las caravanas migrantes","c":"nacional","f":"2026-11-12T18:59","r":"El presidente de EU, Donald Trump, advirtió este jueves en redes sociales que los aranceles a México se duplicarán «de inmediato» si el gobierno no detiene las caravanas de migrantes. No precisó qué productos se verían afectados ni a partir de cuándo. Una caravana de unas 1,500 personas, en su mayoría centroamericanas, salió de Tapachula, Chiapas, el martes 10, según una fuente del gobierno estatal citada por Expansión.","b":"","img":"texas","foto":"","cred":"","src":[["Expansión Política","https://politica.expansion.mx/mexico/2026/11/12/trump-amenaza-duplicar-aranceles-mexico"]],"dest":true,"a":"Redacción"},{"id":"2026-11-12-sheinbaum-responde-a-trump-ninguna-caravana-ha-llegado-a-la-frontera-n","t":"Sheinbaum responde a Trump: ninguna caravana ha llegado a la frontera norte desde que él volvió a la Casa Blanca","c":"politica","f":"2026-11-12T18:58","r":"En su conferencia del jueves, la presidenta Claudia Sheinbaum dijo que desde enero de 2025 ninguna caravana ha llegado a la frontera con EU. Explicó que la que se formó en Arriaga, Chiapas, con 500 a 600 personas hoy tiene menos de 100 integrantes, y que con otra de Honduras se dialoga para su regreso. Rechazó usar la represión y afirmó que a los migrantes se les informa que no podrán cruzar y se busca su retorno seguro.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/sheinbaum-responde-a-trump-tras-amenaza-de-duplicar-aranceles-por-caravanas-migrantes-desde-que-llego-no-ha-llegado-ninguna-caravana-a-la-frontera-norte/"],["Proceso / AP","https://www.proceso.com.mx/nacional/2026/11/12/asi-respondio-sheinbaum-a-la-amenaza-de-trump-de-duplicar-los-aranceles-si-no-detiene-la-caravana-migrante-383585.html"]],"dest":true,"a":"Redacción"},{"id":"2026-11-12-sheinbaum-descarta-reunirse-con-trump-en-china-tendra-bilateral-con-xi","t":"Sheinbaum descarta reunirse con Trump en China; tendrá bilateral con Xi Jinping en el APEC de Shenzhen","c":"politica","f":"2026-11-12T18:57","r":"La presidenta dijo que no prevé un encuentro con Trump durante la cumbre del APEC y que lo más probable es verlo en Mar-a-Lago, sede del G20 en diciembre. Marcelo Ebrard detalló que del 17 al 19 de noviembre, en Shenzhen, Sheinbaum hablará ante el consejo empresarial del foro y tendrá reuniones con los líderes de China, Canadá, Australia y Vietnam. Sheinbaum dijo que la reunión con Xi no debe generar fricciones con Washington.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/12/sheinbaum-descarta-cita-con-trump-en-china-y-apunta-a-reunion-en-mar-a-lago-durante-el-g20/"],["Maya Comunicación","https://mayacomunicacion.com.mx/mananera-12-noviembre-weg-hidalgo-apec-banco-bienestar/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-12-el-gobierno-presenta-12-acciones-en-120-dias-para-consolidar-el-imss-b","t":"El gobierno presenta 12 acciones en 120 días para consolidar el IMSS-Bienestar; contratará a 19,314 trabajadores de la salud","c":"nacional","f":"2026-11-12T18:56","r":"Alejandro Svarch, director del IMSS-Bienestar, expuso en la mañanera el plan de consolidación del sistema para personas sin seguridad social. Incluye contratar a 19,314 profesionales (entre ellos 9,965 enfermeras y 2,606 especialistas), construir cinco hospitales en Michoacán, Estado de México, Guerrero, Sinaloa y Chiapas, sustituir 23 más y distribuir 100 millones de piezas de medicamentos. También prevé digitalizar el expediente en 8,812 unidades médicas.","b":"","img":"imss","foto":"","cred":"","src":[["La-Lista","https://la-lista.com/mexico/imss-bienestar-contratara-a-mas-de-19-mil-trabajadores-y-entregara-100-millones-de-medicamentos-que-cambiara-las-12-acciones-en-120-dias"]],"dest":true,"a":"Redacción"},{"id":"2026-11-12-la-brasilena-weg-invertira-250-millones-de-dolares-en-mexico-con-una-n","t":"La brasileña WEG invertirá 250 millones de dólares en México, con una nueva planta en Hidalgo","c":"economia","f":"2026-11-12T18:55","r":"El secretario de Economía, Marcelo Ebrard, anunció en la mañanera que WEG, fabricante de motores, transformadores y generadores, invertirá 250 millones de dólares entre 2026 y 2030. El plan incluye una planta en Hidalgo y, según el vicepresidente de la empresa, Daniel Marteleto Godinho, generaría unos 2,000 empleos directos y 4,000 indirectos. La inversión se vincula con la demanda de equipo para centros de datos.","b":"","img":"tech2","foto":"","cred":"","src":[["Maya Comunicación","https://mayacomunicacion.com.mx/mananera-12-noviembre-weg-hidalgo-apec-banco-bienestar/"],["Capital México","https://www.capitalmexico.com.mx/estados/weg-invertira-250-millones-de-dolares-en-hidalgo-para-fabricar-equipos-electricos-para-centros-de-datos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-sheinbaum-propone-abrir-despues-de-2027-una-discusion-nacional-sobre-f","t":"Sheinbaum propone abrir después de 2027 una discusión nacional sobre federalizar el INE","c":"politica","f":"2026-11-12T18:54","r":"La presidenta dijo en Palacio Nacional que la concentración de funciones en el INE y el futuro de los organismos electorales estatales deben debatirse a nivel nacional, pero hasta después de las elecciones de 2027. Señaló que en este momento ya no hay tiempo para proponer cambios concretos.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/sheinbaum-abrira-discusion-nacional-sobre-federalizacion-del-ine-tras-elecciones-del-2027/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-el-peso-resiste-la-amenaza-arancelaria-y-cierra-estable-en-18-61-por-d","t":"El peso resiste la amenaza arancelaria y cierra estable en 18.61 por dólar","c":"economia","f":"2026-11-12T18:53","r":"El tipo de cambio terminó el jueves en 18.61 pesos por dólar, sin variación por segundo día, según el cierre de Banxico citado por Publimetro; en la jornada se movió entre 18.56 y 18.69. Gabriela Siller, de Banco Base, atribuyó la presión a la amenaza de Trump de duplicar aranceles y a un dólar más fuerte, aunque consideró poco probable que la medida se concrete.","b":"","img":"bolsa","foto":"","cred":"","src":[["Publimetro","https://www.publimetro.com.mx/noticias/2026/11/12/trump-amenaza-aranceles-peso-resiste18-pesos-con-61-centavos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-el-brent-sube-3-3-a-95-82-dolares-despues-de-que-trump-dijo-que-eu-no","t":"El Brent sube 3.3% a 95.82 dólares después de que Trump dijo que EU no necesita un acuerdo con Irán","c":"economia","f":"2026-11-12T18:52","r":"El barril de Brent para enero ganó 3.06 dólares y cerró en 95.82 en Londres. El crudo bajó buena parte de la sesión, pero repuntó tras un mensaje de Trump en el que afirmó que su país ya no requiere un pacto de paz con Irán. Los ataques a instalaciones energéticas saudíes y las amenazas en el estrecho de Ormuz también presionaron los precios, según EFE.","b":"","img":"pemex","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/12/el-brent-sube-33-a-9582-dolares-tras-decir-trump-que-eeuu-no-necesita-pacto-con-iran/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-detienen-en-xochitepec-al-presunto-autor-material-del-asesinato-del-re","t":"Detienen en Xochitepec al presunto autor material del asesinato del regidor de Cuernavaca Gabriel Rivas Ríos","c":"seguridad","f":"2026-11-12T18:51","r":"Omar García Harfuch informó la captura de Ricardo Alejandro «N», señalado como autor material del homicidio del regidor de Morena, de 72 años, asesinado a tiros el 4 de noviembre en la colonia Ejidos de Acapantzingo. Fue ubicado en Xochitepec, Morelos, con apoyo de videos de vigilancia e inteligencia. Las autoridades siguen buscando a los demás involucrados, incluidos posibles autores intelectuales.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Político MX","https://politico.mx/2026/11/12/detienen-al-presunto-autor-del-asesinato-de-gabriel-rivas-rios-regidor-de-cuernavaca/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-capturan-en-culiacan-a-tres-presuntos-integrantes-de-los-chapitos-uno","t":"Capturan en Culiacán a tres presuntos integrantes de Los Chapitos, uno de ellos menor de edad","c":"seguridad","f":"2026-11-12T18:50","r":"Elementos del Ejército, la Guardia Nacional, la Marina y fuerzas estatales detuvieron a tres hombres armados en la colonia Lomas del Sol VII tras una denuncia anónima al 089. Les aseguraron un fusil AK-47, dos pistolas, 209 cartuchos, 165 dosis de presunta cocaína, una motocicleta y radios. Fueron puestos a disposición de la FGR en Culiacán.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/capturan-en-culiacan-a-tres-integrantes-de-los-chapitos-entre-ellos-un-menor-de-edad/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-arranca-en-guerrero-la-octava-brigada-nacional-de-busqueda-de-desapare","t":"Arranca en Guerrero la octava Brigada Nacional de Búsqueda de desaparecidos, sin la participación de la FGR","c":"estados","f":"2026-11-12T18:49","r":"Familias de la Red de Enlaces Nacionales, que agrupa a más de 140 colectivos, iniciaron búsquedas en Acapulco, Atoyac de Álvarez y Chilpancingo. Juan Carlos Trujillo Herrera dijo que hay 170 familias registradas y que la FGR canceló su participación de último momento, por lo que las familias cubrirán sus propios gastos. Aseguró que la brigada seguirá «con o sin Estado».","b":"","img":"carretera","foto":"","cred":"","src":[["MVS Noticias","https://mvsnoticias.com/nacional/estados/2026/11/12/inicia-brigada-nacional-de-busqueda-en-guerrero-sin-respaldo-de-la-fgr-753311.html"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-la-bolsa-mexicana-cae-0-27-y-corta-una-racha-de-siete-alzas-volaris-y","t":"La Bolsa mexicana cae 0.27% y corta una racha de siete alzas; Volaris y Aeroméxico, las más castigadas","c":"economia","f":"2026-11-12T18:48","r":"El S&P/BMV IPC cerró el jueves en 71,811.2 puntos, tras tres máximos históricos seguidos. Volaris retrocedió 6.34% y Aeroméxico 5.33%, mientras Actinver subió 3.74%. De 781 emisoras, 466 bajaron y 280 subieron. En el mes el índice acumula 2.81% y en el año 11.55%, según Actinver citado por EFE.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/12/la-bolsa-de-mexico-pierde-un-027-rompe-racha-de-siete-alzas-y-baja-a-718112-unidades/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-jensen-huang-renuncia-como-director-de-nvidia-colette-kress-queda-al-f","t":"Jensen Huang renuncia como director de Nvidia; Colette Kress queda al frente de forma interina","c":"tecnologia","f":"2026-11-12T18:47","r":"El cofundador de Nvidia dejó el cargo este jueves en medio del escándalo por una presunta relación con una mujer señalada por EU como espía de China y reportes de otra relación con una empleada bajo su mando. La directora de finanzas, Colette Kress, asumió como CEO interina. Las acciones llegaron a caer cerca de 10% antes de la apertura; Nvidia dijo no tener motivos para creer que se comprometieron secretos o la seguridad nacional.","b":"","img":"tech","foto":"","cred":"","src":[["El Financiero","https://www.elfinanciero.com.mx/mundo/2026/11/12/jensen-huang-ceo-de-nvidia-renuncia-tras-polemico-romance-con-espia-china/"],["BioBioChile","https://www.biobiochile.cl/noticias/economia/negocios-y-empresas/2026/11/12/la-caida-de-jensen-huang-ceo-de-nvidia-renuncia-ante-crisis-por-infidelidad-con-presunta-espia-china.shtml"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-putin-recibe-dos-horas-a-witkoff-y-kushner-sin-acuerdo-de-paz-habra-nu","t":"Putin recibe dos horas a Witkoff y Kushner sin acuerdo de paz; habrá nueva ronda con europeos en la mesa","c":"internacional","f":"2026-11-12T18:46","r":"El presidente ruso se reunió en el Kremlin con los enviados de Trump tras las pláticas de Abu Dabi. Putin rechazó la presencia de tropas europeas en Ucrania después de un eventual alto el fuego. Witkoff confirmó que se pactó otra ronda en la que participarán representantes europeos; los enviados viajarían después a Dublín para informar a Volodímir Zelenski.","b":"","img":"ultimahora","foto":"","cred":"","src":[["ContraPunto","https://www.contrapunto.com.sv/putin-recibe-a-enviados-de-trump-avances-sin-acuerdo-de-paz/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-derrumbe-de-un-edificio-en-brooklyn-deja-al-menos-ocho-muertos-y-19-he","t":"Derrumbe de un edificio en Brooklyn deja al menos ocho muertos y 19 heridos","c":"internacional","f":"2026-11-12T18:45","r":"Un inmueble de tres pisos se vino abajo el miércoles cerca de las 16:00 horas y cayó sobre una obra en construcción contigua, en Nueva York. Al menos siete de los heridos son menores. El alcalde Zohran Mamdani confirmó el saldo, y la jefa de Bomberos, Lillian Bonsignore, dijo que más de 250 rescatistas trabajan en la zona sin saber cuántas personas siguen atrapadas.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Crónica del Quindío","https://cronicadelquindio.com/actualidad/mundo/derrumbe-edificio-brooklyn-nueva-york-ocho-muertos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-banco-del-bienestar-presenta-su-app-para-enviar-dinero-y-pagar-con-qr","t":"Banco del Bienestar presenta su app para enviar dinero y pagar con QR sin comisiones","c":"economia","f":"2026-11-12T18:44","r":"El director del banco, Víctor Manuel Lamoyi Bocanegra, presentó en la mañanera la nueva aplicación, que permite transferencias, envíos y cobros digitales desde el celular sin comisión, así como pagos en comercios con código QR. Fue desarrollada con la Agencia de Transformación Digital, Hacienda y Banxico. El banco tiene más de 3,100 sucursales en el país.","b":"","img":"tech2","foto":"","cred":"","src":[["Maya Comunicación","https://mayacomunicacion.com.mx/mananera-12-noviembre-weg-hidalgo-apec-banco-bienestar/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-nuevo-leon-despliega-mas-de-1-500-unidades-y-nueve-helicopteros-para-e","t":"Nuevo León despliega más de 1,500 unidades y nueve helicópteros para el Buen Fin","c":"estados","f":"2026-11-12T18:43","r":"El gobernador Samuel García arrancó el operativo «Buen Fin Seguro 2026», con 1,200 patrullas de Fuerza Civil, más de 200 camionetas, vehículos blindados, nueve helicópteros y dos aeronaves Black Hawk, en coordinación con policías municipales y la Guardia Nacional. Se espera la participación de más de 36 mil comercios y una derrama de 20 mil millones de pesos en el estado.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Quadratín Nuevo León","https://nuevoleon.quadratin.com.mx/seguridad/despliega-nuevo-leon-mas-de-mil-500-unidades-por-el-buen-fin-2026/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-brugada-lanza-casa-ecologica-356-millones-de-pesos-para-captar-lluvia","t":"Brugada lanza Casa Ecológica: 356 millones de pesos para captar lluvia y calentadores solares en hogares","c":"cdmx","f":"2026-11-12T18:42","r":"La jefa de Gobierno arrancó el programa en Santa Rosa Xochiac, Álvaro Obregón, donde 10 mil viviendas recibirán ecotecnias. Se instalarán 6,500 sistemas de captación de agua de lluvia, con capacidad de hasta 312 millones de litros al año, y 9,500 calentadores solares que podrían ahorrar a cada familia al menos 5 mil pesos anuales en gas.","b":"","img":"zocalo","foto":"","cred":"","src":[["Quadratín","https://mexico.quadratin.com.mx/lanza-brugada-programa-casa-ecologica-con-inversion-de-356-mdp/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-un-juez-anula-la-orden-de-aprehension-contra-vadhir-derbez-la-fiscalia","t":"Un juez anula la orden de aprehensión contra Vadhir Derbez; la Fiscalía capitalina la impugna","c":"entretenimiento","f":"2026-11-12T18:41","r":"Un juez federal concedió un amparo al actor al considerar que la orden por presunto abuso sexual violaba el debido proceso, por lo que, según su defensa, no tiene ninguna orden vigente. La Fiscalía de la CDMX presentó un recurso de revisión que resolverá un tribunal colegiado. Su abogado, Enrique González Casanova, dijo que el actor está tranquilo y que denunciaron ante la FGR un presunto intento de extorsión.","b":"","img":"estudio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/abogados-de-vadhir-derbez-aclaran-por-que-no-existe-orden-de-aprehension-activa-en-su-contra/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-liga-mx-femenil-america-tigres-y-rayadas-llegan-con-ventaja-a-la-vuelt","t":"Liga MX Femenil: América, Tigres y Rayadas llegan con ventaja a la vuelta de cuartos; Chivas y Juárez empataron","c":"deportes","f":"2026-11-12T18:40","r":"En la ida, América goleó 3-0 a Toluca, Tigres ganó 3-2 a Pumas, Rayadas venció 1-0 a Pachuca y Juárez y Chivas igualaron 0-0. La vuelta se jugará el sábado 14 (Tigres-Pumas a las 17:00 y Chivas-Juárez a las 21:00) y el domingo 15 (Rayadas-Pachuca a las 19:00 y Toluca-América a las 21:10), hora del centro.","b":"","img":"estadio","foto":"","cred":"","src":[["Grupo Animal","https://grupoanimal.mx/deportes/liga-mx-femenil-apertura-2026-resultados-ida-cuartos-de-final"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-renuncia-el-hijo-de-guadalupe-taddei-como-secretario-particular-de-dur","t":"Renuncia el hijo de Guadalupe Taddei como secretario particular de Durazo tras aparecer en la lista de cuentas bloqueadas por la UIF","c":"politica","f":"2026-11-12T07:10","r":"Luis Rogelio Piñeda Taddei dejó la noche del miércoles su cargo en el gobierno de Sonora, horas después de conocerse que su nombre figura en el bloqueo de cuentas de la UIF contra 40 personas y empresas ligadas a proveedores electorales. La medida incluye a la expresidenta del INE, otro familiar, ocho exfuncionarios del instituto y empresarios con contratos por más de 2,500 millones de pesos. Taddei renunció al INE el 26 de octubre.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/hijo-de-guadalupe-taddei-renuncia-como-secretario-particular-de-alfonso-durazo-tras-bloqueo-de-cuentas-de-la-uif/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-12-eu-aviso-a-mexico-unos-dias-antes-de-la-captura-del-juez-benitez-alcan","t":"EU avisó a México «unos días antes» de la captura del juez Benítez Alcántara en Colombia, dice Sheinbaum","c":"nacional","f":"2026-11-12T07:09","r":"La presidenta afirmó que el gobierno conoció la orden de aprehensión del Departamento de Justicia poco antes de la detención del exjuez federal Luis Benítez Alcántara, de 49 años, ocurrida el 1 de noviembre en Bogotá, y pidió al Gabinete de Seguridad y al Poder Judicial informar del caso. EU lo acusa de recibir unos 2 millones de dólares para liberar a Andrew Clark, operador de Ryan Wedding. Su defensa se opondrá a la extradición y el Tribunal de Disciplina Judicial abrió una investigación.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/11/eeuu-notifico-a-mexico-unos-dias-antes-sobre-la-detencion-del-juez-mexicano-benitez-alcantara-en-colombia/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-12-ataque-contra-una-base-policial-en-tepalcatepec-deja-un-agente-muerto","t":"Ataque contra una base policial en Tepalcatepec deja un agente muerto; suspenden clases y labores municipales","c":"seguridad","f":"2026-11-12T07:08","r":"La noche del miércoles, hombres armados que viajaban en al menos tres camionetas dispararon contra la base de la Policía Municipal en El Toril, Tepalcatepec, Michoacán; testigos dijeron que los agresores se identificaron como del CJNG. Murió un policía y hubo al menos dos heridos. Guardia Civil, Ejército y Guardia Nacional desplegaron un operativo por tierra y aire, y el ayuntamiento suspendió clases y labores hasta nuevo aviso.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/cjng-ataca-base-policial-en-tepalcatepec-y-deja-un-muerto-suspenden-clases-y-labores-en-ayuntamiento/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-12-el-frente-frio-5-traera-lluvias-intensas-en-veracruz-puebla-y-oaxaca-y","t":"El frente frío 5 traerá lluvias intensas en Veracruz, Puebla y Oaxaca y descenso de temperatura en el centro y norte","c":"nacional","f":"2026-11-12T07:07","r":"El Servicio Meteorológico Nacional prevé para este jueves lluvias intensas puntuales en Veracruz, Puebla y Oaxaca, fuertes a muy fuertes en el noreste, oriente y sureste, y fuertes en la península de Yucatán. Habrá rachas de 50 a 70 km/h en las costas de Tamaulipas y Veracruz y en el istmo de Tehuantepec, y bajará la temperatura por la tarde en el norte, noreste, oriente y centro. En la capital rige alerta amarilla por bajas temperaturas.","b":"","img":"lluvia","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/en-vivo-clima-cdmx-y-resto-de-mexico-hoy-12-de-noviembre-frente-frio-5-provocara-lluvias-intensas-en-14-estados/"],["Uno TV","https://www.unotv.com/clima/clima-mexico-hoy-12-de-noviembre-2026-frente-frio-5-bajara-la-temperatura-y-causara-lluvias-en-todo-el-pais/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-12-sheinbaum-pide-que-la-asf-y-si-es-necesario-la-fgr-investiguen-al-ine","t":"Sheinbaum pide que la ASF y, si es necesario, la FGR investiguen al INE; Gobernación alista iniciativa sobre Talleres Gráficos","c":"politica","f":"2026-11-12T07:06","r":"La presidenta acusó a la oposición de querer desacreditar las elecciones de 2027 y pidió que la Auditoría Superior de la Federación investigue las irregularidades en el INE, con la FGR si hace falta. Informó que Rosa Icela Rodríguez presentará en uno o dos días una iniciativa para fortalecer Talleres Gráficos, que ampliaría su consejo y sumaría a la UNAM, el Tec y el IPN como observadores. Sobre Guadalupe Taddei, dijo no tener información de que haya salido del país.","b":"","img":"ine","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/11/la-mananera-de-la-presidenta-claudia-sheinbaum-hoy-miercoles-11-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-suspenden-la-audiencia-de-el-r2-porque-no-puede-mantenerse-consciente","t":"Suspenden la audiencia de «El R2» porque no puede mantenerse consciente tras su cirugía; los otros 20 detenidos comparecen en Puente Grande","c":"seguridad","f":"2026-11-12T07:05","r":"Un juez federal suspendió, sin nueva fecha, la audiencia inicial de Rafael Álvarez Ayala, «El R2», señalado como líder de Los Rs, brazo armado del CJNG, quien sigue internado en el Antiguo Hospital Civil de Guadalajara. El médico informó que por los analgésicos no puede permanecer consciente más de una hora. Las otras 20 personas detenidas en el operativo sí se presentaron en el penal de Puente Grande.","b":"","img":"jalisco","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/suspenden-audiencia-virtual-del-r2-por-presentar-somnolencia-tras-cirugia/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-el-peso-cierra-sin-cambios-en-18-62-por-dolar-y-la-bolsa-suma-su-terce","t":"El peso cierra sin cambios en 18.62 por dólar y la Bolsa suma su tercer máximo histórico seguido","c":"economia","f":"2026-11-12T07:04","r":"El tipo de cambio terminó el miércoles en 18.62 pesos por dólar, igual que el martes, según el cierre de Banxico citado por EFE, pese a que el dólar se fortaleció en los mercados internacionales; en el día osciló entre 18.56 y 18.69. El S&P/BMV IPC ganó 0.16% y cerró en 72,006.05 puntos, nuevo récord, con siete alzas consecutivas y un avance de 11.94% en el año.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/11/la-bolsa-mexicana-gana-un-016-y-se-apunta-su-tercer-maximo-historico-consecutivo/"],["Publimetro","https://www.publimetro.com.mx/noticias/2026/11/12/dolar-gana-fuerza-peso-resiste-cierre-18-pesos-con-61-centavos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-sheinbaum-pide-a-los-estados-frenar-los-taxis-irregulares-en-los-aerop","t":"Sheinbaum pide a los estados frenar los taxis irregulares en los aeropuertos y reconoce tarifas altas","c":"nacional","f":"2026-11-12T07:03","r":"En la mañanera del miércoles, la presidenta dijo que corresponde a los gobiernos estatales intervenir ante los taxis que operan fuera de la norma en las terminales aéreas, y admitió que hay «tarifas altas» en el transporte que sale de los aeropuertos. Añadió que la Subsecretaría de Transporte de la SICT negocia mejores precios con los taxistas, sin dar fecha. En Guadalajara, el GAP reporta al menos una denuncia diaria por fraudes, robos o extorsiones.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/sheinbaum-pide-a-los-estados-atender-taxis-pirata-en-aeropuertos-y-advierte-por-las-altas-tarifas/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-la-actividad-industrial-cae-1-4-en-septiembre-su-peor-mes-desde-octubr","t":"La actividad industrial cae 1.4% en septiembre, su peor mes desde octubre de 2024","c":"economia","f":"2026-11-12T07:02","r":"Según el Inegi, la producción industrial retrocedió 1.4% frente a agosto en cifras ajustadas por estacionalidad y cortó tres meses al alza. La construcción bajó 2.0% y las manufacturas 1.7% en el mes, mientras la minería subió 0.4% y la electricidad 1.4%. En comparación con septiembre de 2025, la industria todavía crece 1.4%, impulsada por la construcción (6.4%).","b":"","img":"pemex","foto":"","cred":"","src":[["Alto Nivel","https://www.altonivel.com.mx/actividad-industrial-en-mexico-cae-1-4-en-septiembre-e-interrumpe-tres-meses-al-alza/"],["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/11/la-produccion-industrial-de-mexico-se-eleva-un-13-interanual-en-septiembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-detienen-a-14-presuntos-integrantes-del-cartel-de-sinaloa-en-benemerit","t":"Detienen a 14 presuntos integrantes del Cártel de Sinaloa en Benemérito de las Américas, Chiapas; dos serían líderes regionales","c":"seguridad","f":"2026-11-12T07:01","r":"Un operativo de Defensa, Marina, SSPC, FGR, Guardia Nacional y la policía estatal en el municipio chiapaneco, cerca de la frontera con Guatemala, terminó con 14 detenidos. Les aseguraron 12 armas largas, 97 cargadores, 882 cartuchos y 17 chalecos tácticos con placas balísticas. Las autoridades no difundieron los nombres de los dos presuntos jefes.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/11/fuerzas-federales-detienen-a-dos-lideres-del-cartel-de-sinaloa-en-chiapas-hay-catorce-arrestados/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-detienen-en-tijuana-a-beto-leyva-senalado-de-coordinar-el-trafico-de-p","t":"Detienen en Tijuana a «Beto Leyva», señalado de coordinar el tráfico de personas hacia EU para el Cártel de Sinaloa","c":"estados","f":"2026-11-12T07:00","r":"Elementos de la Defensa, la Guardia Nacional y la FGR capturaron a José Alberto «N» durante cateos ordenados por un juez, informó Omar García Harfuch. Las autoridades lo ubican en el círculo cercano de los hermanos Arzate, de una facción aliada de Los Mayos, y lo señalan de mover migrantes hacia San Diego, secuestrarlos para cobrar a sus familias y de lavado de dinero. Tiene una orden de arresto vigente en Estados Unidos.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/11/capturan-en-tijuana-a-beto-leyva-coordinador-del-trafico-de-personas-hacia-eeuu-para-el-cartel-de-sinaloa/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-witkoff-y-kushner-llegan-a-moscu-para-reunirse-con-putin-tras-las-plat","t":"Witkoff y Kushner llegan a Moscú para reunirse con Putin tras las pláticas de Abu Dabi","c":"internacional","f":"2026-11-12T06:59","r":"Los enviados de Estados Unidos aterrizaron en el aeropuerto de Vnukovo y este jueves por la mañana, hora de Moscú, se reúnen con Vladímir Putin, según el asesor del Kremlin Yuri Ushakov. Llevarán al presidente ruso lo tratado el martes y miércoles en Abu Dabi, donde Rusia y Ucrania retomaron el diálogo tras nueve meses y acordaron un intercambio de prisioneros a gran escala. Sobre si hay una salida diplomática más cerca, Witkoff respondió: «Espero que sí».","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/12/witkoff-y-kushner-llegan-a-moscu-para-abordar-con-putin-posibles-vias-para-acabar-la-guerra-en-ucrania/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-las-afores-suman-mas-de-700-mil-millones-de-pesos-en-plusvalias-de-ene","t":"Las Afores suman más de 700 mil millones de pesos en plusvalías de enero a octubre","c":"economia","f":"2026-11-12T06:58","r":"Los ahorros para el retiro acumularon ganancias por más de 700 mil millones de pesos en los primeros diez meses del año, de acuerdo con cifras de la Consar, aunque hubo meses con minusvalías. Solo en octubre las plusvalías llegaron a 209 mil 427 millones de pesos, según la portada de El Economista del miércoles.","b":"","img":"bolsa","foto":"","cred":"","src":[["Tiempo","https://www.tiempo.com.mx/economia/700-mil-millones-acumulan-plusvalias-de-afores-en-10-meses-noviembre-2026/"],["Uno TV","https://unotv.com/nacional/las-de-hoy-11-de-noviembre-de-2026"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-la-fgr-asegura-en-tonaya-jalisco-mas-de-32-mil-envases-de-una-presunta","t":"La FGR asegura en Tonaya, Jalisco, más de 32 mil envases de una presunta fábrica de bebidas falsificadas","c":"estados","f":"2026-11-12T06:57","r":"En cuatro inmuebles de Tonaya, la Fiscalía General de la República detuvo a tres personas y aseguró más de 32 mil envases esféricos que corresponderían a la marca BuzzBallz, además de maquinaria para llenar y sellar, documentos, equipos electrónicos y dinero. La FGR estima que los bienes superan el millón de pesos, cifra que dependerá de los peritajes. La investigación se centra en la posible falsificación de la forma del envase, registrada como marca tridimensional.","b":"","img":"jalisco","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/estados/2026/11/11/fgr-desmantela-presunta-fabrica-de-bebidas-alcoholicas-falsas-en-jalisco/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-el-gobernador-de-queretaro-veta-por-segunda-vez-la-ley-de-identidad-de","t":"El gobernador de Querétaro veta por segunda vez la Ley de Identidad de Género aprobada por el Congreso","c":"estados","f":"2026-11-12T06:56","r":"Mauricio Kuri González vetó de nuevo la ley, que permitiría a personas adultas cambiar su acta de nacimiento conforme a su identidad de género mediante un trámite en el Registro Civil, sin juicio. La diputada federal de Movimiento Ciudadano Laura Ballesteros calificó los vetos como posibles actos discriminatorios y recordó que Querétaro es una de las ocho entidades sin esta legislación. Colectivos trans buscan que la Suprema Corte se pronuncie.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/vetan-por-segunda-vez-ley-de-identidad-de-genero-en-queretaro-laura-ballesteros-acusa-a-mauricio-kuri-de-discriminacion/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-unos-tres-millones-de-personas-reciben-a-leon-xiv-en-las-calles-de-lim","t":"Unos tres millones de personas reciben a León XIV en las calles de Lima y Callao","c":"internacional","f":"2026-11-12T06:55","r":"El papa aterrizó el miércoles poco después de las 17:00 horas en la Base Aérea del Callao y recorrió en caravana unos 10 kilómetros hasta el Centro Histórico de Lima. Vatican News, con datos de autoridades locales, calculó en alrededor de tres millones a las personas que salieron a saludarlo. Su gira por Perú incluye Chiclayo, donde fue obispo, con una misa en las Pampas de Pimentel el viernes 13, además de Cusco y Pucallpa.","b":"","img":"vaticano","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/peru/2026/11/12/el-papa-es-peruano-tres-millones-de-personas-salieron-a-las-calles-para-darle-la-bienvenida-a-leon-xiv/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-un-ataque-israeli-contra-el-hospital-nasser-en-el-sur-de-gaza-deja-al","t":"Un ataque israelí contra el hospital Nasser, en el sur de Gaza, deja al menos seis muertos","c":"internacional","f":"2026-11-12T06:54","r":"Israel atacó de madrugada el hospital Nasser, en el sur de la Franja de Gaza. El saldo preliminar es de al menos seis personas muertas y unas 30 heridas, según el resumen de la agencia EFE publicado este jueves.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae / EFE","https://www.infobae.com/america/agencias/2026/11/12/jueves-12-de-noviembre-de-2026-0800-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-sheinbaum-recibe-a-greg-brockman-cofundador-de-openai-para-hablar-de-i","t":"Sheinbaum recibe a Greg Brockman, cofundador de OpenAI, para hablar de inteligencia artificial en la salud","c":"tecnologia","f":"2026-11-12T06:53","r":"La presidenta se reunió el miércoles 11 en Palacio Nacional con Greg Brockman, presidente y cofundador de OpenAI, y parte de su equipo. Según informó en redes sociales, conversaron sobre los posibles beneficios de la inteligencia artificial para mejorar la atención médica. No se anunciaron convenios, inversiones ni proyectos concretos.","b":"","img":"tech","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/sheinbaum-recibe-a-greg-brockman-cofundador-de-openai-dialogan-sobre-inteligencia-artificial-y-salud/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-muere-a-los-82-anos-la-actriz-regina-torne-la-mama-elena-de-como-agua","t":"Muere a los 82 años la actriz Regina Torné, la Mamá Elena de «Como agua para chocolate»","c":"entretenimiento","f":"2026-11-12T06:52","r":"La primera actriz falleció el miércoles 11 de noviembre en su casa de la Ciudad de México; la causa de la muerte no se ha dado a conocer. Torné es recordada sobre todo por interpretar a Mamá Elena en la película «Como agua para chocolate». En 2014 se retiró de los escenarios, se mudó a Puebla y abrió una academia de artes escénicas.","b":"","img":"bellas","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/12/murio-regina-torne-asi-fue-el-crimen-que-cometio-su-unica-hija-y-que-la-condeno-a-35-anos-de-prision/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-12-el-tri-viaja-este-jueves-a-kingston-para-la-ida-de-cuartos-de-la-natio","t":"El Tri viaja este jueves a Kingston para la ida de cuartos de la Nations League ante Jamaica","c":"deportes","f":"2026-11-12T06:51","r":"La Selección Mexicana de Rafael Márquez concentró desde el domingo en la Riviera Maya y este jueves 12 se traslada a Jamaica. La ida de cuartos de final de la Liga de Naciones de la Concacaf será el sábado 14 a las 19:00 horas, tiempo del centro de México, en el National Stadium de Kingston; la vuelta, el martes 17 a las 20:30 en el Estadio de Monterrey. Está en juego el pase al Final Four. Entre los 28 convocados destacan Julián Quiñones, con 40 goles en 2026, el capitán Johan Vásquez y el regreso de Rodrigo Huescas tras un año lesionado.","b":"","img":"estadio","foto":"","cred":"","src":[["Claro Sports","https://www.clarosports.com/futbol/seleccion-mexicana/quien-llega-mejor-al-mexico-vs-jamaica-los-28-convocados-de-rafa-marquez-bajo-la-lupa/"],["Récord","https://www.record.com.mx/historia/fecha-fifa-noviembre-2026-cuales-partidos-mas-atractivos-2026110920442663960"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-la-camara-de-diputados-aprueba-el-presupuesto-2027-de-10-6-billones-tr","t":"La Cámara de Diputados aprueba el Presupuesto 2027 de 10.6 billones tras casi 20 horas; no pasó ninguna de las 1,760 reservas","c":"politica","f":"2026-11-11T06:59","r":"A las 4:28 de la madrugada de este miércoles, el pleno avaló en lo particular el Presupuesto de Egresos 2027 por 352 votos contra 130, con un gasto neto de 10 billones 636 mil millones de pesos. Los seis grupos presentaron 1,760 reservas y todas fueron rechazadas; el INE queda con 36,274 millones, 6 mil millones menos de lo pedido, y se reasignaron 6,500 millones a los acueductos de Guadalajara. El documento pasa al Ejecutivo para su publicación y entrará en vigor el 1 de enero.","b":"","img":"senado","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/11/tras-casi-20-horas-camara-de-diputados-aprueba-presupuesto-2027-y-pasa-al-ejecutivo/"],["Excélsior","https://www.excelsior.com.mx/nacional/diputados-aprueban-particular-pef-2027-maratonica-sesion-20-horas"]],"dest":true,"a":"Redacción"},{"id":"2026-11-11-los-homicidios-fueron-la-primera-causa-de-muerte-entre-personas-de-25","t":"Los homicidios fueron la primera causa de muerte entre personas de 25 a 44 años en 2025, según el Inegi","c":"nacional","f":"2026-11-11T06:58","r":"De acuerdo con las Estadísticas de Defunciones Registradas 2025 del Inegi, 14,808 personas de 25 a 44 años murieron por homicidio, por encima de cualquier enfermedad en ese grupo de edad. La tasa nacional bajó de 25.8 a 22.6 homicidios por cada 100 mil habitantes y el país registró 792,187 defunciones, 3.4% menos que en 2024; las enfermedades del corazón, la diabetes y los tumores siguen como principales causas generales. Colima tuvo la tasa más alta, con 92.6 por cada 100 mil habitantes.","b":"","img":"palacio","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/11/son-primera-causa-de-muerte-entre-grupo-de-25-a-44-anos-segun-inegi/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-11-cancelan-el-traslado-de-el-r2-a-puente-grande-por-su-estado-de-salud-u","t":"Cancelan el traslado de «El R2» a Puente Grande por su estado de salud; un juez amplía a 96 horas el plazo para los 20 detenidos","c":"seguridad","f":"2026-11-11T06:57","r":"Fuerzas federales llegaron la noche del martes al Antiguo Hospital Civil de Guadalajara para llevar a Rafael Álvarez Ayala, «El R2», al penal de Puente Grande, pero el operativo se suspendió por su condición médica; permanece en terapia intensiva tras ser operado por heridas de bala. A petición de la FEMDO, un juez extendió de 48 a 96 horas el término para resolver la situación de los detenidos con él en Zapopan, entre ellos empleados del restaurante y músicos del grupo Los Arras. El plazo vence la noche del jueves 12 de noviembre.","b":"","img":"jalisco","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/11/cancelan-traslado-del-r2-a-puente-grande-por-su-estado-de-salud-continua-hospitalizado/"],["Infobae","https://www.infobae.com/mexico/2026/11/11/amplian-a-96-horas-el-plazo-para-definir-la-situacion-legal-de-los-20-detenidos-junto-al-r2/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-11-sheinbaum-asegura-que-la-relacion-con-eu-no-ha-cambiado-tras-las-elecc","t":"Sheinbaum asegura que la relación con EU no ha cambiado tras las elecciones intermedias y reitera que México no acepta llamar terroristas a los cárteles","c":"politica","f":"2026-11-11T06:56","r":"En su conferencia del martes, la presidenta dijo que nada indica un cambio en la cooperación bilateral, pese a los resultados electorales en Estados Unidos y los ajustes en el equipo de Donald Trump. Señaló que mantiene comunicación con la Defensa, la Marina, el gabinete de seguridad, la cancillería y la embajada, bajo el principio de «coordinación sin subordinación». Reiteró que México atiende a los grupos criminales como delincuencia organizada y no comparte la designación de terrorismo.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/10/sheinbaum-descarta-cambio-en-relacion-con-eeuu-tras-elecciones-defiende-politica-contra-clasificacion-de-narcos-mexicanos-como-terroristas/"]],"dest":true,"a":"Redacción"},{"id":"2026-11-11-la-fiscalia-de-chihuahua-niega-que-maru-campos-supiera-de-la-presunta","t":"La Fiscalía de Chihuahua niega que Maru Campos supiera de la presunta participación de la CIA en un operativo estatal","c":"estados","f":"2026-11-11T06:55","r":"Tras un reportaje de The New York Times que cita al exfiscal Guillermo Zuany Portillo, la Fiscalía General del Estado afirmó que ninguna de las 150 declaraciones de 86 personas en la causa abierta por el operativo de abril menciona a la gobernadora. En esa operación contra un laboratorio en la sierra murieron dos funcionarios mexicanos y, según el diario, dos agentes estadounidenses al caer su camioneta a un barranco. La dependencia reconoció que los extranjeros eran estadounidenses, pero no precisó a qué agencia pertenecían.","b":"","img":"chihuahua","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/11/fiscalia-de-chihuahua-niega-que-la-gobernadora-maru-campos-supiera-de-la-presunta-operacion-de-la-cia-en-el-estado/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-el-peso-abre-el-miercoles-en-18-61-por-dolar-y-recupera-0-1-tras-la-ca","t":"El peso abre el miércoles en 18.61 por dólar y recupera 0.1% tras la caída del martes","c":"economia","f":"2026-11-11T06:54","r":"El tipo de cambio inició la jornada en un promedio de 18.61 pesos por dólar, frente a 18.63 del cierre previo, con datos de Dow Jones citados por Infobae. En la semana el dólar retrocede 0.08%, aunque en comparación anual sube 2.42%. Los analistas consultados por Banxico prevén un cierre de año de entre 20.00 y 20.50 pesos.","b":"","img":"bolsa","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/11/dolar-hoy-en-mexico-cotizacion-de-apertura-del-11-de-noviembre/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-el-brent-repunta-a-91-71-dolares-por-los-ataques-a-buques-en-el-estrec","t":"El Brent repunta a 91.71 dólares por los ataques a buques en el estrecho de Ormuz","c":"economia","f":"2026-11-11T06:53","r":"El crudo de referencia europeo subía 0.2% a media mañana en Europa, hasta 91.71 dólares por barril, y el WTI avanzaba 0.1% a 86.12 dólares. Las expectativas de desescalada con Irán se moderaron después de que el Ejército iraní informara que un petrolero chocó con una mina y se incendió en Ormuz, y de que la Guardia Revolucionaria reportara tres buques en llamas el martes. Por ese paso circula cerca de una quinta parte del petróleo mundial.","b":"","img":"pemex","foto":"","cred":"","src":[["Euronews","https://es.euronews.com/2026/11/11/el-petroleo-sube-mientras-inversores-vigilan-ataques-en-el-estrecho-de-ormuz"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-termina-en-menos-de-dos-horas-la-segunda-jornada-en-abu-dabi-entre-rus","t":"Termina en menos de dos horas la segunda jornada en Abu Dabi entre Rusia, Ucrania y EU; se habla de un canje de hasta 1,500 prisioneros por bando","c":"internacional","f":"2026-11-11T06:52","r":"La reunión trilateral del miércoles, encabezada por Vladímir Medinski, Rustem Umérov y los enviados Steve Witkoff y Jared Kushner, duró poco menos de dos horas, según TASS. Zelenski mencionó un posible intercambio de entre mil y 1,500 cautivos por lado, aunque ninguno de los gobiernos lo ha confirmado. Ucrania propuso treguas parciales o un alto el fuego total, mientras Moscú insiste en el retiro ucraniano de Donetsk; asesores de Alemania, Francia, Reino Unido e Italia se reunieron aparte con ucranianos y estadounidenses.","b":"","img":"ultimahora","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/america/mundo/2026/11/11/la-segunda-jornada-del-dialogo-entre-eeuu-rusia-y-ucrania-en-abu-dhabi-concluyo-tras-menos-de-dos-horas-de-reunion/"],["ABC Color / EFE","https://www.abc.com.py/internacionales/2026/11/11/comienza-en-abu-dabi-la-segunda-reunion-a-tres-entre-rusia-ucrania-y-eeuu/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-un-tribunal-rechaza-el-recurso-de-hernan-bermudez-requena-para-frenar","t":"Un tribunal rechaza el recurso de Hernán Bermúdez Requena para frenar una posible extradición a EU","c":"seguridad","f":"2026-11-11T06:51","r":"El Segundo Tribunal Colegiado en Materia Penal del Estado de México confirmó por unanimidad el desechamiento del amparo del exsecretario de Seguridad de Tabasco, señalado como líder de La Barredora. Los magistrados concluyeron que no hay prueba de una solicitud formal de extradición de Estados Unidos, por lo que se trata de un acto futuro e incierto. Bermúdez Requena sigue en el penal del Altiplano, donde enfrenta cargos estatales y federales.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/10/tribunal-rechaza-recurso-de-hernan-bermudez-requena-para-frenar-posible-extradicion-a-estados-unidos/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-vinculan-a-proceso-a-el-panda-senalado-como-lider-regional-del-cjng-en","t":"Vinculan a proceso a «El Panda», señalado como líder regional del CJNG en el sur de Veracruz, por desaparición y homicidio de tres personas","c":"seguridad","f":"2026-11-11T06:50","r":"Un juez de control dictó prisión preventiva a Samuel de la Cruz Anaya, detenido el 3 de noviembre en Coatzacoalcos, a solicitud de la Fiscalía General de Veracruz. Se le imputan desaparición cometida por particulares y homicidio doloso calificado; las investigaciones se concentraron en Jáltipan, Cosoleacaque y Minatitlán. Por cada homicidio calificado podría recibir hasta 70 años de prisión.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/11/procesan-a-el-panda-lider-regional-del-cjng-en-veracruz-por-la-desaparicion-y-homicidio-de-tres-victimas/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-la-senadora-karina-ruiz-de-morena-pide-licencia-tras-18-faltas-consecu","t":"La senadora Karina Ruiz, de Morena, pide licencia tras 18 faltas consecutivas; despacha desde Arizona","c":"politica","f":"2026-11-11T06:49","r":"La legisladora plurinominal, presentada como la primera senadora migrante, solicitó licencia del 10 de noviembre al 15 de diciembre sin explicar los motivos, luego de no acudir al Senado en todo el periodo ordinario. Su bancada le había pedido separarse del cargo por exceder las inasistencias permitidas. La panista Verónica Rodríguez criticó que Morena tolerara las ausencias por más de dos meses.","b":"","img":"senado","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/mexico/2026/11/11/senadora-migrante-pide-licencia-por-un-mes-tras-2-meses-de-faltas/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-ernestina-godoy-y-la-oficina-de-la-onu-contra-la-droga-revisan-un-proy","t":"Ernestina Godoy y la oficina de la ONU contra la droga revisan un proyecto para destruir precursores de drogas sintéticas","c":"nacional","f":"2026-11-11T06:48","r":"La fiscal general se reunió en las oficinas de la FGR en Santa Fe con Stacy de la Torre, jefa de la UNODC en México, para identificar áreas de cooperación técnica dentro del Plan Estratégico de Procuración de Justicia 2026-2029. Revisaron un proyecto sobre acceso a laboratorios, manejo de evidencia y trazabilidad para eliminar químicos asegurados en centros clandestinos. No se anunciaron acuerdos concretos; ambas partes intercambiaron propuestas.","b":"","img":"palacio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/11/ernestina-godoy-se-reune-con-la-onu-para-reforzar-la-lucha-contra-las-drogas-sinteticas-en-mexico/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-el-comisionado-de-juchitan-amenaza-con-renunciar-si-no-lo-respaldan-pa","t":"El comisionado de Juchitán amenaza con renunciar si no lo respaldan para depurar una nómina de 1,867 personas","c":"estados","f":"2026-11-11T06:47","r":"Francisco Vásquez Jiménez, designado por el gobernador Salomón Jara tras la desaparición de poderes que siguió a la detención del alcalde Miguel Sánchez Altamirano en septiembre, dijo que encontró una nómina de unos 17 millones de pesos al mes sin registros claros de asistencia ni funciones. Pidió apoyo estatal y federal para seguir con los recortes y aseguró que no negociará plazas a cambio de respaldo político.","b":"","img":"carretera","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/11/comisionado-de-juchitan-amenaza-con-dejar-el-cargo-si-no-lo-respaldan-para-depurar-nomina-irregular-con-presuntos-aviadores/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-el-aifa-ofrece-350-salidas-diarias-de-autobus-y-mas-de-4-200-cajones-d","t":"El AIFA ofrece 350 salidas diarias de autobús y más de 4,200 cajones de estacionamiento, pero los usuarios aún no conocen sus opciones","c":"economia","f":"2026-11-11T06:46","r":"La terminal terrestre del aeropuerto Felipe Ángeles opera con 18 empresas de autobuses, cerca de 300 taxis, tres arrendadoras y el ramal del tren desde Buenavista, con un costo de 10 pesos. La extensión de la Línea 1 del Mexibús lo conecta con Ojo de Agua y Ciudad Azteca. Andrés Arias, subdirector de Servicios Terrestres, reconoció que falta difusión para que los pasajeros conozcan estas alternativas.","b":"","img":"metrobus","foto":"","cred":"","src":[["La Razón","https://www.razon.com.mx/negocios/2026/11/11/amplia-aifa-conectividad-con-red-multimodal-de-transporte/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-repartidores-danan-el-acceso-de-un-edificio-en-la-del-valle-tras-denun","t":"Repartidores dañan el acceso de un edificio en la Del Valle tras denunciar que un vecino amenazó con un arma a un compañero","c":"cdmx","f":"2026-11-11T06:45","r":"La noche del martes, trabajadores de plataformas de entrega bloquearon el Eje 8 Sur en la alcaldía Benito Juárez y derribaron la puerta de un conjunto habitacional, además de dañar la caseta de vigilancia, para exigir una disculpa. La Secretaría de Seguridad Ciudadana envió policías a dialogar y dijo que coordinará con la Fiscalía capitalina las investigaciones contra el residente señalado. No se reportaron detenidos.","b":"","img":"zocalo","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/2026/11/11/repartidores-vandalizan-edificio-en-la-del-valle-tras-amenazas-con-arma-contra-uno-de-sus-companeros/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-leon-xiv-celebra-su-ultima-misa-en-argentina-en-lujan-y-viaja-hoy-a-pe","t":"León XIV celebra su última misa en Argentina en Luján y viaja hoy a Perú, donde permanecerá una semana","c":"internacional","f":"2026-11-11T06:44","r":"El Papa visitará temprano la cárcel de Devoto y después oficiará en la Basílica de Luján, donde se prevé una multitud; el gobernador Axel Kicillof será el anfitrión y Javier Milei lo despedirá en Ezeiza. Por la tarde llegará a Lima para iniciar la última etapa de su primera gira latinoamericana, en el país donde vivió más de 20 años y cuya nacionalidad adoptó.","b":"","img":"vaticano","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/politica/2026/11/11/frente-a-una-multitud-el-papa-celebrara-una-historica-misa-en-la-basilica-de-lujan-antes-de-partir-hacia-peru/"],["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/11/miercoles-11-de-noviembre-de-2026-0800-gmt/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-china-cierra-su-dia-del-soltero-con-la-inteligencia-artificial-en-toda","t":"China cierra su Día del Soltero con la inteligencia artificial en todas las etapas de compra y más quejas de los consumidores","c":"tecnologia","f":"2026-11-11T06:43","r":"La 18.ª edición del festival de compras en línea termina este 11 de noviembre; entre el 7 y el 31 de octubre las principales plataformas vendieron alrededor de 1.02 billones de yuanes, 2.36% más que un año antes, según la consultora Xingtu. Las tiendas usan IA para búsquedas, anuncios y atención al cliente, pero se multiplican las imágenes generadas que no corresponden al producto real y las quejas por chatbots sin acceso a agentes humanos.","b":"","img":"tech","foto":"","cred":"","src":[["ABC Color / EFE","https://www.abc.com.py/internacionales/2026/11/11/china-celebra-el-dia-del-soltero-protagonizado-por-la-ia-y-nuevas-dudas-entre-consumidores/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-tigres-vence-3-2-a-pumas-en-cu-en-la-ida-de-cuartos-de-final-de-la-lig","t":"Tigres vence 3-2 a Pumas en CU en la ida de cuartos de final de la Liga MX Femenil","c":"deportes","f":"2026-11-11T06:42","r":"Maricarmen Reyes anotó dos goles y Diana Ordóñez el tercero para las universitarias de Nuevo León; Stephanie Ribeiro marcó los dos tantos de Pumas, uno de ellos de penal. La serie se definirá el sábado 14 de noviembre en el estadio Universitario de San Nicolás.","b":"","img":"estadio","foto":"","cred":"","src":[["Telemundo","https://www.telemundo.com/deportes/futbol-estelar-liga-mx/tigres-se-queda-con-la-ventaja-en-cu-vence-a-pumas-a-domicilio-en-la-i-rcna608689"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-muere-en-culiacan-el-chevo-martinez-periodista-que-fue-traductor-de-pe","t":"Muere en Culiacán «El Chevo» Martínez, periodista que fue traductor de Pep Guardiola en Dorados; el técnico envió una corona","c":"deportes","f":"2026-11-11T06:41","r":"Eliseo Martínez, originario de Guanajuato, murió por causas naturales la mañana del martes a los 61 años. Fue enlace y traductor de Guardiola durante su paso como jugador por Dorados de Sinaloa entre 2005 y 2006; el entrenador del Manchester City envió flores blancas a la funeraria.","b":"","img":"estadio","foto":"","cred":"","src":[["Infobae","https://www.infobae.com/mexico/deportes/2026/11/11/pep-guardiola-lamenta-muerte-del-periodista-el-chevo-martinez-su-amigo-y-traductor-en-dorados-de-sinaloa/"]],"dest":false,"a":"Redacción"},{"id":"2026-11-11-daddy-yankee-recibe-este-miercoles-en-las-vegas-el-homenaje-como-perso","t":"Daddy Yankee recibe este miércoles en Las Vegas el homenaje como Persona del Año de la Academia Latina de la Grabación","c":"entretenimiento","f":"2026-11-11T06:40","r":"La ceremonia privada forma parte de la semana del Latin Grammy, cuya gala principal es el jueves. La Academia reconoce casi tres décadas de carrera del puertorriqueño, a quien se atribuye haber acuñado el término reguetón; su álbum Barrio Fino vendió más de ocho millones de copias.","b":"","img":"bellas","foto":"","cred":"","src":[["Excélsior","https://www.excelsior.com.mx/espectaculos/daddy-yankee-es-nombrado-persona-ano-2026-academia-latina-grabacion"],["EFE vía Infobae","https://www.infobae.com/america/agencias/2026/11/11/miercoles-11-de-noviembre-de-2026-0800-gmt/"]],"dest":false,"a":"Redacción"}];
